local config = {
  ui_story_5036_50360101_1_dialog_content = "Ahhh...!",
  ui_story_5036_50360101_2_dialog_content = "Socorro!",
  ui_story_5036_50360101_3_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5036_50360101_4_dialog_content = "Eca! *Tosse*",
  ui_story_5036_50360101_5_dialog_content = "Como você ousa me tocar? Você não sabe quem eu sou? Eu possuo o Star Theatre!",
  ui_story_5036_50360101_6_dialog_content = "Você ao menos percebe o que está fazendo?",
  ui_story_5036_50360101_7_dialog_content = "*Tosse*",
  ui_story_5036_50360101_8_dialog_content = "Infelizmente, não vou mais deixar você se apresentar no meu teatro, Srta. Goldie.",
  ui_story_5036_50360101_9_dialog_content = "... Que pena.",
  ui_story_5036_50360101_10_dialog_content = "Bom dia!",
  ui_story_5036_50360101_11_dialog_content = "*Boceja* Bom dia.",
  ui_story_5036_50360101_12_dialog_content = "Você chegou bem cedo. Surgiu algo urgente?",
  ui_story_5036_50360101_13_dialog_content = "Ops, é uma hora ruim?",
  ui_story_5036_50360101_14_dialog_content = "Desculpe, fiquei tão empolgado com a entrevista que nem percebi a hora!",
  ui_story_5036_50360101_15_dialog_content = "Uh, espere um segundo... Você não se lembra de mim?",
  ui_story_5036_50360101_16_option_content = "Nós lembramos de você",
  ui_story_5036_50360101_17_dialog_content = "Você parece um pouco familiar...?",
  ui_story_5036_50360101_18_dialog_content = "Oh espera, você não era um figurante em \"Tattletale\"?",
  ui_story_5036_50360101_19_option_content = "Não lembro de você",
  ui_story_5036_50360101_20_dialog_content = "Hum...",
  ui_story_5036_50360101_21_dialog_content = "Devemos conhecê-lo?",
  ui_story_5036_50360101_22_dialog_content = "Er, aham...",
  ui_story_5036_50360101_23_dialog_content = "Eu estou <color=#FFB400>Brandy</color>, repórter estagiário do The Daily Scoop!",
  ui_story_5036_50360101_24_dialog_content = "Nos encontramos brevemente em frente à Andersen Haunted House antes.",
  ui_story_5036_50360101_25_dialog_content = "Não consegui entrevistar vocês dois então, e meu editor criticou o artigo que escrevi...",
  ui_story_5036_50360101_26_dialog_content = "Mas está tudo bem!",
  ui_story_5036_50360101_27_dialog_content = "Estou muito grato a você pela entrevista exclusiva de hoje!",
  ui_story_5036_50360101_28_dialog_content = "Huh? Quando eu concordei com isso?",
  ui_story_5036_50360101_29_dialog_content = "Bem, não temos um momento a perder! Por que não começamos a entrevista então?",
  ui_story_5036_50360101_30_dialog_content = "Quais são seus pensamentos sobre o <color=#FFB400>Colosso Errante</color>?",
  ui_story_5036_50360101_31_dialog_content = "Colosso Errante?",
  ui_story_5036_50360101_32_dialog_content = "É assim que os jovens de Umbraton chamam Soroz?",
  ui_story_5036_50360101_33_dialog_content = "Hã?",
  ui_story_5036_50360101_34_dialog_content = "Você não conhece o Colosso Errante?",
  ui_story_5036_50360101_35_dialog_content = "Quase todo mundo sabe disso, de Northland ao Rediesel Desert, de Lumopolis a Umbraton.",
  ui_story_5036_50360101_36_dialog_content = "Mas você nunca ouviu falar, apesar de ser um celestita?",
  ui_story_5036_50360101_37_dialog_content = "Acho que isso também conta como notícia!",
  ui_story_5036_50360101_38_dialog_content = "Hmmm, tem potencial para ser manchete. Eu deveria anotar isso!",
  ui_story_5036_50360101_39_dialog_content = "Aham. Ultimamente, tenho estado muito ocupado com o trabalho e outras coisas para acompanhar os assuntos atuais.",
  ui_story_5036_50360101_40_dialog_content = "Não me diga que há tablóides espalhando boatos sobre mim de novo?",
  ui_story_5036_50360101_41_dialog_content = "Não mesmo!",
  ui_story_5036_50360101_42_dialog_content = "Olha, aqui está um pouco da noite passada.",
  ui_story_5036_50360101_43_dialog_content = "Extra:",
  ui_story_5036_50360101_44_dialog_content = "Previsão da Trilha do Colosso Errante",
  ui_story_5036_50360101_45_dialog_content = "Indo para Umbraton ao longo do Rio Dourado!",
  ui_story_5036_50360101_46_dialog_content = "Vou ler para vocês!",
  ui_story_5036_50360101_47_dialog_content = "\"Última atualização: O Colosso Errante deixou Northland.\"",
  ui_story_5036_50360101_48_dialog_content = "\"Os cientistas estão rastreando isso e, de acordo com seus cálculos...\"",
  ui_story_5036_50360101_49_dialog_content = "\"O Colossus continuará para o sul em direção a Umbraton ao longo do Rio Dourado.\"",
  ui_story_5036_50360101_50_dialog_content = "\"O Colossus apareceu pela primeira vez abruptamente nos céus logo acima de Northland e foi pensado para vir da Zona Escura.\"",
  ui_story_5036_50360101_51_dialog_content = "\"Depois que um cientista anônimo confirmou essa teoria, a notícia abalou todo o continente.\"",
  ui_story_5036_50360101_52_dialog_content = "\"Alguns afirmam que o Colossus não tem navegador ou passageiros, nem carrega armas destrutivas.\"",
  ui_story_5036_50360101_53_dialog_content = "\"Mas o exterior, especialmente o fundo, é equipado com telas gigantes e aparelhos estéreo que parecem ser de tempos antigos.\"",
  ui_story_5036_50360101_54_dialog_content = "\"Atualmente, Illumina e Lumopolis estão procurando maneiras de interceptar o Colosso Errante...\"",
  ui_story_5036_50360101_55_dialog_content = "\"... para decidir como eles vão proceder com a situação.\"",
  ui_story_5036_50360101_56_dialog_content = "Um Colosso Errante?",
  ui_story_5036_50360101_57_dialog_content = "Tenho tantas perguntas que nem sei por onde começar.",
  ui_story_5036_50360101_58_dialog_content = "Um Colossus equipado com telas e sistemas estéreo?",
  ui_story_5036_50360101_59_dialog_content = "Acho que já li sobre isso em algum lugar!",
  ui_story_5036_50360101_60_dialog_content = "Sério? O que mais você pode me dizer?",
  ui_story_5036_50360101_61_dialog_content = "Desculpe, não me lembro muito sobre isso.",
  ui_story_5036_50360101_62_dialog_content = "Mas não fique tão desapontado. Vou perguntar ao policial Gronru agora mesmo.",
  ui_story_5036_50360101_63_dialog_content = "Tenho certeza que ela pode nos contar mais com sua amplitude de conhecimento sobre Colossi!",
  ui_story_5036_50360101_64_dialog_content = "Não será necessário.",
  ui_story_5036_50360101_65_dialog_content = "Carleen...? Você voltou!",
  ui_story_5036_50360101_66_dialog_content = "Achei que você ia ficar em Lumopolis para sempre.",
  ui_story_5036_50360101_67_dialog_content = "Eu li sobre o Wanderer Colossus no noticiário alguns dias atrás e achei toda a situação bastante estranha, então me enterrei em pesquisas na biblioteca.",
  ui_story_5036_50360101_68_dialog_content = "Você deve ter encontrado algo!",
  ui_story_5036_50360101_69_dialog_content = "Ou você não teria vindo aqui com tanta pressa...",
  ui_story_5036_50360101_70_dialog_content = "Sim, encontrei algo de mais de um século atrás.",
  ui_story_5036_50360101_71_dialog_content = "Mais de um século?",
  ui_story_5036_50360101_72_dialog_content = "Isso mesmo. Os celestitas eram isolacionistas e não tinham muito contato com os aurorianos naquela época.",
  ui_story_5036_50360101_73_dialog_content = "Mas um dia, de repente, eles procuraram a ajuda de Lumopolis e Illumina.",
  ui_story_5036_50360101_74_dialog_content = "Seu pedido de ajuda implicava que eles pareciam ter perdido contato com um Colosso chamado <color=#FFB400>Eulogoz</color>.",
  ui_story_5036_50360101_75_dialog_content = "Eulogoz tem uma característica muito proeminente—",
  ui_story_5036_50360101_76_dialog_content = "<color=#FFB400>Possui telas externas gigantes</color>.",
  ui_story_5036_50360101_77_dialog_content = "Telas gigantes? Foi assim que o jornal descreveu o Colosso Errante.",
  ui_story_5036_50360101_78_dialog_content = "O que é notável é que os celestitas não conseguiram encontrar Eulogoz cem anos atrás.",
  ui_story_5036_50360101_79_dialog_content = "Quer dizer... que o Colosso Errante é o Eulogoz há muito perdido?",
  ui_story_5036_50360101_80_dialog_content = "Isso é o que eu estou supondo.",
  ui_story_5036_50360101_81_dialog_content = "Como é possível que ela desapareça por mais de um século e permaneça desconhecida até agora?!",
  ui_story_5036_50360101_82_dialog_content = "Achei que você saberia de alguma coisa, sendo você mesmo um celestita.",
  ui_story_5036_50360101_83_dialog_content = "Talvez possa se tornar invisível?",
  ui_story_5036_50360101_84_dialog_content = "Nunca ouvi falar de um celestita capaz de ser invisível.",
  ui_story_5036_50360101_85_dialog_content = "Seu nome e origens são pouco importantes agora.",
  ui_story_5036_50360101_86_dialog_content = "O importante é que um Colosso apareceu do nada no céu!",
  ui_story_5036_50360101_87_dialog_content = "Todos nós sabemos que os Colossi são exclusivos dos Caelestitas.",
  ui_story_5036_50360101_88_dialog_content = "E temos um Caelestita genuíno e autêntico bem aqui.",
  ui_story_5036_50360101_89_dialog_content = "No entanto, são Lumopolis e Illumina que estão decidindo o que fazer com o Colossus.",
  ui_story_5036_50360101_90_dialog_content = "Como você se sente sobre isso, PlayerName?",
  ui_story_5036_50360101_91_dialog_content = "Espero que os pesquisadores do Illumina notifiquem PlayerName depois de uma investigação minuciosa.",
  ui_story_5036_50360101_92_dialog_content = "Os cavaleiros fiéis ao Deus da Luz jamais pegariam algo que não nos pertencesse.",
  ui_story_5036_50360101_93_dialog_content = "*Ahem* Eu queria pedir a opinião do PlayerName sobre a situação, já que ele é um Caelestita.",
  ui_story_5036_50360101_94_dialog_content = "...",
  ui_story_5036_50360101_95_dialog_content = "Desculpe.",
  ui_story_5036_50360101_96_dialog_content = "Hã?",
  ui_story_5036_50360101_97_dialog_content = "Não posso responder sem antes ver o Colosso pessoalmente.",
  ui_story_5036_50360101_98_dialog_content = "Você está planejando...",
  ui_story_5036_50360101_99_dialog_content = "Independentemente disso, tenho o direito de investigar algo que pertence aos celestitas.",
  ui_story_5036_50360101_100_dialog_content = "Vocês dois virão comigo?",
  ui_story_5036_50360101_101_dialog_content = "Eu estava planejando fazer exatamente isso.",
  ui_story_5036_50360101_102_dialog_content = "Você ainda tem que perguntar?",
  ui_story_5036_50360101_103_dialog_content = "Certo!",
  ui_story_5036_50360101_104_dialog_content = "Soroz...",
  ui_story_5036_50360101_105_option_content = "Velocidade máxima!",
  ui_story_5036_50360101_106_dialog_content = "Oh meu, então isso é tão legal PlayerName a aparência do celestita ao comandar um colosso!",
  ui_story_5036_50360101_107_dialog_content = "Eu preciso gravar isso!",
  ui_story_5036_50360101_108_dialog_content = "<color=#e8d9bb>Aviso! Aviso! Comando inválido.</color>",
  ui_story_5036_50360101_109_dialog_content = "Hã?",
  ui_story_5036_50360101_110_dialog_content = "<color=#e8d9bb>Insira as coordenadas do alvo.</color>",
  ui_story_5036_50360101_111_dialog_content = "Ah, aquilo...",
  ui_story_5036_50360101_112_dialog_content = "Diga, alguém tem as coordenadas do Wandering Colossus?",
  ui_story_5036_50360101_113_dialog_content = "...",
  ui_story_5036_50360101_114_dialog_content = "Eu estava me perguntando quando você ia perguntar.",
  ui_story_5036_50360101_115_dialog_content = "Desculpe, mas não posso alugar o teatro para você.",
  ui_story_5036_50360101_116_dialog_content = "Por favor, a receita não é um problema! Meus shows são bem atendidos!",
  ui_story_5036_50360101_117_dialog_content = "Você não vai reconsiderar?",
  ui_story_5036_50360101_118_dialog_content = "Sugiro que tente a sorte em outro lugar.",
  ui_story_5036_50360101_119_dialog_content = "Mas todos os outros teatros em Umbraton já me rejeitaram...",
  ui_story_5036_50360101_120_dialog_content = "Adicional, adicional! O Colossus Errante deve seguir para Umbraton ao longo do Rio Dourado!",
  ui_story_5036_50360101_121_dialog_content = "Colosso Errante?",
  ui_story_5036_50360101_122_dialog_content = "Posso ter uma cópia por favor?",
  ui_story_5036_50360101_123_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_5036_50360101_124_dialog_content = "Nossa!",
  ui_story_5036_50360101_125_dialog_content = "Estamos realmente decolando!",
  ui_story_5036_50360101_126_dialog_content = "Aquele editor que me assedia dia após dia nunca teria imaginado isso em um milhão de anos!",
  ui_story_5036_50360101_127_dialog_content = "Que de todos os jornalistas lutando por uma chance de seguir uma das histórias do Caelestite em Umbraton, eu sou o único a realmente voar dentro do Colossus!",
  ui_story_5036_50360101_128_dialog_content = "Vou mostrar a ele quem é o repórter mais incrível da cidade!",
  ui_story_5036_50360101_129_dialog_content = "Ué, Brandy...?",
  ui_story_5036_50360101_130_dialog_content = "Oh não, eu não deveria ter me exposto na frente dos meus entrevistados!",
  ui_story_5036_50360101_131_dialog_content = "Aham. Por favor, fiquem tranquilos, pessoal. Sou um profissional e farei meu trabalho com a máxima objetividade.",
  ui_story_5036_50360101_132_dialog_content = "Isso não foi o que eu quis dizer.",
  ui_story_5036_50360101_133_dialog_content = "Você queria voltar para Umbraton? Posso deixar você no caminho.",
  ui_story_5036_50360101_134_dialog_content = "Ah, de jeito nenhum! Ainda não estou nem perto de terminar minha entrevista com você.",
  ui_story_5036_50360101_135_dialog_content = "Eu também gostaria de sua permissão para acompanhá-lo em sua jornada para o Wandering Colossus.",
  ui_story_5036_50360101_136_dialog_content = "Prometo que escreverei o artigo mais épico e glorioso sobre você!",
  ui_story_5036_50360101_137_dialog_content = "Aqueles em Lumopolis e Illumina nem pensarão em tocar na propriedade de Caelestite depois de lê-la!",
  ui_story_5036_50360101_138_dialog_content = "Er, isso é... isso é um pouco dramático, ha...",
  ui_story_5036_50360101_139_dialog_content = "Ei, o que é isso?",
  ui_story_5036_50360101_140_dialog_content = "Um pôster acabou de cair da sua bolsa, Brandy.",
  ui_story_5036_50360101_141_dialog_content = "Ahahaha, certo! Obrigado! Afastando-o imediatamente!",
  ui_story_5036_50360101_142_dialog_content = "Espere, não conhecemos aquela pessoa no pôster?",
  ui_story_5036_50360101_143_dialog_content = "Sim, não é Goldie?",
  ui_story_5036_50360101_144_dialog_content = "Depois que \"Into the Haunted House\" estreou, nós a encontramos uma vez na Andersen Haunted House.",
  ui_story_5036_50360101_145_dialog_content = "O filme recebeu ótimas críticas, mas ela decidiu parar de atuar.",
  ui_story_5036_50360101_146_dialog_content = "Eu me pergunto o que ela tem feito ultimamente?",
  ui_story_5036_50360101_147_dialog_content = "Eu sinto que ela se tornou popular em Umbraton ultimamente. Vejo pôsteres dela em todos os lugares que vou.",
  ui_story_5036_50360101_148_dialog_content = "Essa que tenho é diferente das que tem na rua.",
  ui_story_5036_50360101_149_dialog_content = "Este é um colecionável de edição limitada!",
  ui_story_5036_50360101_150_dialog_content = "Então você é fã dela?",
  ui_story_5036_50360101_151_dialog_content = "Eu realmente não me chamaria de Cachinho Dourado...",
  ui_story_5036_50360101_152_dialog_content = "Um Cachinho Dourado?",
  ui_story_5036_50360101_153_dialog_content = "É assim que os fãs de Goldie são chamados. Eu realmente não sou um deles!",
  ui_story_5036_50360101_154_dialog_content = "Acabei de entrevistar Goldie depois que \"Into the Haunted House\" estreou.",
  ui_story_5036_50360101_155_dialog_content = "Achei-a muito otimista e gentil, como uma brisa morna dissipando todos os meus problemas.",
  ui_story_5036_50360101_156_dialog_content = "Caso contrário, provavelmente não teria durado tanto quanto como estagiário no The Daily Scoop.",
  ui_story_5036_50360101_157_dialog_content = "Então, depois disso, eu apenas seguia o trabalho dela de vez em quando, só isso.",
  ui_story_5036_50360101_158_dialog_content = "Isso basicamente não faz de você um fã?",
  ui_story_5036_50360101_159_dialog_content = "D-Será? Mas ouvi boatos que Goldie tinha tendências violentas.",
  ui_story_5036_50360101_160_dialog_content = "É verdade que muitas figuras públicas têm um lado que ninguém conhece.",
  ui_story_5036_50360101_161_dialog_content = "Mas não quero idolatrar alguém que é violento.",
  ui_story_5036_50360101_162_dialog_content = "Goldie, violento? De jeito nenhum!",
  ui_story_5036_50360101_163_dialog_content = "Tem havido muitos rumores absurdos ultimamente, e esse é provavelmente um deles.",
  ui_story_5036_50360101_164_dialog_content = "Os jornais da Umbraton provavelmente estão retratando PlayerName como um monstro místico de três cabeças agora.",
  ui_story_5036_50360101_165_dialog_content = "Verdadeiro! Eu odeio isso.",
  ui_story_5036_50360101_166_dialog_content = "É melhor não me arrastar na lama como eles, Brandy!",
  ui_story_5036_50360101_167_dialog_content = "Relaxar!",
  ui_story_5036_50360101_168_dialog_content = "Eu apenas relato a verdade como a vejo com meus próprios olhos.",
  ui_story_5036_50360101_169_dialog_content = "Eu gostaria que houvesse mais jornalistas como você em Umbraton.",
  ui_story_5036_50360101_170_dialog_content = "M-eu? Nossa, hehehe...",
  ui_story_5036_50360101_171_dialog_content = "<color=#e8d9bb>Aviso: Objeto voador não identificado detectado à frente.</color>",
  ui_story_5036_50360101_172_dialog_content = "<color=#e8d9bb>Por favor, dê comando para ação evasiva!</color>",
  ui_story_5036_50360101_173_dialog_content = "Objeto voador não identificado?",
  ui_story_5036_50360101_174_dialog_content = "A build dele é bem diferente do Soroz...",
  ui_story_5036_50360101_175_dialog_content = "mas o design e o brilho de seu casco são obviamente de um Colosso!",
  ui_story_5036_50360101_176_dialog_content = "A tela...",
  ui_story_5036_50360101_177_dialog_content = "Eu vejo isso! Essa enorme coisa quadrada é a tela?",
  ui_story_5036_50360101_178_dialog_content = "Isso definitivamente não é do nosso tempo!",
  ui_story_5036_50360101_179_dialog_content = "Deve ser isso! Deve ser o Colosso Errante!",
  ui_story_5036_50360101_180_dialog_content = "Mas por que Soroz não consegue identificá-lo pelo nome?",
  ui_story_5036_50360101_181_dialog_content = "E por que não consigo sentir seu Navegador?",
  ui_story_5036_50360101_182_dialog_content = "Você é realmente o Eulogoz que desapareceu há um século?",
  ui_story_5036_50360101_183_dialog_content = "♪ La... La la la... ♪",
  ui_story_5036_50360101_184_dialog_content = "(Quem está cantando?)",
  ui_story_5036_50360101_185_dialog_content = "Vocês ouvem isso?",
  ui_story_5036_50360101_186_dialog_content = "Do quê?",
  ui_story_5036_50360101_187_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360101_188_dialog_content = "Cantando... Alguém está cantando!",
  ui_story_5036_50360101_189_dialog_content = "O que? Eu não ouço nada.",
  ui_story_5036_50360101_190_dialog_content = "♪ Lá lá lá lá... ♪",
  ui_story_5036_50360101_191_dialog_content = "(Você é o Navegador de Eulogoz?)",
  ui_story_5036_50360101_192_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360101_193_dialog_content = "(Por que você abandonou seu Colosso?)",
  ui_story_5036_50360101_194_dialog_content = "♪ Lá... Lá lá... ♪",
  ui_story_5036_50360101_195_dialog_content = "(Por que...?)",
  ui_story_5036_50360101_196_dialog_content = "<color=#e8d9bb>Aviso: Objeto voador não identificado detectado à frente.</color>",
  ui_story_5036_50360101_197_dialog_content = "<color=#e8d9bb>Para evitar colisões, o Colossus mudará automaticamente a rota de voo em três segundos.</color>",
  ui_story_5036_50360101_198_dialog_content = "<color=#e8d9bb>Três...</color>",
  ui_story_5036_50360101_199_dialog_content = "<color=#e8d9bb>Dois...</color>",
  ui_story_5036_50360101_200_dialog_content = "Pare o desvio da rota de voo.",
  ui_story_5036_50360101_201_dialog_content = "Combine a velocidade e a direção do objeto voador não identificado.",
  ui_story_5036_50360101_202_dialog_content = "Ajuste o voo conforme necessário.",
  ui_story_5036_50360201_1_dialog_content = "<color=#e8d9bb>Atenção, aproximando-se de objeto voador não identificado.</color>",
  ui_story_5036_50360201_2_dialog_content = "O Colosso está tremendo muito! Nós colidimos com o Colosso Errante?",
  ui_story_5036_50360201_3_dialog_content = "Não se preocupe. É só o Soroz reduzindo a velocidade.",
  ui_story_5036_50360201_4_dialog_content = "Isso é ruim. Achei que poderia capturar uma foto de dois Colossi colidindo um contra o outro.",
  ui_story_5036_50360201_5_dialog_content = "Uma foto tão incrível faria a primeira página de todos os jornais!",
  ui_story_5036_50360201_6_dialog_content = "Se isso acontecesse, duvido que você tivesse tempo de tirar uma foto.",
  ui_story_5036_50360201_7_dialog_content = "Estou apenas dizendo!",
  ui_story_5036_50360201_8_dialog_content = "Dito isso, sua câmera parece bem única.",
  ui_story_5036_50360201_9_dialog_content = "Você tem um bom olho, Vice!",
  ui_story_5036_50360201_10_dialog_content = "Nem todo mundo tem o privilégio de possuir um dispositivo avançado como uma câmera.",
  ui_story_5036_50360201_11_dialog_content = "Sem falar que sempre atualizo suas peças para conseguir fotos melhores.",
  ui_story_5036_50360201_12_dialog_content = "Fui contratado como estagiário graças a esta câmera.",
  ui_story_5036_50360201_13_dialog_content = "Uau! Então, sua câmera pode fazer as pessoas parecerem mais bonitas nas fotos?",
  ui_story_5036_50360201_14_dialog_content = "Isso não posso prometer, mas posso garantir que capturará a imagem mais autêntica e realista!",
  ui_story_5036_50360201_15_dialog_content = "<color=#e8d9bb>Ajuste feito para manter velocidade e direção consistentes com o objeto não identificado.</color>",
  ui_story_5036_50360201_16_dialog_content = "Vamos.",
  ui_story_5036_50360201_17_dialog_content = "Espere, ainda estamos muito longe do Wandering Colossus.",
  ui_story_5036_50360201_18_dialog_content = "Como vamos chegar perto dele?",
  ui_story_5036_50360201_19_dialog_content = "Voando, é claro.",
  ui_story_5036_50360201_20_dialog_content = "<anim type=Shake>Ahhhh!!!</anim>",
  ui_story_5036_50360201_21_dialog_content = "N-nós realmente voamos!",
  ui_story_5036_50360201_22_dialog_content = "Essa foi a minha primeira vez em um dirigível, foi brilhante!",
  ui_story_5036_50360201_23_dialog_content = "Sem falar que não acredito que o Colosso Errante está realmente sob meus pés agora!",
  ui_story_5036_50360201_24_dialog_content = "Oh Deus, tantos repórteres morreriam por uma oportunidade como esta!",
  ui_story_5036_50360201_25_dialog_content = "Mas, opa, não importa o quão animado eu esteja, um repórter profissional nunca deve negligenciar o assunto de sua redação.",
  ui_story_5036_50360201_26_dialog_content = "Deixe-me perguntar como PlayerName sente neste momento!",
  ui_story_5036_50360201_27_dialog_content = "Com licença, PlayerName...?",
  ui_story_5036_50360201_28_dialog_content = "...",
  ui_story_5036_50360201_29_dialog_content = "Ei, você está pálido... Isso é alguma forma de protesto sem palavras contra as ações de Illumina e Lumopolis?",
  ui_story_5036_50360201_30_dialog_content = "É Darkflow! Tanto Darkflow de repente!",
  ui_story_5036_50360201_31_dialog_content = "O que? Estamos no lugar errado?",
  ui_story_5036_50360201_32_dialog_content = "Impossível, a juíza-chefe Irridon me deu as coordenadas pessoalmente. Eles não podem estar errados.",
  ui_story_5036_50360201_33_dialog_content = "Pessoal, não há tempo para isso agora, temos um problema maior!",
  ui_story_5036_50360201_34_dialog_content = "<size=45>Ah!!!</size>",
  ui_story_5036_50360202_1_dialog_content = "♪ La... La la la... ♪",
  ui_story_5036_50360202_2_dialog_content = "(É a cantoria de novo...)",
  ui_story_5036_50360202_3_dialog_content = "(Por que soa estranhamente familiar quando nunca o ouvi antes?)",
  ui_story_5036_50360202_4_dialog_content = "(É como um ritmo que sempre esteve pulsando em minhas veias, apenas borbulhando na superfície da minha memória neste momento.)",
  ui_story_5036_50360202_5_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360202_6_dialog_content = "♪ Lá lá lá lá... ♪",
  ui_story_5036_50360202_7_dialog_content = "V-você é...",
  ui_story_5036_50360202_8_dialog_content = "Como um mero celestita ousa esquecer o nome do juiz Matthieu!",
  ui_story_5036_50360202_9_dialog_content = "Nem mesmo uma alma em Lumopolis ousa me ignorar assim! Eu me recuso a sofrer tamanha indignidade!",
  ui_story_5036_50360202_10_dialog_content = "Não concorda, Loewe? ... O que você está fazendo, Loewe?",
  ui_story_5036_50360202_11_dialog_content = "Você está bem, Alteza?",
  ui_story_5036_50360202_12_dialog_content = "Estou bem. Foram apenas alguns Eclipsites.",
  ui_story_5036_50360202_13_dialog_content = "Mas, graças à sua chegada oportuna, nos livramos deles rapidamente.",
  ui_story_5036_50360202_14_dialog_content = "Hmph, eu nunca teria imaginado...",
  ui_story_5036_50360202_15_dialog_content = "que um dia você aprenderia a receber o crédito e roubar o trovão para si mesmo, Loewe!",
  ui_story_5036_50360202_16_dialog_content = "A investigação ainda não acabou.",
  ui_story_5036_50360202_17_dialog_content = "Mas alguém queria ir para casa.",
  ui_story_5036_50360202_18_dialog_content = "De novo com isso!",
  ui_story_5036_50360202_19_dialog_content = "Não tenho ideia de onde Loewe aprendeu a ser um puxa-saco e apunhalar seus colegas pelas costas.",
  ui_story_5036_50360202_20_dialog_content = "Não deixe que suas tolices a influenciem, Lady Carleen.",
  ui_story_5036_50360202_21_dialog_content = "Nos últimos dias, conduzi o trabalho da unidade de investigação de Lumopolis no Colosso Errante da maneira mais adequada e ordenada.",
  ui_story_5036_50360202_22_dialog_content = "Você poderá ler meu relatório detalhado em cima de sua almofada de veludo em Lumopolis no devido tempo.",
  ui_story_5036_50360202_23_dialog_content = "Oh sério? Então você não andou perambulando por Siobhan na tentativa de plagiar o trabalho dela, hein?",
  ui_story_5036_50360202_24_dialog_content = "Fique tranquilo, oficial Gronru.",
  ui_story_5036_50360202_25_dialog_content = "Vou proteger nossos arquivos com tudo o que tenho.",
  ui_story_5036_50360202_26_dialog_content = "Parece que você foi pego em flagrante.",
  ui_story_5036_50360202_27_dialog_content = "Ah, cale a boca! Eu estava apenas confirmando nossas próprias descobertas!",
  ui_story_5036_50360202_28_dialog_content = "Oficial Gronru, senhorita Siobhan!",
  ui_story_5036_50360202_29_dialog_content = "Então você está aqui em missão no Wandering Colossus?",
  ui_story_5036_50360202_30_dialog_content = "Vamos dar uma olhada em você... Vice, querida, você emagreceu de novo?",
  ui_story_5036_50360202_31_dialog_content = "Ué, eu?",
  ui_story_5036_50360202_32_dialog_content = "Se você continuar tratando Vice assim, PlayerName, Vou roubá-la de você!",
  ui_story_5036_50360202_33_dialog_content = "Eu não fiz nada...",
  ui_story_5036_50360202_34_dialog_content = "É assim mesmo? Heehee...",
  ui_story_5036_50360202_35_dialog_content = "De qualquer forma, você chegou aqui muito mais tarde do que eu esperava.",
  ui_story_5036_50360202_36_dialog_content = "eu quase pensei PlayerName havia desistido da idéia de inspecionar este Colosso.",
  ui_story_5036_50360202_37_dialog_content = "Mas até onde eu sei...",
  ui_story_5036_50360202_38_dialog_content = "Nem Lumopolis nem a Federação Illumina notificaram oficialmente PlayerName sobre o Colosso Errante.",
  ui_story_5036_50360202_39_dialog_content = "Hum? Não acredito que nos conhecemos.",
  ui_story_5036_50360202_40_dialog_content = "Olá, sou Brandy, uma repórter estagiária do The Daily Scoop.",
  ui_story_5036_50360202_41_dialog_content = "Estou fazendo um recurso sobre PlayerName. Por favor responda minha pergunta.",
  ui_story_5036_50360202_42_dialog_content = "Por que nenhum de vocês informou PlayerName sobre o Colosso Errante?",
  ui_story_5036_50360202_43_dialog_content = "É verdade que Illumina e Lumopolis planejaram dividir o Colosso pelas costas do Celestita?",
  ui_story_5036_50360202_44_dialog_content = "Jovem repórter, a Illumina é obrigada a informar PlayerName?",
  ui_story_5036_50360202_45_dialog_content = "Oficial Gronru!",
  ui_story_5036_50360202_46_dialog_content = "Oh! Eu assustei todos vocês?",
  ui_story_5036_50360202_47_dialog_content = "Ehehe tudo bem, vou responder bem.",
  ui_story_5036_50360202_48_dialog_content = "Enviamos uma grande equipe para investigar assim que recebemos notícias sobre o Wandering Colossus.",
  ui_story_5036_50360202_49_dialog_content = "Temos muito apoio em espera, tanto no solo quanto no ar nas proximidades.",
  ui_story_5036_50360202_50_dialog_content = "Ao contrário de suas suposições, nosso objetivo principal não é tomar o Colosso para nós mesmos.",
  ui_story_5036_50360202_51_dialog_content = "Estamos aqui para avaliar o nível de ameaça que um Colosso saindo da Zona Cega pode representar para a Illumina.",
  ui_story_5036_50360202_52_dialog_content = "Afinal, veio da Dark Zone, e ninguém sabe que tipos de <color=#FFB400>passageiros</color> estão a bordo.",
  ui_story_5036_50360202_53_dialog_content = "A Lumópolis compartilha dessa visão.",
  ui_story_5036_50360202_54_dialog_content = "Só não entendo por que sempre fui escolhido para tarefas trabalhosas e sujas como essa.",
  ui_story_5036_50360202_55_dialog_content = "As notícias do Colosso Errante nunca foram censuradas.",
  ui_story_5036_50360202_56_dialog_content = "Estou curioso para saber por que PlayerName não estava ciente disso.",
  ui_story_5036_50360202_57_dialog_content = "B-Bem, há uma razão...",
  ui_story_5036_50360202_58_dialog_content = "Ah?",
  ui_story_5036_50360202_59_dialog_content = "Esqueça isso. Acho que não chegamos muito tarde.",
  ui_story_5036_50360202_60_dialog_content = "Mas estou intrigado ao ver os Eclipsites vagando pelos corredores do Wandering Colossus.",
  ui_story_5036_50360202_61_dialog_content = "Lamento muito que tenha passado por tal susto ao chegar, Lady Carleen.",
  ui_story_5036_50360202_62_dialog_content = "Se me permite, recomendo que deixe este Colosso imediatamente.",
  ui_story_5036_50360202_63_dialog_content = "Não só está cheio de teias de aranha, mas também parece abrigar incontáveis Eclipsites sujos.",
  ui_story_5036_50360202_64_dialog_content = "No entanto, você não precisa se preocupar com a nossa segurança.",
  ui_story_5036_50360202_65_dialog_content = "Após dias de esforço, contivemos a maioria dos Eclipsites em um <color=#FFB400>área bloqueada</color> na seção traseira.",
  ui_story_5036_50360202_66_dialog_content = "Então fique tranquilo!",
  ui_story_5036_50360202_67_dialog_content = "Já mandei pessoal para intensificar a eliminação dos Eclipsites, prometo!",
  ui_story_5036_50360202_68_dialog_content = "Essa escória imunda nunca mais vai incomodá-lo.",
  ui_story_5036_50360202_69_dialog_content = "Muito bem, Juiz Matthieu.",
  ui_story_5036_50360202_70_dialog_content = "A honra é minha.",
  ui_story_5036_50360202_71_dialog_content = "Então é relativamente seguro neste Colossus por enquanto?",
  ui_story_5036_50360202_72_dialog_content = "Desde que você não ponha os pés no <color=#FFB400>área bloqueada</color> onde a dificuldade é aumentada, você deve ficar bem!",
  ui_story_5036_50360202_73_dialog_content = "Gronru, eu quero saber mais sobre esse Colosso'...",
  ui_story_5036_50360202_74_option_content = "Sistema de controle",
  ui_story_5036_50360202_75_dialog_content = "Talvez eu possa tentar pousar.",
  ui_story_5036_50360202_76_dialog_content = "Também pensei nisso, então verificamos minuciosamente a ponte.",
  ui_story_5036_50360202_77_dialog_content = "Mas encontramos os sistemas de controle e navegação, até mesmo o Echo Template, todos danificados.",
  ui_story_5036_50360202_78_dialog_content = "Mesmo você provavelmente não pode controlá-lo agora.",
  ui_story_5036_50360202_79_dialog_content = "Como pode ser isso? Então e quanto ao—",
  ui_story_5036_50360202_80_option_content = "Núcleo de energia",
  ui_story_5036_50360202_81_dialog_content = "O Colossus ainda se move, então o núcleo de poder deve estar intacto, certo?",
  ui_story_5036_50360202_82_dialog_content = "Pode-se dizer que sim.",
  ui_story_5036_50360202_83_dialog_content = "Já que ainda está fornecendo energia para o Colossus continuar voando.",
  ui_story_5036_50360202_84_dialog_content = "Mas, ao mesmo tempo, também não está na melhor forma...",
  ui_story_5036_50360202_85_dialog_content = "porque sofreu ataques de Eclipsite em algum momento no passado.",
  ui_story_5036_50360202_86_dialog_content = "Não é ruim o suficiente que a energia seja perdida repentinamente, mas definitivamente afeta a produção de energia.",
  ui_story_5036_50360202_87_dialog_content = "Isso é corrigível, certo?",
  ui_story_5036_50360202_88_dialog_content = "Restaurar o núcleo de energia não é uma tarefa fácil.",
  ui_story_5036_50360202_89_dialog_content = "No mínimo, você precisa desligar o Colossus e desligar o núcleo de energia primeiro.",
  ui_story_5036_50360202_90_dialog_content = "Caso contrário, não temos tempo suficiente para diagnosticá-lo e repará-lo.",
  ui_story_5036_50360202_91_dialog_content = "Exceto que agora nem sabemos como impedi-lo de voar.",
  ui_story_5036_50360202_92_dialog_content = "Como pode ser isso? Então e quanto ao—",
  ui_story_5036_50360202_93_option_content = "Sistema de tela e alto-falante",
  ui_story_5036_50360202_94_dialog_content = "Percebi que estava equipado com o que parecia ser uma tela e alto-falantes do lado de fora.",
  ui_story_5036_50360202_95_dialog_content = "Sim, esses são autênticos!",
  ui_story_5036_50360202_96_dialog_content = "A tecnologia está muito além da nossa amplitude atual de conhecimento.",
  ui_story_5036_50360202_97_dialog_content = "Eles estão surpreendentemente bem preservados, apesar da idade.",
  ui_story_5036_50360202_98_dialog_content = "Graças à ajuda de Siobhan, descobrimos como ativá-los!",
  ui_story_5036_50360202_99_dialog_content = "Seria espetacular reproduzir filmes em uma tela tão gigante!",
  ui_story_5036_50360202_100_dialog_content = "E...",
  ui_story_5036_50360202_100X1_dialog_content = "Mais alguma coisa?",
  ui_story_5036_50360202_100X2_option_content = "Sim.",
  ui_story_5036_50360202_100X3_option_content = "Isso é tudo",
  ui_story_5036_50360202_101_dialog_content = "Ah, e outra coisa...",
  ui_story_5036_50360202_102_dialog_content = "Você descobriu algum caelestita ou itens relacionados?",
  ui_story_5036_50360202_103_dialog_content = "Ainda não.",
  ui_story_5036_50360202_104_dialog_content = "Mas falando nisso...",
  ui_story_5036_50360202_105_dialog_content = "Minha querida assistente Siobhan nos ajudou a desenterrar registros históricos sobre este Colosso errante.",
  ui_story_5036_50360202_106_dialog_content = "Pela sua aparência e tamanho, é muito óbvio que este Colosso foi dado como desaparecido pelos celestitas há mais de cem anos, chamado—",
  ui_story_5036_50360202_107_dialog_content = "<color=#FFB400>Eulogoz?</color>",
  ui_story_5036_50360202_108_dialog_content = "O quê, você já sabia?",
  ui_story_5036_50360202_109_dialog_content = "Infelizmente, saber seu nome não importa.",
  ui_story_5036_50360202_110_dialog_content = "Este Colosso está repleto de tecnologia maligna e deve ser inevitavelmente destruído.",
  ui_story_5036_50360202_111_dialog_content = "Desculpe, o que? Quem está destruindo Eulogoz?",
  ui_story_5036_50360202_112_dialog_content = "Não entenda mal. Não foi minha única decisão.",
  ui_story_5036_50360202_113_dialog_content = "Foi a solução que a maioria de nós concordou.",
  ui_story_5036_50360202_114_dialog_content = "Uau, você pode agir de forma mais vilã?",
  ui_story_5036_50360202_115_dialog_content = "É muito cedo para dizer isso. Ainda não assinei.",
  ui_story_5036_50360202_116_dialog_content = "Bem, talvez não seja sua escolha no final.",
  ui_story_5036_50360202_117_dialog_content = "O que está acontecendo, Juiz Matthieu? Por favor elabore.",
  ui_story_5036_50360202_118_dialog_content = "Você me ouviu, Lady Carleen.",
  ui_story_5036_50360202_119_dialog_content = "Este Colosso não tem valor e está repleto de Eclipsites incontroláveis.",
  ui_story_5036_50360202_120_dialog_content = "Deixá-lo à deriva representará uma grande ameaça à sobrevivência de todos no Astra.",
  ui_story_5036_50360202_121_dialog_content = "Ah, uma coisinha...",
  ui_story_5036_50360202_122_dialog_content = "O que acontece se ele cair em Lumopolis?",
  ui_story_5036_50360202_123_dialog_content = "Destruir esta máquina abandonada mantém nossa cidade natal segura.",
  ui_story_5036_50360202_124_dialog_content = "Tenho certeza de que você está tão ciente quanto eu de que o Lorde da Cidade faria a mesma ligação se estivesse presente.",
  ui_story_5036_50360202_125_dialog_content = "Nossas equipes de expedição têm procurado incansavelmente por restos de Colossos no deserto.",
  ui_story_5036_50360202_126_dialog_content = "Agora que finalmente encontramos um que realmente funciona, vamos destruí-lo?",
  ui_story_5036_50360202_127_dialog_content = "Não dê ouvidos a suas tolices vilãs, Vice.",
  ui_story_5036_50360202_128_dialog_content = "Já determinamos que sua rota de voo não cruzará para Lumopolis.",
  ui_story_5036_50360202_129_dialog_content = "E se continuarmos fazendo o que estamos fazendo aqui, nos livraremos de todos os Eclipsites.",
  ui_story_5036_50360202_130_dialog_content = "Além disso, Eulogoz não é \"completamente inútil\" como afirma aquele palhaço.",
  ui_story_5036_50360202_131_dialog_content = "Cada parte dele é valiosa para a pesquisa.",
  ui_story_5036_50360202_132_dialog_content = "Mesmo que muito esteja danificado e muito difícil de consertar...",
  ui_story_5036_50360202_133_dialog_content = "Ainda acho que vale o preço do conserto.",
  ui_story_5036_50360202_134_dialog_content = "Mas você também deve perceber...",
  ui_story_5036_50360202_135_dialog_content = "que é muito mais eficiente financeiramente para você apenas salvar as partes que deseja estudar e explodir o resto.",
  ui_story_5036_50360202_136_dialog_content = "Por que deixar essa coisa incontrolável voando por todo o céu?",
  ui_story_5036_50360202_137_dialog_content = "É muito mais valioso estudar uma amostra inteira!",
  ui_story_5036_50360202_138_dialog_content = "Você é capaz de fornecer evidências do potencial para o Colossus ser consertado?",
  ui_story_5036_50360202_139_dialog_content = "Eu... eu preciso de mais tempo!",
  ui_story_5036_50360202_140_dialog_content = "O tempo não espera por ninguém.",
  ui_story_5036_50360202_141_dialog_content = "Quanto mais você esperar, mais caro será esse esforço.",
  ui_story_5036_50360202_142_dialog_content = "Abatemos o Colossus, completamos a missão e seguimos caminhos separados. Não é melhor?",
  ui_story_5036_50360202_143_dialog_content = "Então você só quer ir para casa?",
  ui_story_5036_50360202_144_dialog_content = "Não entenda mal, estou apenas empregando táticas de negociação, Lady Carleen.",
  ui_story_5036_50360202_145_dialog_content = "Eulogoz pertence aos celestitas. Eu não vou deixar ninguém derrubá-lo!",
  ui_story_5036_50360202_146_dialog_content = "Posso ajudar a limpar os Eclipsites!",
  ui_story_5036_50360202_147_dialog_content = "Eu também vou provar a você o seu verdadeiro valor!",
  ui_story_5036_50360202_148_dialog_content = "De fato. Eu vou ajudar também.",
  ui_story_5036_50360202_149_dialog_content = "O que está fazendo, Lady Carleen?",
  ui_story_5036_50360202_150_dialog_content = "Aha, parece que a princesa de Lumopolis está relutante em ver Eulogoz abatido também!",
  ui_story_5036_50360202_151_dialog_content = "Querida, não há tempo para relutância neste mundo.",
  ui_story_5036_50360202_152_dialog_content = "Se houver, significa apenas que não foi oferecido dinheiro suficiente.",
  ui_story_5036_50360202_153_dialog_content = "Hã?",
  ui_story_5036_50360202_154_dialog_content = "Mesmo que eu não me importe com as garotas me bajulando, isso ainda me dá arrepios.",
  ui_story_5036_50360202_155_dialog_content = "Senhora Sheol?",
  ui_story_5036_50360202_156_dialog_content = "Ah, PlayerName, meu VIP!",
  ui_story_5036_50360202_157_dialog_content = "Faz muito tempo que você não vai à Guilda Cloudrover para me ver.",
  ui_story_5036_50360202_158_dialog_content = "Mas isso não é motivo para você vir até aqui para me vender coisas...",
  ui_story_5036_50360202_159_dialog_content = "Hahaha nossa linda PlayerName desenvolveu um senso de humor.",
  ui_story_5036_50360202_160_dialog_content = "Mas, em certo sentido, você está certo.",
  ui_story_5036_50360202_161_dialog_content = "Desta vez, porém, tenho uma proposta um pouco diferente.",
  ui_story_5036_50360202_162_dialog_content = "Venha aqui, querida!",
  ui_story_5036_50360202_163_dialog_content = "Você falando comigo?",
  ui_story_5036_50360202_164_dialog_content = "Não tema o dano nem o fracasso.",
  ui_story_5036_50360202_165_dialog_content = "A persistência será recompensada pela boa sorte.",
  ui_story_5036_50360202_166_dialog_content = "Não desanime ou desanimado.",
  ui_story_5036_50360202_167_dialog_content = "Basta olhar para o caminho de Goldie!",
  ui_story_5036_50360202_168_dialog_content = "Visitantes do Colossus, prazer em conhecê-los!",
  ui_story_5036_50360202_169_dialog_content = "G-Goldie?",
  ui_story_5036_50360202_170_dialog_content = "Olá, PlayerName! Como você tem estado?",
  ui_story_5036_50360202_171_dialog_content = "O quê?",
  ui_story_5036_50360202_172_dialog_content = "O que Goldie está fazendo aqui?",
  ui_story_5036_50360202_173_dialog_content = "Como parece que todos se conhecem, posso começar a conversa sobre negócios.",
  ui_story_5036_50360202_174_dialog_content = "Acho que você me superestima, Lady Sheol.",
  ui_story_5036_50360202_175_dialog_content = "Eu nunca poderia contratar uma celebridade para fazer um show para mim.",
  ui_story_5036_50360202_176_dialog_content = "Querida, a razão pela qual viajei em um caro dirigível alugado e vim até aqui com a estrela mais quente a reboque...",
  ui_story_5036_50360202_177_dialog_content = "certamente não foi apenas para lançar um empreendimento comercial apenas para você.",
  ui_story_5036_50360202_178_dialog_content = "Isso pode ser um pouco repentino e pode soar chocante, hehe.",
  ui_story_5036_50360202_179_dialog_content = "Mas veja, queremos fazer um show especial e único neste Colosso que envia ondas de choque por todo o Astra!",
  ui_story_5036_50360202_180_dialog_content = "Quando chegar a Umbraton...",
  ui_story_5036_50360202_181_dialog_content = "Vou ficar em cima dela e cantar minhas bênçãos para todos ouvirem!",
  ui_story_5036_50360202_182_dialog_content = "Todos em Umbraton e Lumopolis poderão ver o show na tela gigante!",
  ui_story_5036_50360202_183_dialog_content = "Hmph, plebeus nunca mudam... Sempre sonhando alto demais para suas calças.",
  ui_story_5036_50360202_184_dialog_content = "Você realmente não acha que pode cantar só porque tem boca, certo? Aliás, parece que você está usando enfeites de bolo.",
  ui_story_5036_50360202_185_dialog_content = "Que tipo de termo vulgar é \"ídolo\", afinal?",
  ui_story_5036_50360202_186_dialog_content = "Uau, é por isso que as pessoas não devem se isolar em pequenas ilhas flutuantes como vocês fazem em Lumopolis.",
  ui_story_5036_50360202_187_dialog_content = "Você não deve falar quando nem sabe o que é um ídolo.",
  ui_story_5036_50360202_188_dialog_content = "Você está me chamando de ignorante?",
  ui_story_5036_50360202_189_dialog_content = "A verdade sempre dói.",
  ui_story_5036_50360202_190_dialog_content = "Siobhan, vamos educar nosso juiz aqui sobre o conceito de ídolo, certo?",
  ui_story_5036_50360202_191_dialog_content = "Sim, oficial Gronru.",
  ui_story_5036_50360202_192_dialog_content = "Os ídolos são uma ocupação recém-emergida em Umbraton e no Deserto de Rediesel.",
  ui_story_5036_50360202_193_dialog_content = "Eles se envolvem principalmente em atividades relacionadas ao entretenimento, como canto, dança e hospedagem.",
  ui_story_5036_50360202_194_dialog_content = "Em comparação com cantores, dançarinos e atores tradicionais, eles estão muito mais dispostos a estar mais próximos de seus fãs.",
  ui_story_5036_50360202_195_dialog_content = "Eles conquistam apoio com seu charme individual e, em troca, espalham positividade para seus fãs.",
  ui_story_5036_50360202_196_dialog_content = "Sim, essa é a essência disso.",
  ui_story_5036_50360202_197_dialog_content = "My Goldie é multitalentosa, embora nosso foco atual seja sua carreira de cantora.",
  ui_story_5036_50360202_198_dialog_content = "Entendo...",
  ui_story_5036_50360202_199_dialog_content = "Uh, quero dizer, não estou interessado em assuntos comuns!",
  ui_story_5036_50360202_200_dialog_content = "Cheguei onde estou hoje graças aos meus fãs, os Cachinhos Dourados.",
  ui_story_5036_50360202_201_dialog_content = "Eu quero que eles me vejam atuando para eles no maior palco possível!",
  ui_story_5036_50360202_202_dialog_content = "Heh, eu não me importo com shows...",
  ui_story_5036_50360202_203_dialog_content = "Mas não é demais hospedar um no Wandering Colossus?",
  ui_story_5036_50360202_204_dialog_content = "Querida, você mesma não disse que a tela e os sistemas de som estavam funcionando perfeitamente?",
  ui_story_5036_50360202_205_dialog_content = "Certamente alguém tão apaixonado por Colossi quanto você adoraria testemunhar esses sistemas funcionando pessoalmente, não é?",
  ui_story_5036_50360202_206_dialog_content = "Bom...",
  ui_story_5036_50360202_207_dialog_content = "Imagine, uma enorme multidão se reunindo na margem do Gold River. Eles só têm que olhar para cima...",
  ui_story_5036_50360202_208_dialog_content = "para ver o concerto em uma tela enorme.",
  ui_story_5036_50360202_209_dialog_content = "As pessoas que viajam em aeronaves podem até assistir ao show no palco.",
  ui_story_5036_50360202_210_dialog_content = "Parece que seria um grande festival para todo o continente...",
  ui_story_5036_50360202_211_dialog_content = "Sim, um grande festival para o Astra! Eu gosto de como você coloca isso, PlayerName!",
  ui_story_5036_50360202_212_dialog_content = "Fiquei surpreso ao ouvir você chamar esse Colosso de Eulogoz.",
  ui_story_5036_50360202_213_dialog_content = "Talvez tenha sido construído para transmitir músicas.",
  ui_story_5036_50360202_214_dialog_content = "Se realmente deve ser destruído...",
  ui_story_5036_50360202_215_dialog_content = "Eu adoraria que ele entregasse uma música final antes disso!",
  ui_story_5036_50360202_216_dialog_content = "!!!",
  ui_story_5036_50360202_217_dialog_content = "Que pena.",
  ui_story_5036_50360202_218_dialog_content = "O Colossus está voando por uma região desabitada amanhã, que é o melhor local para derrubá-lo.",
  ui_story_5036_50360202_219_dialog_content = "Isso não vai deixar você com tempo para um show.",
  ui_story_5036_50360202_220_dialog_content = "Não vamos apressar as coisas, pessoal.",
  ui_story_5036_50360202_221_dialog_content = "Depois de sobrevoar Umbraton, se continuar ao longo do Rio Dourado...",
  ui_story_5036_50360202_222_dialog_content = "atingirá uma região desabitada ainda maior.",
  ui_story_5036_50360202_223_dialog_content = "Você quer dizer... o mar?",
  ui_story_5036_50360202_224_dialog_content = "Abater o Colosso sobre o mar?",
  ui_story_5036_50360202_225_dialog_content = "Acho que é uma boa ideia, Oficial Gronru.",
  ui_story_5036_50360202_226_dialog_content = "Um concerto de sucesso demonstraria seu valor e o salvaria da destruição.",
  ui_story_5036_50360202_227_dialog_content = "Isso também nos dará mais tempo para tentar consertar o Colossus.",
  ui_story_5036_50360202_228_dialog_content = "Se o show for um fracasso, ainda podemos derrubá-lo assim que estiver no oceano.",
  ui_story_5036_50360202_229_dialog_content = "É a forma mais segura de fazer isso, pois não faria mal a ninguém em terra.",
  ui_story_5036_50360202_230_dialog_content = "Ah, eu te imploro!",
  ui_story_5036_50360202_231_dialog_content = "Por favor, adie a destruição deste Colosso...",
  ui_story_5036_50360202_232_dialog_content = "Permita-nos construir um palco e receber um concerto inédito!",
  ui_story_5036_50360301_1_dialog_content = "<color=#e8d9bb>Seis dias para o concerto</color>",
  ui_story_5036_50360301_2_dialog_content = "O lado esquerdo está desligado. Mova-o um pouco para cima.",
  ui_story_5036_50360301_3_dialog_content = "Assim?",
  ui_story_5036_50360301_4_dialog_content = "Agora o lado direito está desligado.",
  ui_story_5036_50360301_5_dialog_content = "Mm, acho que o pôster parece bem torto.",
  ui_story_5036_50360301_6_dialog_content = "O que você acha, PlayerName?",
  ui_story_5036_50360301_7_dialog_content = "Não sou especialista, por que não perguntamos a Goldie?",
  ui_story_5036_50360301_8_dialog_content = "Au!",
  ui_story_5036_50360301_9_dialog_content = "Ahh! Uma gracinha! Eu quero acariciar o Marshmallow toda vez que o vejo!",
  ui_story_5036_50360301_10_dialog_content = "Marshmallow também adora ser animal de estimação!",
  ui_story_5036_50360301_11_dialog_content = "Au, au!",
  ui_story_5036_50360301_12_dialog_content = "Tudo bem, Marshmallow, depois jogo com você.",
  ui_story_5036_50360301_13_dialog_content = "Então nos dê um tempo para conversar, ok?",
  ui_story_5036_50360301_14_dialog_content = "Au!",
  ui_story_5036_50360301_15_dialog_content = "O que vocês queriam me perguntar com tanta urgência?",
  ui_story_5036_50360301_16_dialog_content = "Estamos ocupados colocando cartazes, mas não temos certeza de qual é a melhor maneira de fazer isso...",
  ui_story_5036_50360301_17_dialog_content = "O que? Vocês não precisam fazer tudo isso.",
  ui_story_5036_50360301_18_dialog_content = "Sim nós fazemos.",
  ui_story_5036_50360301_19_dialog_content = "Se não fosse pela sua ideia de concerto, o Eulogoz provavelmente já estaria destruído.",
  ui_story_5036_50360301_20_dialog_content = "Não podemos lidar com nenhum equipamento, então os pôsteres são tudo o que podemos fazer.",
  ui_story_5036_50360301_21_dialog_content = "Oh, vocês já me ajudaram mais do que imaginam.",
  ui_story_5036_50360301_22_dialog_content = "Sem você, acho que Illumina e Lumopolis nunca teriam concordado com isso.",
  ui_story_5036_50360301_23_dialog_content = "O Grande Marechal me autorizou a tomar decisões sobre o Colosso Errante...",
  ui_story_5036_50360301_24_dialog_content = "mas ainda preciso de mais alguns dias para investigar antes de poder lhe dar uma resposta.",
  ui_story_5036_50360301_25_dialog_content = "O que mais há para investigar? Isso é uma farsa!",
  ui_story_5036_50360301_26_dialog_content = "Por que os nobres de Lumopolis se importariam com os ídolos dos plebeus?",
  ui_story_5036_50360301_27_dialog_content = "Eu sei que apenas eu sozinho não é suficiente, então este não será meu próprio show solo.",
  ui_story_5036_50360301_28_dialog_content = "Pretendo convidar estrelas de todos os lugares para se juntarem a mim neste concerto no céu!",
  ui_story_5036_50360301_29_dialog_content = "Talvez em Lumopolis e Illumina você tenha uma ideia diferente do que são ídolos,",
  ui_story_5036_50360301_30_dialog_content = "mas tudo bem. Você pode enviar seus ídolos para participar também, sejam eles quem forem!",
  ui_story_5036_50360301_31_dialog_content = "Eu apoio isso!",
  ui_story_5036_50360301_32_dialog_content = "Hã?",
  ui_story_5036_50360301_33_dialog_content = "Apoio Goldie a fazer um concerto no Colossus!",
  ui_story_5036_50360301_34_dialog_content = "Ela está certa. O propósito de Eulogoz pode ter sido transmitir música.",
  ui_story_5036_50360301_35_dialog_content = "Como celestita, quero vê-lo cumprir seu propósito.",
  ui_story_5036_50360301_36_dialog_content = "E eu quero ver pessoas de diferentes lugares deixando seus preconceitos de lado e se divertindo juntos com a música!",
  ui_story_5036_50360301_37_dialog_content = "Talvez Eulogoz tenha voltado para nos ajudar a entender",
  ui_story_5036_50360301_38_dialog_content = "que somos capazes de realizar algo juntos, independente de onde viemos ou quem somos!",
  ui_story_5036_50360301_39_dialog_content = "Por favor, dê a Goldie e Eugoloz o tempo que eles precisam.",
  ui_story_5036_50360301_40_dialog_content = "E eu também. Pode ser...",
  ui_story_5036_50360301_41_dialog_content = "Talvez eu encontre uma maneira de salvar Eulogoz!",
  ui_story_5036_50360301_42_dialog_content = "Pensando agora, seu discurso foi tão épico, PlayerName!",
  ui_story_5036_50360301_43_dialog_content = "Isso me emocionou tanto que quase chorei.",
  ui_story_5036_50360301_44_dialog_content = "Não é de admirar que Sheol sempre diga que os Lovegators superam os Cachinhos Dourados.",
  ui_story_5036_50360301_45_dialog_content = "Não, eu não sou tudo isso... Acho que sou facilmente excitável e tenho uma tendência a começar a divagar sem pensar.",
  ui_story_5036_50360301_46_dialog_content = "Pessoalmente, achei Lady Sheol a mais legal.",
  ui_story_5036_50360301_47_dialog_content = "Ela praticamente brilhou quando sorriu e disse que pagaria a conta de todos que trabalharem no projeto!",
  ui_story_5036_50360301_48_dialog_content = "Empresários não fazem negócios perdidos.",
  ui_story_5036_50360301_49_dialog_content = "Ela tinha certeza de que o show seria lucrativo quando decidiu investir nele.",
  ui_story_5036_50360301_50_dialog_content = "Mas como ela vai ganhar dinheiro quando todo mundo só tem que ficar perto do Gold River e ouvi-lo de graça?",
  ui_story_5036_50360301_51_dialog_content = "Pena que ela já está de volta a Umbraton para promover o show.",
  ui_story_5036_50360301_52_dialog_content = "Eu tenho que perguntar a ela como ela está lucrando!",
  ui_story_5036_50360301_53_dialog_content = "Vice, às vezes acho que você deveria ter nascido em Umbraton.",
  ui_story_5036_50360301_54_dialog_content = "Você está falando muito mais sério sobre Nightium do que nunca durante seus anos como estudante de intercâmbio em Lumopolis.",
  ui_story_5036_50360301_55_dialog_content = "Eu sou? Bem, culpe um certo alguém por isso.",
  ui_story_5036_50360301_56_dialog_content = "Ei, por que vocês estão olhando para mim?",
  ui_story_5036_50360301_57_dialog_content = "Heh, não podemos esperar entender as manobras de negócios do Sheol.",
  ui_story_5036_50360301_58_dialog_content = "Tudo o que temos a fazer é fazer nosso próprio trabalho!",
  ui_story_5036_50360301_59_dialog_content = "E agora, meu trabalho é me preparar para o show!",
  ui_story_5036_50360301_60_dialog_content = "...",
  ui_story_5036_50360301_61_dialog_content = "Algo em sua mente, PlayerName?",
  ui_story_5036_50360301_62_dialog_content = "Ah, eu só estava pensando, enquanto a tela e os alto-falantes do Eulogoz estão bons...",
  ui_story_5036_50360301_63_dialog_content = "Isso é realmente suficiente para que todos no terreno ouçam a música?",
  ui_story_5036_50360301_64_dialog_content = "Você tem tão pouca fé na tecnologia Caelestite?",
  ui_story_5036_50360301_65_dialog_content = "Tenho fé nisso, claro! É só isso...",
  ui_story_5036_50360301_66_dialog_content = "Olha, eu sei com o que todos estão preocupados. Confie em mim, eu quero que o show corra bem mais do que ninguém.",
  ui_story_5036_50360301_67_dialog_content = "Perguntei a Siobhan sobre os problemas do equipamento e aprendi a controlar o volume.",
  ui_story_5036_50360301_68_dialog_content = "Com certeza eles vão conseguir ouvir minha voz no chão através do equipamento!",
  ui_story_5036_50360301_69_dialog_content = "Então você já cuidou disso? Eu não deveria ter esperado menos de um ídolo profissional.",
  ui_story_5036_50360301_70_dialog_content = "A propósito, você não está procurando uma maneira de salvar Eulogoz?",
  ui_story_5036_50360301_71_dialog_content = "Alguma notícia nessa frente?",
  ui_story_5036_50360301_72_dialog_content = "Nada mesmo.",
  ui_story_5036_50360301_73_dialog_content = "Eu realmente não tinha ideia no que estava me metendo.",
  ui_story_5036_50360301_74_dialog_content = "Por que eu pensei que poderia inventar algo quando nem mesmo o oficial de tecnologia da Illumina poderia?",
  ui_story_5036_50360301_75_dialog_content = "Não seja tão negativo, PlayerName!",
  ui_story_5036_50360301_76_dialog_content = "Você quer que eu consulte o meu <color=#FFB400>bala da sorte</color> para voce?",
  ui_story_5036_50360301_77_dialog_content = "Seu o quê?",
  ui_story_5036_50360301_78_dialog_content = "Bala da sorte, vontade PlayerName encontrar uma maneira de salvar Eulogoz?",
  ui_story_5036_50360301_79_dialog_content = "Nesse caso, aterrisse de cabeça!",
  ui_story_5036_50360301_80_dialog_content = "PlayerName, venha jogar a bala no ar!",
  ui_story_5036_50360301_81_dialog_content = "Jogar? Assim?",
  ui_story_5036_50360301_82_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5036_50360301_83_dialog_content = "Lá vai...",
  ui_story_5036_50360301_84_dialog_content = "<color=#e8d9bb>Clink!</color>",
  ui_story_5036_50360301_85_dialog_content = "Perfeito! Olha, caiu de cabeça!",
  ui_story_5036_50360301_86_dialog_content = "Minha bala da sorte é certeza que você encontrará um caminho!",
  ui_story_5036_50360301_87_dialog_content = "Sério?",
  ui_story_5036_50360301_88_dialog_content = "Quando me deparo com problemas, a bala sempre tem uma resposta para mim.",
  ui_story_5036_50360301_89_dialog_content = "Acho que vai te trazer boa sorte também!",
  ui_story_5036_50360301_90_dialog_content = "... Tudo bem. Eu não vou desistir!",
  ui_story_5036_50360301_91_dialog_content = "Você sempre me enche de motivação, Goldie.",
  ui_story_5036_50360301_92_dialog_content = "Acho que vou ser um Cachinho Dourado!",
  ui_story_5036_50360301_93_dialog_content = "Haha, você deveria!",
  ui_story_5036_50360301_94_dialog_content = "Já sou um Lovegator obstinado há muito tempo, só para você saber.",
  ui_story_5036_50360301_95_dialog_content = "O quê?",
  ui_story_5036_50360301_96_dialog_content = "<color=#e8d9bb>Clique!</color>",
  ui_story_5036_50360301_97_dialog_content = "Hã?",
  ui_story_5036_50360301_98_dialog_content = "P-Perdoe-me!",
  ui_story_5036_50360301_99_dialog_content = "Fiquei emocionado com sua nova camaradagem e não pude deixar de tirar uma foto de grupo para salvar a memória...",
  ui_story_5036_50360301_100_dialog_content = "Uau, obrigado Brandy!",
  ui_story_5036_50360301_101_dialog_content = "(Goldie... disse meu nome...?)",
  ui_story_5036_50360301_102_dialog_content = "A imprensa em Umbraton com certeza sabe o que está fazendo se puder enviar você para cobrir o show tão rápido.",
  ui_story_5036_50360301_103_dialog_content = "Na verdade, eu vim com PlayerName.",
  ui_story_5036_50360301_104_dialog_content = "Sim, Brandy está fazendo um artigo sobre mim.",
  ui_story_5036_50360301_105_dialog_content = "Ah, então você estava aqui por ele?",
  ui_story_5036_50360301_106_dialog_content = "Acho que estou com um pouco de ciúme.",
  ui_story_5036_50360301_107_dialog_content = "Ué...",
  ui_story_5036_50360301_108_dialog_content = "Estou brincando!",
  ui_story_5036_50360301_109_dialog_content = "Achei que você não se lembraria de mim.",
  ui_story_5036_50360301_110_dialog_content = "Claro que eu faço. Guardei um recorte daquele artigo que você fez sobre mim!",
  ui_story_5036_50360301_111_dialog_content = "Mas isso foi tão mal escrito que o editor até me repreendeu por isso.",
  ui_story_5036_50360301_112_dialog_content = "Não quero ouvir você dizer isso sobre você, Brandy.",
  ui_story_5036_50360301_113_dialog_content = "Você é mais diligente do que ninguém quando se trata de entrevistas!",
  ui_story_5036_50360301_114_dialog_content = "Você tem que acreditar em si mesmo e em seu julgamento, não importa o que os outros possam dizer.",
  ui_story_5036_50360301_115_dialog_content = "Acredite em mim...",
  ui_story_5036_50360301_116_dialog_content = "Você sempre espalha tanta positividade que eu ganho energia para continuar trabalhando.",
  ui_story_5036_50360301_117_dialog_content = "Mas ouvi os repórteres seniores dizerem que você está planejando seu show no Star Theatre há muito tempo.",
  ui_story_5036_50360301_118_dialog_content = "Isso não será cancelado se você estiver fazendo um show no Wandering Colossus?",
  ui_story_5036_50360301_119_dialog_content = "Sobre isso...",
  ui_story_5036_50360301_120_dialog_content = "Simplesmente não posso perder um local tão grandioso quanto o Eulogoz.",
  ui_story_5036_50360301_121_dialog_content = "Haverá muito mais oportunidades para mim nos estágios de Umbraton no futuro.",
  ui_story_5036_50360301_122_dialog_content = "Entendi.",
  ui_story_5036_50360301_123_dialog_content = "Haha! Tudo funcionou perfeitamente!",
  ui_story_5036_50360301_124_dialog_content = "A bala da sorte estava certa sobre eu conseguir um ótimo repórter!",
  ui_story_5036_50360301_125_dialog_content = "O quê?",
  ui_story_5036_50360301_126_dialog_content = "Sheol me pediu para conseguir um repórter para cobrir o show, mas eu não tinha ideia de onde encontrar um.",
  ui_story_5036_50360301_127_dialog_content = "Se possível, adoraria que você cobrisse este projeto até o fim, Brandy!",
  ui_story_5036_50360301_128_dialog_content = "Ou seja, se não for pedir muito...",
  ui_story_5036_50360301_129_dialog_content = "Você pode pensar sobre isso antes de me dar uma resposta.",
  ui_story_5036_50360301_130_dialog_content = "(Esse é o tipo e atencioso Goldie que eu conheço!)",
  ui_story_5036_50360301_131_dialog_content = "(Aquela notícia sobre ela ter uma veia má provavelmente foi inventada.)",
  ui_story_5036_50360301_132_dialog_content = "Não vamos ficar parados.",
  ui_story_5036_50360301_133_dialog_content = "Ainda temos cartazes para colocar!",
  ui_story_5036_50360301_134_dialog_content = "Eles com certeza se movem rápido.",
  ui_story_5036_50360301_135_dialog_content = "O corredor aqui também está coberto de pôsteres coloridos.",
  ui_story_5036_50360301_136_dialog_content = "Eu simplesmente não entendo o negócio com ídolos.",
  ui_story_5036_50360301_137_dialog_content = "Eles sobem no palco, sorriem, agem de forma fofa e recebem aplausos e aplausos.",
  ui_story_5036_50360301_138_dialog_content = "Enquanto isso, trabalhamos duro aqui e não recebemos nenhum elogio.",
  ui_story_5036_50360301_139_dialog_content = "Certo? Eu nunca ouvi falar de ídolos em trajes tão berrantes e estranhos antes.",
  ui_story_5036_50360301_140_dialog_content = "Cantar e dançar só podem entreter, não salvar as pessoas!",
  ui_story_5036_50360301_141_dialog_content = "Nunca pensei que um dia ficaria frente a frente com alguém de Lumopolis.",
  ui_story_5036_50360301_142_dialog_content = "Bem, nós somos os azarados.",
  ui_story_5036_50360301_143_dialog_content = "Eles farão um show e nos deixarão para proteger o perímetro e limpar os Eclipsites!",
  ui_story_5036_50360301_144_dialog_content = "Não sei por que, mas nos últimos dias tenho me sentido cada vez mais cansada.",
  ui_story_5036_50360301_145_dialog_content = "Pode falar.",
  ui_story_5036_50360301_146_dialog_content = "Aham…",
  ui_story_5036_50360301_147_dialog_content = "!!!",
  ui_story_5036_50360301_148_dialog_content = "Saudações, Tenente Vice!",
  ui_story_5036_50360301_149_dialog_content = "Bom dia, Lady Carleen!",
  ui_story_5036_50360301_150_dialog_content = "À vontade. Você está fazendo um ótimo trabalho.",
  ui_story_5036_50360301_151_dialog_content = "Uh, provavelmente dissemos muitas coisas estúpidas, então, por favor, perdoe-nos!",
  ui_story_5036_50360301_152_dialog_content = "Perdoe-nos, Tenente Vice!",
  ui_story_5036_50360301_153_dialog_content = "Zombar de civis não é o que fazemos como cavaleiros.",
  ui_story_5036_50360301_154_dialog_content = "Você deve saber o que deve fazer agora.",
  ui_story_5036_50360301_155_dialog_content = "Minhas desculpas, senhorita Goldie!",
  ui_story_5036_50360301_156_dialog_content = "E você também.",
  ui_story_5036_50360301_157_dialog_content = "D-Desculpe, senhorita Goldie!",
  ui_story_5036_50360301_158_dialog_content = "Não fui cavalheiresco em meu discurso. Por favor, me castigue com esta espada!",
  ui_story_5036_50360301_159_dialog_content = "Tudo bem. Eu vou punir vocês dois...",
  ui_story_5036_50360301_160_dialog_content = "mandando você para a cama cedo. Tenha bons sonhos!",
  ui_story_5036_50360301_161_dialog_content = "Hã?",
  ui_story_5036_50360301_162_dialog_content = "Vamos lá, quem não reclama quando está no trabalho?",
  ui_story_5036_50360301_163_dialog_content = "E, sinceramente, sou a razão do aumento da carga de trabalho de todos.",
  ui_story_5036_50360301_164_dialog_content = "Eu deveria estar me desculpando!",
  ui_story_5036_50360301_165_dialog_content = "Pedi ao Sheol para contratar mercenários de Umbraton para ajudar a arcar com o fardo.",
  ui_story_5036_50360301_166_dialog_content = "Você terá mais tempo de inatividade para si mesmo!",
  ui_story_5036_50360301_167_dialog_content = "Bom...",
  ui_story_5036_50360301_168_dialog_content = "Há bebidas energéticas no final do corredor. Eu acho que vocês dois não tiveram a chance de pegar alguns?",
  ui_story_5036_50360301_169_dialog_content = "Vá experimentar!",
  ui_story_5036_50360301_170_dialog_content = "Garanto que você vai se sentir revigorado depois de tomar um pouco!",
  ui_story_5036_50360301_171_dialog_content = "...",
  ui_story_5036_50360301_172_dialog_content = "Por que você ainda esta aqui? Você a ouviu.",
  ui_story_5036_50360301_173_dialog_content = "Sua Alteza...?",
  ui_story_5036_50360301_174_dialog_content = "A senhorita Goldie distribuiu sua punição, então você pode ir embora.",
  ui_story_5036_50360301_175_dialog_content = "Obrigado, Alteza! Obrigado, senhorita Goldie!",
  ui_story_5036_50360301_176_dialog_content = "Obrigado, Tenente Vice! Obrigado, senhorita Goldie!",
  ui_story_5036_50360301_177_dialog_content = "Há muito a considerar ao fazer um show, de fato.",
  ui_story_5036_50360301_178_dialog_content = "Não acredito que esqueci de levar os soldados em consideração...",
  ui_story_5036_50360301_179_dialog_content = "Se achar necessário, Goldie, posso pedir mais Lumo Knights.",
  ui_story_5036_50360301_180_dialog_content = "Tudo bem, eu não deveria incomodá-lo mais do que já fiz!",
  ui_story_5036_50360301_181_dialog_content = "Já pedi aos Mercenários da Chama Branca para me ajudar a entregar suprimentos e construir o palco.",
  ui_story_5036_50360301_182_dialog_content = "Vou adicionar à agenda deles quando chegarem aqui!",
  ui_story_5036_50360301_183_dialog_content = "Não é barato contratar as Chamas Brancas para coisas como esta.",
  ui_story_5036_50360301_184_dialog_content = "O Sheol será responsável pelas despesas?",
  ui_story_5036_50360301_185_dialog_content = "...",
  ui_story_5036_50360301_186_dialog_content = "Goldie?",
  ui_story_5036_50360301_187_dialog_content = "Hã?",
  ui_story_5036_50360301_188_dialog_content = "Oh, uh... sim, Sheol é muito engenhoso. Não deve ser um problema.",
  ui_story_5036_50360301_189_dialog_content = "Você estava preocupado com alguma coisa, Goldie?",
  ui_story_5036_50360301_190_dialog_content = "Na verdade não...",
  ui_story_5036_50360301_191_dialog_content = "É que as Chamas Brancas já deveriam estar aqui, mas não estão...",
  ui_story_5036_50360301_192_dialog_content = "<color=#e8d9bb>*Passos caóticos*</color>",
  ui_story_5036_50360301_193_dialog_content = "Eu ouço passos... Parece um grupo de pessoas vindo para cá.",
  ui_story_5036_50360301_194_dialog_content = "Falando no diabo... Devem ser eles.",
  ui_story_5036_50360301_195_dialog_content = "Que coincidência!",
  ui_story_5036_50360301_196_dialog_content = "Grrrrr!",
  ui_story_5036_50360301_197_dialog_content = "O que? Oh não!",
  ui_story_5036_50360301_198_dialog_content = "Estes não são mercenários!",
  ui_story_5036_50360301_199_dialog_content = "Eu não contratei Eclipsites!",
  ui_story_5036_50360302_1_dialog_content = "Cuidado atrás de você, Goldie!",
  ui_story_5036_50360302_2_dialog_content = "O quê...?",
  ui_story_5036_50360302_3_dialog_content = "Ah!",
  ui_story_5036_50360302_4_dialog_content = "Vá embora!",
  ui_story_5036_50360302_5_dialog_content = "Os Mercenários da Chama Branca estão aqui!",
  ui_story_5036_50360302_6_dialog_content = "Você está bem, senhorita Goldie?",
  ui_story_5036_50360302_7_dialog_content = "Estou bem, graças ao seu timing perfeito.",
  ui_story_5036_50360302_8_dialog_content = "Eu não diria que é perfeito...",
  ui_story_5036_50360302_9_dialog_content = "Conseguir os suprimentos para o palco custou mais tempo do que o esperado, então sinto muito por termos chegado aqui agora.",
  ui_story_5036_50360302_10_dialog_content = "Embora eu nunca tenha pensado que haveria Eclipsites no Wandering Colossus também.",
  ui_story_5036_50360302_11_dialog_content = "Bem, eu descobri isso depois que eu mesmo comecei.",
  ui_story_5036_50360302_12_dialog_content = "Mas os soldados de Illumina e Lumopolis confinaram a maioria dos Eclipsites em uma área segura na seção traseira.",
  ui_story_5036_50360302_13_dialog_content = "Ainda há alguns retardatários vagando por aí, mas como você viu...",
  ui_story_5036_50360302_14_dialog_content = "Eles não são formidáveis.",
  ui_story_5036_50360302_15_dialog_content = "Os soldados intensificaram seus esforços de limpeza.",
  ui_story_5036_50360302_16_dialog_content = "Agora com sua ajuda...",
  ui_story_5036_50360302_17_dialog_content = "Tenho certeza de que esses retardatários e os que estão na retaguarda também serão tratados.",
  ui_story_5036_50360302_18_dialog_content = "Faremos o possível para cumprir as tarefas de Lady Sheol.",
  ui_story_5036_50360302_19_dialog_content = "Você pode contar conosco!",
  ui_story_5036_50360302_20_dialog_content = "Obrigado a todos!",
  ui_story_5036_50360302_21_dialog_content = "Sem suor. Oh, nós ouvimos em Umbraton que",
  ui_story_5036_50360302_22_dialog_content = "uma tonelada de pessoas já se inscreveu para o show!",
  ui_story_5036_50360302_23_dialog_content = "Notícias com certeza viajam rápido!",
  ui_story_5036_50360302_24_dialog_content = "Uau, as pessoas estão muito mais animadas com isso do que eu imaginava.",
  ui_story_5036_50360302_25_dialog_content = "Antes do show começar oficialmente, também estamos realizando um <color=#FFB400>audição de ídolo</color>.",
  ui_story_5036_50360302_26_dialog_content = "Vamos escolher ídolos com forte presença de palco.",
  ui_story_5036_50360302_27_dialog_content = "Uma audição de ídolo? Isso soa como um evento emocionante!",
  ui_story_5036_50360302_28_dialog_content = "A primeira rodada é amanhã, então vamos precisar de vários de vocês para controlar a multidão.",
  ui_story_5036_50360302_29_dialog_content = "Sem problemas!",
  ui_story_5036_50360302_30_dialog_content = "Vamos nos ocupar, pessoal!",
  ui_story_5036_50360302_31_dialog_content = "Sim!",
  ui_story_5036_50360302_32_dialog_content = "Você é um grande motivador.",
  ui_story_5036_50360302_33_dialog_content = "Uma audição de ídolo parece muito trabalhosa, no entanto.",
  ui_story_5036_50360302_34_dialog_content = "É algo que sempre quis fazer. Nem todos os dias tenho a chance de realizar um dos meus sonhos.",
  ui_story_5036_50360302_35_dialog_content = "Não parece trabalho para mim!",
  ui_story_5036_50360302_36_dialog_content = "Você sempre quis fazer uma audição?",
  ui_story_5036_50360302_37_dialog_content = "Isso mesmo. Eu amo o palco e o público abaixo dele.",
  ui_story_5036_50360302_38_dialog_content = "Eu quero espalhar minha paixão para os outros!",
  ui_story_5036_50360302_39_dialog_content = "Eu quero que haja mais ídolos para emocionar e inspirar o público.",
  ui_story_5036_50360302_40_dialog_content = "Eu tenho que apoiar todos aqueles que aspiram ser ídolos enquanto eu tenho a capacidade de fazê-lo.",
  ui_story_5036_50360302_41_dialog_content = "Você realmente ama sua carreira.",
  ui_story_5036_50360302_42_dialog_content = "Falando nisso...",
  ui_story_5036_50360302_43_dialog_content = "Você estaria interessado em <color=#FFB400>integrando a comissão de seleção</color>?",
  ui_story_5036_50360302_44_dialog_content = "Quem eu?",
  ui_story_5036_50360302_45_dialog_content = "Sim! Estar no comitê é realmente muito fácil.",
  ui_story_5036_50360302_46_dialog_content = "Você só precisa assistir às apresentações dos competidores e decidir quem deve subir no palco com base em suas preferências.",
  ui_story_5036_50360302_47_dialog_content = "Eu estava guardando a posição para Sheol, mas ela parece muito ocupada fazendo todas as coisas de promoção.",
  ui_story_5036_50360302_48_dialog_content = "Depois de refletir sobre isso, decidi que você é o mais adequado para a tarefa.",
  ui_story_5036_50360302_49_dialog_content = "Mas não tenho certeza se posso lidar com isso.",
  ui_story_5036_50360302_50_dialog_content = "Ei! Carleen, Vice... Vocês dois também não gostam de cantar?",
  ui_story_5036_50360302_51_dialog_content = "Interessado em fazer parte da comissão?",
  ui_story_5036_50360302_52_dialog_content = "Hum...",
  ui_story_5036_50360302_53_dialog_content = "Bom...",
  ui_story_5036_50360302_54_dialog_content = "Ah, você não sabia?",
  ui_story_5036_50360302_55_dialog_content = "Vice e Carleen se inscreveram para a audição!",
  ui_story_5036_50360302_56_dialog_content = "Eles o quê?!",
  ui_story_5036_50360302_57_dialog_content = "Por que eu não estava ciente disso?",
  ui_story_5036_50360302_58_dialog_content = "Você não pode nos culpar por isso. Nós contamos a você.",
  ui_story_5036_50360302_59_dialog_content = "Mas você estava ouvindo alguma coisa na hora e não prestou atenção em nós.",
  ui_story_5036_50360302_60_dialog_content = "Vice e eu discutimos isso. Se o concerto for um sucesso, isso deve bastar para provar o valor de Eulogoz.",
  ui_story_5036_50360302_61_dialog_content = "Então, podemos persuadir os superiores da Illumina e meu pai a destruí-lo.",
  ui_story_5036_50360302_62_dialog_content = "Mesmo que não encontremos uma maneira de manter o Colosso sob controle...",
  ui_story_5036_50360302_63_dialog_content = "Pelo menos Eulogoz ainda poderia continuar vagando como agora.",
  ui_story_5036_50360302_64_dialog_content = "Talvez daqui a cem anos, volte aos céus de Astra!",
  ui_story_5036_50360302_65_dialog_content = "Vocês dois realmente pensaram muito à frente.",
  ui_story_5036_50360302_66_dialog_content = "Na verdade, quase inscrevemos você também, mas então pensamos...",
  ui_story_5036_50360302_67_dialog_content = "Não, não deveríamos.",
  ui_story_5036_50360302_68_dialog_content = "Eu definitivamente não tenho confiança em minhas habilidades de desempenho, mas você não precisa ser tão direto sobre isso!",
  ui_story_5036_50360302_69_dialog_content = "Você não precisa ser bom em artes cênicas para fazer parte do comitê de seleção.",
  ui_story_5036_50360302_70_dialog_content = "Tudo que você precisa é um olho para o talento para se qualificar!",
  ui_story_5036_50360302_71_dialog_content = "Hum...",
  ui_story_5036_50360302_72_dialog_content = "Suspiro, acho que esta é a única opção.",
  ui_story_5036_50360302_73_dialog_content = "É difícil de acreditar...",
  ui_story_5036_50360302_74_dialog_content = "que eu estaria fazendo algo assim na minha idade.",
  ui_story_5036_50360302_75_dialog_content = "*Rugido*",
  ui_story_5036_50360302_76_dialog_content = "Rápido!",
  ui_story_5036_50360302_77_dialog_content = "<size=35>Rugido?</size>",
  ui_story_5036_50360302_78_dialog_content = "É tarde, pequeno Drako.",
  ui_story_5036_50360302_79_dialog_content = "Você vai assustar as pessoas falando tão alto.",
  ui_story_5036_50360302_80_dialog_content = "Eu não quero ficar como um polegar dolorido imediatamente.",
  ui_story_5036_50360302_81_dialog_content = "*funga*",
  ui_story_5036_50360302_82_dialog_content = "Ok, volte logo para Fia agora.",
  ui_story_5036_50360302_83_dialog_content = "Mas lembre-se...",
  ui_story_5036_50360302_84_dialog_content = "Não revele meu paradeiro a ela.",
  ui_story_5036_50360401_1_dialog_content = "Sou eu, editor-chefe!",
  ui_story_5036_50360401_2_dialog_content = "Como vou saber quem você é se não me diz seu nome?",
  ui_story_5036_50360401_3_dialog_content = "... É Brandy.",
  ui_story_5036_50360401_4_dialog_content = "Ah, eu me lembro agora.",
  ui_story_5036_50360401_5_dialog_content = "O estagiário que só escreve artigos chatos.",
  ui_story_5036_50360401_6_dialog_content = "Achei que você já tinha desistido.",
  ui_story_5036_50360401_7_dialog_content = "Você disse que me daria uma última chance.",
  ui_story_5036_50360401_8_dialog_content = "Ah, parece que me lembro de algo assim... Então, você tem uma boa notícia para mim?",
  ui_story_5036_50360401_9_dialog_content = "Sim! Adivinha?",
  ui_story_5036_50360401_10_dialog_content = "Estou no Eulogoz agora, o Wandering Colossus de que todos estão falando!",
  ui_story_5036_50360401_11_dialog_content = "E?",
  ui_story_5036_50360401_12_dialog_content = "Quando ele sobrevoar Umbraton, haverá um grande show a bordo!",
  ui_story_5036_50360401_13_dialog_content = "Eu tenho uma agenda apertada, então me diga algo que eu não saiba.",
  ui_story_5036_50360401_14_dialog_content = "Óh, e...",
  ui_story_5036_50360401_15_dialog_content = "Fui escolhido para ser o repórter oficial do show e também serei o anfitrião das audições dos ídolos!",
  ui_story_5036_50360401_16_dialog_content = "Você tem orgulho de reportar comunicados de imprensa oficiais?",
  ui_story_5036_50360401_17_dialog_content = "Parece que você ainda não entendeu.",
  ui_story_5036_50360401_18_dialog_content = "O que eu quero é um furo de reportagem que seja quente o suficiente para atrair visualizações!",
  ui_story_5036_50360401_19_dialog_content = "O quê?",
  ui_story_5036_50360401_20_dialog_content = "... Furo interno?",
  ui_story_5036_50360401_21_dialog_content = "<color=#e8d9bb>Cinco dias para o concerto</color>",
  ui_story_5036_50360401_22_dialog_content = "Desculpe deixá-los esperando, queridos competidores!",
  ui_story_5036_50360401_23_dialog_content = "Bem-vindo à audição para o <color=#FFB400>Concerto no céu \"O momento em que as estrelas brilham mais forte\"</color>.",
  ui_story_5036_50360401_24_dialog_content = "Como você se sentiu embarcando no Colossus em aeronaves exclusivas?",
  ui_story_5036_50360401_25_dialog_content = "Animado? Exaltado? Nervoso? Emocionados?",
  ui_story_5036_50360401_26_dialog_content = "Mas há mais emoção e emoção por vir.",
  ui_story_5036_50360401_27_dialog_content = "Venho por meio desta anunciar o início da primeira rodada de audições!",
  ui_story_5036_50360401_28_dialog_content = "Ohhh! Aqui vamos nós!",
  ui_story_5036_50360401_29_dialog_content = "Por favor, fique quieto por um momento enquanto eu explico as regras.",
  ui_story_5036_50360401_30_dialog_content = "Como você pode ver, temos um painel de seis juízes.",
  ui_story_5036_50360401_31_dialog_content = "Você pode falar comigo sobre seus jogos sim favoritos!",
  ui_story_5036_50360401_32_dialog_content = "Estarei julgando seu canto, dança, visual, figura, QE e QI.",
  ui_story_5036_50360401_33_dialog_content = "Você precisa se destacar em apenas um dos seis para obter meu voto.",
  ui_story_5036_50360401_34_dialog_content = "Estou procurando performances perfeitamente altruístas, saudáveis, puras e adequadas dignas de nobres...",
  ui_story_5036_50360401_35_dialog_content = "você é capaz?",
  ui_story_5036_50360401_36_dialog_content = "Vá, todos.",
  ui_story_5036_50360401_37_dialog_content = "Espero iluminar os céus com você!",
  ui_story_5036_50360401_38_dialog_content = "Olá pessoal. Vou prestar muita atenção em suas apresentações!",
  ui_story_5036_50360401_39_dialog_content = "As regras são simples, tudo que você precisa é de quatro votos dos juízes...",
  ui_story_5036_50360401_40_dialog_content = "e você passará para a próxima rodada para ter a chance de se apresentar no palco do show.",
  ui_story_5036_50360401_41_dialog_content = "Aqueles que receberem votos unânimes automaticamente se apresentarão no show!",
  ui_story_5036_50360401_42_dialog_content = "Se você não avançar, não se preocupe, porque todos têm três chances.",
  ui_story_5036_50360401_43_dialog_content = "Fique à vontade para usar as salas do Eulogoz para ensaiar.",
  ui_story_5036_50360401_44_dialog_content = "Agora, então, vamos começar o show rolando!",
  ui_story_5036_50360401_45_dialog_content = "Por favor, suba e se apresente quando seu número for chamado!",
  ui_story_5036_50360401_46_dialog_content = "Número 1, o Coro Illumina!",
  ui_story_5036_50360401_47_dialog_content = "As audições começaram. Você não quer dar uma olhada?",
  ui_story_5036_50360401_48_dialog_content = "Não, agora não.",
  ui_story_5036_50360401_49_dialog_content = "Ainda não decidi o que vou fazer.",
  ui_story_5036_50360401_50_dialog_content = "Se eu assistir agora, só vai me deixar ainda mais nervoso.",
  ui_story_5036_50360401_51_dialog_content = "Também não decidi o que fazer.",
  ui_story_5036_50360401_52_dialog_content = "Nós nos inscrevemos principalmente porque estávamos preocupados que não haveria participantes suficientes.",
  ui_story_5036_50360401_53_dialog_content = "Mas vendo quantas pessoas estão aqui, estou pensando...",
  ui_story_5036_50360401_54_dialog_content = "Talvez eu não seja necessário.",
  ui_story_5036_50360401_55_dialog_content = "O que? Ouvi dizer que Illumina e Lumopolis têm vagas reservadas.",
  ui_story_5036_50360401_56_dialog_content = "Illumina escolheu o Coro, e pensei que você conseguiria a vaga de Lumopolis.",
  ui_story_5036_50360401_57_dialog_content = "Essa foi a nossa atuação. Obrigada!",
  ui_story_5036_50360401_58_dialog_content = "Seus movimentos foram bem sincronizados e enérgicos, e você cantou canções inspiradoras que realmente exemplificam os soldados de Illumina!",
  ui_story_5036_50360401_59_dialog_content = "Eu sei que seu grupo sempre faz turnês por Illumina, e sua familiaridade com o palco era evidente.",
  ui_story_5036_50360401_60_dialog_content = "Adorei seu canto! Boa sorte!",
  ui_story_5036_50360401_61_dialog_content = "Obrigado.",
  ui_story_5036_50360401_62_dialog_content = "Agora então, o Coro Illumina fica...",
  ui_story_5036_50360401_63_dialog_content = "Todos os 6 votos!",
  ui_story_5036_50360401_64_dialog_content = "Eles resistiram à pressão do teste primeiro e ganharam a chance de se apresentar no show! Parabéns!",
  ui_story_5036_50360401_65_dialog_content = "Obrigada! Não vamos decepcionar o público!",
  ui_story_5036_50360401_66_dialog_content = "Ok, a seguir, temos o Coro Lumopolis, Keating!",
  ui_story_5036_50360401_67_dialog_content = "Então é assim que funciona.",
  ui_story_5036_50360401_68_dialog_content = "Seria uma pena perder uma oportunidade tão rara.",
  ui_story_5036_50360401_69_dialog_content = "É exatamente por isso que deve ser reservado para quem merece.",
  ui_story_5036_50360401_70_dialog_content = "Que diabos?",
  ui_story_5036_50360401_71_dialog_content = "Hum?",
  ui_story_5036_50360401_72_dialog_content = "Então eu sou o único fazendo testes agora?",
  ui_story_5036_50360401_73_dialog_content = "Oh espere, eu sei!",
  ui_story_5036_50360401_74_dialog_content = "Eles vão ver o show em Lumopolis também...",
  ui_story_5036_50360401_75_dialog_content = "Você é muito tímida para se apresentar para sua torcida, Carleen?",
  ui_story_5036_50360401_76_dialog_content = "Não mesmo!",
  ui_story_5036_50360401_77_dialog_content = "Então prove isso.",
  ui_story_5036_50360401_78_dialog_content = "Mostre a todos do que você é capaz.",
  ui_story_5036_50360401_79_dialog_content = "Isso é ♪",
  ui_story_5036_50360401_80_dialog_content = "Nosso desempenho ♪",
  ui_story_5036_50360401_81_dialog_content = "Agora, por favor, comece ♪",
  ui_story_5036_50360401_82_dialog_content = "Seu desempenho ♪",
  ui_story_5036_50360401_83_dialog_content = "Graça inacreditável!",
  ui_story_5036_50360401_84_dialog_content = "Não admira que tenha sido escolhido pelo próprio Lord Schwartz!",
  ui_story_5036_50360401_85_dialog_content = "Suas vozes são simplesmente divinas e me limparam por dentro e por fora.",
  ui_story_5036_50360401_86_dialog_content = "Os plebeus devem valorizar isso.",
  ui_story_5036_50360401_87_dialog_content = "Você foi abençoado pelo Deus da Luz por poder ouvir um hino tão sagrado.",
  ui_story_5036_50360401_88_dialog_content = "Seu ato ♪",
  ui_story_5036_50360401_89_dialog_content = "é bobo ♪",
  ui_story_5036_50360401_90_dialog_content = "Suas palavras ♪",
  ui_story_5036_50360401_91_dialog_content = "São lisonjas vazias ♪",
  ui_story_5036_50360401_92_dialog_content = "Ouviu isso? Eles são melodiosos até quando falam!",
  ui_story_5036_50360401_93_dialog_content = "Você não pode distinguir lisonja de zombaria.",
  ui_story_5036_50360401_94_dialog_content = "O que é isso...?",
  ui_story_5036_50360401_95_dialog_content = "Keating também recebe 6 votos e vai direto para o show! Parabéns!",
  ui_story_5036_50360401_96_dialog_content = "Ambos os concorrentes? Isso não é manipulado, é?",
  ui_story_5036_50360401_97_dialog_content = "Você é o concorrente nº. 3, Bárbara?",
  ui_story_5036_50360401_98_dialog_content = "Essa sou eu, Bárbara!",
  ui_story_5036_50360401_99_dialog_content = "Ignore aquela mulher barulhenta. Eu, Bárbara, realmente nasci para ser uma ídola!",
  ui_story_5036_50360401_100_dialog_content = "Ha, talvez você deva se certificar de que consegue acertar suas notas antes de subir no palco!",
  ui_story_5036_50360401_101_dialog_content = "Por que você não gasta menos tempo me criticando e mais tempo aprendendo a cantar de verdade?",
  ui_story_5036_50360401_102_dialog_content = "É hora de vocês dois se apresentarem.",
  ui_story_5036_50360401_103_dialog_content = "Eu não posso acreditar nisso.",
  ui_story_5036_50360401_104_dialog_content = "Como o Rediesel Wrench acabou com alguém com um gosto musical tão ruim quanto você?",
  ui_story_5036_50360401_105_dialog_content = "Uau, olha quem está falando...",
  ui_story_5036_50360401_106_dialog_content = "Você realmente acha que alguém na Rediesel Wrench gosta da sua voz ruim?",
  ui_story_5036_50360401_107_dialog_content = "O que? Diga isso de novo!",
  ui_story_5036_50360401_108_dialog_content = "Atreva-se!",
  ui_story_5036_50360401_109_dialog_content = "Ei, por que outra pessoa está no palco?",
  ui_story_5036_50360401_110_dialog_content = "Eu sou o número 3!",
  ui_story_5036_50360401_111_dialog_content = "Desculpe Barbara, e a entrada não. 4 Regina...",
  ui_story_5036_50360401_112_dialog_content = "Os juízes o desqualificaram por conduta desordeira.",
  ui_story_5036_50360401_113_dialog_content = "Por favor, inscreva-se novamente para a próxima rodada.",
  ui_story_5036_50360401_114_dialog_content = "O quê?!",
  ui_story_5036_50360401_115_dialog_content = "Entendi.",
  ui_story_5036_50360401_116_dialog_content = "O-o que você vê?",
  ui_story_5036_50360401_117_dialog_content = "Você está se sentindo sozinho porque vai se apresentar sozinho?",
  ui_story_5036_50360401_118_dialog_content = "Não tão alto...",
  ui_story_5036_50360401_119_dialog_content = "Tudo bem, eu admito.",
  ui_story_5036_50360401_120_dialog_content = "Afinal, sempre fazemos tudo juntos como um grupo.",
  ui_story_5036_50360401_121_dialog_content = "Parece um pouco estranho de repente ir solo.",
  ui_story_5036_50360401_122_dialog_content = "Então tá.",
  ui_story_5036_50360401_123_dialog_content = "Acho que posso ajudar uma pomba solitária.",
  ui_story_5036_50360401_124_dialog_content = "Eu não sou uma pomba solitária!",
  ui_story_5036_50360401_125_dialog_content = "Hahaha...",
  ui_story_5036_50360401_126_dialog_content = "No entanto, comparado a ficar lá sozinho...",
  ui_story_5036_50360401_127_dialog_content = "Eu sinto falta de como é estar no palco com você.",
  ui_story_5036_50360401_128_dialog_content = "Hã?",
  ui_story_5036_50360401_129_dialog_content = "O que há com a nostalgia repentina?",
  ui_story_5036_50360401_130_dialog_content = "Bem, de qualquer forma, acho que a pessoa que eu era naquela época estaria muito mais interessada em atuar.",
  ui_story_5036_50360401_131_dialog_content = "Na verdade, eu também...",
  ui_story_5036_50360401_132_dialog_content = "Que pena.",
  ui_story_5036_50360401_133_dialog_content = "Nenhum competidor até agora conseguiu entrar no show além dos nossos dois primeiros.",
  ui_story_5036_50360401_134_dialog_content = "Agora, vamos dar as boas-vindas ao último participante de hoje.",
  ui_story_5036_50360401_135_dialog_content = "Que desempenho ele tem reservado para nós?",
  ui_story_5036_50360401_136_dialog_content = "E ai pessoal.",
  ui_story_5036_50360401_137_dialog_content = "Eu sou Vic. Eu sou um treinador de feras maravilhoso.",
  ui_story_5036_50360401_138_dialog_content = "Victor?!",
  ui_story_5036_50360401_139_dialog_content = "PlayerName?",
  ui_story_5036_50360401_140_dialog_content = "Não esperava ver um rosto familiar no comitê de seleção.",
  ui_story_5036_50360401_141_dialog_content = "Devo esclarecer que eu realmente não sabia PlayerName ia ser juiz.",
  ui_story_5036_50360401_142_dialog_content = "É realmente você!",
  ui_story_5036_50360401_143_dialog_content = "Achei que estava enganado... Por que você se inscreveu nisso?",
  ui_story_5036_50360401_144_dialog_content = "Porque eu quero ser um ídolo e me apresentar neste palco único.",
  ui_story_5036_50360401_145_dialog_content = "Eu nunca soube que você queria ser um ídolo.",
  ui_story_5036_50360401_146_dialog_content = "Pelo que sei, você já fez seu nome no mundo do maravilhoso treinamento de feras.",
  ui_story_5036_50360401_147_dialog_content = "Quem disse que extrozoologistas não podem ser ídolos?",
  ui_story_5036_50360401_148_dialog_content = "Só eu posso decidir isso!",
  ui_story_5036_50360401_149_dialog_content = "Hoje em dia, qualquer um pode ser um ídolo...",
  ui_story_5036_50360401_150_dialog_content = "e aproveite seus 15 minutos de fama no centro das atenções.",
  ui_story_5036_50360401_151_dialog_content = "\"Hoje em dia, qualquer um pode ser um ídolo\", você diz?",
  ui_story_5036_50360401_152_dialog_content = "Muito bem colocado!",
  ui_story_5036_50360401_153_dialog_content = "Eu aprecio sua atitude e compreensão sobre este negócio. Estou ansioso para o seu ato!",
  ui_story_5036_50360401_154_dialog_content = "Uau, este é o primeiro concorrente até agora a chamar a atenção da própria Miss Goldie!",
  ui_story_5036_50360401_155_dialog_content = "Então, que performance emocionante ele nos trará?",
  ui_story_5036_50360401_156_dialog_content = "Por favor, comece, Vic!",
  ui_story_5036_50360401_157_dialog_content = "Vou recitar algo para todos vocês. Aham...",
  ui_story_5036_50360401_158_dialog_content = "Ah! A primavera chegou e a terra ganha vida mais uma vez!",
  ui_story_5036_50360401_159_dialog_content = "É mais uma vez a estação em que as feras maravilhosas exibem seu vigor.",
  ui_story_5036_50360401_160_dialog_content = "(Eu nem tenho certeza se isso se qualifica como uma performance...)",
  ui_story_5036_50360401_161_dialog_content = "(Mas parece que Vic está recitando sua Enciclopédia Exótica?!)",
  ui_story_5036_50360401_162_dialog_content = "Infelizmente! A glória da vida preenche cada centímetro da terra, sejam as florestas ou as planícies!",
  ui_story_5036_50360401_163_dialog_content = "Mas em meio a essa cacofonia, há uma criatura que é a exceção.",
  ui_story_5036_50360401_164_dialog_content = "o <color=#FFB400>Ouroboros</color> é um dos <color=#FFB400> vida mais longa </color> bestas maravilhosas em Astra.",
  ui_story_5036_50360401_165_dialog_content = "Quando atingem a maturidade—",
  ui_story_5036_50360401_166_dialog_content = "Desculpe, deixe-me interrompê-lo por um segundo!",
  ui_story_5036_50360401_167_dialog_content = "Os juízes estão se perguntando se você tem mais alguma coisa para nos mostrar?",
  ui_story_5036_50360401_168_dialog_content = "Bem, não... Eu só preparei essa narração dramática para hoje.",
  ui_story_5036_50360401_169_dialog_content = "Entendo... Que pena.",
  ui_story_5036_50360401_170_dialog_content = "Você se saiu bem em sua recitação, mas não é bem o que estamos procurando.",
  ui_story_5036_50360401_171_dialog_content = "Mas não fique para baixo em si mesmo!",
  ui_story_5036_50360401_172_dialog_content = "Você tem uma voz muito boa e visual muito bom também.",
  ui_story_5036_50360401_173_dialog_content = "Tenho certeza que você fará bem em mudar para cantar ou dançar.",
  ui_story_5036_50360401_174_dialog_content = "Não me surpreenderia se um dia você superasse até mesmo alguns dos artistas experientes.",
  ui_story_5036_50360401_175_dialog_content = "Espero ver um diferente de você em uma rodada posterior.",
  ui_story_5036_50360401_176_dialog_content = "Eu acho que você tem um grande potencial, então continue se esforçando!",
  ui_story_5036_50360401_177_dialog_content = "Ah, acho que vou tentar de novo.",
  ui_story_5036_50360401_178_dialog_content = "(Goldie está olhando para Vic como se ela tivesse acabado de descobrir uma joia escondida...)",
  ui_story_5036_50360401_179_dialog_content = "(Vic realmente tem o que é preciso para ser um ídolo?)",
  ui_story_5036_50360401_180_dialog_content = "Obrigado a todos os nossos candidatos e jurados! As audições de hoje chegaram ao fim.",
  ui_story_5036_50360401_181_dialog_content = "Certifique-se de sintonizar as próximas rodadas de audições!",
  ui_story_5036_50360401_182_dialog_content = "Bem, até amanhã!",
  ui_story_5036_50360401_183_dialog_content = "PlayerName, Goldie, acabou?",
  ui_story_5036_50360401_184_dialog_content = "Sim. Achei que seria relaxante assistir às apresentações, mas na verdade isso exigiu muito de mim.",
  ui_story_5036_50360401_185_dialog_content = "A propósito, como é que vocês não apareceram?",
  ui_story_5036_50360401_186_dialog_content = "Queríamos ensaiar um pouco mais antes de entrar.",
  ui_story_5036_50360401_187_dialog_content = "Vocês estão ensaiando juntos?",
  ui_story_5036_50360401_188_dialog_content = "Sim. Achamos que seria mais divertido entrar como dupla.",
  ui_story_5036_50360401_189_dialog_content = "Não fique tão chocado. Você ouviu isso corretamente.",
  ui_story_5036_50360401_190_dialog_content = "Vice e eu vamos nos apresentar como uma dupla.",
  ui_story_5036_50360401_191_dialog_content = "Essa é uma ótima ideia!",
  ui_story_5036_50360401_192_dialog_content = "Já tem ideia do que vai fazer?",
  ui_story_5036_50360401_193_dialog_content = "Estaremos cantando. Já temos algumas músicas escolhidas.",
  ui_story_5036_50360401_194_dialog_content = "Mas temos que ensaiar antes de decidir com qual deles ir.",
  ui_story_5036_50360401_195_dialog_content = "Sinceramente, não sei se vamos conseguir...",
  ui_story_5036_50360401_196_dialog_content = "Não se preocupe. Deixe-me contar um segredo.",
  ui_story_5036_50360401_197_dialog_content = "Na verdade, ainda não decidi quais músicas cantar.",
  ui_story_5036_50360401_198_dialog_content = "Você deve ter uma grande seleção de suas próprias músicas para escolher, certo?",
  ui_story_5036_50360401_199_dialog_content = "Sim, mas não acho que haja um adequado para um palco no Eulogoz.",
  ui_story_5036_50360401_200_dialog_content = "Tudo bem, no entanto. Talvez eu descubra nos próximos dias.",
  ui_story_5036_50360401_201_dialog_content = "Quer dizer que está escrevendo uma nova música só para Eulogoz?",
  ui_story_5036_50360401_202_dialog_content = "Shh, não tão alto! Mas sim, essa é a ideia.",
  ui_story_5036_50360401_203_dialog_content = "Não tenho certeza se posso fazer isso, então, por favor, mantenha isso em segredo.",
  ui_story_5036_50360401_204_dialog_content = "Você escreve todas as suas músicas?",
  ui_story_5036_50360401_205_dialog_content = "Isso é impressionante!",
  ui_story_5036_50360401_206_dialog_content = "Nem todos, não.",
  ui_story_5036_50360401_207_dialog_content = "É que uma melodia ou batida aparece em minha mente ocasionalmente.",
  ui_story_5036_50360401_208_dialog_content = "Então eu tento escrevê-la e transformá-la em uma música.",
  ui_story_5036_50360401_209_dialog_content = "Mas não é sempre que consigo a melodia que quero.",
  ui_story_5036_50360401_210_dialog_content = "Uma melodia que surge em sua mente...?",
  ui_story_5036_50360401_211_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360401_212_dialog_content = "♪ Lá lá lá lá... ♪",
  ui_story_5036_50360401_213_dialog_content = "Então, desde que me aproximei de Eulogoz, tenho ouvido músicas na minha cabeça.",
  ui_story_5036_50360401_214_dialog_content = "Eu diria até que não é uma melodia tanto quanto alguém realmente cantarolando.",
  ui_story_5036_50360401_215_dialog_content = "Sério?",
  ui_story_5036_50360401_216_dialog_content = "Ouvi dizer que os celestitas eram uma raça amante da música.",
  ui_story_5036_50360401_217_dialog_content = "Talvez você tenha uma afinidade natural para fazer música!",
  ui_story_5036_50360401_218_dialog_content = "V-você acha?",
  ui_story_5036_50360401_219_dialog_content = "Eugoloz poderia estar me enviando inspiração?",
  ui_story_5036_50360401_220_dialog_content = "É bem possível!",
  ui_story_5036_50360401_221_dialog_content = "Faz sentido.",
  ui_story_5036_50360401_222_dialog_content = "Eulogoz pertencia aos celestitas.",
  ui_story_5036_50360401_223_dialog_content = "Se eu pudesse cantar uma música composta por um celestita em Eulogoz, isso seria muito significativo!",
  ui_story_5036_50360401_224_dialog_content = "PlayerName!",
  ui_story_5036_50360401_225_dialog_content = "Se você não se importa, você pode compartilhar a melodia que está surgindo em sua cabeça?",
  ui_story_5036_50360401_226_dialog_content = "Claro que não me importo.",
  ui_story_5036_50360401_227_dialog_content = "Pare-!",
  ui_story_5036_50360401_228_dialog_content = "O que houve?",
  ui_story_5036_50360401_229_dialog_content = "Ah!",
  ui_story_5036_50360401_230_dialog_content = "Parece que teremos que esperar por isso, PlayerName!",
  ui_story_5036_50360402_1_dialog_content = "Desculpe incomodá-lo!",
  ui_story_5036_50360402_2_dialog_content = "Um guarda desmaiou na área de bloqueio durante a limpeza dos Eclipsites, que os deixou sair.",
  ui_story_5036_50360402_3_dialog_content = "Felizmente, os soldados de Illumina e Lumopolis nos ajudaram.",
  ui_story_5036_50360402_4_dialog_content = "E o guarda? Ele está ferido?",
  ui_story_5036_50360402_5_dialog_content = "Ele está consciente e deve ficar bem.",
  ui_story_5036_50360402_6_dialog_content = "Foi porque lidar com os Eclipsites na área de bloqueio era muito desgastante?",
  ui_story_5036_50360402_7_dialog_content = "Seguimos seu conselho e demos bastante descanso a todos, então as coisas não estão tão ruins.",
  ui_story_5036_50360402_8_dialog_content = "Ele disse que desmaiou porque não tinha nada para comer.",
  ui_story_5036_50360402_9_dialog_content = "Não fornecemos refeições suficientes?",
  ui_story_5036_50360402_10_dialog_content = "Bem, alguém roubou sua parte e ele não teve tempo de conseguir uma reposição.",
  ui_story_5036_50360402_11_dialog_content = "Alguém roubou a comida dele?",
  ui_story_5036_50360402_12_dialog_content = "De jeito nenhum, não me diga que eles me pegaram também!",
  ui_story_5036_50360402_13_dialog_content = "Você está ferido, soldado?",
  ui_story_5036_50360402_14_dialog_content = "Estou bem, Tenente Vice!",
  ui_story_5036_50360402_15_dialog_content = "É que as rações que eu tinha comigo parecem ter sumido.",
  ui_story_5036_50360402_16_dialog_content = "Você também?",
  ui_story_5036_50360402_17_dialog_content = "Sim. Os caras ao meu redor tiveram a mesma coisa acontecendo com eles.",
  ui_story_5036_50360402_18_dialog_content = "Nossas rações continuam desaparecendo misteriosamente.",
  ui_story_5036_50360402_19_dialog_content = "Achei que carregar minhas rações comigo seria seguro, mas...",
  ui_story_5036_50360402_20_dialog_content = "Talvez vocês os tenham perdido enquanto lutavam contra os Eclipsites?",
  ui_story_5036_50360402_21_dialog_content = "Foi o que pensamos também, por isso não denunciamos.",
  ui_story_5036_50360402_22_dialog_content = "o <color=#FFB400>ladrão fantasma</color>... Deve ser o ladrão fantasma!",
  ui_story_5036_50360402_23_dialog_content = "Ladrão fantasma?",
  ui_story_5036_50360402_24_dialog_content = "Há um ladrão fantasma no Colosso, Lady Carleen!",
  ui_story_5036_50360402_25_dialog_content = "O ladrão te derruba quando você menos espera.",
  ui_story_5036_50360402_26_dialog_content = "Então leva todos os seus objetos de valor sem ser visto!",
  ui_story_5036_50360402_27_dialog_content = "Foi assim que perdi meu relógio de bolso de pedras preciosas.",
  ui_story_5036_50360402_28_dialog_content = "Roubando comida e joias?",
  ui_story_5036_50360402_29_dialog_content = "Isso não soa como algo que os Eclipsites fariam.",
  ui_story_5036_50360402_30_dialog_content = "Então temos um ladrão em nossas mãos...",
  ui_story_5036_50360402_31_dialog_content = "Sabe, de alguma forma, isso soa familiar.",
  ui_story_5036_50360402_32_dialog_content = "Onde já vi uma situação semelhante antes...",
  ui_story_5036_50360402_33_dialog_content = "Poderia um batedor de carteira profissional ter embarcado no Wandering Colossus?",
  ui_story_5036_50360402_34_dialog_content = "Os mercenários também notaram esse problema, Srta. Goldie.",
  ui_story_5036_50360402_35_dialog_content = "Não apenas nós, mas até mesmo aqueles que se inscreveram para a audição reclamaram de perder doces e bebidas.",
  ui_story_5036_50360402_36_dialog_content = "Maldições, por que os criminosos têm que aparecer no céu?!",
  ui_story_5036_50360402_37_dialog_content = "Estou preocupado que o ladrão incomode os candidatos à audição, Goldie.",
  ui_story_5036_50360402_38_dialog_content = "Carleen está certa. A questão mais urgente é garantir que o ladrão não os faça perder a fé nos anfitriões do show.",
  ui_story_5036_50360402_39_dialog_content = "Você se importaria de enviar alguém para comprar outro carregamento de comida e bebida de Umbraton?",
  ui_story_5036_50360402_40_dialog_content = "Temos que garantir que todos os competidores e soldados em Eulogoz sejam alimentados.",
  ui_story_5036_50360402_41_dialog_content = "Considerando o volume envolvido, terei que enviar mais pessoas.",
  ui_story_5036_50360402_42_dialog_content = "Por favor, faça e inclua o custo na conta.",
  ui_story_5036_50360402_43_dialog_content = "Sim!",
  ui_story_5036_50360402_44_dialog_content = "...",
  ui_story_5036_50360402_45_dialog_content = "Você está bem, Goldie?",
  ui_story_5036_50360402_46_dialog_content = "...",
  ui_story_5036_50360402_47_dialog_content = "Goldie?",
  ui_story_5036_50360402_48_dialog_content = "Hum? Huh... Sim, estou bem, não se preocupe comigo!",
  ui_story_5036_50360402_49_dialog_content = "Concentre-se no seu ensaio e não se preocupe com isso, Carleen, Vice.",
  ui_story_5036_50360402_50_dialog_content = "Eu absolutamente...",
  ui_story_5036_50360402_51_dialog_content = "Eu absolutamente não vou deixar ninguém impedir o show de acontecer!",
  ui_story_5036_50360501_1_dialog_content = "Mercenários...",
  ui_story_5036_50360501_2_dialog_content = "O que você fez?!",
  ui_story_5036_50360501_3_dialog_content = "Que palco maravilhoso você construiu!",
  ui_story_5036_50360501_4_dialog_content = "Você limpou completamente a tela de Eugoloz e a equipou com iluminação multicolorida!",
  ui_story_5036_50360501_5_dialog_content = "Acredite em mim quando digo isso...",
  ui_story_5036_50360501_6_dialog_content = "Este estágio é mais impressionante do que qualquer outro que eu já vi em Umbraton!",
  ui_story_5036_50360501_7_dialog_content = "Obrigado pelo elogio, Srta. Goldie.",
  ui_story_5036_50360501_8_dialog_content = "Apenas seguimos as instruções da Sra. Sheol.",
  ui_story_5036_50360501_9_dialog_content = "Não, vocês são diferentes.",
  ui_story_5036_50360501_10_dialog_content = "Lady Sheol diz que a maioria dos mercenários faz um trabalho de má qualidade e descuidado.",
  ui_story_5036_50360501_11_dialog_content = "Somente as Chamas Brancas podem ser confiadas para serem sempre meticulosas e confiáveis.",
  ui_story_5036_50360501_12_dialog_content = "É uma pena, no entanto...",
  ui_story_5036_50360501_13_dialog_content = "que um local tão impressionante só será realizado de uma vez.",
  ui_story_5036_50360501_14_dialog_content = "Se quiser, senhorita Goldie...",
  ui_story_5036_50360501_15_dialog_content = "Podemos construir o mesmo estágio para você mais tarde em Umbraton.",
  ui_story_5036_50360501_16_dialog_content = "Tchau?",
  ui_story_5036_50360501_17_dialog_content = "Supondo que eu ainda seja um ídolo até então...",
  ui_story_5036_50360501_18_dialog_content = "Hã?",
  ui_story_5036_50360501_19_dialog_content = "Deixa para lá. Alguma notícia do ladrão?",
  ui_story_5036_50360501_20_dialog_content = "Nada até agora.",
  ui_story_5036_50360501_21_dialog_content = "O culpado é muito astuto. Ainda não temos pistas sólidas.",
  ui_story_5036_50360501_22_dialog_content = "Tudo o que sabemos é que a maioria das coisas foi roubada durante a noite.",
  ui_story_5036_50360501_23_dialog_content = "Isso é um começo.",
  ui_story_5036_50360501_24_dialog_content = "Estarei patrulhando com você à noite.",
  ui_story_5036_50360501_25_dialog_content = "Você vai patrulhar conosco?",
  ui_story_5036_50360501_26_dialog_content = "Haha, você é a primeira pessoa a rejeitar a companhia de um ídolo famoso.",
  ui_story_5036_50360501_27_dialog_content = "eu não ousaria! Só estou preocupado que isso tome tempo para você compor.",
  ui_story_5036_50360501_28_dialog_content = "Oh, nunca subestime o que um ídolo pode fazer!",
  ui_story_5036_50360501_29_dialog_content = "Eu tenho muitas músicas que posso cantar no palco.",
  ui_story_5036_50360501_30_dialog_content = "Eu adoraria escrever uma nova música para a melodia do Caelestite...",
  ui_story_5036_50360501_31_dialog_content = "mas PlayerName só me deu algumas notas. Não sei onde posso levar isso.",
  ui_story_5036_50360501_32_dialog_content = "Apenas algumas notas?",
  ui_story_5036_50360501_33_dialog_content = "Você é curioso?",
  ui_story_5036_50360501_34_dialog_content = "U-Uh, eu não ousaria me intrometer...",
  ui_story_5036_50360501_35_dialog_content = "Não? Mas tenho vontade de cantá-la neste novo palco.",
  ui_story_5036_50360501_36_dialog_content = "♪ Lá... ♪",
  ui_story_5036_50360501_37_dialog_content = "♪ La... La la la... ♪",
  ui_story_5036_50360501_38_dialog_content = "Grahhhhhh!",
  ui_story_5036_50360501_39_dialog_content = "Os Eclipsites que escaparam... Eles estão se escondendo embaixo do palco!",
  ui_story_5036_50360501_40_dialog_content = "Eles saíram assim que a senhorita Goldie começou a cantar...",
  ui_story_5036_50360501_41_dialog_content = "Não me diga que eles também são Cachinhos Dourados?!",
  ui_story_5036_50360502_1_dialog_content = "Ouvi dizer que o palco será concluído esta noite.",
  ui_story_5036_50360502_2_dialog_content = "Eu preciso vencer todos lá para conseguir as fotos de todos os ângulos!",
  ui_story_5036_50360502_3_dialog_content = "O que eu quero é um furo de reportagem que seja quente o suficiente para atrair visualizações!",
  ui_story_5036_50360502_4_dialog_content = "Sério, o editor poderia ter feito uma exigência mais difícil?",
  ui_story_5036_50360502_5_dialog_content = "Onde devo obter informações privilegiadas?",
  ui_story_5036_50360502_6_dialog_content = "A única coisa que posso fazer é ser o primeiro a relatar qualquer notícia no Eulogoz.",
  ui_story_5036_50360502_7_dialog_content = "Ei, tem alguém no palco...",
  ui_story_5036_50360502_8_dialog_content = "Se ao menos os Eclipsites pudessem se tornar Cachinhos Dourados...",
  ui_story_5036_50360502_9_dialog_content = "Você gosta de Eclipsites?",
  ui_story_5036_50360502_10_dialog_content = "Você está brincando comigo?!",
  ui_story_5036_50360502_11_dialog_content = "S-Desculpe!",
  ui_story_5036_50360502_12_dialog_content = "Bem, a culpa foi minha por não esclarecer.",
  ui_story_5036_50360502_13_dialog_content = "Eu só estava pensando, seria ótimo se os Eclipsites pudessem entender minhas músicas.",
  ui_story_5036_50360502_14_dialog_content = "Se eles pudessem ouvir o amor e a paz neles, talvez isso os influenciasse",
  ui_story_5036_50360502_15_dialog_content = "para parar seu comportamento selvagem e assassino.",
  ui_story_5036_50360502_16_dialog_content = "Heh... Isso saiu pomposo ou o quê?",
  ui_story_5036_50360502_17_dialog_content = "Influência, selvagem, ... assassino?",
  ui_story_5036_50360502_18_dialog_content = "O que Goldie está dizendo? É difícil dizer de tão longe.",
  ui_story_5036_50360502_19_dialog_content = "Acho que tenho que chegar um pouco mais perto...",
  ui_story_5036_50360502_20_dialog_content = "<color=#e8d9bb>Pow!</color>",
  ui_story_5036_50360502_21_dialog_content = "Oh vamos lá! Como pude ser tão azarado?",
  ui_story_5036_50360502_22_dialog_content = "Claro que tive que bater em uma caixa de madeira neste exato momento!",
  ui_story_5036_50360502_23_dialog_content = "Eles me ouviram?",
  ui_story_5036_50360502_24_dialog_content = "Ufa, acho que não.",
  ui_story_5036_50360502_25_dialog_content = "Quem está aí?",
  ui_story_5036_50360502_26_dialog_content = "Hã?",
  ui_story_5036_50360502_27_dialog_content = "Opa, fui pego!",
  ui_story_5036_50360502_28_dialog_content = "Está bem. Só vou explicar que estava só de passagem. A senhorita Goldie com certeza...",
  ui_story_5036_50360502_29_dialog_content = "acredite em mim, certo?",
  ui_story_5036_50360502_30_dialog_content = "<color=#e8d9bb>*Batida*</color>",
  ui_story_5036_50360502_31_dialog_content = "Pare aí mesmo!",
  ui_story_5036_50360502_32_dialog_content = "O que? O que...?",
  ui_story_5036_50360502_33_dialog_content = "Goldie parece estar gritando em outra direção?",
  ui_story_5036_50360502_34_dialog_content = "Há mais alguém além de mim se escondendo aqui?",
  ui_story_5036_50360502_35_dialog_content = "Você é ainda mais perspicaz do que nosso batedor, Srta. Goldie!",
  ui_story_5036_50360502_36_dialog_content = "Não achei que alguém estaria escondido embaixo do piso.",
  ui_story_5036_50360502_37_dialog_content = "Pena que o criminoso fugiu antes que eu pudesse levantá-lo.",
  ui_story_5036_50360502_38_dialog_content = "Olha, rações meio comidas.",
  ui_story_5036_50360502_39_dialog_content = "É a embalagem Illumina.",
  ui_story_5036_50360502_40_dialog_content = "Ilumina rações?",
  ui_story_5036_50360502_41_dialog_content = "Mas nenhum dos soldados de Illumina foi designado para trabalhar perto do palco.",
  ui_story_5036_50360502_42_dialog_content = "Sim. Os caras ao meu redor tiveram a mesma coisa acontecendo com eles.",
  ui_story_5036_50360502_43_dialog_content = "Nossas rações continuam desaparecendo misteriosamente.",
  ui_story_5036_50360502_44_dialog_content = "Será que...",
  ui_story_5036_50360502_45_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5036_50360502_46_dialog_content = "Aquilo era um rato?",
  ui_story_5036_50360502_47_dialog_content = "Não! Não um rato.",
  ui_story_5036_50360502_48_dialog_content = "Você vê aquela coisa fugindo, Marshmallow?",
  ui_story_5036_50360502_49_dialog_content = "Vá atrás disso!",
  ui_story_5036_50360502_50_dialog_content = "Au, au!",
  ui_story_5036_50360502_51_dialog_content = "Hai?",
  ui_story_5036_50360502_52_dialog_content = "Hiya!",
  ui_story_5036_50360502_53_dialog_content = "Não o capture, Marshmallow. Basta segui-lo de perto por enquanto.",
  ui_story_5036_50360502_54_dialog_content = "Talvez isso nos leve a <color=#FFB400>peixe maior</color>.",
  ui_story_5036_50360502_55_dialog_content = "Hai—!",
  ui_story_5036_50360502_56_dialog_content = "Huh? Suspirar...",
  ui_story_5036_50360502_57_dialog_content = "Você me ignorou totalmente há um minuto, Bica...",
  ui_story_5036_50360502_58_dialog_content = "Agora você quer abraçar?",
  ui_story_5036_50360502_59_dialog_content = "Au!",
  ui_story_5036_50360502_60_dialog_content = "Aham. Diga, você não deveria manter uma coleira naquele seu cachorro gordinho?",
  ui_story_5036_50360502_61_dialog_content = "A minha Bica é muito sensível e fica nervosa com facilidade, o que depois incomoda o estômago—",
  ui_story_5036_50360502_62_dialog_content = "Você é o ladrão fantasma?",
  ui_story_5036_50360502_63_dialog_content = "Fantasma? Sem chance.",
  ui_story_5036_50360502_64_dialog_content = "Não acredita em mim? Vou me morder para provar isso. Uau!",
  ui_story_5036_50360502_65_dialog_content = "Cara, isso doeu muito!",
  ui_story_5036_50360502_66_dialog_content = "Veja, eu sou tão vivo quanto possível. Eu sinto dor. Fantasmas não.",
  ui_story_5036_50360502_67_dialog_content = "(É uma tarefa árdua falar com esse cara.)",
  ui_story_5036_50360502_68_dialog_content = "(Mas por que ele soa familiar?)",
  ui_story_5036_50360502_69_dialog_content = "Não me importa se você é o fantasma ou não, mas não vou tolerar ninguém tentando estragar meu show!",
  ui_story_5036_50360502_70_dialog_content = "É melhor você começar a se explicar!",
  ui_story_5036_50360502_71_dialog_content = "<color=#828282>Ding!</color>",
  ui_story_5036_50360502_72_dialog_content = "Esta coisa na minha mão não é apenas ornamental!",
  ui_story_5036_50360502_73_dialog_content = "Está bem, está bem...",
  ui_story_5036_50360502_74_dialog_content = "Vá com calma! Quase tropecei em mim mesmo por causa de suas ameaças.",
  ui_story_5036_50360502_75_dialog_content = "Sua roupa parece irregular. O que você está escondendo aí embaixo?",
  ui_story_5036_50360502_76_dialog_content = "Apenas um bebê precioso que acabei de domesticar. Está descansando agora.",
  ui_story_5036_50360502_77_dialog_content = "Por que não acredito nisso nem um pouco?",
  ui_story_5036_50360502_78_dialog_content = "Suspirar. Só posso dizer que você não tem compreensão então.",
  ui_story_5036_50360502_79_dialog_content = "Leia mais livros, folheie mais jornais, faça mais trabalhos de caridade... Esse é todo o conselho que posso lhe dar.",
  ui_story_5036_50360502_80_dialog_content = "Se não houver mais nada, vou me retirar agora.",
  ui_story_5036_50360502_81_dialog_content = "Tira as tuas roupas!",
  ui_story_5036_50360502_82_dialog_content = "Ha?! Pode estar escuro e você não pode ver nada...",
  ui_story_5036_50360502_83_dialog_content = "mas ainda tenho minha modéstia para proteger!",
  ui_story_5036_50360502_84_dialog_content = "Pega ele, Marshmallow!",
  ui_story_5036_50360502_85_dialog_content = "Au!",
  ui_story_5036_50360502_86_dialog_content = "Assista...!",
  ui_story_5036_50360502_87_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5036_50360502_88_dialog_content = "Eu caí de qualquer maneira...",
  ui_story_5036_50360502_89_dialog_content = "Ei, ele não era um dos artistas na audição?",
  ui_story_5036_50360502_90_dialog_content = "Então esse é o pretexto que você usou para esgueirar-se a bordo.",
  ui_story_5036_50360502_91_dialog_content = "Ai, ai, ai...",
  ui_story_5036_50360502_92_dialog_content = "Ele?!",
  ui_story_5036_50360502_93_dialog_content = "Cau ca!",
  ui_story_5036_50360502_94_dialog_content = "O que...? Uma coruja acabou de cair de seus braços?",
  ui_story_5036_50360502_95_dialog_content = "Não era mercadoria roubada? Eu estava sendo muito paranóico?",
  ui_story_5036_50360502_96_dialog_content = "Eu disse que era inocente.",
  ui_story_5036_50360502_97_dialog_content = "<color=#e8d9bb>*Splash* Clang, clang...</color>",
  ui_story_5036_50360502_98_dialog_content = "Muitas joias simplesmente caíram de dentro das penas da coruja.",
  ui_story_5036_50360502_99_dialog_content = "Veja, eu disse que não era um ladrão.",
  ui_story_5036_50360502_100_dialog_content = "Oh, Lutumi, você poderia ter sido qualquer coisa! Por que você seria um ladrão?",
  ui_story_5036_50360502_101_dialog_content = "Ai...",
  ui_story_5036_50360502_102_dialog_content = "Como você ainda está negando isso? A evidência está literalmente espalhada ao nosso redor!",
  ui_story_5036_50360502_103_dialog_content = "Relaxar!",
  ui_story_5036_50360502_104_dialog_content = "Não terei piedade de você!",
  ui_story_5036_50360502_105_dialog_content = "Hum...",
  ui_story_5036_50360502_106_dialog_content = "Senhorita Goldie?!",
  ui_story_5036_50360502_107_dialog_content = "Não se preocupe, ele está apenas temporariamente nocauteado.",
  ui_story_5036_50360502_108_dialog_content = "Ele tem uma língua de prata, e nenhum de nós tem tempo nem energia para lidar com isso agora.",
  ui_story_5036_50360502_109_dialog_content = "Por favor, leve-o sob custódia e interrogue-o quando terminar a tarefa em questão.",
  ui_story_5036_50360502_110_dialog_content = "<color=#e8d9bb>Clique!</color>",
  ui_story_5036_50360502_111_dialog_content = "Então...",
  ui_story_5036_50360502_112_dialog_content = "O boato sobre a maldade de Goldie era verdade?",
  ui_story_5036_50360502_113_dialog_content = "Com esta imagem, poderei...",
  ui_story_5036_50360601_1_dialog_content = "E agora?",
  ui_story_5036_50360601_2_dialog_content = "Eu entendi! Furo interno que garantirá visualizações!",
  ui_story_5036_50360601_3_dialog_content = "É melhor não estar desperdiçando meu tempo.",
  ui_story_5036_50360601_4_dialog_content = "Eu prometo que você ficará feliz com o que eu tenho!",
  ui_story_5036_50360601_5_dialog_content = "Lembra quando você recebeu uma dica sobre Goldie ter uma raia de maldade?",
  ui_story_5036_50360601_6_dialog_content = "(Onde estou?)",
  ui_story_5036_50360601_7_dialog_content = "(Quando voltei para Eraveil? A última vez que me lembro, eu estava...)",
  ui_story_5036_50360601_8_dialog_content = "(Onde eu estava mesmo?)",
  ui_story_5036_50360601_9_dialog_content = "♪ La... La la la... ♪",
  ui_story_5036_50360601_10_dialog_content = "(conheço essa música!)",
  ui_story_5036_50360601_11_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360601_12_dialog_content = "(Quem está cantarolando?)",
  ui_story_5036_50360601_13_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_5036_50360601_14_dialog_content = "(O que acabou de passar, um Colosso?)",
  ui_story_5036_50360601_15_dialog_content = "(Eu deveria descobrir.)",
  ui_story_5036_50360601_16_dialog_content = "♪ Lá lá lá lá... ♪",
  ui_story_5036_50360601_17_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360601_18_dialog_content = "♪ Lá... Lá lá... ♪",
  ui_story_5036_50360601_19_dialog_content = "(A garota ali, é ela que está cantando.)",
  ui_story_5036_50360601_20_dialog_content = "Aí está você.",
  ui_story_5036_50360601_21_dialog_content = "(Ela está falando comigo?)",
  ui_story_5036_50360601_22_dialog_content = "Cree, cree!",
  ui_story_5036_50360601_23_dialog_content = "(Ah, ela está falando com uma criatura que parece um Colosso.)",
  ui_story_5036_50360601_24_dialog_content = "Aqui para me ouvir cantar? Você é um fã tão leal!",
  ui_story_5036_50360601_25_dialog_content = "Mas acho que é hora de colocar palavras na música.",
  ui_story_5036_50360601_26_dialog_content = "(A maneira como ela está vestida e agindo... Ela é definitivamente uma celestita.)",
  ui_story_5036_50360601_27_dialog_content = "(Eu sabia que encontraria outros celestitas!)",
  ui_story_5036_50360601_28_dialog_content = "Hmm, estou com um pouco de sede.",
  ui_story_5036_50360601_29_dialog_content = "Vamos colher algumas frutas silvestres!",
  ui_story_5036_50360601_30_dialog_content = "Cree, cree!",
  ui_story_5036_50360601_31_dialog_content = "Ei, garotinha!",
  ui_story_5036_50360601_32_dialog_content = "Espere!",
  ui_story_5036_50360601_33_dialog_content = "Hã?",
  ui_story_5036_50360601_34_dialog_content = "<color=#e8d9bb>Toc, toc!</color>",
  ui_story_5036_50360601_35_dialog_content = "Garotinha!",
  ui_story_5036_50360601_36_dialog_content = "Hã?",
  ui_story_5036_50360601_37_dialog_content = "Ah, foi só um sonho...",
  ui_story_5036_50360601_38_dialog_content = "<color=#e8d9bb>Quatro dias para o concerto</color>",
  ui_story_5036_50360601_39_dialog_content = "<color=#e8d9bb>Libra, libra, libra!</color>",
  ui_story_5036_50360601_40_dialog_content = "Você está bem aí, PlayerName?",
  ui_story_5036_50360601_41_dialog_content = "Tô indo!",
  ui_story_5036_50360601_42_dialog_content = "Você estava morto de sono!",
  ui_story_5036_50360601_43_dialog_content = "Você não nos ouviu batendo na porta?",
  ui_story_5036_50360601_44_dialog_content = "Estávamos começando a pensar que os Eclipsites haviam entrado no seu quarto...",
  ui_story_5036_50360601_45_dialog_content = "Vice e eu estávamos quase arrombando a porta.",
  ui_story_5036_50360601_46_dialog_content = "Desculpe, acabei de ter esse sonho. Parecia que eu ainda estava nele.",
  ui_story_5036_50360601_47_dialog_content = "Ah, outro sonho.",
  ui_story_5036_50360601_48_dialog_content = "Outro?",
  ui_story_5036_50360601_49_dialog_content = "Sim. Você esqueceu, Carleen?",
  ui_story_5036_50360601_50_dialog_content = "PlayerName tem sonhos estranhos com bastante frequência.",
  ui_story_5036_50360601_51_dialog_content = "De repente, lembrei-me de que também tive um sonho estranho esta manhã.",
  ui_story_5036_50360601_52_dialog_content = "Acho que sonhei com Eraveil.",
  ui_story_5036_50360601_53_dialog_content = "Só que a pessoa que mora lá não era PlayerName, mas uma garotinha que eu nunca tinha visto antes.",
  ui_story_5036_50360601_54_dialog_content = "Eu também! Eu tive o mesmo sonho!",
  ui_story_5036_50360601_55_dialog_content = "Uau, nós realmente temos uma ótima química hoje em dia.",
  ui_story_5036_50360601_56_dialog_content = "Deve ser todos aqueles ensaios!",
  ui_story_5036_50360601_57_dialog_content = "Mas eu sonhei a mesma coisa.",
  ui_story_5036_50360601_58_dialog_content = "O quê?",
  ui_story_5036_50360601_59_dialog_content = "Eu vi uma garotinha cantando em Eraveil.",
  ui_story_5036_50360601_60_dialog_content = "A música dela foi a melodia que ficou presa na minha cabeça!",
  ui_story_5036_50360601_61_dialog_content = "A garota do meu sonho não cantava. Ela estava apenas arrumando sua casa.",
  ui_story_5036_50360601_62_dialog_content = "A garota com quem sonhei estava lendo em uma sala.",
  ui_story_5036_50360601_63_dialog_content = "Portanto, nossos sonhos eram ligeiramente diferentes.",
  ui_story_5036_50360601_64_dialog_content = "Ouvi dizer que quando várias pessoas experimentam a mesma coisa, há uma chance de que acabem tendo sonhos semelhantes.",
  ui_story_5036_50360601_65_dialog_content = "Por causa de sua experiência compartilhada, seu subconsciente gravita em torno dos mesmos pensamentos, resultando em sonhos semelhantes.",
  ui_story_5036_50360601_66_dialog_content = "Sonha-se à noite o que se pensa durante o dia, como diz o ditado.",
  ui_story_5036_50360601_67_dialog_content = "Mas nossas diferentes personalidades se refletem nos detalhes de um sonho idêntico.",
  ui_story_5036_50360601_68_dialog_content = "Isso é tudo? Eu me emocionei por nada.",
  ui_story_5036_50360601_69_dialog_content = "A propósito, PlayerName, tem certeza que quer continuar conversando conosco?",
  ui_story_5036_50360601_70_dialog_content = "Você precisa estar presente na segunda rodada de audições hoje, não?",
  ui_story_5036_50360601_71_dialog_content = "Ops!! Eu esqueci totalmente!",
  ui_story_5036_50360601_72_dialog_content = "♪ Oo-oo-oo-oo... ♪",
  ui_story_5036_50360601_73_dialog_content = "♪ Lá... Lá lá... ♪",
  ui_story_5036_50360601_74_dialog_content = "Essa é a totalidade da melodia na minha cabeça. É bom colocar tudo para fora!",
  ui_story_5036_50360601_75_dialog_content = "*Boceja*",
  ui_story_5036_50360601_76_dialog_content = "W-Eu estava totalmente desafinado ou algo assim?",
  ui_story_5036_50360601_77_dialog_content = "Não. Eu não dormi bem ontem à noite, então me perdoe, PlayerName.",
  ui_story_5036_50360601_78_dialog_content = "É porque você teve muitos sonhos?",
  ui_story_5036_50360601_79_dialog_content = "Você tem muita imaginação, PlayerName.",
  ui_story_5036_50360601_80_dialog_content = "Verifiquei o palco ontem à noite.",
  ui_story_5036_50360601_81_dialog_content = "E foi para a área de bloqueio para cuidar dos Eclipsites até altas horas da madrugada.",
  ui_story_5036_50360601_82_dialog_content = "Não são os Mercenários da Chama Branca encarregados disso?",
  ui_story_5036_50360601_83_dialog_content = "Sim, mas eu não aguentava ficar presa no meu quarto.",
  ui_story_5036_50360601_84_dialog_content = "Achei que, em vez de me preocupar com isso, poderia muito bem ajudar.",
  ui_story_5036_50360601_85_dialog_content = "Não é à toa que você é o ídolo mais popular de Umbraton. Você trabalha demais.",
  ui_story_5036_50360601_86_dialog_content = "Você se envolve em tudo!",
  ui_story_5036_50360601_87_dialog_content = "Qualquer pequena coisa pode fazer ou quebrar o concerto.",
  ui_story_5036_50360601_88_dialog_content = "O show é de extrema importância para mim. Não posso deixar que nada atrapalhe.",
  ui_story_5036_50360601_89_dialog_content = "Você parece ser do tipo que trata cada apresentação como se fosse a última.",
  ui_story_5036_50360601_90_dialog_content = "R-Sério? Ahaha...",
  ui_story_5036_50360601_91_dialog_content = "Mas nós divagamos. Como devo descrever a melodia que você acabou de compartilhar comigo?",
  ui_story_5036_50360601_92_dialog_content = "Gentil, calmante, terapêutico, exclusivamente Caelestita e fácil de cantar!",
  ui_story_5036_50360601_93_dialog_content = "É exatamente o tipo de música que procuro em todos os aspectos!",
  ui_story_5036_50360601_94_dialog_content = "Tem certeza de que não se importa que eu a apresente no palco?",
  ui_story_5036_50360601_95_dialog_content = "Eu nunca pensei que seria um compositor, então arrase!",
  ui_story_5036_50360601_96_dialog_content = "Ter um ídolo tão famoso cantando minha música seria uma honra.",
  ui_story_5036_50360601_97_dialog_content = "Deixe-me saber se você tem alguma idéia para as letras!",
  ui_story_5036_50360601_98_dialog_content = "Agora, há outra coisa que eu queria falar com você.",
  ui_story_5036_50360601_99_dialog_content = "Você se lembra do participante final nas audições de ontem?",
  ui_story_5036_50360601_100_dialog_content = "Você quer dizer Vic?",
  ui_story_5036_50360601_101_dialog_content = "Ele é seu amigo?",
  ui_story_5036_50360601_102_dialog_content = "Sou próximo ao aprendiz dele, então acho que você pode dizer isso.",
  ui_story_5036_50360601_103_dialog_content = "Mas eu não sabia que ele se inscreveu e também não votei nele.",
  ui_story_5036_50360601_104_dialog_content = "Você não precisa se preocupar com meu favoritismo!",
  ui_story_5036_50360601_105_dialog_content = "Ele tem tendências cleptomaníacas?",
  ui_story_5036_50360601_106_dialog_content = "O que? Por que você pergunta?",
  ui_story_5036_50360601_107_dialog_content = "Bem, ontem à noite...",
  ui_story_5036_50360601_108_dialog_content = "Socorro!",
  ui_story_5036_50360601_109_dialog_content = "Grahhhhhh!",
  ui_story_5036_50360601_110_dialog_content = "Para de correr!",
  ui_story_5036_50360601_111_dialog_content = "Eclipsitas perseguindo Vic, mercenários perseguindo os Eclipsitas? O que está acontecendo aqui?!",
  ui_story_5036_50360602_1_dialog_content = "Os outros juízes estão em seus lugares, Miss Goldie e PlayerName.",
  ui_story_5036_50360602_2_dialog_content = "Se não tiver problema...",
  ui_story_5036_50360602_3_dialog_content = "Socorro!",
  ui_story_5036_50360602_4_dialog_content = "Você deve se juntar a nós para a segunda rodada de audições.",
  ui_story_5036_50360602_5_dialog_content = "Graagh!!!!",
  ui_story_5036_50360602_6_dialog_content = "Toma essa!",
  ui_story_5036_50360602_7_dialog_content = "Todo mundo parece um pouco preocupado no momento...",
  ui_story_5036_50360602_8_dialog_content = "Socorro!",
  ui_story_5036_50360602_9_dialog_content = "Você pode parar de gritar agora. Os Eclipsites estão em baixo.",
  ui_story_5036_50360602_10_dialog_content = "*Ofega pesadamente*",
  ui_story_5036_50360602_11_dialog_content = "Eu estava gritando para que você não me trancasse com eles de novo!",
  ui_story_5036_50360602_12_dialog_content = "Para minha sorte, as garras de Little Furball eram longas o suficiente para forçar a fechadura.",
  ui_story_5036_50360602_13_dialog_content = "Caso contrário, eu nem teria a chance de pedir ajuda!",
  ui_story_5036_50360602_14_dialog_content = "Desculpe, não tínhamos intenção de colocá-lo em perigo.",
  ui_story_5036_50360602_15_dialog_content = "Mas quando o confinamos naquela sala, não havia Eclipsites lá.",
  ui_story_5036_50360602_16_dialog_content = "...",
  ui_story_5036_50360602_17_dialog_content = "Eles saíram pelas saídas de ar, Srta. Goldie.",
  ui_story_5036_50360602_18_dialog_content = "A ventilação naquela sala parece estar conectada à área de bloqueio.",
  ui_story_5036_50360602_19_dialog_content = "Mas a saída de ar não está protegida com uma tampa?",
  ui_story_5036_50360602_20_dialog_content = "Entendi.",
  ui_story_5036_50360602_21_dialog_content = "Você estava tentando escapar pela abertura, que atraiu os Eclipsites para lá!",
  ui_story_5036_50360602_22_dialog_content = "Uh... Hee hee.",
  ui_story_5036_50360602_23_dialog_content = "Estava tão quente no quarto. Eu realmente precisava de um pouco de ar.",
  ui_story_5036_50360602_24_dialog_content = "O que está acontecendo? Por que você trancou Vic?",
  ui_story_5036_50360602_25_dialog_content = "Sinto muito, PlayerName.",
  ui_story_5036_50360602_26_dialog_content = "Mas seu amigo Vic é o ladrão fantasma que vem roubando nos últimos dias.",
  ui_story_5036_50360602_27_dialog_content = "Vic é o ladrão?",
  ui_story_5036_50360602_28_option_content = "Bem, é possível.",
  ui_story_5036_50360602_29_dialog_content = "Ele é um extrozoologista publicado, mas isso foi há muitos anos.",
  ui_story_5036_50360602_30_dialog_content = "Eu podia vê-lo recorrendo ao furto sem nenhum livro novo em seu currículo ou qualquer renda confiável.",
  ui_story_5036_50360602_31_dialog_content = "Mas não importa o quão pobre você seja, você ainda deve ganhar dinheiro com suas próprias mãos.",
  ui_story_5036_50360602_32_dialog_content = "Você não deve colocar as mãos nos bolsos dos outros e pegar suas coisas!",
  ui_story_5036_50360602_33_option_content = "Impossível!",
  ui_story_5036_50360602_34_dialog_content = "Ele é um extrozoologista publicado com muitos alunos.",
  ui_story_5036_50360602_35_dialog_content = "Não importa o quão pobre ele seja, ele não recorreria a pequenos furtos!",
  ui_story_5036_50360602_36_dialog_content = "Eu sei que é difícil para você aceitar.",
  ui_story_5036_50360602_37_dialog_content = "Eu mesmo não posso acreditar. Eu vi muito potencial nele.",
  ui_story_5036_50360602_38_dialog_content = "Mas descobrimos comida e joias roubadas em seus bolsos ontem. A prova estava ali.",
  ui_story_5036_50360602_39_dialog_content = "Ouça-me explicar...",
  ui_story_5036_50360602_40_dialog_content = "Eu ouvi o suficiente de suas desculpas complicadas ontem.",
  ui_story_5036_50360602_41_dialog_content = "Você ainda está tentando negá-lo com a quantidade de evidências disponíveis?",
  ui_story_5036_50360602_42_dialog_content = "Ok, ok, confesso todos os roubos recentes.",
  ui_story_5036_50360602_43_dialog_content = "Então você realmente é o ladrão fantasma?!",
  ui_story_5036_50360602_44_dialog_content = "Embora eu seja o responsável, há um aviso!",
  ui_story_5036_50360602_45_dialog_content = "Eu, Vic, sou um extrozoologista famoso, mas nunca fui um ladrão.",
  ui_story_5036_50360602_46_dialog_content = "O ladrão que todo mundo está falando é na verdade uma besta maravilhosa que eu trouxe comigo.",
  ui_story_5036_50360602_47_dialog_content = "Hai...",
  ui_story_5036_50360602_48_dialog_content = "Ai...",
  ui_story_5036_50360602_49_dialog_content = "Piu, piu!",
  ui_story_5036_50360602_50_dialog_content = "O peludinho no seu ombro parece estar agitado.",
  ui_story_5036_50360602_51_dialog_content = "A Bolinha de Pelos está dizendo: \"Foram aqueles dois, não eu!\"",
  ui_story_5036_50360602_52_dialog_content = "Piu!",
  ui_story_5036_50360602_53_dialog_content = "Normalmente, eu mudo suas refeições todos os dias.",
  ui_story_5036_50360602_54_dialog_content = "Mas fiquei muito ocupado fazendo as malas e trouxe apenas um tipo de comida.",
  ui_story_5036_50360602_55_dialog_content = "Esses dois saíram sozinhos, provavelmente porque estavam cansados de comer a mesma coisa.",
  ui_story_5036_50360602_56_dialog_content = "Quando soube do roubo do Colossus, pensei que poderiam ter sido eles.",
  ui_story_5036_50360602_57_dialog_content = "Levei uma eternidade para finalmente pegar os dois ontem à noite.",
  ui_story_5036_50360602_58_dialog_content = "Pouco antes de pegarmos você?",
  ui_story_5036_50360602_59_dialog_content = "Sim. Que coincidência, hein?",
  ui_story_5036_50360602_60_dialog_content = "Eu entendo que os animais querem comer, mas por que roubar joias?",
  ui_story_5036_50360602_61_dialog_content = "Foi a Coruja Lutumi?",
  ui_story_5036_50360602_62_dialog_content = "Isso mesmo. A Coruja Lutumi pode emitir um gás anestésico. Trouxe comigo para fins de autodefesa.",
  ui_story_5036_50360602_63_dialog_content = "Mas ele adora colecionar objetos brilhantes, então se você o perder de vista...",
  ui_story_5036_50360602_64_dialog_content = "Acaba se tornando exatamente o tipo de ladrão que todo mundo está fofocando.",
  ui_story_5036_50360602_65_dialog_content = "No entanto, eles estão agindo apenas por instinto. Eles não guardam nenhuma maldade em relação a nós.",
  ui_story_5036_50360602_66_dialog_content = "Eu sou o culpado por não mantê-los na linha.",
  ui_story_5036_50360602_67_dialog_content = "Prometo devolver todas as joias e moedas aos seus donos!",
  ui_story_5036_50360602_68_dialog_content = "Se necessário, pagarei até pelos problemas que causei a todos.",
  ui_story_5036_50360602_69_dialog_content = "Apenas, por favor, não castigue as criaturas! Eles não queriam dizer isso.",
  ui_story_5036_50360602_70_dialog_content = "Ai, ai, ai.",
  ui_story_5036_50360602_71_dialog_content = "...",
  ui_story_5036_50360602_72_dialog_content = "Ok, mas você deve fazer o que prometeu.",
  ui_story_5036_50360602_73_dialog_content = "Devolva tudo com um pedido de desculpas e compensação.",
  ui_story_5036_50360602_74_dialog_content = "Então, que tal não nos trancar mais em um quartinho escuro?",
  ui_story_5036_50360602_75_dialog_content = "Está muito abafado lá dentro...",
  ui_story_5036_50360602_76_dialog_content = "Eu posso fazer isso.",
  ui_story_5036_50360602_77_dialog_content = "Mas você deve me prometer que deixará Eulogoz depois de cuidar de tudo.",
  ui_story_5036_50360602_78_dialog_content = "O que? Não, não posso ir. Eu ainda não realizei meu sonho de ser um ídolo!",
  ui_story_5036_50360602_79_dialog_content = "Você não me encorajou a continuar fazendo testes, Srta. Goldie?",
  ui_story_5036_50360602_80_dialog_content = "Você tem talento, assim como uma língua loquaz...",
  ui_story_5036_50360602_81_dialog_content = "Mas de alguma forma tenho a sensação de que você não veio aqui para uma audição de ídolo.",
  ui_story_5036_50360602_82_dialog_content = "!!!",
  ui_story_5036_50360602_83_dialog_content = "... Tudo bem, suponho que vou confessar.",
  ui_story_5036_50360602_84_dialog_content = "Na verdade, estou aqui em busca de uma fera maravilhosa chamada Ouroboros.",
  ui_story_5036_50360602_85_dialog_content = "Quando a criatura atinge um determinado estágio, ela se transforma em um ovo.",
  ui_story_5036_50360602_86_dialog_content = "Em seguida, ele irrompe após a incubação e o ciclo se repete, permitindo que ele alcance a imortalidade.",
  ui_story_5036_50360602_87_dialog_content = "Existem criaturas imortais no mundo?!",
  ui_story_5036_50360602_88_dialog_content = "Eu sei desde muito jovem que meu pai e minha mãe não eram meus pais biológicos.",
  ui_story_5036_50360602_89_dialog_content = "Recentemente descobri que minha linhagem parece estar ligada ao Ouroboros. Portanto, devo encontrá-lo!",
  ui_story_5036_50360602_89X1_dialog_content = "Se eu encontrar um Ouroboros, posso descobrir mais sobre minhas origens e talvez até encontrar meus pais biológicos.",
  ui_story_5036_50360602_90_dialog_content = "Registros sobre a espécie são escassos. A única coisa certa sobre eles é que gostam de ficar perto de Colossi.",
  ui_story_5036_50360602_91_dialog_content = "Você está bêbado de novo, mestre! Sair dessa!",
  ui_story_5036_50360602_92_dialog_content = "Eu já vasculhei informações sobre todos os Colossi em Astra, incluindo Soroz do PlayerName.",
  ui_story_5036_50360602_93_dialog_content = "Nenhum sinal de qualquer Ouroboros foi encontrado perto de qualquer um deles.",
  ui_story_5036_50360602_94_dialog_content = "Os Ouroboros realmente existem?",
  ui_story_5036_50360602_96_dialog_content = "Você não está brincando comigo de novo, está?!",
  ui_story_5036_50360602_97_dialog_content = "Hmph! Nunca mais me faça procurar alguns Ouroboros estúpidos para você!",
  ui_story_5036_50360602_98_dialog_content = "Eu vasculhei todos os Colossos em Astra, mas não consegui encontrar nenhum vestígio de um Ouroboros.",
  ui_story_5036_50360602_99_dialog_content = "O único lugar que ainda não procurei é este Colosso voador em que estamos.",
  ui_story_5036_50360602_100_dialog_content = "Então você encontrou algum vestígio de um Ouroboros em Eulogoz?",
  ui_story_5036_50360602_101_dialog_content = "Não, mas tenho um palpite, um palpite muito forte.",
  ui_story_5036_50360602_102_dialog_content = "Há definitivamente um Ouroboros em Eulogoz!",
  ui_story_5036_50360602_103_dialog_content = "Por favor, permita-me ficar e procurá-lo!",
  ui_story_5036_50360602_104_dialog_content = "Por favor, dê a alguém que nunca experimentou o calor de um lar amoroso a chance de encontrar sua família!",
  ui_story_5036_50360602_105_dialog_content = "... Você terminou?",
  ui_story_5036_50360602_106_dialog_content = "Sim, terminei.",
  ui_story_5036_50360602_107_dialog_content = "Essa sua história é mais incrédula do que qualquer filme de baixo orçamento de Umbraton poderia oferecer.",
  ui_story_5036_50360602_108_dialog_content = "Eu deveria te agradecer por ampliar meus horizontes.",
  ui_story_5036_50360602_109_dialog_content = "Ehehe, sem problemas. Obrigado pela compreensão.",
  ui_story_5036_50360602_110_dialog_content = "Eu deveria ter deixado claro para todos desde o início.",
  ui_story_5036_50360602_111_dialog_content = "Pronto, acabou a hora da história.",
  ui_story_5036_50360602_112_dialog_content = "Agora você poderia, por favor, sair de Eulogoz?",
  ui_story_5036_50360602_113_dialog_content = "O quê?",
  ui_story_5036_50360602_114_dialog_content = "Esse caminho por favor. Eu vou acompanhá-lo.",
  ui_story_5036_50360602_115_dialog_content = "Espere um minuto! Eu ainda não terminei!",
  ui_story_5036_50360602_116_dialog_content = "Estou brincando! Eu só estava brincando, hahaha.",
  ui_story_5036_50360602_116X1_dialog_content = "Adaptar e improvisar para qualquer situação, animar a atmosfera e apelar para as emoções dos fãs – tudo isso faz parte das responsabilidades de um ídolo.",
  ui_story_5036_50360602_116X2_dialog_content = "Eu queria mostrar a vocês do que eu era capaz, então vocês sabem o quão sinceramente eu desejo participar das audições!",
  ui_story_5036_50360602_117_dialog_content = "Quer dizer, comédia improvisada?",
  ui_story_5036_50360602_118_dialog_content = "Minha história espontânea não fez você rir?",
  ui_story_5036_50360602_119_dialog_content = "Bom...",
  ui_story_5036_50360602_120_dialog_content = "(Na verdade, Vic cativou toda a minha atenção desde o início.)",
  ui_story_5036_50360602_121_dialog_content = "(Lady Sheol disse que eu estava perdendo alguma coisa ... Poderia ser o senso de humor desarmante que Vic possui?)",
  ui_story_5036_50360602_124_dialog_content = "Eu realmente quero ser um ídolo... Por favor, deixe-me ficar e competir.",
  ui_story_5036_50360602_125_dialog_content = "Você pode não acreditar em mim, mas você não acredita PlayerName?",
  ui_story_5036_50360602_126_dialog_content = "Ele é nosso VIP, é claro que acredito nele de todo o coração.",
  ui_story_5036_50360602_127_dialog_content = "Aí está então.",
  ui_story_5036_50360602_128_dialog_content = "A Fia te ajudou muitas vezes antes, né, PlayerName?",
  ui_story_5036_50360602_129_dialog_content = "Er... sim, você poderia dizer isso.",
  ui_story_5036_50360602_130_dialog_content = "E por associação, isso não significa que sou tecnicamente seu benfeitor?",
  ui_story_5036_50360602_131_dialog_content = "B-Benfeitor?",
  ui_story_5036_50360602_132_dialog_content = "Então, como juiz, você vai responder por mim, certo?",
  ui_story_5036_50360602_133_dialog_content = "...",
  ui_story_5036_50360602_134_dialog_content = "PlayerName responde por mim, senhorita Goldie.",
  ui_story_5036_50360602_135_dialog_content = "Por favor, não me expulse em nome dele...",
  ui_story_5036_50360602_136_dialog_content = "Você garante por ele, PlayerName?",
  ui_story_5036_50360602_137_dialog_content = "Hã, bom...",
  ui_story_5036_50360602_138_dialog_content = "Chegue perto, PlayerName. Ouço...",
  ui_story_5036_50360602_139_dialog_content = "Não me diga que você não notou a poderosa presença de Lumina na área de bloqueio em Eulogoz!",
  ui_story_5036_50360602_140_dialog_content = "O quê?!",
  ui_story_5036_50360602_141_dialog_content = "Então Goldie estava tentando pegar um ladrão ontem à noite...",
  ui_story_5036_50360602_142_dialog_content = "Isso significa que minha foto foi enganosa...",
  ui_story_5036_50360602_143_dialog_content = "<color=#e8d9bb>Zumbido!</color>",
  ui_story_5036_50360602_144_dialog_content = "Quando você vai me enviar a foto que mencionou, Brandy?",
  ui_story_5036_50360602_145_dialog_content = "Preciso me aprofundar mais na situação!",
  ui_story_5036_50360602_146_dialog_content = "O que mais cavar você tem que fazer?",
  ui_story_5036_50360602_147_dialog_content = "A verdade não importa, apenas notícias cativantes são boas notícias!",
  ui_story_5036_50360602_148_dialog_content = "Mas...",
  ui_story_5036_50360602_149_dialog_content = "Não se preocupe em voltar se não enviar a foto!",
  ui_story_5036_50360602_150_dialog_content = "Editor! Editor!",
  ui_story_5036_50360701_1_dialog_content = "Seus comentários estão ficando mais profissionais, PlayerName!",
  ui_story_5036_50360701_2_dialog_content = "Você pode se tornar um verdadeiro produtor de idols um dia!",
  ui_story_5036_50360701_3_dialog_content = "Mas...",
  ui_story_5036_50360701_4_dialog_content = "Você ainda está preocupado com Vic?",
  ui_story_5036_50360701_5_dialog_content = "Sim, desculpe-me!",
  ui_story_5036_50360701_6_dialog_content = "Mesmo que você tenha atestado por ele, ainda estou ansioso.",
  ui_story_5036_50360701_7_dialog_content = "Eu o coloquei em uma sala de ensaio próxima, mas não sei se ele está praticando seriamente.",
  ui_story_5036_50360701_8_dialog_content = "Eu me pergunto se ele está sendo perturbador para os outros?",
  ui_story_5036_50360701_9_dialog_content = "Quer saber, preciso ir ver como ele está.",
  ui_story_5036_50360701_10_dialog_content = "Aqui.",
  ui_story_5036_50360701_11_dialog_content = "Ele está cumprindo minha palavra, então eu deveria supervisioná-lo.",
  ui_story_5036_50360701_12_dialog_content = "E você quase não descansou desde ontem. Você deveria fazer uma pausa.",
  ui_story_5036_50360701_13_dialog_content = "Verdadeiro. Eu também tenho uma música para escrever... Não posso desperdiçar a melodia que você compartilhou comigo!",
  ui_story_5036_50360701_14_dialog_content = "Vou deixar Vic para você!",
  ui_story_5036_50360701_15_dialog_content = "*Bocejo* O que você disse?",
  ui_story_5036_50360701_16_dialog_content = "Como está indo hoje?",
  ui_story_5036_50360701_17_dialog_content = "Legal.",
  ui_story_5036_50360701_18_dialog_content = "Eu dormi muito bem ontem à noite!",
  ui_story_5036_50360701_19_dialog_content = "Eu estava perguntando sobre o seu ensaio.",
  ui_story_5036_50360701_20_dialog_content = "Não me diga que você dormiu o dia inteiro e nunca pensou nisso?",
  ui_story_5036_50360701_21_dialog_content = "Já não me fiz claro? Tudo bem, mais uma vez.",
  ui_story_5036_50360701_22_dialog_content = "A inscrição no concurso foi um pretexto, a história do Ouroboros não é falsa.",
  ui_story_5036_50360701_23_dialog_content = "Eu queria aproveitar esta oportunidade para entrar em Eulogoz e encontrar a criatura.",
  ui_story_5036_50360701_24_dialog_content = "Eu sei disso, mas não sinto nenhum Lumina poderoso vindo da área de bloqueio.",
  ui_story_5036_50360701_25_dialog_content = "Há apenas um monte de Eclipsites dormindo lá.",
  ui_story_5036_50360701_26_dialog_content = "Um Ouroboros em incubação não libera Lumina significativa.",
  ui_story_5036_50360701_27_dialog_content = "Então isso significa que a criatura ainda está em um ovo!",
  ui_story_5036_50360701_28_dialog_content = "Como você tem tanta certeza de que existe uma dessas coisas em Eugoloz?",
  ui_story_5036_50360701_29_dialog_content = "Chame isso de intuição. A intuição de um extrozoologista.",
  ui_story_5036_50360701_30_dialog_content = "Então, basicamente, você não tem nenhuma evidência.",
  ui_story_5036_50360701_31_dialog_content = "Eu posso entender um pouco porque Fia está sempre de mau humor perto de você agora.",
  ui_story_5036_50360701_32_dialog_content = "Você ainda não pode convencê-los a me deixar entrar na área de bloqueio?",
  ui_story_5036_50360701_33_dialog_content = "C-Como você espera que eu aborde o assunto?",
  ui_story_5036_50360701_34_dialog_content = "Goldie ordenou que os mercenários guardassem a área, então ela claramente não quer que ninguém entre e cause problemas.",
  ui_story_5036_50360701_35_dialog_content = "Mesmo que haja um Ouroboros no Eulogoz, você pode pelo menos esperar até o show acabar antes de procurá-lo.",
  ui_story_5036_50360701_36_dialog_content = "Quer dizer que posso ficar no Eulogoz até o show acabar?",
  ui_story_5036_50360701_37_dialog_content = "Isso depende se você passar pelas audições.",
  ui_story_5036_50360701_38_dialog_content = "Os competidores que não conseguirem obter votos suficientes devem sair imediatamente. Está claro nas regras.",
  ui_story_5036_50360701_39_dialog_content = "Oh aquilo? Isso é um pedaço de bolo.",
  ui_story_5036_50360701_40_dialog_content = "Oh? Você tinha um show em mente?",
  ui_story_5036_50360701_41_dialog_content = "O que você acha de fazer o Bola de Pelos fazer backflips?",
  ui_story_5036_50360701_42_dialog_content = "Um show de animais? Seria melhor fazer um teste para um circo.",
  ui_story_5036_50360701_43_dialog_content = "Isso não é uma competição de canto de ídolos?",
  ui_story_5036_50360701_44_dialog_content = "Você tropeçou no lugar errado?",
  ui_story_5036_50360701_45_dialog_content = "Ooh, há drama aqui?",
  ui_story_5036_50360701_46_dialog_content = "Onde há drama, há notícias. É melhor eu tirar boas notas!",
  ui_story_5036_50360701_47_dialog_content = "Ei, pare de olhar para outras pessoas! Sim, você!",
  ui_story_5036_50360701_48_dialog_content = "Você me conhece?",
  ui_story_5036_50360701_49_dialog_content = "Eu conheço você.",
  ui_story_5036_50360701_50_dialog_content = "Nossa, não esperava encontrar alguém que lesse meu trabalho aqui!",
  ui_story_5036_50360701_51_dialog_content = "Você é aquele ladrão fantasma que foi pego recentemente.",
  ui_story_5036_50360701_52_dialog_content = "Ladrões não deveriam ser presos? O que ele ainda está fazendo na audição?",
  ui_story_5036_50360701_53_dialog_content = "Sem falar que ele está ocupando uma vaga!",
  ui_story_5036_50360701_54_dialog_content = "Ouça, ladrão. Não sei de quem é a palma da mão que você untou...",
  ui_story_5036_50360701_55_dialog_content = "Mas nenhum de nós permitirá que você profane o palco ou nossos sonhos!",
  ui_story_5036_50360701_56_dialog_content = "Se você não está planejando fazer um teste de verdade, então vá embora!",
  ui_story_5036_50360701_57_dialog_content = "Calma, pessoal...",
  ui_story_5036_50360701_58_dialog_content = "Foi tudo um mal-entendido. Eu realmente quero competir.",
  ui_story_5036_50360701_59_dialog_content = "Além disso, decidi chegar até a fase final.",
  ui_story_5036_50360701_60_dialog_content = "Com seu número de circo?",
  ui_story_5036_50360701_61_dialog_content = "Eu estava apenas brincando!",
  ui_story_5036_50360701_62_dialog_content = "Por que eu me inscreveria se não tivesse uma performance preparada?",
  ui_story_5036_50360701_63_dialog_content = "Então mostre-nos o que você tem.",
  ui_story_5036_50360701_64_dialog_content = "Sim!",
  ui_story_5036_50360701_65_dialog_content = "Vamos ver que tipo de show você está fazendo!",
  ui_story_5036_50360701_66_dialog_content = "Sobre isso...",
  ui_story_5036_50360701_67_dialog_content = "Bem, o que você está esperando?",
  ui_story_5036_50360701_68_dialog_content = "Vamos! Mostre-nos!",
  ui_story_5036_50360701_69_dialog_content = "Ok, acalme-se! Eu vou fazer isso!",
  ui_story_5036_50360701_70_dialog_content = "Ahem, senhoras e senhores: a dança Drakolion.",
  ui_story_5036_50360701_71_dialog_content = "Esta dança é uma imitação de um Drakolion em voo, procurando por uma companheira. Dê uma boa olhada!",
  ui_story_5036_50360701_72_dialog_content = "Ei!",
  ui_story_5036_50360701_73_dialog_content = "Ha!",
  ui_story_5036_50360701_74_dialog_content = "Isso é para ser uma dança?",
  ui_story_5036_50360701_75_dialog_content = "Parece mais alguém reaprendendo a andar depois de quebrar uma perna.",
  ui_story_5036_50360701_76_dialog_content = "Veja isso, um backflip no ar!",
  ui_story_5036_50360701_77_dialog_content = "Ei! Aqui está.",
  ui_story_5036_50360701_78_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5036_50360701_79_dialog_content = "Oh Deus... Ai, ai, ai, ai, ai!",
  ui_story_5036_50360701_80_dialog_content = "Hahaha!",
  ui_story_5036_50360701_81_dialog_content = "Em vez disso, você machucou as costas?",
  ui_story_5036_50360701_82_dialog_content = "É preciso um talento especial para dançar assim!",
  ui_story_5036_50360701_83_dialog_content = "Extrozoologista virou ídolo intimidado em Eulogoz...",
  ui_story_5036_50360701_84_dialog_content = "Será que o editor vai gostar desse tipo de história?",
  ui_story_5036_50360701_85_dialog_content = "Você está bem, Vick?",
  ui_story_5036_50360701_86_dialog_content = "eu vejo apenas PlayerName se preocupa com os idosos!",
  ui_story_5036_50360701_87_dialog_content = "Minha bunda está presa em alguma coisa. Você pode me puxar para cima?",
  ui_story_5036_50360701_88_dialog_content = "Claro...",
  ui_story_5036_50360701_89_dialog_content = "Ei, isso é... uma saída de ar atrás de você?!",
  ui_story_5036_50360701_90_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5036_50360701_91_dialog_content = "O que foi isso?",
  ui_story_5036_50360701_92_dialog_content = "Nossa, quebrei a ventilação de novo, hahaha!",
  ui_story_5036_50360701_93_dialog_content = "Graagh!",
  ui_story_5036_50360701_94_dialog_content = "Por que há Eclipsites nesta abertura também?",
  ui_story_5036_50360701_95_dialog_content = "Corre-!",
  ui_story_5036_50360702_1_dialog_content = "Graagh!",
  ui_story_5036_50360702_2_dialog_content = "Florescer!",
  ui_story_5036_50360702_3_dialog_content = "A maneira como Goldie lidou com aqueles Eclipsites... Preciso me apressar e descobrir uma maneira de investigar essa dica sobre ela.",
  ui_story_5036_50360702_4_dialog_content = "Oh não! Esqueci de tirar fotos...",
  ui_story_5036_50360702_5_dialog_content = "Alguém está ferido?",
  ui_story_5036_50360702_6_dialog_content = "Todos estão bem, só um pouco assustados.",
  ui_story_5036_50360702_7_dialog_content = "Obrigado por nos salvar, Srta. Goldie.",
  ui_story_5036_50360702_8_dialog_content = "Você é tão bonita quanto nos cartazes... Não, você é muito mais bonita!",
  ui_story_5036_50360702_9_dialog_content = "Senhorita Goldie?!",
  ui_story_5036_50360702_10_dialog_content = "Eu sou um Cachinho Dourado desde que você debutou!",
  ui_story_5036_50360702_11_dialog_content = "Quer autografar aqui mesmo, Srta. Goldie?",
  ui_story_5036_50360702_12_dialog_content = "Goldie! Goldie! Goldie!",
  ui_story_5036_50360702_13_dialog_content = "Desculpe por isto. Vou mandar alguém para fechar o respiradouro e dar comida a todos.",
  ui_story_5036_50360702_14_dialog_content = "É tudo culpa daquele ladrão. Nada disso teria acontecido se a bunda dele não tivesse quebrado a tela.",
  ui_story_5036_50360702_15_dialog_content = "E ele com certeza é um péssimo dançarino!",
  ui_story_5036_50360702_16_dialog_content = "Expulse-o! Expulse-o! Expulse-o!",
  ui_story_5036_50360702_17_dialog_content = "Mas...",
  ui_story_5036_50360702_18_dialog_content = "Eu realmente quero passar pela audição.",
  ui_story_5036_50360702_19_dialog_content = "Oh sim?",
  ui_story_5036_50360702_20_dialog_content = "Você tem perseverança para chegar até o fim?",
  ui_story_5036_50360702_21_dialog_content = "Para Ouroboros...",
  ui_story_5036_50360702_22_dialog_content = "Eu devo!",
  ui_story_5036_50360702_23_dialog_content = "Devo ir até o fim!",
  ui_story_5036_50360702_24_dialog_content = "(Tal otimismo cego e determinação me deixam nostálgico.)",
  ui_story_5036_50360702_25_dialog_content = "(Antes de passar por qualquer treinamento, também jurei que um dia estaria em um palco maior.)",
  ui_story_5036_50360702_26_dialog_content = "(Estou vendo coisas?)",
  ui_story_5036_50360702_27_dialog_content = "(Por que vejo meu eu mais jovem em Vic?)",
  ui_story_5036_50360702_28_dialog_content = "(É porque nós dois acreditamos no poder da fé?)",
  ui_story_5036_50360702_29_dialog_content = "Devo perseverar até o fim!",
  ui_story_5036_50360702_30_dialog_content = "...",
  ui_story_5036_50360702_31_dialog_content = "Tudo bem, vou acreditar em você uma última vez.",
  ui_story_5036_50360702_32_dialog_content = "Expulse-o! Expulse-o! Expulse-o!",
  ui_story_5036_50360702_33_dialog_content = "Escute-me...",
  ui_story_5036_50360702_34_dialog_content = "Devido a uma série de mal-entendidos, nós erroneamente consideramos Vic o ladrão fantasma.",
  ui_story_5036_50360702_35_dialog_content = "Mas tudo foi esclarecido. Vic já devolveu tudo aos seus respectivos donos e fez as devidas reparações.",
  ui_story_5036_50360702_36_dialog_content = "Então, concordamos em deixá-lo continuar fazendo testes.",
  ui_story_5036_50360702_37_dialog_content = "Mas suas ações, no entanto, interromperam os procedimentos.",
  ui_story_5036_50360702_38_dialog_content = "Portanto, estamos dando a ele apenas uma última chance.",
  ui_story_5036_50360702_39_dialog_content = "Se ele ainda não puder ir, nós o faremos sair.",
  ui_story_5036_50360702_40_dialog_content = "Faltam apenas um ou dois dias. Ele não vai melhorar por mais que pratique.",
  ui_story_5036_50360702_41_dialog_content = "Mas, já que a senhorita Goldie falou...",
  ui_story_5036_50360702_42_dialog_content = "Apoio a decisão dela!",
  ui_story_5036_50360702_43_dialog_content = "Se ele passar com uma dança dessas...",
  ui_story_5036_50360702_44_dialog_content = "Não posso deixar de duvidar da Srta. Goldie e da integridade do evento.",
  ui_story_5036_50360702_45_dialog_content = "Por favor, acredite em mim quando digo que serei justo!",
  ui_story_5036_50360702_46_dialog_content = "Goldie! Goldie! Goldie!",
  ui_story_5036_50360702_47_dialog_content = "Ahem, obrigado, senhorita Goldie.",
  ui_story_5036_50360702_48_dialog_content = "O que você ainda está fazendo aqui?",
  ui_story_5036_50360702_49_dialog_content = "Hã?",
  ui_story_5036_50360702_50_dialog_content = "Encontre uma sala e comece a praticar.",
  ui_story_5036_50360702_51_dialog_content = "Mas agora é tão tarde...",
  ui_story_5036_50360702_52_dialog_content = "Eu disse que você tinha uma voz muito boa e visuais excelentes.",
  ui_story_5036_50360702_53_dialog_content = "Você já está muito à frente da curva do que a maioria das pessoas.",
  ui_story_5036_50360702_54_dialog_content = "Mas se você realmente quer chegar até o fim...",
  ui_story_5036_50360702_55_dialog_content = "Você deve fazer o que eu digo.",
  ui_story_5036_50360801_1_dialog_content = "<color=#e8d9bb>Três dias para o concerto</color>",
  ui_story_5036_50360801_2_dialog_content = "♪ Ai... Ai...",
  ui_story_5036_50360801_3_dialog_content = "Para!",
  ui_story_5036_50360801_4_dialog_content = "É essa a música que você está planejando cantar?",
  ui_story_5036_50360801_5_dialog_content = "Eu disse que tinha algo preparado, mas nenhum de vocês acreditou em mim!",
  ui_story_5036_50360801_6_dialog_content = "Essa música vai funcionar?",
  ui_story_5036_50360801_7_dialog_content = "Eu fui até uma floresta remota em Northland e observei raras auroragales cantando em busca de inspiração para a melodia.",
  ui_story_5036_50360801_8_dialog_content = "Juntamente com letras selvagens e naturistas escritas por um extrozoologista como eu...",
  ui_story_5036_50360801_9_dialog_content = "Não tem como não dar certo!",
  ui_story_5036_50360801_10_dialog_content = "Aham…",
  ui_story_5036_50360801_11_dialog_content = "A música não é o problema. Seu canto ainda tem muito a melhorar.",
  ui_story_5036_50360801_12_dialog_content = "Eu acho que você está colocando isso muito bem.",
  ui_story_5036_50360801_13_dialog_content = "De fato, MUITO bem.",
  ui_story_5036_50360801_14_dialog_content = "PlayerName é uma coisa, mas por que você zombaria de mim também, Srta. Repórter?",
  ui_story_5036_50360801_15_dialog_content = "Só estou falando a verdade.",
  ui_story_5036_50360801_16_dialog_content = "Brandy é uma repórter amável, objetiva e profissional.",
  ui_story_5036_50360801_17_dialog_content = "Se o seu canto não a impressionou, você deve descobrir qual é o problema.",
  ui_story_5036_50360801_18_dialog_content = "Talvez suas orelhas tenham sofrido ferimentos no passado? É por isso que você não conseguiu entender como minha voz é linda, Srta. Repórter?",
  ui_story_5036_50360801_19_dialog_content = "Não, não é para onde estou indo com isso!",
  ui_story_5036_50360801_20_dialog_content = "Hum, então, de qualquer maneira...",
  ui_story_5036_50360801_21_dialog_content = "Para cantar uma música corretamente, primeiro você deve aprender a respirar corretamente.",
  ui_story_5036_50360801_22_dialog_content = "Preciso aprender a respirar?",
  ui_story_5036_50360801_23_dialog_content = "Se você quiser ser selecionado, siga minhas instruções.",
  ui_story_5036_50360801_24_dialog_content = "Entendido, Mestre Goldie!",
  ui_story_5036_50360801_25_dialog_content = "Inspire e encha a barriga de ar como um balão. Contraia a barriga ao expirar.",
  ui_story_5036_50360801_26_dialog_content = "Esta é a técnica de respiração abdominal.",
  ui_story_5036_50360801_27_dialog_content = "Pratique por cerca de dez minutos.",
  ui_story_5036_50360801_28_dialog_content = "Isso soa como quando a Bolinha de Pelos se enrola e vai dormir.",
  ui_story_5036_50360801_29_dialog_content = "Inalar exalar...",
  ui_story_5036_50360801_30_dialog_content = "Nada mal. Desenhe por mais tempo.",
  ui_story_5036_50360801_31_dialog_content = "Innhaaaale... Exhaaaale...",
  ui_story_5036_50360801_32_dialog_content = "Muito bom. Mantem.",
  ui_story_5036_50360801_33_dialog_content = "Inalar exalar...",
  ui_story_5036_50360801_34_dialog_content = "Inalar exalar...",
  ui_story_5036_50360801_35_dialog_content = "Vic adormeceu?",
  ui_story_5036_50360801_36_dialog_content = "Zzz...",
  ui_story_5036_50360801_37_dialog_content = "Vic!",
  ui_story_5036_50360801_38_dialog_content = "Não fique brava, Fia! O que...?",
  ui_story_5036_50360801_39_dialog_content = "Ah, é Goldie. Espere, estou brincando, é o Mestre Goldie.",
  ui_story_5036_50360801_40_dialog_content = "Você deveria praticar a respiração, não adormecer.",
  ui_story_5036_50360801_41_dialog_content = "<color=#e8d9bb>Algum tempo depois</color>",
  ui_story_5036_50360801_42_dialog_content = "Depois de aprender a respirar, você pode trabalhar sua técnica vocal.",
  ui_story_5036_50360801_43_dialog_content = "Você tem uma boa voz, Vic, mas lembre-se disso!",
  ui_story_5036_50360801_44_dialog_content = "Cantar sem técnicas vocais adequadas causará danos irreversíveis às suas cordas vocais.",
  ui_story_5036_50360801_45_dialog_content = "Mas como desenvolvo uma técnica vocal adequada, Mestre Goldie?",
  ui_story_5036_50360801_46_dialog_content = "Boa pergunta.",
  ui_story_5036_50360801_47_dialog_content = "Vou te ensinar meu método super especial... Trilhos labiais!",
  ui_story_5036_50360801_48_dialog_content = "Olhe com cuidado! Aperte os lábios e depois...",
  ui_story_5036_50360801_49_dialog_content = "Brrrrrrrrr...",
  ui_story_5036_50360801_50_dialog_content = "Brrrrrrrrr...",
  ui_story_5036_50360801_51_dialog_content = "Uau, isso é muito bom. Você é um aprendiz rápido!",
  ui_story_5036_50360801_52_dialog_content = "Isso não é nada difícil para mim!",
  ui_story_5036_50360801_53_dialog_content = "Às vezes, faço esse som no campo para atrair rinocerontes de lama no cio.",
  ui_story_5036_50360801_54_dialog_content = "Brrrrrrrrr...",
  ui_story_5036_50360801_55_dialog_content = "Em um bom dia, posso atrair mais de uma dúzia de uma vez!",
  ui_story_5036_50360801_56_dialog_content = "Eu... entendi...",
  ui_story_5036_50360801_57_dialog_content = "Felizmente, estamos no céu agora.",
  ui_story_5036_50360801_58_dialog_content = "De qualquer forma, praticar isso não apenas adicionará profundidade à sua voz, mas também resolverá problemas respiratórios.",
  ui_story_5036_50360801_59_dialog_content = "Você tem menos de dois dias até a última rodada de audição.",
  ui_story_5036_50360801_60_dialog_content = "Se você leva a sério a prática, um dia é mais do que suficiente para treinar a memória muscular e melhorar o canto.",
  ui_story_5036_50360801_61_dialog_content = "Imitar o rinoceronte da lama grunhindo com os lábios melhorará meu canto?",
  ui_story_5036_50360801_62_dialog_content = "Eu deveria expandir isso e imitar outras feras maravilhosas também!",
  ui_story_5036_50360801_63_dialog_content = "Ai, ai, ai!",
  ui_story_5036_50360801_64_dialog_content = "Hai?",
  ui_story_5036_50360801_65_dialog_content = "Piu, piu, piu.",
  ui_story_5036_50360801_66_dialog_content = "Gruau?",
  ui_story_5036_50360801_67_dialog_content = "Chilro! Chirp, chirp!",
  ui_story_5036_50360801_68_dialog_content = "Chilro?",
  ui_story_5036_50360801_69_dialog_content = "A-Tudo bem, tudo bem.",
  ui_story_5036_50360801_70_dialog_content = "Apenas os rinocerontes de lama servirão.",
  ui_story_5036_50360801_71_dialog_content = "Sério? Acho que fui um pouco longe demais.",
  ui_story_5036_50360801_72_dialog_content = "O que você realmente precisa trabalhar é a sua dança.",
  ui_story_5036_50360801_73_dialog_content = "Cantar é apenas uma parte. A dança completará seu desempenho.",
  ui_story_5036_50360801_74_dialog_content = "Ainda precisamos coreografar uma rotina para sua música.",
  ui_story_5036_50360801_75_dialog_content = "Antes de fazermos isso, preciso ver como você está coordenado.",
  ui_story_5036_50360801_76_dialog_content = "Vou fazer alguns passos básicos de dança. Tente o seu melhor para acompanhar.",
  ui_story_5036_50360801_77_dialog_content = "Você pode lidar com a música, PlayerName?",
  ui_story_5036_50360801_78_dialog_content = "Sim, eu vou tocar o acompanhamento!",
  ui_story_5036_50360801_79_dialog_content = "Ok, Vic, continue com a batida!",
  ui_story_5036_50360801_80_dialog_content = "A-um, a-dois, mova seus pés!",
  ui_story_5036_50360801_81_dialog_content = "Uma vez à esquerda, uma vez à direita!",
  ui_story_5036_50360801_82_dialog_content = "Uh, esquerda... direita... Por alguma razão, de repente não consigo distinguir a esquerda da direita?!",
  ui_story_5036_50360801_83_dialog_content = "Agora, levante os braços! Faça círculos no ar!",
  ui_story_5036_50360801_84_dialog_content = "Mão esquerda para fora, puxe para trás!",
  ui_story_5036_50360801_85_dialog_content = "Mão direita para fora, puxe para trás!",
  ui_story_5036_50360801_86_dialog_content = "Pé esquerdo... Uh, você já está com a mão direita?!",
  ui_story_5036_50360801_87_dialog_content = "Não pare de mexer os pés!",
  ui_story_5036_50360801_88_dialog_content = "Não estou vendo coisas, estou?",
  ui_story_5036_50360801_89_dialog_content = "Senhorita Goldie...",
  ui_story_5036_50360801_90_dialog_content = "O ídolo mais popular de Umbraton, Miss Goldie, está realmente dançando na minha frente agora?!",
  ui_story_5036_50360801_91_dialog_content = "Nem mesmo o Cachinho Dourado mais obstinado conseguiu desfrutar de tal privilégio!",
  ui_story_5036_50360801_X91_dialog_content = "Fique calmo, deve ficar calmo... Eu ainda nem encontrei o que vim buscar aqui...",
  ui_story_5036_50360801_92_dialog_content = "Ela parece ainda mais graciosa ao lado de Vic!",
  ui_story_5036_50360801_93_dialog_content = "Eu tenho que colocar isso no filme!",
  ui_story_5036_50360801_94_dialog_content = "Abra os braços como se estivesse alcançando seus sonhos... e então puxe-os para dentro do seu peito!",
  ui_story_5036_50360801_95_dialog_content = "A-um, a-dois, mova seus pés!",
  ui_story_5036_50360801_96_dialog_content = "Acene com a mão esquerda, acene com a mão direita!",
  ui_story_5036_50360801_97_dialog_content = "*Ofegante* Já acabou?",
  ui_story_5036_50360801_98_dialog_content = "Por último, levantamos as duas mãos!",
  ui_story_5036_50360801_99_dialog_content = "Gire uma vez ao redor!",
  ui_story_5036_50360801_100_dialog_content = "Girar... Girar!",
  ui_story_5036_50360801_101_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5036_50360801_102_dialog_content = "Ai, ai... Isso doeu.",
  ui_story_5036_50360801_103_dialog_content = "Quantas vezes você já caiu hoje?",
  ui_story_5036_50360801_104_dialog_content = "Tudo bem, estou acostumada!",
  ui_story_5036_50360801_105_dialog_content = "Difícil de acreditar que você é ainda mais desajeitado do que uma criança aprendendo a andar.",
  ui_story_5036_50360801_106_dialog_content = "E você está respirando com tanta dificuldade depois de apenas algumas manobras simples... Você não se exercita regularmente?",
  ui_story_5036_50360801_107_dialog_content = "O sono conta como exercício?",
  ui_story_5036_50360801_108_dialog_content = "Isso vai ser um problema. A coordenação leva tempo para se desenvolver.",
  ui_story_5036_50360801_109_dialog_content = "<color=#e8d9bb>Mais algum tempo depois...</color>",
  ui_story_5036_50360801_110_dialog_content = "Você consegue se lembrar dos passos?",
  ui_story_5036_50360801_111_dialog_content = "Sim, é só andar por aí acenando com as mãos!",
  ui_story_5036_50360801_112_dialog_content = "Mesmo que esses sejam os passos mais básicos e simples...",
  ui_story_5036_50360801_113_dialog_content = "Eu ainda preciso que você coloque seus sentimentos nisso.",
  ui_story_5036_50360801_114_dialog_content = "Dançar com sentimentos? Eu não entendo muito disso.",
  ui_story_5036_50360801_115_dialog_content = "Vic, qual você acha que é o maior trunfo de um ídolo?",
  ui_story_5036_50360801_116_dialog_content = "A capacidade de cantar e dançar?",
  ui_story_5036_50360801_117_dialog_content = "Correto e incorreto.",
  ui_story_5036_50360801_118_dialog_content = "Saber cantar e dançar é praticamente obrigatório, sem dúvida.",
  ui_story_5036_50360801_119_dialog_content = "Mas eles são apenas um meio de transmitir suas emoções ao seu público.",
  ui_story_5036_50360801_120_dialog_content = "As coisas mais importantes para um ídolo são sua determinação e paixão inflexíveis.",
  ui_story_5036_50360801_121_dialog_content = "Você passa isso para o público através da música e da dança.",
  ui_story_5036_50360801_122_dialog_content = "Ah...",
  ui_story_5036_50360801_123_dialog_content = "<size=35>Talvez ele já tenha isso...</size>",
  ui_story_5036_50360801_124_dialog_content = "Você disse alguma coisa, mestre?",
  ui_story_5036_50360801_125_dialog_content = "*Ahem* Você deve primeiro impressionar a si mesmo antes de mover os outros.",
  ui_story_5036_50360801_126_dialog_content = "Eu disse tudo o que posso dizer. O resto é com você.",
  ui_story_5036_50360801_127_dialog_content = "Não mostrarei nenhum favoritismo durante a audição.",
  ui_story_5036_50360801_128_dialog_content = "Você só tem um dia e meio restante.",
  ui_story_5036_50360801_129_dialog_content = "Mais um dia e meio e posso retomar a busca pelo Ouroboros!",
  ui_story_5036_50360801_130_dialog_content = "*Tosse* Goldie!",
  ui_story_5036_50360801_131_dialog_content = "Muito obrigado por ter vindo no final.",
  ui_story_5036_50360801_132_dialog_content = "Sem problemas. É meu trabalho oferecer conselhos aos competidores, de qualquer maneira.",
  ui_story_5036_50360801_133_dialog_content = "Para ser honesto, pensei que você não iria ajudá-lo depois de todos os problemas que ele causou.",
  ui_story_5036_50360801_134_dialog_content = "Ele é definitivamente um encrenqueiro.",
  ui_story_5036_50360801_135_dialog_content = "Mas, seu potencial também é inegável.",
  ui_story_5036_50360801_136_dialog_content = "Se ele realmente conseguir se tornar um ídolo, isso também servirá como uma espécie de motivação para mim.",
  ui_story_5036_50360801_137_dialog_content = "Ei, vocês dois estão dizendo coisas legais sobre mim?",
  ui_story_5036_50360801_138_dialog_content = "Posso ouvir?",
  ui_story_5036_50360801_139_dialog_content = "Oh, eu quase esqueci a coisa mais importante.",
  ui_story_5036_50360801_140_dialog_content = "Para os ídolos, o condicionamento físico é a base de tudo o que você faz.",
  ui_story_5036_50360801_141_dialog_content = "Acontece que eu tenho o segredo disso. Quer saber o que é?",
  ui_story_5036_50360801_142_dialog_content = "Ei, onde você conseguiu uma gaiola cheia de Eclipsites?",
  ui_story_5036_50360801_143_dialog_content = "Eu os capturei, é claro!",
  ui_story_5036_50360801_144_dialog_content = "Ah!",
  ui_story_5036_50360801_145_dialog_content = "Seu segredo não seria lutar contra os Eclipsites, não é?",
  ui_story_5036_50360801_146_dialog_content = "Separe seus amigos maravilhosos.",
  ui_story_5036_50360801_147_dialog_content = "Você está por conta própria desta vez.",
  ui_story_5036_50360801_148_dialog_content = "O quê?",
  ui_story_5036_50360801_149_dialog_content = "Graagh!",
  ui_story_5036_50360801_150_dialog_content = "Fica longe de mim!",
  ui_story_5036_50360801_151_dialog_content = "Eu sabia que você poderia lutar contra os Eclipsites sozinho!",
  ui_story_5036_50360801_152_dialog_content = "Mas é muito cansativo!",
  ui_story_5036_50360801_153_dialog_content = "Não pare agora!",
  ui_story_5036_50360801_154_dialog_content = "Continue cantando e dançando enquanto luta!",
  ui_story_5036_50360801_155_dialog_content = "O quê?!",
  ui_story_5036_50360801_156_dialog_content = "Você é o verdadeiro diabo!",
  ui_story_5036_50360801_157_dialog_content = "Grahhhhhh!",
  ui_story_5036_50360802_1_dialog_content = "<color=#e8d9bb>Dois dias para o concerto</color>",
  ui_story_5036_50360802_2_dialog_content = "Mãos ao ar, pessoal! Vamos...",
  ui_story_5036_50360802_3_dialog_content = "Faça isso novamente!",
  ui_story_5036_50360802_4_dialog_content = "I-É mesmo o ladrão que vimos há alguns dias?",
  ui_story_5036_50360802_5_dialog_content = "Pode ser ele, mas talvez não?",
  ui_story_5036_50360802_6_dialog_content = "♪ Ah, a primavera chegou e tudo voltou à vida! ♪",
  ui_story_5036_50360802_7_dialog_content = "♪ Os animais saem de suas tocas e tocas ♪",
  ui_story_5036_50360802_8_dialog_content = "♪ Na mata e nas pradarias ♪",
  ui_story_5036_50360802_9_dialog_content = "♪ A doçura da vida é abundante ♪",
  ui_story_5036_50360802_10_dialog_content = "Eu não tenho ideia do que ele está cantando...",
  ui_story_5036_50360802_11_dialog_content = "mas a melodia é de alguma forma realmente cativante?",
  ui_story_5036_50360802_12_dialog_content = "♪ Olha, o que é isso? ♪",
  ui_story_5036_50360802_13_dialog_content = "♪ Uma Bica felpuda que adora dizer \"Hai!\" ♪",
  ui_story_5036_50360802_14_dialog_content = "Ai ai ai!",
  ui_story_5036_50360802_15_dialog_content = "Ai ai ai!",
  ui_story_5036_50360802_16_dialog_content = "♪ Olha, o que é isso? ♪",
  ui_story_5036_50360802_17_dialog_content = "♪ Uma coruja Lutumi está virando a esquina. Cuidado com os bolsos! ♪",
  ui_story_5036_50360802_18_dialog_content = "Cau ca!",
  ui_story_5036_50360802_19_dialog_content = "Cau ca cau!!",
  ui_story_5036_50360802_20_dialog_content = "Goldie, você encontrou alguém para se passar por Vic?",
  ui_story_5036_50360802_21_dialog_content = "Como assim?",
  ui_story_5036_50360802_22_dialog_content = "Quero dizer, ele melhorou aos trancos e barrancos em apenas um dia e meio!",
  ui_story_5036_50360802_23_dialog_content = "Eu nem reconheço essa pessoa diante dos meus olhos.",
  ui_story_5036_50360802_24_dialog_content = "Ele é como uma pessoa totalmente diferente!",
  ui_story_5036_50360802_25_dialog_content = "Disse que Vic tinha um grande potencial de ídolo.",
  ui_story_5036_50360802_26_dialog_content = "Ele era um diamante bruto que precisava de polimento para brilhar.",
  ui_story_5036_50360802_27_dialog_content = "A alegria do crescimento!",
  ui_story_5036_50360802_28_dialog_content = "Quem aqui entende a alegria do crescimento?",
  ui_story_5036_50360802_29_dialog_content = "Quase perfeito em canto, dança, aparência, figura, QE e QI.",
  ui_story_5036_50360802_30_dialog_content = "Finalmente, um competidor completo!",
  ui_story_5036_50360802_31_dialog_content = "Não acredito que fiquei hipnotizado com aquela performance...",
  ui_story_5036_50360802_32_dialog_content = "Perdoe-me, Deus da Luz!",
  ui_story_5036_50360802_33_dialog_content = "Sim, grande melhora.",
  ui_story_5036_50360802_34_dialog_content = "♪ Brrrrrrrr... ♪",
  ui_story_5036_50360802_35_dialog_content = "♪ Alguém viu o indescritível ovo de Ouroboros♪",
  ui_story_5036_50360802_36_dialog_content = "♪ Brrrrrrrrrr... ♪",
  ui_story_5036_50360802_37_dialog_content = "♪ Não vou parar até te encontrar ♪",
  ui_story_5036_50360802_38_dialog_content = "E isso é o fim. Obrigado a todos!",
  ui_story_5036_50360802_39_dialog_content = "Vic! Vic! Vic! Vic!",
  ui_story_5036_50360802_40_dialog_content = "Como podemos ver, todo o local foi tomado por aquela performance!",
  ui_story_5036_50360802_41_dialog_content = "Obrigado, Vic, por um show tão bom!",
  ui_story_5036_50360802_42_dialog_content = "Vamos ver o que nossos juízes têm a dizer.",
  ui_story_5036_50360802_43_dialog_content = "Senhorita Goldie, é todo seu!",
  ui_story_5036_50360802_44_dialog_content = "Não tenho nada a dizer.",
  ui_story_5036_50360802_45_dialog_content = "O que? Mas fiquei acordado para praticar por duas noites seguidas! ainda não consigo?",
  ui_story_5036_50360802_46_dialog_content = "Eu teria ficado na cama se soubesse disso.",
  ui_story_5036_50360802_47_dialog_content = "O que quero dizer é que seu desempenho foi bom demais para eu encontrar falhas.",
  ui_story_5036_50360802_48_dialog_content = "Acredito que nossos votos falarão por si.",
  ui_story_5036_50360802_49_dialog_content = "Tudo bem! Os resultados estão em.",
  ui_story_5036_50360802_50_dialog_content = "Vamos ver se Vic consegue subir no palco do show!",
  ui_story_5036_50360802_51_dialog_content = "Ele recebeu...",
  ui_story_5036_50360802_52_dialog_content = "Eu recebi...?",
  ui_story_5036_50360802_53_dialog_content = "<size=45>Uma votação unânime!</size>",
  ui_story_5036_50360802_54_dialog_content = "Seriamente? Até o novato conseguiu. A pressão está sobre uma certa pessoa.",
  ui_story_5036_50360802_55_dialog_content = "Devo cantar uma música positiva para incentivá-la?",
  ui_story_5036_50360802_56_dialog_content = "Leve sua música pop monótona de sacarina para outro lugar.",
  ui_story_5036_50360802_57_dialog_content = "Oh, mas eu ficaria tão triste e solitário se você não sobrevivesse.",
  ui_story_5036_50360802_58_dialog_content = "Você só chegou antes de mim porque se apresentou antes de mim.",
  ui_story_5036_50360802_59_dialog_content = "Espere e verá. Os jurados vão se arrepender de escolher vocês, palhaços, depois de verem minha apresentação!",
  ui_story_5036_50360802_60_dialog_content = "Como você se sente, Vik?",
  ui_story_5036_50360802_61_dialog_content = "Finalmente posso dormir um pouco...",
  ui_story_5036_50360802_62_dialog_content = "Quando eu acordo, eu...",
  ui_story_5036_50360802_63_dialog_content = "pode ir encontrar... Ourobo...",
  ui_story_5036_50360802_64_dialog_content = "Vic?",
  ui_story_5036_50360802_65_dialog_content = "Você está bem, Vick?",
  ui_story_5036_50360802_66_dialog_content = "Zzz...",
  ui_story_5036_50360802_67_dialog_content = "Ué, Vik...",
  ui_story_5036_50360802_68_dialog_content = "Por favor, não durma durante a audição!",
  ui_story_5036_50360802_69_dialog_content = "Vic realmente caiu em um sono extraordinariamente profundo, ao que parece.",
  ui_story_5036_50360802_70_dialog_content = "Nem acredito que ele dormiu o dia todo, com tanto barulho!",
  ui_story_5036_50360802_71_dialog_content = "Sim, ele nem acordou quando os mercenários o arrastaram de volta para seu quarto.",
  ui_story_5036_50360802_72_dialog_content = "Todos nós testemunhamos sua melhora.",
  ui_story_5036_50360802_73_dialog_content = "Ele devia estar exausto de praticar tanto nos últimos dois dias.",
  ui_story_5036_50360802_74_dialog_content = "Acho que vocês dois praticaram muito também.",
  ui_story_5036_50360802_75_dialog_content = "Ou você também não teria obtido um voto unânime.",
  ui_story_5036_50360802_76_dialog_content = "Oh, nós totalmente esperávamos isso!",
  ui_story_5036_50360802_77_dialog_content = "Mas sim, estou cansado.",
  ui_story_5036_50360802_78_dialog_content = "Devemos nos recolher cedo hoje.",
  ui_story_5036_50360802_79_dialog_content = "Haverá um dia inteiro de ensaios amanhã.",
  ui_story_5036_50360802_80_dialog_content = "Espero não ter outro sonho esta noite.",
  ui_story_5036_50360802_81_dialog_content = "Sim. Boa noite.",
  ui_story_5036_50360802_82_dialog_content = "Vício? Carleen?",
  ui_story_5036_50360802_83_dialog_content = "Eles saíram tão rápido...",
  ui_story_5036_50360802_84_dialog_content = "Então...",
  ui_story_5036_50360802_85_dialog_content = "Eu deveria me entregar também.",
  ui_story_5036_50360901_1_dialog_content = "Onde estou...?",
  ui_story_5036_50360901_2_dialog_content = "Em um Colosso, eu acho... Aquele é o Celestita que estava no meu sonho antes?",
  ui_story_5036_50360901_3_dialog_content = "Estou sonhando de novo?",
  ui_story_5036_50360901_4_dialog_content = "Você é o Eulogoz, certo?",
  ui_story_5036_50360901_5_dialog_content = "Sim. Você é meu novo navegador, presumo?",
  ui_story_5036_50360901_6_dialog_content = "Isso mesmo! Meu nome é Chaminade. Prazer em conhecê-la.",
  ui_story_5036_50360901_7_dialog_content = "(A localização mudou... Parece ser a ponte?)",
  ui_story_5036_50360901_8_dialog_content = "Por que você tem tantas telas e sistemas de som esquisitos, Eulogoz?",
  ui_story_5036_50360901_9_dialog_content = "Eu perguntei aos meus amigos, e eles nunca viram nada parecido em outros Colossi antes.",
  ui_story_5036_50360901_10_dialog_content = "Nem eu sei a resposta para essa pergunta.",
  ui_story_5036_50360901_11_dialog_content = "Há muito tempo memórias escapam de mim como cantar ao vento.",
  ui_story_5036_50360901_12_dialog_content = "Que pena...",
  ui_story_5036_50360901_13_dialog_content = "Mas todo mundo te ama!",
  ui_story_5036_50360901_14_dialog_content = "Somente você pode fazer a música reverberar em Eraveil.",
  ui_story_5036_50360901_15_dialog_content = "Obrigada. Estou muito feliz em ouvir isso.",
  ui_story_5036_50360901_16_dialog_content = "Vamos viajar, Eulogoz!",
  ui_story_5036_50360901_17_dialog_content = "Hum? Por que tão repentino?",
  ui_story_5036_50360901_18_dialog_content = "Meus professores dizem que muitos no Astra ainda sofrem com a guerra e os Eclipsites.",
  ui_story_5036_50360901_19_dialog_content = "A vida deles é desesperadora e difícil, então eu quero cantar para eles!",
  ui_story_5036_50360901_20_dialog_content = "Eu sei que meu canto não pode derrotar os Eclipsites ou fornecer-lhes algo de útil...",
  ui_story_5036_50360901_21_dialog_content = "mas, pelo menos, posso dar a eles algo para ouvir além de tiros.",
  ui_story_5036_50360901_22_dialog_content = "Lugares como esse são muito perigosos para você.",
  ui_story_5036_50360901_23_dialog_content = "Eu sei, mas se meu canto pode lhes dar um pouco de conforto e esperança, qualquer perigo vale a pena.",
  ui_story_5036_50360901_24_dialog_content = "Entendi.",
  ui_story_5036_50360901_25_dialog_content = "Vamos agora.",
  ui_story_5036_50360901_26_dialog_content = "Outro sonho? Mas parece diferente... mais como uma memória.",
  ui_story_5036_50360901_27_dialog_content = "Então o nome da garota celestita é Chaminade.",
  ui_story_5036_50360901_28_dialog_content = "A menos que aquele sonho fosse eu sentindo os vestígios persistentes de sua presença neste Colosso.",
  ui_story_5036_50360901_29_dialog_content = "Uma caelestita cantora cavalgando um Colossus, viajando por Astra... Ela se parece muito com Goldie.",
  ui_story_5036_50360901_30_dialog_content = "*Bocejo* Com certeza sonhei muito por apenas uma hora de sono.",
  ui_story_5036_50360901_31_dialog_content = "Não vou conseguir voltar a dormir por um tempo... talvez eu devesse comer alguma coisa.",
  ui_story_5036_50360901_32_dialog_content = "<color=#e8d9bb>Toc, toc!</color>",
  ui_story_5036_50360901_33_dialog_content = "(Quem está batendo tão tarde da noite?)",
  ui_story_5036_50360901_34_dialog_content = "Tô indo!",
  ui_story_5036_50360901_35_dialog_content = "Desculpe, PlayerName, eu te acordei?",
  ui_story_5036_50360901_36_dialog_content = "Não, eu estava acordado... O que você está fazendo aqui, Goldie?",
  ui_story_5036_50360901_37_dialog_content = "Preciso da tua ajuda. O futuro de todo o show depende disso!",
  ui_story_5036_50360901_38_dialog_content = "Tão sério? O Eulogoz está travando?",
  ui_story_5036_50360901_39_dialog_content = "Não, não é tão ruim... Você teve um sonho estranho ultimamente?",
  ui_story_5036_50360901_40_dialog_content = "Um sonho de um vasto vale e o som de uma menina cantando.",
  ui_story_5036_50360901_41_dialog_content = "Sim eu tenho. Por alguma razão, tenho tido esse sonho todas as noites.",
  ui_story_5036_50360901_42_dialog_content = "O vale é Eraveil, e a garota é uma Caelestita.",
  ui_story_5036_50360901_43_dialog_content = "Então ela é uma Celestita?!",
  ui_story_5036_50360901_44_dialog_content = "A maneira como ela estava vestida não o denunciava?",
  ui_story_5036_50360901_45_dialog_content = "O sonho é estranho, mas não dei muita atenção porque não é um pesadelo.",
  ui_story_5036_50360901_46_dialog_content = "Espere, nós não conversamos sobre isso antes e consideramos isso uma coincidência?",
  ui_story_5036_50360901_47_dialog_content = "Foi o que eu pensei também, mas agora todos no Colossus tiveram o mesmo sonho!",
  ui_story_5036_50360901_48_dialog_content = "Todos?!",
  ui_story_5036_50360901_49_dialog_content = "Sim. É coincidência quando são duas ou três pessoas, mas não quando são todos!",
  ui_story_5036_50360901_50_dialog_content = "Tem deixado todos ansiosos.",
  ui_story_5036_50360901_51_dialog_content = "Concorrentes vêm até mim reclamando que o sonho está atrapalhando seu sono.",
  ui_story_5036_50360901_52_dialog_content = "Eles não podem executar corretamente sem descanso adequado.",
  ui_story_5036_50360901_53_dialog_content = "Então você quer chegar à raiz do problema para garantir um descanso adequado para todos?",
  ui_story_5036_50360901_54_dialog_content = "Sim. Eu mesmo tentei investigar, mas sem sucesso, já que não tenho suas habilidades psíquicas.",
  ui_story_5036_50360901_55_dialog_content = "Pode me ajudar, PlayerName?",
  ui_story_5036_50360901_56_dialog_content = "Pelo bem do show, definitivamente!",
  ui_story_5036_50360901_57_dialog_content = "Obrigada!",
  ui_story_5036_50360901_58_dialog_content = "Mas dado o tamanho de Eulogoz, não posso cobrir toda a estrutura nem com minha telepatia.",
  ui_story_5036_50360901_59_dialog_content = "Por onde devemos começar?",
  ui_story_5036_50360901_60_dialog_content = "Não sei mesmo.",
  ui_story_5036_50360901_61_dialog_content = "Sugiro começar pela parte de trás!",
  ui_story_5036_50360901_62_dialog_content = "Vic! De onde você veio?",
  ui_story_5036_50360901_63_dialog_content = "O concerto é daqui a dois dias! Você não deveria estar praticando?",
  ui_story_5036_50360901_64_dialog_content = "Vamos, você não estava apenas estressado com o sonho estranho?",
  ui_story_5036_50360901_65_dialog_content = "Você precisa primeiro ter um sono de qualidade para ter energia para praticar.",
  ui_story_5036_50360901_66_dialog_content = "Isso é verdade, mas ouvir isso da sua boca é suspeito.",
  ui_story_5036_50360901_67_dialog_content = "Hahaha! Você está apenas sendo paranóico.",
  ui_story_5036_50360901_68_dialog_content = "É suspeito ver você sendo tão proativo.",
  ui_story_5036_50360901_69_dialog_content = "Eu me lembro agora! Você está querendo procurar o Ouroboros por lá. Você definitivamente tem um motivo oculto!",
  ui_story_5036_50360901_70_dialog_content = "Como você pôde dizer isso? Quanto mais melhor. Você não tem nada a perder deixando-me acompanhá-lo.",
  ui_story_5036_50360901_71_dialog_content = "Ok, mas estarei de olho em você no treino de amanhã, então não tente relaxar.",
  ui_story_5036_50360901_72_dialog_content = "Extrozoologistas não mentem.",
  ui_story_5036_50360901_73_dialog_content = "Mas, por enquanto, vamos nos concentrar em lidar com o sonho estranho.",
  ui_story_5036_50360901_74_dialog_content = "(É suspeito que Vic esteja tão interessado nisso.)",
  ui_story_5036_50360901_75_dialog_content = "(O que ele está fazendo?)",
  ui_story_5036_50360901_76_dialog_content = "A seção traseira... Não é lá que os Eclipsites estão contidos?",
  ui_story_5036_50360901_77_dialog_content = "Existe alguma evidência que sugira que devemos começar com um lugar tão perigoso?",
  ui_story_5036_50360901_78_dialog_content = "Nenhum mesmo!",
  ui_story_5036_50360901_79_option_content = "Vamos ignorá-lo",
  ui_story_5036_50360901_80_dialog_content = "Oh vamos lá, PlayerName, já trabalhamos juntos antes. Não seja tão sem coração!",
  ui_story_5036_50360901_81_option_content = "...",
  ui_story_5036_50360901_82_dialog_content = "...",
  ui_story_5036_50360901_83_dialog_content = "Os jovens ficam tão facilmente abalados porque há muita coisa que eles não viram.",
  ui_story_5036_50360901_84_dialog_content = "Não tenho provas concretas, mas minha sugestão não era infundada.",
  ui_story_5036_50360901_85_dialog_content = "As seções superiores estão todas livres de Eclipsites, então todos podem se movimentar livremente.",
  ui_story_5036_50360901_86_dialog_content = "Naturalmente, isso significa que essas áreas praticamente não precisam ser investigadas.",
  ui_story_5036_50360901_87_dialog_content = "Verdadeiro. Alguém já teria notado que algo estava errado.",
  ui_story_5036_50360901_88_dialog_content = "Então isso deixa apenas a seção traseira.",
  ui_story_5036_50360901_89_dialog_content = "Mas há muitos Eclipsites lá. É muito arriscado com apenas nós três.",
  ui_story_5036_50360901_90_dialog_content = "Eu pensei nisso também. Só precisamos de Lutumi Owl para ajudar.",
  ui_story_5036_50360901_91_dialog_content = "Deixe-o colocar os Eclipsites para dormir antes de nos esgueirarmos. Isso deve minimizar a necessidade de lutar.",
  ui_story_5036_50360901_92_dialog_content = "Foi assim que você roubou todas aquelas coisas antes?",
  ui_story_5036_50360901_93_dialog_content = "Claro que não!",
  ui_story_5036_50360901_94_dialog_content = "De qualquer forma, foi a coruja que causou todo aquele mal-entendido.",
  ui_story_5036_50360901_95_dialog_content = "Agora, vamos deixar isso compensar o problema. Como é isso?",
  ui_story_5036_50360901_96_dialog_content = "Vamos discutir esse assunto depois do show.",
  ui_story_5036_50360901_97_dialog_content = "Vic tem um ponto, no entanto. Vamos começar com a extremidade traseira do Colossus.",
  ui_story_5036_50360901_98_dialog_content = "OK, vamos lá.",
  ui_story_5036_50360901_99_dialog_content = "Eu ia falar com a Goldie sobre os rumores de que ela era má...",
  ui_story_5036_50360901_100_dialog_content = "mas agora os três estão fazendo algo secreto!",
  ui_story_5036_50360901_101_dialog_content = "Felizmente, eu estava muito longe para PlayerName para me sentir com sua habilidade!",
  ui_story_5036_50360901_102_dialog_content = "Eles estavam muito longe para eu ouvi-los claramente embora...",
  ui_story_5036_50360901_103_dialog_content = "Não é... onde fica a parte traseira?",
  ui_story_5036_50360901_104_dialog_content = "Eles estão agindo de forma muito suspeita para eu não seguir!",
  ui_story_5036_50360901_105_dialog_content = "Está tão escuro aqui... Parece que os Eclipsites vão aparecer a qualquer segundo.",
  ui_story_5036_50360901_106_dialog_content = "Relaxe e deixe tudo para Lutumi Owl. Olhar.",
  ui_story_5036_50360901_107_dialog_content = "Cau ca!",
  ui_story_5036_50360901_108_dialog_content = "(Eclipsian) L-Lady Forsakin?!",
  ui_story_5036_50360901_109_dialog_content = "Cau ca cau!!",
  ui_story_5036_50360901_110_dialog_content = "(Eclipsiano) Obrigado pelo elogio. Vou trabalhar mais!",
  ui_story_5036_50360901_111_dialog_content = "(Eclipsian) Nem acredito que fui elogiado... Tão estranho... tão sonolento...",
  ui_story_5036_50360901_112_dialog_content = "(Eclipsiano) Bocejo...",
  ui_story_5036_50360901_113_dialog_content = "Ver? Mole-mole.",
  ui_story_5036_50360901_114_dialog_content = "Tem certeza de que isso não conta como exploração do animal por seu poder?",
  ui_story_5036_50360901_115_dialog_content = "Lutumi Coruja é minha amiga. Está me ajudando de bom grado. Estou certo disso.",
  ui_story_5036_50360901_116_dialog_content = "Está muito escuro aqui...",
  ui_story_5036_50360901_117_dialog_content = "*choraminga* Não! Eu tenho que continuar!",
  ui_story_5036_50360901_118_dialog_content = "Você está bem, Goldie?",
  ui_story_5036_50360901_119_dialog_content = "Huh? Estou totalmente bem!",
  ui_story_5036_50360901_120_dialog_content = "Por que um ídolo não estaria bem? Só estou um pouco cansado e preciso de uma pausa.",
  ui_story_5036_50360901_121_dialog_content = "Deixe-me abraçar você, Marshmallow.",
  ui_story_5036_50360901_122_dialog_content = "Uau...",
  ui_story_5036_50360901_123_dialog_content = "Tão macio e felpudo... Ok, estou pronto agora!",
  ui_story_5036_50360901_124_dialog_content = "Vamos continuar!",
  ui_story_5036_50360901_125_dialog_content = "(Goldie está agindo de forma estranha. Ela tem medo do escuro?)",
  ui_story_5036_50360901_126_dialog_content = "Estamos andando há tanto tempo... Já deveríamos estar perto da cauda do Colosso.",
  ui_story_5036_50360901_X126_dialog_content = "Você pode sentir qualquer coisa por perto, PlayerName?",
  ui_story_5036_50360901_127_dialog_content = "Deixe-me ver.",
  ui_story_5036_50360901_128_option_content = "Aumento de Força!",
  ui_story_5036_50360901_129_dialog_content = "(Não há nada além de Eclipsites adormecidos por aí.)",
  ui_story_5036_50360901_130_dialog_content = "(Exceto que algo parece errado ... estou sendo paranóico?)",
  ui_story_5036_50360901_131_dialog_content = "(Espere, isso parece...)",
  ui_story_5036_50360901_132_dialog_content = "(É muito parecido com quando senti as emoções persistentes dos Caelestitas quando voltei para Eraveil pela primeira vez!)",
  ui_story_5036_50360901_133_dialog_content = "(Deixe-me tentar cavar mais fundo.)",
  ui_story_5036_50360901_134_dialog_content = "Uau! O-O que é isso, Eulogoz?",
  ui_story_5036_50360901_135_dialog_content = "Não entre em pânico, Chaminade, não é um Eclipsite.",
  ui_story_5036_50360901_136_dialog_content = "Segundo meus dados, é um animal chamado Ouroboros. É muito amigável com aurorianos e celestitas.",
  ui_story_5036_50360901_137_dialog_content = "Graças a Deus não é um Eclipsite.",
  ui_story_5036_50360901_138_dialog_content = "Cree, cree!",
  ui_story_5036_50360901_139_dialog_content = "Hee, pare de lamber meu rosto!",
  ui_story_5036_50360901_140_dialog_content = "Sente alguma coisa, PlayerName?",
  ui_story_5036_50360901_141_dialog_content = "Afinal, o nome dela é Chaminade...",
  ui_story_5036_50360901_142_dialog_content = "Chamada? Você está falando daquela garota celestita?",
  ui_story_5036_50360901_143_dialog_content = "Sim. Eu senti traços persistentes dela, e...",
  ui_story_5036_50360901_144_dialog_content = "o Ouroboros também!",
  ui_story_5036_50360901_145_dialog_content = "O quê?!",
  ui_story_5036_50360901_146_dialog_content = "Você sentiu o Ouroboros? Rápido, conte-me mais!",
  ui_story_5036_50360901_147_dialog_content = "Pare de me sacudir e solte antes que eu vomite!",
  ui_story_5036_50360901_148_dialog_content = "Fale primeiro, depois eu deixo ir.",
  ui_story_5036_50360901_149_dialog_content = "O que senti não foi um Ouroboros do presente, mas do passado!",
  ui_story_5036_50360901_150_dialog_content = "O passado?",
  ui_story_5036_50360901_151_dialog_content = "A ex-proprietária deste Colosso e a garota caelestita com quem todos sonham, seu nome era Chaminade.",
  ui_story_5036_50360901_152_dialog_content = "Era uma vez, ela conheceu um Ouroboros e o deixou ficar a bordo.",
  ui_story_5036_50360901_153_dialog_content = "Mas suponho que isso aconteceu há pelo menos cem anos.",
  ui_story_5036_50360901_154_dialog_content = "O Ouroboros que você está procurando provavelmente já se foi há muito tempo.",
  ui_story_5036_50360901_155_dialog_content = "Ai...",
  ui_story_5036_50360901_156_dialog_content = "Diga, que tal me deixar ir?",
  ui_story_5036_50360901_157_dialog_content = "Bem, você não conseguiu um local, mas ainda é uma informação valiosa.",
  ui_story_5036_50360901_158_dialog_content = "Ajude-me jovem celestita, continue usando seus sentidos!",
  ui_story_5036_50360901_159_dialog_content = "Considere isso me pagando por todo o perigo que minha querida aluna Fia sofreu por sua causa!",
  ui_story_5036_50360901_160_dialog_content = "Pagando VOCÊ de volta?!",
  ui_story_5036_50360901_161_dialog_content = "Pare! Não deveríamos estar resolvendo o problema do sonho agora?",
  ui_story_5036_50360901_162_dialog_content = "Quando nosso objetivo passou a ser encontrar o Ouroboros?",
  ui_story_5036_50360901_163_dialog_content = "Oh sim, eu quase fui desviado!",
  ui_story_5036_50360901_164_dialog_content = "Jovens, vocês estão olhando para isso da maneira errada.",
  ui_story_5036_50360901_165_dialog_content = "Você não disse que a Celestita com o Ouroboros era a garota dos nossos sonhos?",
  ui_story_5036_50360901_166_dialog_content = "Sim... E devemos centrar nossa investigação nela, independentemente disso.",
  ui_story_5036_50360901_167_dialog_content = "Bem, eu só peço que você fique de olho nas pistas do Ouroboros nesse ínterim.",
  ui_story_5036_50360901_168_dialog_content = "Por que sinto que estou lhe dando trabalho de graça?",
  ui_story_5036_50360901_169_dialog_content = "Não é mão de obra gratuita. Mostrar respeito pelos mais velhos é uma boa virtude.",
  ui_story_5036_50360901_170_dialog_content = "Você realmente pensa em alguma coisa, não é...",
  ui_story_5036_50360901_171_dialog_content = "Por que, obrigado.",
  ui_story_5036_50360901_172_dialog_content = "Nós precisamos PlayerName para investigar o sonho.",
  ui_story_5036_50360901_173_dialog_content = "Você se importaria de sentir novamente em outro lugar para ver se consegue encontrar mais vestígios remanescentes?",
  ui_story_5036_50360901_174_dialog_content = "Talvez possamos examiná-los e descobrir a origem dos sonhos.",
  ui_story_5036_50360901_175_dialog_content = "Claro, vou tentar!",
  ui_story_5036_50360901_176_dialog_content = "Eu nunca estive aqui antes.",
  ui_story_5036_50360901_177_dialog_content = "Estamos mais perto da seção traseira do que antes, então devemos encontrar algo novo.",
  ui_story_5036_50360901_178_dialog_content = "Goldie, Vic, vocês sentem algo estranho sobre este lugar?",
  ui_story_5036_50360901_179_dialog_content = "Está um pouco frio. Talvez por causa do Darkflow?",
  ui_story_5036_50360901_180_dialog_content = "Não, não estou sentindo muito Darkflow. Eu apenas me sinto ansioso por algum motivo.",
  ui_story_5036_50360901_181_dialog_content = "Você não tem medo do escuro, tem?",
  ui_story_5036_50360901_182_dialog_content = "É claro que não!",
  ui_story_5036_50360901_183_dialog_content = "Não é nada para se envergonhar.",
  ui_story_5036_50360901_184_dialog_content = "Shira tinha medo do escuro quando era jovem. O vento iria assustá-la em lágrimas à noite!",
  ui_story_5036_50360901_185_dialog_content = "Além de caçar pássaros, um Drakolion também pode... Achoo!",
  ui_story_5036_50360901_186_dialog_content = "... Também pode espirrar?",
  ui_story_5036_50360901_187_dialog_content = "Não, não... Acho!",
  ui_story_5036_50360901_188_dialog_content = "Eu só precisava espirrar de repente.",
  ui_story_5036_50360901_189_dialog_content = "Você pegou um resfriado?",
  ui_story_5036_50360901_190_dialog_content = "Não. Acho que Vic está falando mal de mim em algum lugar.",
  ui_story_5036_50360901_191_dialog_content = "Vou interrogá-lo sobre isso quando ele voltar.",
  ui_story_5036_50360901_192_dialog_content = "Você está mentindo de novo?",
  ui_story_5036_50360901_193_dialog_content = "Sem chance. Pergunte a Shira se você não acredita.",
  ui_story_5036_50360901_194_dialog_content = "Não importa, tenho coisas melhores para fazer.",
  ui_story_5036_50360901_X194_dialog_content = "Parece haver algumas emoções ainda por aqui. Vou tentar senti-los.",
  ui_story_5036_50360901_195_option_content = "Mindlink!",
  ui_story_5036_50360901_196_dialog_content = "♪ Gotas de orvalho, capturando o amanhecer dourado ♪",
  ui_story_5036_50360901_197_dialog_content = "♪ Brilhe sempre tão timidamente ♪",
  ui_story_5036_50360901_198_dialog_content = "(É a música para começar o Colossus!)",
  ui_story_5036_50360901_199_dialog_content = "Kree, kree... kree!",
  ui_story_5036_50360901_200_dialog_content = "Ouroboros? Você não estava dormindo? O que você está fazendo aqui?",
  ui_story_5036_50360901_201_dialog_content = "Kree—♪ Kree—♪",
  ui_story_5036_50360901_202_dialog_content = "Você está cantando?! A música que eu estava cantando?!",
  ui_story_5036_50360901_203_dialog_content = "Você entende minha música?!",
  ui_story_5036_50360901_204_dialog_content = "Kree— ♪ Kree, kree, kree ♪",
  ui_story_5036_50360901_205_dialog_content = "Isso é uma afirmação?!",
  ui_story_5036_50360901_206_dialog_content = "Que incrível, a criatura podia se comunicar usando a melodia que os Celestitas usam para controlar os Colossos.",
  ui_story_5036_50360901_207_dialog_content = "sinto outra coisa...",
  ui_story_5036_50360901_208_dialog_content = "Essas memórias estão chegando a mim apenas em pedaços e fragmentos.",
  ui_story_5036_50360901_209_dialog_content = "O que é isso? Diga-me!",
  ui_story_5036_50360901_210_dialog_content = "Eles mencionam algo sobre os sonhos estranhos?",
  ui_story_5036_50360901_211_dialog_content = "Não.",
  ui_story_5036_50360901_212_dialog_content = "Sinto a agradável surpresa de Chaminade ao descobrir por acaso o segredo do Ouroboros.",
  ui_story_5036_50360901_213_dialog_content = "Essas criaturas parecem ser capazes de transmitir emoções e se comunicar com as pessoas usando as melodias para controlar os Colossos.",
  ui_story_5036_50360901_214_dialog_content = "Essa é uma informação completamente nova referente ao Ouroboros!",
  ui_story_5036_50360901_215_dialog_content = "Excelente! Eu não tenho nada para recompensá-lo com embora.",
  ui_story_5036_50360901_216_dialog_content = "...",
  ui_story_5036_50360901_217_dialog_content = "Você sabe, os livros antigos mencionam uma conexão misteriosa entre esta espécie e os Colossos.",
  ui_story_5036_50360901_218_dialog_content = "Não podemos descartar a possibilidade de que talvez eles também possuíssem certas habilidades psíquicas.",
  ui_story_5036_50360901_219_dialog_content = "Por exemplo... fazer as pessoas sonharem.",
  ui_story_5036_50360901_220_dialog_content = "Você acha?!",
  ui_story_5036_50360901_221_dialog_content = "Eu realmente vou te punir desta vez se você estiver mentindo!",
  ui_story_5036_50360901_222_dialog_content = "eu não ousaria!",
  ui_story_5036_50360901_223_dialog_content = "É apenas uma teoria. Não posso garantir que estou certo.",
  ui_story_5036_50360901_224_dialog_content = "Que dúvida...",
  ui_story_5036_50360901_225_dialog_content = "O que você acha, PlayerName?",
  ui_story_5036_50360901_226_option_content = "Acredite Vic",
  ui_story_5036_50360901_227_dialog_content = "Enquanto Vic geralmente mente muito e não é muito confiável...",
  ui_story_5036_50360901_228_dialog_content = "ele realmente é uma autoridade absoluta em todas as coisas relacionadas às bestas maravilhosas.",
  ui_story_5036_50360901_229_dialog_content = "Não deveria ser um problema confiar nele nessa área.",
  ui_story_5036_50360901_230_dialog_content = "Na verdade, você deve sempre ouvir os mais velhos.",
  ui_story_5036_50360901_231_dialog_content = "Tudo bem, confio no julgamento de PlayerName.",
  ui_story_5036_50360901_232_option_content = "Não acredite Vik",
  ui_story_5036_50360901_233_dialog_content = "Meu conselho é não ouvi-lo, porque ele quase nunca diz a verdade.",
  ui_story_5036_50360901_234_dialog_content = "Oh, meu pobre velho coração... *Solução*",
  ui_story_5036_50360901_235_dialog_content = "Simples assim, você vê? Ele chora que é um homem velho em um segundo, depois diz que terá 18 anos para sempre no próximo.",
  ui_story_5036_50360901_236_dialog_content = "Vocês malucos não entendem. Chama-se ser jovem de coração.",
  ui_story_5036_50360901_237_dialog_content = "Definitivamente não é confiável.",
  ui_story_5036_50360901_238_dialog_content = "Suspirar!",
  ui_story_5036_50360901_239_dialog_content = "No entanto, não temos escolha a não ser seguir essa única pista que temos.",
  ui_story_5036_50360901_240_dialog_content = "Então só podemos continuar? Suspiro, mas ainda assim, acho que não podemos desistir tão facilmente.",
  ui_story_5036_50360901_241_dialog_content = "Vamos ver o que mais podemos encontrar.",
  ui_story_5036_50360901_242_dialog_content = "Eles continuam parando, o que eles estão fazendo?",
  ui_story_5036_50360901_243_dialog_content = "Agora que percebi, esta é a área de bloqueio, não é? Tão escuro e assustador...",
  ui_story_5036_50360901_244_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5036_50360901_245_dialog_content = "Eh?! W-foi o vento? Eu provavelmente deveria voltar e perguntar a Goldie outro dia...",
  ui_story_5036_50360901_246_dialog_content = "Não, Brandy, você é um repórter em busca da verdade. Você não pode desistir agora!",
  ui_story_5036_50360901_247_dialog_content = "Eu tenho que acompanhá-los!",
  ui_story_5036_50360901_248_dialog_content = "Há quanto tempo estamos caminhando? Vinte minutos?",
  ui_story_5036_50360901_249_dialog_content = "Os corredores aqui são labirínticos. Estamos apenas dando voltas e mais voltas.",
  ui_story_5036_50360901_250_dialog_content = "Você não deveria liderar, PlayerName, desde que você viveu em um Colossus por tanto tempo?",
  ui_story_5036_50360901_251_dialog_content = "Só conheço o Soroz, esse aqui não.",
  ui_story_5036_50360901_252_dialog_content = "Verdadeiro. Que tal tentar suas habilidades psíquicas?",
  ui_story_5036_50360901_253_dialog_content = "Se os vestígios daquele celestita ainda estiverem por aí, isso pode nos guiar.",
  ui_story_5036_50360901_254_dialog_content = "Isso é uma ideia. Deixe-me tentar.",
  ui_story_5036_50360901_255_option_content = "Mindlink!",
  ui_story_5036_50360901_256_dialog_content = "Oh não, Eulogoz!",
  ui_story_5036_50360901_257_dialog_content = "Veja o que aconteceu com o Ouroboros!",
  ui_story_5036_50360901_258_dialog_content = "*Soluço* O que aconteceu com ele? Acabou para sempre?",
  ui_story_5036_50360901_259_dialog_content = "Sem ela, não teríamos sido capazes de escapar de todos os ataques do Eclipsite...",
  ui_story_5036_50360901_260_dialog_content = "Não entre em pânico, Chaminade.",
  ui_story_5036_50360901_261_dialog_content = "Os Ouroboros são criaturas de longevidade. Eles se transformam em ovos quando envelhecem, incubam novamente e depois renascem.",
  ui_story_5036_50360901_262_dialog_content = "Ele confia em você para protegê-lo quando está em seu momento mais fraco. É por isso que escolheu se tornar um ovo aqui.",
  ui_story_5036_50360901_263_dialog_content = "Espere um pouco e ele poderá viajar ao seu lado novamente.",
  ui_story_5036_50360901_264_dialog_content = "Sério?",
  ui_story_5036_50360901_265_dialog_content = "Isso é ótimo! Então os Ouroboros não morreram e ainda podemos ficar juntos.",
  ui_story_5036_50360901_266_dialog_content = "Eu o protegerei. Que tal agora? Vamos colocar o ovo na sala mais segura!",
  ui_story_5036_50360901_267_dialog_content = "Nenhum Eclipsite pode chegar perto então!",
  ui_story_5036_50360901_268_dialog_content = "Eu vejo isso! Excepcionalmente claro desta vez!",
  ui_story_5036_50360901_269_dialog_content = "Chaminade disse que colocou o ovo na sala mais fortificada do Colosso.",
  ui_story_5036_50360901_X269_dialog_content = "Ela correu naquela direção.",
  ui_story_5036_50360901_270_dialog_content = "Vamos lá! Podemos encontrar algo novo.",
  ui_story_5036_50360901_271_dialog_content = "Já se passaram anos. Qualquer pista já teria esfriado.",
  ui_story_5036_50360901_272_dialog_content = "Não importa, vamos embora.",
  ui_story_5036_50361001_1_dialog_content = "Estamos caminhando há algum tempo. Como é que ainda não chegamos àquela sala?",
  ui_story_5036_50361001_2_dialog_content = "Eulogoz é enorme, mas ainda deveríamos estar lá agora.",
  ui_story_5036_50361001_3_dialog_content = "A menos que estejamos andando em círculos esse tempo todo?",
  ui_story_5036_50361001_4_dialog_content = "Não faço ideia, mas isso está se tornando cada vez mais insuportável.",
  ui_story_5036_50361001_5_dialog_content = "Este lugar é assustador e me dá arrepios.",
  ui_story_5036_50361001_6_dialog_content = "Muitas vezes me perco e ando em círculos na selva.",
  ui_story_5036_50361001_7_dialog_content = "O jeito é deixar rastro!",
  ui_story_5036_50361001_8_dialog_content = "Boa ideia. Alguém tem algo para escrever?",
  ui_story_5036_50361001_9_dialog_content = "Não!",
  ui_story_5036_50361001_10_dialog_content = "Nem eu, mas trouxe isto.",
  ui_story_5036_50361001_11_dialog_content = "Cartazes para o concerto? Você trouxe isso com você?",
  ui_story_5036_50361001_12_dialog_content = "Muitos fãs chegam e pedem autógrafos, mas nem sempre têm algo em mãos para eu assinar.",
  ui_story_5036_50361001_13_dialog_content = "Trago cartazes para eles assinarem, para que não fiquem desapontados.",
  ui_story_5036_50361001_14_dialog_content = "Muito atencioso de sua parte!",
  ui_story_5036_50361001_15_dialog_content = "Ser atencioso com os fãs é um dos trabalhos mais básicos de um ídolo!",
  ui_story_5036_50361001_16_dialog_content = "Cartazes, né? Definitivamente um rastreador muito perceptível.",
  ui_story_5036_50361001_17_dialog_content = "De qualquer forma, vou colocar um aqui. Vamos continuar!",
  ui_story_5036_50361001_18_dialog_content = "<color=#e8d9bb>Algum tempo depois</color>",
  ui_story_5036_50361001_19_dialog_content = "Já faz um tempo, mas nada ao nosso redor parece ter mudado.",
  ui_story_5036_50361001_20_dialog_content = "Ei, esse não é o pôster que Goldie colocou?",
  ui_story_5036_50361001_21_dialog_content = "Isso é! Nós realmente estamos apenas vagando em círculos!",
  ui_story_5036_50361001_22_dialog_content = "Espere, algo está errado com este pôster...",
  ui_story_5036_50361001_23_dialog_content = "Por que o cabelo de Goldie está escuro neste pôster? E a expressão dela não parece natural...",
  ui_story_5036_50361001_24_dialog_content = "H-Como isso pode acontecer? Alguém está pregando uma peça?",
  ui_story_5036_50361001_25_dialog_content = "Esta é uma área desconhecida na seção traseira. Ninguém mais deveria estar aqui além de nós três.",
  ui_story_5036_50361001_26_dialog_content = "Não me diga que...",
  ui_story_5036_50361001_27_option_content = "Estamos sendo seguidos?!",
  ui_story_5036_50361001_28_dialog_content = "Um fã excessivamente zeloso, talvez? Ou um canalha empenhado em sabotar o show?",
  ui_story_5036_50361001_29_dialog_content = "Independentemente disso, isso é bastante assustador ...",
  ui_story_5036_50361001_30_dialog_content = "Devemos sair daqui.",
  ui_story_5036_50361001_31_option_content = "Eclipses?!",
  ui_story_5036_50361001_32_dialog_content = "Mas a Coruja Lutumi não os colocou para dormir?",
  ui_story_5036_50361001_33_dialog_content = "Eles ainda devem estar fora.",
  ui_story_5036_50361001_34_dialog_content = "Este lugar simplesmente não parece certo. Vamos nos apressar e sair daqui.",
  ui_story_5036_50361001_35_dialog_content = "Mas para que lado?",
  ui_story_5036_50361001_36_dialog_content = "Basta escolher uma direção e seguir em frente!",
  ui_story_5036_50361001_37_dialog_content = "Vamos por aqui!",
  ui_story_5036_50361001_38_dialog_content = "Ei, desacelere para este velho!",
  ui_story_5036_50361001_39_dialog_content = "Desacelerar!",
  ui_story_5036_50361001_40_dialog_content = "S-Algo está estranho neste pôster.",
  ui_story_5036_50361001_41_dialog_content = "Ei, espere!",
  ui_story_5036_50361001_42_dialog_content = "*Ofegante* Hmm, isso é diferente dos corredores em que estávamos.",
  ui_story_5036_50361001_43_dialog_content = "Poderia ser este o quarto de que Chaminade falou?",
  ui_story_5036_50361001_44_dialog_content = "Parece muito sólido, embora a parede ainda esteja em frangalhos devido a anos de abandono.",
  ui_story_5036_50361001_45_dialog_content = "Também parece ainda mais assustador aqui. Eu realmente não quero ficar por aqui...",
  ui_story_5036_50361001_46_dialog_content = "Eu continuo sentindo que os Eclipsites vão aparecer a qualquer segundo.",
  ui_story_5036_50361001_47_dialog_content = "*Sons de farfalhar*",
  ui_story_5036_50361001_48_dialog_content = "Quem tá aí?!",
  ui_story_5036_50361001_49_dialog_content = "Mostre-se!",
  ui_story_5036_50361001_50_dialog_content = "Sou eu! Não me bata!",
  ui_story_5036_50361001_51_dialog_content = "Não estou falando de você!",
  ui_story_5036_50361001_52_dialog_content = "Hã?",
  ui_story_5036_50361001_53_dialog_content = "Brandy? O que você está fazendo aqui? Espere, cuidado!",
  ui_story_5036_50361001_54_dialog_content = "Graaaaaah!",
  ui_story_5036_50361001_55_dialog_content = "Pato!",
  ui_story_5036_50361001_56_dialog_content = "Douradinho?!",
  ui_story_5036_50361001_57_dialog_content = "(Goldie acabou de salvar minha vida!)",
  ui_story_5036_50361001_58_dialog_content = "Eu não vou deixar você machucar ninguém na minha presença!",
  ui_story_5036_50361001_59_dialog_content = "Prepare-se para o que está vindo para você!",
  ui_story_5036_50361001_60_dialog_content = "Au!",
  ui_story_5036_50361002_1_dialog_content = "Uau, isso foi perto!",
  ui_story_5036_50361002_2_dialog_content = "Está tudo bem agora. Eu matei o último Eclipsite.",
  ui_story_5036_50361002_3_dialog_content = "Você está bem? Você não está ferido, está?",
  ui_story_5036_50361002_4_dialog_content = "Estou bem, tirando minhas pernas parecendo geleia...",
  ui_story_5036_50361002_5_dialog_content = "Não é à toa que senti que alguém estava observando todo esse tempo... Você tem nos seguido.",
  ui_story_5036_50361002_6_dialog_content = "O que está fazendo aqui?",
  ui_story_5036_50361002_7_dialog_content = "Você não sabe que perseguir é ilegal, Brandy? Você é punido por isso!",
  ui_story_5036_50361002_8_dialog_content = "Eu... eu não estava perseguindo!",
  ui_story_5036_50361002_9_dialog_content = "Estou aqui para descobrir a verdade!",
  ui_story_5036_50361002_10_dialog_content = "A verdade? Você está olhando para os sonhos estranhos também?",
  ui_story_5036_50361002_11_dialog_content = "Não não Isso. Era outra coisa. Eu queria investigar em segredo, mas agora que você sabe, vou perguntar diretamente.",
  ui_story_5036_50361002_12_dialog_content = "Goldie, você se lembra do dono do Star Theater?",
  ui_story_5036_50361002_13_dialog_content = "Deixe-me pensar... Isso me lembra.",
  ui_story_5036_50361002_14_dialog_content = "Goldie também o espancou?",
  ui_story_5036_50361002_15_dialog_content = "Pare de interromper, Vic.",
  ui_story_5036_50361002_16_dialog_content = "Trabalhamos juntos brevemente, mas as coisas terminaram com uma nota amarga.",
  ui_story_5036_50361002_17_dialog_content = "Então você saiu em más condições? Por que você não encontrou outro local em vez de passar por todo o trabalho de embarcar no Wandering Colossus apenas para fazer um show?",
  ui_story_5036_50361002_18_dialog_content = "Desde então, outros proprietários de teatros recusaram minhas ofertas para alugar seus espaços.",
  ui_story_5036_50361002_19_dialog_content = "Você sabe por quê?",
  ui_story_5036_50361002_20_dialog_content = "É uma longa história.",
  ui_story_5036_50361002_21_dialog_content = "O dono do teatro uma vez enviou uma denúncia ao editor do The Daily Scoop, alegando que você o agrediu.",
  ui_story_5036_50361002_X21_dialog_content = "O que isso significa? Você é propenso a explosões violentas?",
  ui_story_5036_50361002_22_dialog_content = "Ele até mostrou ao editor as feridas em seu rosto. Seu rosto e nariz estavam tão inchados e machucados... Parecia muito doloroso.",
  ui_story_5036_50361002_23_dialog_content = "Eu não o machuquei nem um pouco! Pelo contrário, foi ele quem feriu criancinhas inocentes!",
  ui_story_5036_50361002_24_dialog_content = "Ainda não quero acreditar que você fez isso, mas... Sou um repórter, então devo confiar nas evidências.",
  ui_story_5036_50361002_25_dialog_content = "Você tem alguma coisa para provar sua inocência ou provar qualquer irregularidade da parte dele?",
  ui_story_5036_50361002_26_dialog_content = "Eu estou dizendo a verdade! Aqui, a história completa deve esclarecer as coisas.",
  ui_story_5036_50361002_27_dialog_content = "Tudo começou há cerca de dez dias. Na época, eu estava procurando um local para realizar meu próximo show.",
  ui_story_5036_50361002_28_dialog_content = "Depois de pensar muito, decidi que o Star Theatre era a melhor escolha, então abordei o proprietário sobre isso.",
  ui_story_5036_50361002_29_dialog_content = "Marquei um ensaio antes do meu show para me acostumar com o local.",
  ui_story_5036_50361002_30_dialog_content = "♪ La—la la la ♪",
  ui_story_5036_50361002_31_dialog_content = "<color=#e8d9bb>Tapa-!</color>",
  ui_story_5036_50361002_32_dialog_content = "Ahhhh!",
  ui_story_5036_50361002_33_dialog_content = "Socorro!",
  ui_story_5036_50361002_34_dialog_content = "Huh? O que foi isso agora?",
  ui_story_5036_50361002_35_dialog_content = "Parece que vocês punks pertencem aqui, hein? Scram! Batam, todos vocês!",
  ui_story_5036_50361002_36_dialog_content = "Malditos ratos imundos, fiquem longe do meu teatro!",
  ui_story_5036_50361002_37_dialog_content = "Ah!",
  ui_story_5036_50361002_38_dialog_content = "Não bata no meu irmão!",
  ui_story_5036_50361002_39_dialog_content = "O que tá acontecendo aqui?",
  ui_story_5036_50361002_40_dialog_content = "Bem, se não é a própria Goldie! Não há nada para ver aqui, não há motivo para sua preocupação.",
  ui_story_5036_50361002_41_dialog_content = "Era apenas um par de pirralhos sem dinheiro tentando pegar um show grátis. Vou jogá-los fora em um segundo.",
  ui_story_5036_50361002_42_dialog_content = "Este não é um concerto oficial, é apenas um ensaio. O que há de errado em virmos aqui para ouvir Goldie cantar?",
  ui_story_5036_50361002_43_dialog_content = "Ouvir não é de graça, punk. Pague ou se perca.",
  ui_story_5036_50361002_44_dialog_content = "Mas se você ainda está se sentindo arrogante, deixe-me colocá-lo de volta no seu lugar!",
  ui_story_5036_50361002_45_dialog_content = "Afe!",
  ui_story_5036_50361002_X45_dialog_content = "Socorro!",
  ui_story_5036_50361002_46_dialog_content = "Para!",
  ui_story_5036_50361002_47_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5036_50361002_48_dialog_content = "Eca! *Tosse*",
  ui_story_5036_50361002_49_dialog_content = "Como você ousa me tocar? Você não sabe quem eu sou? Eu possuo o Star Theatre!",
  ui_story_5036_50361002_50_dialog_content = "Eu não me importo se você é o dono! Eu não vou deixar você machucar um casal de crianças inocentes!",
  ui_story_5036_50361002_51_dialog_content = "Você ao menos percebe o que está fazendo?",
  ui_story_5036_50361002_52_dialog_content = "*Tosse*",
  ui_story_5036_50361002_53_dialog_content = "Infelizmente, não vou mais deixar você se apresentar no meu teatro, Srta. Goldie.",
  ui_story_5036_50361002_54_dialog_content = "... Que pena.",
  ui_story_5036_50361002_55_dialog_content = "Então você pulou para defender aqueles garotos e acidentalmente o derrubou no chão?",
  ui_story_5036_50361002_56_dialog_content = "Isso é totalmente diferente do que todos estão dizendo!",
  ui_story_5036_50361002_57_dialog_content = "Esses são apenas rumores infundados!",
  ui_story_5036_50361002_58_dialog_content = "E outra coisa! Quando ele caiu no chão, ele caiu de bunda, não de rosto!",
  ui_story_5036_50361002_59_dialog_content = "Se você não acredita em mim, pergunte a essas duas crianças sobre isso! Eles vão te contar tudo o que aconteceu naquele dia.",
  ui_story_5036_50361002_60_dialog_content = "(Goldie sempre foi uma pessoa boa e justa. Não acho que ela agiria violentamente sem um bom motivo.)",
  ui_story_5036_50361002_61_dialog_content = "Por que você não contou a todos tudo isso em primeiro lugar?",
  ui_story_5036_50361002_62_dialog_content = "Eu sou um ídolo, não posso me dar ao luxo de expor minhas vulnerabilidades.",
  ui_story_5036_50361002_63_dialog_content = "Para arruinar minha reputação, vários donos de teatros estão conspirando uns com os outros para me impedir de alugar um local para o meu show.",
  ui_story_5036_50361002_64_dialog_content = "Eles sabem que prometi aos meus fãs um show aqui em Umbraton e estão tentando me fazer voltar atrás na minha palavra.",
  ui_story_5036_50361002_65_dialog_content = "Meus fãs ficarão tão desapontados se eu não conseguir cumprir minha promessa a eles...",
  ui_story_5036_50361002_X65_dialog_content = "Eu também posso dar adeus à minha carreira de ídolo se eu fizer isso!",
  ui_story_5036_50361002_X66_dialog_content = "É por isso que, não importa o que aconteça, tenho que realizar aquele show conforme programado.",
  ui_story_5036_50361002_X67_dialog_content = "Tenho que provar aos meus fãs que nunca trairia todo o amor e apoio que eles me deram!",
  ui_story_5036_50361002_66_dialog_content = "Como essas pessoas puderam fazer isso com você?!",
  ui_story_5036_50361002_67_dialog_content = "A única coisa que posso fazer agora é realizar um show único para que todos possam experimentar o verdadeiro eu por si mesmos.",
  ui_story_5036_50361002_68_dialog_content = "À medida que me tornar mais popular, mais e mais pessoas estarão dispostas a me ouvir e acreditar em mim!",
  ui_story_5036_50361002_69_dialog_content = "Então, quando o incidente aconteceu, optei por ficar quieto e manter as coisas para mim. Eu não queria que ninguém me visse em uma posição vulnerável.",
  ui_story_5036_50361002_70_dialog_content = "(Então era isso que Goldie estava pensando o tempo todo...)",
  ui_story_5036_50361002_71_dialog_content = "(O olhar em seus olhos me diz que ela não está mentindo. Além disso, ela até me salvou dos Eclipsites.)",
  ui_story_5036_50361002_72_dialog_content = "Ufa... Quase acreditei nos boatos e pensei que você fosse algum tipo de pessoa má...",
  ui_story_5036_50361002_73_dialog_content = "Vou esclarecer esse assunto com as duas crianças mais tarde.",
  ui_story_5036_50361002_X73_dialog_content = "Se você está dizendo a verdade, escreverei um artigo sobre isso imediatamente. Vamos limpar seu bom nome e acabar com todos os boatos!",
  ui_story_5036_50361002_74_dialog_content = "Eu não poderia pedir mais nada!",
  ui_story_5036_50361002_75_dialog_content = "Vamos guardar a penugem sentimental para depois que terminarmos aqui. Ainda temos outros assuntos a tratar.",
  ui_story_5036_50361002_76_dialog_content = "Isso mesmo! Para onde vamos a seguir, PlayerName?",
  ui_story_5036_50361002_77_dialog_content = "Posso sentir que estamos nos aproximando do local onde Chaminade escondeu o ovo.",
  ui_story_5036_50361002_78_dialog_content = "Deixe-me tentar mais uma vez.",
  ui_story_5036_50361002_79_option_content = "Conexão mental!",
  ui_story_5036_50361002_80_dialog_content = "Graah—!",
  ui_story_5036_50361002_81_dialog_content = "<color=#e8d9bb>Baque-!</color>",
  ui_story_5036_50361002_82_dialog_content = "Ah—!",
  ui_story_5036_50361002_83_dialog_content = "Eles estão tentando invadir... O que devo fazer?",
  ui_story_5036_50361002_84_dialog_content = "Mesmo a sala mais forte do Colossus não pode conter todos esses Eclipsites?",
  ui_story_5036_50361002_85_dialog_content = "Eulogoz? Eulogoz!",
  ui_story_5036_50361002_86_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361002_87_dialog_content = "Não... Será que o Eulogoz já é...?",
  ui_story_5036_50361002_88_dialog_content = "Não! Eu não posso desistir! Eu ainda tenho que proteger o Ouroboros!",
  ui_story_5036_50361002_89_dialog_content = "Eu preciso escondê-lo em algum lugar seguro primeiro!",
  ui_story_5036_50361002_90_dialog_content = "Ninguém deve ser capaz de encontrá-lo dentro deste compartimento secreto na parede.",
  ui_story_5036_50361002_91_dialog_content = "Fique aqui e não mova um músculo, ok?",
  ui_story_5036_50361002_92_dialog_content = "Eu vou te proteger não importa o que aconteça!",
  ui_story_5036_50361002_93_dialog_content = "<color=#e8d9bb>Uau!!!</color>",
  ui_story_5036_50361002_94_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5036_50361002_95_dialog_content = "Graaah...",
  ui_story_5036_50361002_96_dialog_content = "Eclipsitas...",
  ui_story_5036_50361002_97_dialog_content = "Venham para mim... Venham para mim, todos vocês!",
  ui_story_5036_50361002_98_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361002_99_dialog_content = "Tá doendo...",
  ui_story_5036_50361002_100_dialog_content = "Meu corpo... Está tão frio...",
  ui_story_5036_50361002_101_dialog_content = "Eulogoz... Ouroboros... Vocês dois ainda estão aí?",
  ui_story_5036_50361002_102_dialog_content = "Eu... eu só quero ir para casa...",
  ui_story_5036_50361002_103_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361002_104_dialog_content = "Kree—!",
  ui_story_5036_50361101_1_dialog_content = "...",
  ui_story_5036_50361101_2_dialog_content = "PlayerName?",
  ui_story_5036_50361101_3_dialog_content = "...",
  ui_story_5036_50361101_4_dialog_content = "PlayerName! Você está bem? O que você viu?",
  ui_story_5036_50361101_5_dialog_content = "Eu... eu vi a memória final de Chaminade.",
  ui_story_5036_50361101_6_dialog_content = "Depois que o Ouroboros se transformou em um ovo, ela e Eulogoz foram atacados por Eclipsites.",
  ui_story_5036_50361101_7_dialog_content = "Para proteger o ovo de Ouroboros, ela o escondeu em um compartimento secreto na parede.",
  ui_story_5036_50361101_8_dialog_content = "Depois disso, Chaminade puxou os Eclipsitas para fora da sala sozinha... E então...",
  ui_story_5036_50361101_9_dialog_content = "... É o bastante. Nós entendemos.",
  ui_story_5036_50361101_10_dialog_content = "Aquela pobre garota lutou até o fim para proteger o ovo de Ouroboros.",
  ui_story_5036_50361101_11_dialog_content = "Ela se saiu bem, mesmo que pareça um pouco demais.",
  ui_story_5036_50361101_12_dialog_content = "Não é hora de falar assim, Vic.",
  ui_story_5036_50361101_13_dialog_content = "O que você quer dizer? Olhe dentro da rachadura nesta parede, se você não acredita em mim.",
  ui_story_5036_50361101_14_dialog_content = "Tem alguma coisa aí?",
  ui_story_5036_50361101_15_dialog_content = "Ahhh!",
  ui_story_5036_50361101_16_dialog_content = "O que você vê?",
  ui_story_5036_50361101_17_dialog_content = "O que é isto? Não se parece em nada com o padrão na parede.",
  ui_story_5036_50361101_18_dialog_content = "Não é feito de metal ou Colossus Patches. Parece mais... uma casca de ovo.",
  ui_story_5036_50361101_19_dialog_content = "Poderia pertencer ao Ouroboros?",
  ui_story_5036_50361101_20_dialog_content = "Então ainda está aqui, afinal. Mas como ficou tão grande? Até quebrou a parede!",
  ui_story_5036_50361101_21_dialog_content = "Não deveria ser um pouco maior que uma melancia? Mesmo aquela garotinha poderia carregá-lo.",
  ui_story_5036_50361101_22_dialog_content = "Um \"ovo de Ouroboros\"?! Eu pensei que Vic estava apenas brincando sobre isso! Como isso está realmente acontecendo?",
  ui_story_5036_50361101_23_dialog_content = "O que exatamente está acontecendo aqui, Vic?",
  ui_story_5036_50361101_24_dialog_content = "Não faço ideia...",
  ui_story_5036_50361101_25_dialog_content = "O que? Você não deveria ser o maior extrozoologista do mundo?",
  ui_story_5036_50361101_26_dialog_content = "É precisamente por ser um extrozoologista que me recuso a fazer qualquer suposição precipitada.",
  ui_story_5036_50361101_27_dialog_content = "A única coisa que posso verificar por enquanto é que este ovo já passou do período de incubação, mas ainda não eclodiu.",
  ui_story_5036_50361101_28_dialog_content = "Além disso, o Ouroboros dentro do ovo ainda está muito vivo. Ele continua crescendo e o ovo cresce com ele.",
  ui_story_5036_50361101_29_dialog_content = "Quanto a todo o resto, não tenho absolutamente nenhuma ideia!",
  ui_story_5036_50361101_30_dialog_content = "Ouroboros é uma espécie extremamente rara, então as informações sobre ela são escassas na melhor das hipóteses.",
  ui_story_5036_50361101_31_dialog_content = "É um mistério total, para simplificar.",
  ui_story_5036_50361101_32_dialog_content = "Todo esse tempo, pensei que Vic estava apenas inventando coisas. Eu não tinha ideia de que ele estava falando sério.",
  ui_story_5036_50361101_33_dialog_content = "Você acha que este ovo é a fonte dos sonhos estranhos de todos?",
  ui_story_5036_50361101_34_dialog_content = "É possível!",
  ui_story_5036_50361101_35_dialog_content = "Você acha mesmo?",
  ui_story_5036_50361101_36_dialog_content = "Não tenho nenhuma prova, então é só um palpite.",
  ui_story_5036_50361101_37_dialog_content = "Sempre tive curiosidade de saber como o Ouroboros sobrevive ao seu período de incubação como ovo.",
  ui_story_5036_50361101_38_dialog_content = "Como um ovo deve lutar contra predadores ou fugir deles?",
  ui_story_5036_50361101_39_dialog_content = "Mas agora, eu vim com uma nova hipótese! Eu acredito que o Ouroboros pode possuir uma habilidade psíquica única enquanto está em seu estado de ovo.",
  ui_story_5036_50361101_40_dialog_content = "Um que pode fazer com que outras criaturas tenham sonhos estranhos ou alucinações! Ao fazê-los sentir o perigo, o Ouroboros pode mantê-los a uma distância segura.",
  ui_story_5036_50361101_41_dialog_content = "Ele se protege dessa maneira para afastar os perigos.",
  ui_story_5036_50361101_42_dialog_content = "Então você está dizendo que os sonhos estranhos que temos tido, e aquela estranha sensação de desconforto...",
  ui_story_5036_50361101_43_dialog_content = "Ou até mesmo aquele pôster estranho de antes. Tudo isso foi feito pelos Ouroboros?!",
  ui_story_5036_50361101_44_dialog_content = "De fato. Ou melhor, essa é a explicação mais razoável que consigo pensar!",
  ui_story_5036_50361101_45_dialog_content = "Portanto, nosso próximo passo é óbvio, certo? Precisamos encontrar uma maneira de mover este ovo para algum lugar distante!",
  ui_story_5036_50361101_46_option_content = "Este ovo?",
  ui_story_5036_50361101_47_option_content = "Mova isso?",
  ui_story_5036_50361101_48_dialog_content = "Uhum!",
  ui_story_5036_50361101_49_dialog_content = "Se não tirarmos este ovo daqui, o poder do Ouroboros continuará afetando a todos.",
  ui_story_5036_50361101_50_dialog_content = "E nesse ritmo, com certeza vai impactar meu show!",
  ui_story_5036_50361101_51_dialog_content = "Discordo.",
  ui_story_5036_50361101_52_dialog_content = "O quê?!",
  ui_story_5036_50361101_53_dialog_content = "O ovo é colossal e está preso na parede.",
  ui_story_5036_50361101_54_dialog_content = "Mesmo que você consiga removê-lo, como pretende transportá-lo para outro lugar com segurança?",
  ui_story_5036_50361101_55_dialog_content = "Vou contratar os Mercenários da Chama Branca para desenterrá-lo e levá-lo em uma aeronave!",
  ui_story_5036_50361101_56_dialog_content = "Essas paredes não são exatamente feitas de paus e pedras, sabe? Quando você terminar de desenterrá-lo, o show já terá terminado há muito tempo.",
  ui_story_5036_50361101_57_dialog_content = "Eu...",
  ui_story_5036_50361101_58_dialog_content = "Sem mencionar que este pode muito bem ser o único ovo de Ouroboros deixado em todo o mundo, dada a raridade dos exóticos.",
  ui_story_5036_50361101_59_dialog_content = "Se algo acontecesse com ele durante o desencarceramento, a vida do Ouroboros poderia ser colocada em risco.",
  ui_story_5036_50361101_60_dialog_content = "Se isso acontecer, você estará pronto para assumir a culpa por causar a extinção de toda uma espécie de animais maravilhosos?",
  ui_story_5036_50361101_61_dialog_content = "Eu...",
  ui_story_5036_50361101_62_dialog_content = "Por que não seguir meu conselho e cancelar este show?",
  ui_story_5036_50361101_63_dialog_content = "Você pode realizar um concerto em qualquer outro lugar a qualquer momento. Seria apenas uma vez, então vamos esperar que o Ouroboros ecloda e...",
  ui_story_5036_50361101_64_dialog_content = "Parou!",
  ui_story_5036_50361101_65_dialog_content = "Este concerto é <color=#FFB400>Especialmente importante</color> para mim! Eu não posso desistir disso assim!",
  ui_story_5036_50361101_66_dialog_content = "Posso me comprometer em qualquer outra situação, mas não nesta!",
  ui_story_5036_50361101_67_dialog_content = "É verdade, esse show é algo que Goldie prometeu aos fãs...",
  ui_story_5036_50361101_68_dialog_content = "(\"Especialmente importante\"? Goldie parece realmente angustiada agora. O que está acontecendo?)",
  ui_story_5036_50361101_69_dialog_content = "Ah, então parece que temos um pequeno dilema em nossas mãos.",
  ui_story_5036_50361101_70_dialog_content = "...",
  ui_story_5036_50361101_71_dialog_content = "(Nenhum deles está disposto a recuar. Tenho que fazer algo a respeito.)",
  ui_story_5036_50361101_72_dialog_content = "Não há realmente outra maneira?",
  ui_story_5036_50361101_73_dialog_content = "Talvez possamos nos livrar da influência psíquica do ovo sem movê-lo?",
  ui_story_5036_50361101_74_dialog_content = "Isso mesmo! Você é o especialista em extrozoologia, Vic. Você não consegue pensar em uma maneira melhor?",
  ui_story_5036_50361101_75_dialog_content = "Suspirar. Como sempre, vocês pirralhos adoram fazer um velho sofrer. Eles só pioram geração após geração...",
  ui_story_5036_50361101_76_dialog_content = "Ah bem, acho que não pode ser ajudado. Meus aprendizes estão sempre me implorando para salvar suas bundas. Isso não é diferente, suponho.",
  ui_story_5036_50361101_77_dialog_content = "Interessante escolha de palavras, Vic. Eu me pergunto o que Shira e Fia pensariam deles.",
  ui_story_5036_50361101_78_dialog_content = "Desculpe, o que? Eu disse algo? Eu não consigo me lembrar!",
  ui_story_5036_50361101_79_dialog_content = "Oh, pare de agir, Vic. Vamos continuar com isso.",
  ui_story_5036_50361101_80_dialog_content = "Aham. Existe outro método, mas é um pouco problemático e não posso garantir que funcione.",
  ui_story_5036_50361101_81_dialog_content = "Basta dizer-nos já! Farei qualquer coisa, desde que me dê a chance de fazer esse show!",
  ui_story_5036_50361101_82_dialog_content = "Conte-me sobre a visão que você teve alguns minutos atrás, PlayerName. Chaminade parecia ser afetado negativamente pelo ovo Ouroboros de alguma forma?",
  ui_story_5036_50361101_83_dialog_content = "Huh? Agora que penso nisso... Não, ela realmente não parecia nem um pouco incomodada com isso.",
  ui_story_5036_50361101_84_dialog_content = "Eu vejo. Aí está a resposta, meus amigos!",
  ui_story_5036_50361101_85_dialog_content = "As habilidades psíquicas do Ouroboros parecem ser um mecanismo de autodefesa que ele só usa quando sente o perigo próximo.",
  ui_story_5036_50361101_86_dialog_content = "Se pudermos remover a fonte desse perigo do Colosso, ele deve se sentir seguro o suficiente para dissipar sua influência psíquica!",
  ui_story_5036_50361101_87_dialog_content = "Então você está dizendo que só temos que limpar os Eclipsites no Colossus?",
  ui_story_5036_50361101_88_dialog_content = "Essa é uma maneira de colocar isso, sim.",
  ui_story_5036_50361101_89_dialog_content = "Isso é tudo? Isso não é um problema para nós!",
  ui_story_5036_50361101_90_dialog_content = "N-Agora espere só um minuto!",
  ui_story_5036_50361101_91_dialog_content = "Este Colosso é, bem, colossal! Como vamos acabar com cada Eclipsite apenas com nós quatro?! É impossível!",
  ui_story_5036_50361101_92_dialog_content = "Você tem razão...",
  ui_story_5036_50361101_93_dialog_content = "Além disso, há uma chance de que isso nem funcione, certo?",
  ui_story_5036_50361101_94_dialog_content = "Correto. Mas não descobriremos a menos que tentemos!",
  ui_story_5036_50361101_95_dialog_content = "E se tentarmos eliminar os eclipsitos nas imediações e depois selar todas as rachaduras nas paredes? Assim, eles não terão como chegar perto do ovo!",
  ui_story_5036_50361101_96_dialog_content = "Hmm, isso pode produzir um resultado semelhante, sim.",
  ui_story_5036_50361101_97_dialog_content = "Vamos tentar!",
  ui_story_5036_50361101_98_dialog_content = "Tudo bem, vamos embora!",
  ui_story_5036_50361101_99_dialog_content = "Para o concerto!",
  ui_story_5036_50361102_1_dialog_content = "Vem me dar uma mão aqui, PlayerName.",
  ui_story_5036_50361102_2_dialog_content = "Vamos empurrar essa pedra ali e bloquear aquela rachadura na parede.",
  ui_story_5036_50361102_3_dialog_content = "Entendido!",
  ui_story_5036_50361102_4_dialog_content = "Hrrrnnnng-!",
  ui_story_5036_50361102_5_dialog_content = "Ufa! Essa deve ser a última rachadura, certo?",
  ui_story_5036_50361102_6_dialog_content = "Parece que sim! Excelente trabalho, pessoal.",
  ui_story_5036_50361102_7_dialog_content = "Outro empreendimento de sucesso sob minha liderança impecável!",
  ui_story_5036_50361102_8_dialog_content = "Se você pode chamar sentar e torcer por nós \"liderança\", então com certeza...",
  ui_story_5036_50361102_9_dialog_content = "Você realmente esperava que um velhote como eu acompanhasse um bando de galinhas da primavera como você?",
  ui_story_5036_50361102_10_dialog_content = "A atmosfera sombria parece estar enfraquecendo...",
  ui_story_5036_50361102_11_dialog_content = "Você tem razão. Mesmo que eu ainda possa sentir isso vagamente, parece muito melhor agora do que antes.",
  ui_story_5036_50361102_12_dialog_content = "Então parece que minha hipótese estava correta!",
  ui_story_5036_50361102_13_dialog_content = "Então o que fazemos agora? Devemos continuar limpando os Eclipsites?",
  ui_story_5036_50361102_14_dialog_content = "Acho que já fizemos mais do que o suficiente neste momento. A única coisa que resta a fazer agora...",
  ui_story_5036_50361102_15_dialog_content = "é voltar rastejando para a cama para ver se temos mais sonhos estranhos!",
  ui_story_5036_50361102_16_dialog_content = "Você só quer ir para a cama, não é?!",
  ui_story_5036_50361102_17_dialog_content = "Desculpe, mas como há tão pouca informação sobre o Ouroboros, tentativa e erro é nossa única escolha.",
  ui_story_5036_50361102_18_dialog_content = "Ele tem razão.",
  ui_story_5036_50361102_19_dialog_content = "Está ficando muito tarde e todos parecem exaustos.",
  ui_story_5036_50361102_20_dialog_content = "Vamos voltar e descansar um pouco, e ver se nossos esforços valeram a pena.",
  ui_story_5036_50361102_21_dialog_content = "E se não tiverem, pensarei em outra coisa.",
  ui_story_5036_50361102_22_dialog_content = "Acho que todo o seu trabalho duro vai valer a pena, Goldie!",
  ui_story_5036_50361102_23_dialog_content = "Heehee! Obrigado por dizer isso!",
  ui_story_5036_50361102_24_dialog_content = "Tudo bem então, vamos voltar para um sono muito necessário. Nos encontraremos novamente pela manhã!",
  ui_story_5036_50361102_25_dialog_content = "<color=#e8d9bb>Na manhã seguinte, um dia antes do concerto</color>",
  ui_story_5036_50361102_26_dialog_content = "Yaaaawn... Fazia tempo que eu não tinha uma boa noite de sono assim!",
  ui_story_5036_50361102_27_dialog_content = "Eu estava tão abatido depois da noite passada que desmaiei assim que cheguei ao meu quarto. Eu estava cansada demais para sonhar!",
  ui_story_5036_50361102_28_dialog_content = "Bom dia, meu rival derrotado!",
  ui_story_5036_50361102_29_dialog_content = "Se você acabou de acordar, isso significa que ganhei o jogo de despertar hoje! Incrível!",
  ui_story_5036_50361102_30_dialog_content = "Oi, Gronru. Você dormiu bem noite passada?",
  ui_story_5036_50361102_31_dialog_content = "Eu fiz uma soneca de nível S de verdade ontem à noite!",
  ui_story_5036_50361102_32_dialog_content = "Nada comparado às últimas noites, onde continuei sonhando com aquela garota celestita.",
  ui_story_5036_50361102_33_dialog_content = "Sério? Isso é uma notícia maravilhosa!",
  ui_story_5036_50361102_34_dialog_content = "Você acha? Eu não. Ter sonhos estranhos como esse é como desbloquear uma conquista oculta em um jogo!",
  ui_story_5036_50361102_35_dialog_content = "Uh, sim, claro... De qualquer forma, estou feliz que você tenha conseguido um descanso decente.",
  ui_story_5036_50361102_36_dialog_content = "Obrigado! Vou assistir o ensaio, te vejo depois!",
  ui_story_5036_50361102_37_dialog_content = "Tudo bem, até mais!",
  ui_story_5036_50361102_38_dialog_content = "Isso é ótimo! Parece que todo o nosso trabalho duro ontem à noite não foi em vão!",
  ui_story_5036_50361102_39_dialog_content = "Eu deveria ir contar a Goldie imediatamente, para que ela possa finalmente relaxar um pouco.",
  ui_story_5036_50361102_40_dialog_content = "Agora, ela deveria estar... na sala de treinamento, eu acho?",
  ui_story_5036_50361102_41_dialog_content = "Ei PlayerName!",
  ui_story_5036_50361102_42_dialog_content = "Você já acordou? Saímos tão tarde ontem à noite que pensei que você gostaria de dormir um pouco mais hoje.",
  ui_story_5036_50361102_43_dialog_content = "De jeito nenhum! Eu me sinto completamente revigorado agora!",
  ui_story_5036_50361102_44_dialog_content = "Além disso, parece que nosso trabalho árduo valeu a pena. Acabei de falar com Gronru e ela disse que não teve nenhum sonho estranho ontem à noite!",
  ui_story_5036_50361102_45_dialog_content = "Isso é bom! Eu também perguntei a alguns concorrentes, e todos eles disseram que dormiram bem na noite passada também!",
  ui_story_5036_50361102_46_dialog_content = "Isto é perfeito!",
  ui_story_5036_50361102_47_dialog_content = "Realmente é... perfeito.",
  ui_story_5036_50361102_48_option_content = "Goldie? Você está bem?",
  ui_story_5036_50361102_49_dialog_content = "Por que você parece tão cansado?",
  ui_story_5036_50361102_50_dialog_content = "Huh? Eu?",
  ui_story_5036_50361102_51_dialog_content = "Não me sinto exausta de jeito nenhum! Afinal, os ídolos estão cheios de energia!",
  ui_story_5036_50361102_52_option_content = "Por que você parece tão exausto?",
  ui_story_5036_50361102_53_dialog_content = "Huh? Eu?",
  ui_story_5036_50361102_54_dialog_content = "Acho que você pode estar vendo coisas. Eu me sinto perfeitamente bem agora!",
  ui_story_5036_50361102_55_dialog_content = "(Juro que não estou vendo coisas. Essa expressão agora... Será?)",
  ui_story_5036_50361102_56_dialog_content = "Você está se forçando a manter o ânimo, não é?",
  ui_story_5036_50361102_57_dialog_content = "...!",
  ui_story_5036_50361102_58_dialog_content = "Não é difícil dizer. Afinal, você saiu tão tarde quanto nós na noite passada.",
  ui_story_5036_50361102_59_dialog_content = "Além do mais, você teve que organizar o treinamento e a audição hoje, certo? Parece que você não descansou nada ontem à noite.",
  ui_story_5036_50361102_60_dialog_content = "Está tudo bem, eu juro! Eu sou um ídolo, lembra? E ídolos—",
  ui_story_5036_50361102_61_option_content = "- são pessoas também, certo?",
  ui_story_5036_50361102_62_dialog_content = "Você ainda é gente. Você também precisa descansar.",
  ui_story_5036_50361102_63_dialog_content = "Talvez eu não conheça a história completa por trás desse show ou por que ele é tão importante para você...",
  ui_story_5036_50361102_64_dialog_content = "Mas eu sei que você deveria deixar seu trabalho de lado um pouco e descansar um pouco agora, Goldie.",
  ui_story_5036_50361102_65_dialog_content = "*Suspira*",
  ui_story_5036_50361102_66_dialog_content = "Suponho que não faria mal dizer-lhe a verdade, PlayerName. Afinal, você já fez tanto para me ajudar.",
  ui_story_5036_50361102_67_dialog_content = "Huh? Você acabou de dizer \"a verdade\"?",
  ui_story_5036_50361102_X67_dialog_content = "Não estou apenas cumprindo minha promessa aos meus fãs com este show... estou cumprindo minha promessa a Lady Sheol também.",
  ui_story_5036_50361102_68_dialog_content = "Para ser completamente honesto com você, eu meio que fiz um pacto com o Sheol.",
  ui_story_5036_50361102_69_dialog_content = "Um pacto? Com Sheol?!",
  ui_story_5036_50361102_70_dialog_content = "Ela reconheceu o potencial da indústria de ídolos, assim como minhas próprias habilidades. Então ela decidiu investir na minha carreira.",
  ui_story_5036_50361102_71_dialog_content = "Ela é minha maior fonte de apoio financeiro, mas, ao mesmo tempo, tenho que fazer tudo ao meu alcance para cumprir suas exigências.",
  ui_story_5036_50361102_72_dialog_content = "Uma delas era apresentar um concerto aqui em Umbraton dentro de um certo período de tempo, e esse concerto...",
  ui_story_5036_50361102_73_dialog_content = "Tem que esclarecer a todos em Umbraton e Lumopolis sobre o conceito de um ídolo, e espalhar meu nome por toda a região.",
  ui_story_5036_50361102_74_dialog_content = "Você não acha que o Sheol está se aproveitando de você? Esse objetivo é mesmo possível?!",
  ui_story_5036_50361102_75_dialog_content = "Admito que não será fácil para alguém com meu nível de popularidade. Mas nada é impossível desde que eu planeje tudo perfeitamente.",
  ui_story_5036_50361102_76_dialog_content = "Mas então você sabe, todas essas coisas aconteceram, então eu não pude alugar um local.",
  ui_story_5036_50361102_77_dialog_content = "Mas quando toda a esperança parecia perdida, o Colosso Errante apareceu de repente no céu! Sua chegada foi tão fortuita!",
  ui_story_5036_50361102_78_dialog_content = "De acordo com meu pacto com Sheol, amanhã é o último dia em que posso fazer meu show. É minha última chance, então tenho que dar tudo de mim.",
  ui_story_5036_50361102_79_dialog_content = "Se eu falhar, terei que reembolsar Sheol por todas as suas despesas. Estarei sob uma montanha de dívidas.",
  ui_story_5036_50361102_80_dialog_content = "Minha carreira como ídolo também vai acabar.",
  ui_story_5036_50361102_81_dialog_content = "Não fazia ideia de que você estava trabalhando sob tanta pressão, Goldie. Não é tudo demais?",
  ui_story_5036_50361102_82_dialog_content = "Eu não acho. Afinal, é meu dever.",
  ui_story_5036_50361102_83_dialog_content = "Como um ídolo, toda a minha razão de ser é trazer esperança e felicidade aos meus fãs leais através da música e da dança.",
  ui_story_5036_50361102_84_dialog_content = "Sem o amor e apoio deles, eu nunca poderia me chamar de ídolo.",
  ui_story_5036_50361102_85_dialog_content = "Depois de todo o amor que eles demonstraram por mim, que tipo de pessoa eu seria se não retribuísse trabalhando o máximo que pudesse?",
  ui_story_5036_50361102_86_dialog_content = "Eu arriscarei tudo se isso significar que meu show ajudará minha voz a alcançar ainda mais pessoas!",
  ui_story_5036_50361102_87_dialog_content = "Eu sei que você consegue, Goldie!",
  ui_story_5036_50361102_88_dialog_content = "Mas você não está sozinho. Você também tem a mim!",
  ui_story_5036_50361102_89_dialog_content = "Se houver algo que eu possa fazer para ajudar, é só pedir.",
  ui_story_5036_50361102_90_dialog_content = "Obrigado, PlayerName!",
  ui_story_5036_50361102_91_dialog_content = "Vamos fazer o possível para proteger o Eulogoz e fazer desse show o maior que o mundo já viu!",
  ui_story_5036_50361201_1_dialog_content = "<color=#e8d9bb>No dia seguinte, quinze minutos antes do início do concerto</color>",
  ui_story_5036_50361201_2_dialog_content = "O concerto está prestes a começar! Todos prontos?",
  ui_story_5036_50361201_3_dialog_content = "Prontos!",
  ui_story_5036_50361201_4_dialog_content = "O show está finalmente começando? É o momento que todos esperávamos!",
  ui_story_5036_50361201_5_dialog_content = "(Honestamente, fazendo-me perder meu valioso tempo me relacionando com esses plebeus.)",
  ui_story_5036_50361201_6_dialog_content = "Expressão, revelador.",
  ui_story_5036_50361201_7_dialog_content = "A presença de pensamentos rudes e humilhantes é claramente visível em seu rosto.",
  ui_story_5036_50361201_8_dialog_content = "Ah, cale a boca.",
  ui_story_5036_50361201_9_dialog_content = "Incrível! O jogo está prestes a começar!",
  ui_story_5036_50361201_10_dialog_content = "Pronto para me ajudar a animá-los, Sio?",
  ui_story_5036_50361201_11_dialog_content = "R-Pronto...",
  ui_story_5036_50361201_12_dialog_content = "Por que ainda não começamos? Estou morrendo de vontade de surpreender essa multidão com minha música rock!",
  ui_story_5036_50361201_13_dialog_content = "Caia na real, seu idiota! Este é um show de ídolos, não um show de rock! O mais importante aqui é o ídolo!",
  ui_story_5036_50361201_14_dialog_content = "É por isso que eu, Bárbara, a Doçura Diesel, fui feita para isso!",
  ui_story_5036_50361201_15_dialog_content = "Quem gostaria de ouvir música infantil como a sua? A multidão não quer ouvir esse lixo!",
  ui_story_5036_50361201_16_dialog_content = "O que é que foi isso?!",
  ui_story_5036_50361201_17_dialog_content = "Esses dois estão tão animados como sempre. Espero que não nos causem problemas.",
  ui_story_5036_50361201_18_dialog_content = "Concordou. Afinal, eles têm que fazer o ato de abertura juntos!",
  ui_story_5036_50361201_19_dialog_content = "Sim, eu sei o que você... Espere, O QUÊ?! Ato de abertura? Juntos?!",
  ui_story_5036_50361201_20_dialog_content = "Tem certeza que está tudo bem?!",
  ui_story_5036_50361201_21_dialog_content = "Não vou mentir, também estou um pouco preocupado com isso. Mas se eu deixá-los tocar separadamente, eles vão brigar para ver quem vai primeiro.",
  ui_story_5036_50361201_22_dialog_content = "Ao fazê-los subir ao palco ao mesmo tempo, pelo menos o concerto decorrerá sem problemas.",
  ui_story_5036_50361201_23_dialog_content = "Além disso, ambos juraram que fariam uma abertura matadora para o show!",
  ui_story_5036_50361201_24_dialog_content = "Oh, vai ser \"assassino\", tudo bem... Só não tenho certeza do que vai acontecer...",
  ui_story_5036_50361201_25_dialog_content = "Tenha um pouco de fé neles! Eu sei que eles brigam o tempo todo, mas não há como negar suas habilidades ou sua dedicação às suas performances.",
  ui_story_5036_50361201_26_dialog_content = "Tudo bem, eu só espero que eles possam dividir o palco por tempo suficiente para se apresentarem.",
  ui_story_5036_50361201_27_dialog_content = "Afinal, Eulogoz também aposta tudo neste concerto.",
  ui_story_5036_50361201_28_dialog_content = "Você realmente se importa com Eulogoz, não é?",
  ui_story_5036_50361201_29_dialog_content = "Isso porque é o único Colossus totalmente operacional no mundo, além de Soroz e Lepidoz.",
  ui_story_5036_50361201_30_dialog_content = "Os Celestitas compartilham um vínculo estreito com todos os Colossos. Eles são a prova de que meu povo já existiu.",
  ui_story_5036_50361201_31_dialog_content = "Quero fazer o possível para preservá-los o máximo possível. Eu sei que os outros celestitas teriam gostado disso...",
  ui_story_5036_50361201_32_dialog_content = "Sem falar que se consertarmos o Eulogoz, o Soroz finalmente terá outro companheiro. Não seria tão solitário.",
  ui_story_5036_50361201_33_dialog_content = "Não se preocupe, PlayerName. Farei o meu melhor pelo seu bem, assim como pelo deles!",
  ui_story_5036_50361201_34_dialog_content = "Nós também vamos ajudar!",
  ui_story_5036_50361201_35_dialog_content = "Se algo realmente der errado, estarei lá para manter a ordem.",
  ui_story_5036_50361201_36_dialog_content = "Como sempre, Carleen tem tudo sob controle!",
  ui_story_5036_50361201_37_dialog_content = "Uau, vocês dois parecem totalmente prontos para este show.",
  ui_story_5036_50361201_38_dialog_content = "É claro! Até preparamos uma arma secreta só para a ocasião!",
  ui_story_5036_50361201_39_dialog_content = "Qual música vocês vão fazer juntos?",
  ui_story_5036_50361201_40_dialog_content = "Originalmente, íamos cantar uma música dos nossos tempos de estudante, mas quando a ensaiamos, algo parecia faltar.",
  ui_story_5036_50361201_41_dialog_content = "Não capturou totalmente tudo sobre nossas viagens, dificuldades ou momentos de alegria.",
  ui_story_5036_50361201_42_dialog_content = "Isso mesmo! E quando perguntei a ela sobre isso, percebi que nós dois sentíamos o mesmo!",
  ui_story_5036_50361201_43_dialog_content = "É por isso que decidimos escrever uma música totalmente nova para o show!",
  ui_story_5036_50361201_44_dialog_content = "Uau, mal posso esperar para ouvir!",
  ui_story_5036_50361201_45_dialog_content = "Regina, Bárbara, Carleen, Vice, Vic...",
  ui_story_5036_50361201_46_dialog_content = "Espere, onde está Vic?",
  ui_story_5036_50361201_47_dialog_content = "Vic? Agora que você mencionou, notei que o quarto dele estava vazio quando passei por ele no caminho para cá.",
  ui_story_5036_50361201_48_dialog_content = "Eu pensei que ele veio mais cedo?",
  ui_story_5036_50361201_49_dialog_content = "Você também não o viu?",
  ui_story_5036_50361201_50_dialog_content = "Oh, pelo amor de Deus, o show está prestes a começar! Para onde ele poderia ter fugido?",
  ui_story_5036_50361201_51_dialog_content = "Talvez ele tenha voltado para verificar o ovo de Ouroboros?",
  ui_story_5036_50361201_52_dialog_content = "Às vezes, ele se preocupa muito mais com bestas maravilhosas do que com outras pessoas, e também tem a tendência de adormecer aleatoriamente.",
  ui_story_5036_50361201_53_dialog_content = "Há uma boa chance de ele ter dormido demais lá.",
  ui_story_5036_50361201_54_dialog_content = "Mas não se preocupe, vou trazê-lo de volta.",
  ui_story_5036_50361201_55_dialog_content = "Por você mesmo? Tem certeza?",
  ui_story_5036_50361201_56_dialog_content = "Eu vou ficar bem. Apenas deixe comigo!",
  ui_story_5036_50361201_57_dialog_content = "Eles nos informaram. É na área de bloqueio, não é?",
  ui_story_5036_50361201_58_dialog_content = "Aquele lugar é muito perigoso! Eu estou indo com você!",
  ui_story_5036_50361201_59_dialog_content = "Conte comigo também.",
  ui_story_5036_50361201_60_dialog_content = "É bem longe do palco. Indo para lá e para trás definitivamente demoraria um pouco.",
  ui_story_5036_50361201_61_dialog_content = "Se vocês dois ainda planejam se apresentar, é melhor ficar aqui e se preparar.",
  ui_story_5036_50361201_62_dialog_content = "Mas como você pode lidar com esses Eclipsites sozinho?",
  ui_story_5036_50361201_63_dialog_content = "Não precisa se preocupar com isso, Carleen. Goldie, Vic e eu já nos livramos de todos os Eclipsite aqui e ali.",
  ui_story_5036_50361201_64_dialog_content = "Eu ficaria bem se fosse sozinha.",
  ui_story_5036_50361201_65_dialog_content = "Se você diz, seja rápido e tenha cuidado!",
  ui_story_5036_50361201_66_dialog_content = "Eu vou, não se preocupe.",
  ui_story_5036_50361201_67_dialog_content = "Tudo bem, pessoal! É hora de começar nosso concerto!",
  ui_story_5036_50361201_68_dialog_content = "Se Vic não voltar a tempo, vocês dois terão que subir no palco um pouco antes do previsto, entendeu?",
  ui_story_5036_50361201_69_dialog_content = "Sim! Entendi!",
  ui_story_5036_50361201_70_dialog_content = "Entendi.",
  ui_story_5036_50361201_71_dialog_content = "Ainda não começou?",
  ui_story_5036_50361201_72_dialog_content = "Eu acho que eles estão prestes a! Olhe para lá!",
  ui_story_5036_50361201_73_dialog_content = "O momento finalmente chegou, pessoal! Desculpe por ter deixado todos vocês esperando!",
  ui_story_5036_50361201_74_dialog_content = "O Sky Concert \"O Momento em que as Estrelas Mais Brilham\" está finalmente prestes a começar!",
  ui_story_5036_50361201_75_dialog_content = "Uau!!!",
  ui_story_5036_50361201_76_dialog_content = "<color=#e8d9bb>Enquanto isso</color>",
  ui_story_5036_50361201_77_dialog_content = "Hum? O que poderia ser?",
  ui_story_5036_50361201_78_dialog_content = "Algo brilhante está passando pelas nuvens... Isso é um Colosso?!",
  ui_story_5036_50361201_79_dialog_content = "Parece haver música vindo dele. Essa voz disse algo sobre um Sky Concert, certo?",
  ui_story_5036_50361201_80_dialog_content = "Permita-me esclarecer, senhorita. Como você pode ou não saber, esse é o Colosso Errante que chegou recentemente da Noite Eterna.",
  ui_story_5036_50361201_81_dialog_content = "Parece que um ídolo chamado Goldie está realizando um show a bordo.",
  ui_story_5036_50361201_82_dialog_content = "Todos os jornais de Umbraton estão cheios de notícias sobre esse show.",
  ui_story_5036_50361201_83_dialog_content = "É assim mesmo? Que divertido.",
  ui_story_5036_50361201_84_dialog_content = "Venha, vamos encontrar um bom ângulo de visão e ver o que está acontecendo!",
  ui_story_5036_50361201_85_dialog_content = "Como quiser, milady.",
  ui_story_5036_50361201_86_dialog_content = "Olha lá em cima, mana! É um Colosso!",
  ui_story_5036_50361201_87_dialog_content = "Uau! Um verdadeiro Colosso!",
  ui_story_5036_50361201_88_dialog_content = "Espere, no topo do Colossus, isso é uma tela? Parece que está tocando alguma coisa...",
  ui_story_5036_50361201_89_dialog_content = "Ei! Não é a garota que nos protegeu do dono do teatro naquele dia?!",
  ui_story_5036_50361201_90_dialog_content = "É ela! Afinal, ela encontrou um lugar para realizar seu show! E em um Colosso, nada menos!",
  ui_story_5036_50361201_91_dialog_content = "Embora não tenhamos ingressos, podemos ver e ouvir tudo claro como o dia. Ela é incrível, né mana?",
  ui_story_5036_50361201_92_dialog_content = "Está voando por aí! Vamos lá, vamos alcançá-lo!",
  ui_story_5036_50361201_93_dialog_content = "Vamos seguir o rio e torcer por ela o tempo todo!",
  ui_story_5036_50361201_94_dialog_content = "Já posso sentir o entusiasmo de todos!",
  ui_story_5036_50361201_95_dialog_content = "Para o nosso ato de abertura, temos dois ídolos quentes de um lugar ainda mais quente - o Rediesel Desert, trazendo a você uma performance apaixonada e ardente!",
  ui_story_5036_50361201_96_dialog_content = "Vamos aplaudir Regina e Bárbara!",
  ui_story_5036_50361201_97_dialog_content = "♪ Incinerar, queimar tudo no chão—♪",
  ui_story_5036_50361201_98_dialog_content = "♪ Eu ofereço a você todo o meu amor—♪",
  ui_story_5036_50361201_99_dialog_content = "<size=40>♪ Explosão! Explosão! Quebre-o em pedaços! ♪</size>",
  ui_story_5036_50361201_100_dialog_content = "<size=45>♪ Ouça as batidas do meu coração, que anseia por vê-lo novamente ♪</size>",
  ui_story_5036_50361201_101_dialog_content = "(Droga, por que a voz dela está tão alta?!)",
  ui_story_5036_50361201_102_dialog_content = "(não vou deixar ela me bater!!!)",
  ui_story_5036_50361201_103_dialog_content = "<size=40>♪ Este é meu—♪</size>",
  ui_story_5036_50361201_104_dialog_content = "<size=45>♪ Meu único desejo, ser seu—♪</size>",
  ui_story_5036_50361201_105_dialog_content = "<size=50>♪ Rock'n'Roll!!! ♪</size>",
  ui_story_5036_50361201_106_dialog_content = "<size=50>♪ Ídolo!!! ♪</size>",
  ui_story_5036_50361201_107_dialog_content = "Que diabos é esse barulho?! É tão alto e não consigo entender nada do que eles estão dizendo!",
  ui_story_5036_50361201_108_dialog_content = "Ugh, parece que meus ouvidos estão prestes a explodir. Desligue os microfones deles!",
  ui_story_5036_50361201_109_dialog_content = "Você está brincando comigo?! Eles prometeram não lutar no palco!",
  ui_story_5036_50361201_110_dialog_content = "Isso não vai adiantar... Se as coisas continuarem assim, a performance será um desastre. Eu tenho que colocá-los de volta nos trilhos!",
  ui_story_5036_50361201_111_dialog_content = "♪ Sinta meu coração, como está batendo e queimando, assim como o sol do deserto—♪",
  ui_story_5036_50361201_112_dialog_content = "(Espere, o que a apresentadora está fazendo no palco? E por que ela está cantando?!)",
  ui_story_5036_50361201_113_dialog_content = "(Isso não fazia parte do ensaio!)",
  ui_story_5036_50361201_114_dialog_content = "(Espero que eles entendam a mensagem. Vamos, sorte, não me decepcione agora!)",
  ui_story_5036_50361201_115_dialog_content = "♪ Tudo que eu quero é que você me ouça e sinta como eu me sinto! E isso é—♪",
  ui_story_5036_50361201_116_dialog_content = "♪ Isso é—♪",
  ui_story_5036_50361201_117_dialog_content = "♪ Isso é—♪",
  ui_story_5036_50361201_118_dialog_content = "<size=45>♪ Amor—!!!♪</size>",
  ui_story_5036_50361201_119_dialog_content = "♪ Amor que nunca acaba! ♪",
  ui_story_5036_50361201_120_dialog_content = "♪ O amor que sempre vem para ficar! ♪",
  ui_story_5036_50361201_121_dialog_content = "<size=50>♪ Amor como as areias infinitas do Rediesel—♪</size>",
  ui_story_5036_50361201_122_dialog_content = "(Funcionou! Esses dois finalmente voltaram a sincronizar!)",
  ui_story_5036_50361201_123_dialog_content = "(Agora, para fazer a minha saída.)",
  ui_story_5036_50361201_124_dialog_content = "♪ Com minha rocha justa que não pode ser parada— ♪",
  ui_story_5036_50361201_125_dialog_content = "♪ Vou estender a mão e tocar seu coração— ♪",
  ui_story_5036_50361201_126_dialog_content = "<size=50>♪ Deixe nossa música ecoar nos céus—♪</size>",
  ui_story_5036_50361201_127_dialog_content = "Huh? Ei, eles estão começando a soar muito bem!",
  ui_story_5036_50361201_128_dialog_content = "As poses de Goldie são incríveis! É melhor eu tirar o máximo de fotos que puder!",
  ui_story_5036_50361201_129_dialog_content = "Apesar de suas melodias serem diferentes, as duas cantam em perfeita harmonia. Basta olhar para a multidão reunida!",
  ui_story_5036_50361201_130_dialog_content = "Surpreendente! Eu não acredito que Lumopolis já recebeu um show como este!",
  ui_story_5036_50361201_131_dialog_content = "Parece que o Colosso está voando agora, senhorita.",
  ui_story_5036_50361201_132_dialog_content = "Rápido! Para minha aeronave particular!",
  ui_story_5036_50361201_133_dialog_content = "?!?",
  ui_story_5036_50361201_134_dialog_content = "Como eu poderia perder um show tão incrível? Pressa!",
  ui_story_5036_50361201_135_dialog_content = "Fazendo um show em um Colosso para o mundo ver. Acho que ninguém nunca fez isso antes!",
  ui_story_5036_50361201_136_dialog_content = "Mais e mais pessoas estão se reunindo.",
  ui_story_5036_50361201_137_dialog_content = "Até os comerciantes estão começando a alugar seus navios para que as pessoas assistam ao show do Gold River.",
  ui_story_5036_50361201_138_dialog_content = "Heheheh. Afinal, parece que fiz certo em investir no sonho dessa menina.",
  ui_story_5036_50361201_139_dialog_content = "São Vic e PlayerName de volta ainda?",
  ui_story_5036_50361201_140_dialog_content = "Ainda não.",
  ui_story_5036_50361201_141_dialog_content = "Estou começando a me preocupar com esses dois...",
  ui_story_5036_50361201_142_dialog_content = "Parece que não temos escolha a não ser deixar vocês dois subirem no palco primeiro.",
  ui_story_5036_50361201_143_dialog_content = "Nele!",
  ui_story_5036_50361201_144_dialog_content = "Vamos dar uma salva de palmas para Regina e Barbara por sua performance maravilhosa!",
  ui_story_5036_50361201_145_dialog_content = "O show está começando a esquentar. Meu coração está praticamente saindo do meu peito!",
  ui_story_5036_50361201_146_dialog_content = "A seguir, temos duas das estrelas mais brilhantes de todo o Astra prontas para fazer sua grande estreia!",
  ui_story_5036_50361201_147_dialog_content = "Uma dupla improvável: um é um cavaleiro de Lumopolis e o outro é um oficial da Federação Illumina!",
  ui_story_5036_50361201_148_dialog_content = "Mas, apesar de suas diferentes facções, eles se tornaram amigos íntimos e embarcaram em inúmeras aventuras junto com o lendário Caelestite!",
  ui_story_5036_50361201_149_dialog_content = "Hoje, eles gostariam de compartilhar sua música com todos vocês, uma música que captura a beleza e a emoção de todas as suas viagens juntos!",
  ui_story_5036_50361201_150_dialog_content = "Junte as mãos para Carleen e Vice-!",
  ui_story_5036_50361201_151_dialog_content = "Uau, basta olhar para todas aquelas pessoas. Se apenas PlayerName estava aqui...",
  ui_story_5036_50361201_152_dialog_content = "Não fique nervoso. Nós ficaremos bem.",
  ui_story_5036_50361201_153_dialog_content = "Você tem razão! Vamos, Carleen!",
  ui_story_5036_50361201_154_dialog_content = "♪ Uma viagem inimaginável ♪",
  ui_story_5036_50361201_155_dialog_content = "♪ Uma estrada não encontrada em nenhum mapa ♪",
  ui_story_5036_50361201_156_dialog_content = "♪ Diga-me, o que pode vir pela frente? ♪",
  ui_story_5036_50361201_157_dialog_content = "♪ Uma sensação de admiração ♪",
  ui_story_5036_50361201_158_dialog_content = "♪ Caminhamos lado a lado, desde o dia em que nos conhecemos ♪",
  ui_story_5036_50361201_159_dialog_content = "♪ Não importa a distância, sempre nos encontraremos novamente! ♪",
  ui_story_5036_50361201_160_dialog_content = "♪ Meu querido companheiro ♪",
  ui_story_5036_50361201_161_dialog_content = "♪ De estranhos a amigos! ♪",
  ui_story_5036_50361201_162_dialog_content = "♪ Uma companheira para toda a vida, uma luz sem fim! ♪",
  ui_story_5036_50361201_163_dialog_content = "♪ Navegamos pelo céu como dois cometas entrelaçados ♪",
  ui_story_5036_50361201_164_dialog_content = "Graças a Deus Gronru teve a visão de instalar um transmissor de sinal antes do show começar. Agora todos podemos curtir a música, mesmo daqui.",
  ui_story_5036_50361201_165_dialog_content = "Devo dizer que esta nova forma de entretenimento é bastante digna de consideração.",
  ui_story_5036_50361201_166_dialog_content = "Talvez possamos realizar testes semelhantes nas Cidades Subterrâneas algum dia. O que você diz, Grande Marechal?",
  ui_story_5036_50361201_167_dialog_content = "Muito bem. Eu vou permitir isso.",
  ui_story_5036_50361201_168_dialog_content = "R-Sério? Excelente!",
  ui_story_5036_50361201_169_dialog_content = "Por que você parece tão surpreso?",
  ui_story_5036_50361201_170_dialog_content = "Eu só estava preocupado que você não aprovasse esse tipo de entretenimento, só isso.",
  ui_story_5036_50361201_171_dialog_content = "Hahaha! Claro, eu tenho minhas considerações sobre esse tipo de coisa... mas ouça atentamente a música.",
  ui_story_5036_50361201_172_dialog_content = "Posso não ter muito talento para cantar, mas até eu posso dizer que agora, neste exato momento, Vice está transbordando de felicidade.",
  ui_story_5036_50361201_173_dialog_content = "É exatamente o tipo de sentimento que precisamos, não é?",
  ui_story_5036_50361201_174_dialog_content = "Eu mal consigo ouvir Lady Carleen e Vice cantando, mesmo daqui...",
  ui_story_5036_50361201_175_dialog_content = "Eles soam incríveis! Essa é Lady Carleen para você!",
  ui_story_5036_50361201_176_dialog_content = "Raphael, fique aqui e guarde este lugar com vigilância extra.",
  ui_story_5036_50361201_177_dialog_content = "Além disso, peça a alguém que prepare uma aeronave para mim e a mantenha em segredo.",
  ui_story_5036_50361201_178_dialog_content = "Huh? Você está saindo agora, meu senhor?",
  ui_story_5036_50361201_179_dialog_content = "Ainda não está claro se o Colossus representa uma ameaça ou não. Como City Lord, é meu dever investigar o assunto e garantir a segurança de nossa cidade pessoalmente.",
  ui_story_5036_50361201_180_dialog_content = "U-entendido!",
  ui_story_5036_50361201_181_dialog_content = "Suspirar...",
  ui_story_5036_50361201_182_dialog_content = "Quando Lord Schwartz simplesmente admitirá que se importa com Lady Carleen?",
  ui_story_5036_50361201_183_dialog_content = "<color=#e8d9bb>Enquanto isso, dentro do Colosso Errante</color>",
  ui_story_5036_50361201_184_dialog_content = "Esse canto soa como Vice e Carleen!",
  ui_story_5036_50361201_185_dialog_content = "Já é hora de sua apresentação? Merda, eu deveria pegar o ritmo!",
  ui_story_5036_50361201_186_dialog_content = "Eu já deveria estar lá, no entanto...",
  ui_story_5036_50361201_187_dialog_content = "Nada como uma performance de dois dos maiores aventureiros do mundo!",
  ui_story_5036_50361201_188_dialog_content = "Isso apenas mostra que os ídolos podem vir de todas as esferas da vida!",
  ui_story_5036_50361201_189_dialog_content = "Para alguns fãs, os melhores ídolos são aqueles que trazem a verdadeira força de outras pessoas!",
  ui_story_5036_50361201_190_dialog_content = "O próximo a subir ao palco é um coral carismático do Illumina!",
  ui_story_5036_50361201_191_dialog_content = "Eles estão aqui para cantar um hino militar inspirador—!",
  ui_story_5036_50361201_192_dialog_content = "Uau!!!",
  ui_story_5036_50361201_193_dialog_content = "Ufa! Mais uma vez obrigada pela ajuda, meninas!",
  ui_story_5036_50361201_194_dialog_content = "Não mencione isso! Estou feliz que tudo correu bem!",
  ui_story_5036_50361201_195_dialog_content = "estou começando a me preocupar PlayerName e Vic embora. Eles se foram por um tempo.",
  ui_story_5036_50361201_196_dialog_content = "De fato. O Colossus pode ser grande, mas não deve demorar tanto para encontrar alguém.",
  ui_story_5036_50361201_197_dialog_content = "Hum...",
  ui_story_5036_50361201_198_dialog_content = "Vamos, Carleen. Devíamos ir procurá-los.",
  ui_story_5036_50361201_199_dialog_content = "Concordo. Agora que nossa apresentação acabou, nossa principal prioridade é garantir que esses dois estejam seguros.",
  ui_story_5036_50361201_200_dialog_content = "Claro, mas tenha cuidado lá fora e lembre-se de voltar para poder fazer uma reverência!",
  ui_story_5036_50361201_201_dialog_content = "Sim!",
  ui_story_5036_50361201_202_dialog_content = "Vamos.",
  ui_story_5036_50361201_203_dialog_content = "<color=#e8d9bb>Algum tempo depois</color>",
  ui_story_5036_50361201_204_dialog_content = "O Illumina Choir terminou sua música, e o Lumopolis Choir está quase terminando a deles também...",
  ui_story_5036_50361201_205_dialog_content = "Onde na terra estão PlayerName e os outros? Será que algo pode ter acontecido com eles?",
  ui_story_5036_50361201_206_dialog_content = "Eles estão começando a me preocupar, mas não posso simplesmente ir embora. Minha apresentação final está chegando em breve!",
  ui_story_5036_50361201_207_dialog_content = "Tenho que garantir que todos ouçam minha música.",
  ui_story_5036_50361201_208_dialog_content = "Caso contrário, todo o nosso trabalho duro terá sido em vão.",
  ui_story_5036_50361201_209_dialog_content = "Vou procurá-los assim que terminar.",
  ui_story_5036_50361201_210_dialog_content = "Estamos nos aproximando do gran finale, pessoal! Ainda estamos nos divertindo?!",
  ui_story_5036_50361201_211_dialog_content = "Sim-!",
  ui_story_5036_50361201_212_dialog_content = "Fantástico! Obrigado por manter a energia alta durante todo o show, pessoal!",
  ui_story_5036_50361201_213_dialog_content = "Agora, para o ato final do show, deixe-me despedir todos vocês com uma música de minha autoria!",
  ui_story_5036_50361201_214_dialog_content = "Uau!!! Finalmente é a vez de Goldie cantar!!!",
  ui_story_5036_50361201_215_dialog_content = "A próxima música é muito especial. Foi usado pelos celestitas para se comunicar com os colossos.",
  ui_story_5036_50361201_216_dialog_content = "Usando sua melodia única, os Caelestitas pilotariam seus majestosos Colossos por todo o mundo!",
  ui_story_5036_50361201_217_dialog_content = "Hoje, em homenagem ao tão esperado retorno deste Colosso, esta melodia soará mais uma vez!",
  ui_story_5036_50361201_218_dialog_content = "Uau-!!!",
  ui_story_5036_50361201_219_dialog_content = "(É isso. Este é o momento que todos esperávamos.)",
  ui_story_5036_50361201_220_dialog_content = "Onde quer que Goldie vá, os Goldilocks seguem!",
  ui_story_5036_50361201_221_dialog_content = "(Deixe essa música ser minha forma de retribuir meus fãs e PlayerName por todo o seu apoio infinito!)",
  ui_story_5036_50361201_222_dialog_content = "♪ Luz das estrelas, brilhando no céu ♪",
  ui_story_5036_50361201_223_dialog_content = "♪ Um passarinho abre suas asas para voar ♪",
  ui_story_5036_50361201_224_dialog_content = "♪ Uma longa e perigosa viagem está diante de seus olhos ♪",
  ui_story_5036_50361201_225_dialog_content = "♪ Então ilumine o caminho dela durante toda a noite! ♪",
  ui_story_5036_50361201_226_dialog_content = "Goldie! Goldie!",
  ui_story_5036_50361201_227_dialog_content = "Ah... posso ouvir a senhorita Goldie cantando...",
  ui_story_5036_50361201_228_dialog_content = "Não importa o quão difícil as coisas tenham sido. Isso faz tudo valer a pena!",
  ui_story_5036_50361201_229_dialog_content = "♪ Uma chance de te ver, uma chance de o amor crescer! ♪",
  ui_story_5036_50361201_230_dialog_content = "♪ Encha meu coração de coragem e me diga para onde ir! ♪",
  ui_story_5036_50361201_231_dialog_content = "(Urgh... P-Por que me sinto tão sonolento...?)",
  ui_story_5036_50361201_232_dialog_content = "(Espera, o que estou pensando?! Estou no meio de uma música agora!!)",
  ui_story_5036_50361201_233_dialog_content = "♪ Vamos, vamos, me leve embora! ♪",
  ui_story_5036_50361201_234_dialog_content = "♪ Para um lugar onde eu possa te ver todos os dias! ♪",
  ui_story_5036_50361201_235_dialog_content = "(O que está acontecendo...? Minha cabeça está girando...)",
  ui_story_5036_50361201_236_dialog_content = "Kree—!",
  ui_story_5036_50361201_237_dialog_content = "(Aquele som... De onde veio esse som?)",
  ui_story_5036_50361201_238_dialog_content = "(Estou tão cansado... Mas ainda não consigo dormir! O concerto... Ainda não acabou...)",
  ui_story_5036_50361301_1_dialog_content = "<color=#e8d9bb>Enquanto isso, na área de bloqueio</color>",
  ui_story_5036_50361301_2_dialog_content = "O que está acontecendo? Parece que estou andando em círculos de novo.",
  ui_story_5036_50361301_3_dialog_content = "Ainda me lembro do caminho para o ovo, então por que ainda não cheguei lá?",
  ui_story_5036_50361301_4_dialog_content = "O Ouroboros poderia ter ativado seus poderes psíquicos novamente?",
  ui_story_5036_50361301_5_dialog_content = "Já estamos lá? O concerto provavelmente já está quase no fim...",
  ui_story_5036_50361301_6_dialog_content = "Ah! Aí está! Depois de tanto tempo, finalmente consegui!",
  ui_story_5036_50361301_7_dialog_content = "Hum? O que você está fazendo aqui, PlayerName?",
  ui_story_5036_50361301_8_dialog_content = "Não me diga que o show foi tão chato que você veio aqui para tirar uma soneca também?",
  ui_story_5036_50361301_9_dialog_content = "Que tipo de idiota você acha que sou?!",
  ui_story_5036_50361301_10_dialog_content = "Mais importante, o que VOCÊ está fazendo aqui?! Todo mundo ainda está esperando pelo seu desempenho!",
  ui_story_5036_50361301_11_dialog_content = "Minha performance? Oh, você quer dizer a coisa toda de cantar, certo?",
  ui_story_5036_50361301_12_dialog_content = "Desculpe, mas não consigo.",
  ui_story_5036_50361301_13_dialog_content = "O que você quer dizer?! Você tem um dom, e Goldie passou todo esse tempo e esforço treinando você! Como você pode optar por desistir em um momento como este?!",
  ui_story_5036_50361301_14_dialog_content = "Hahahaha! Você está absolutamente certo, eu tenho um dom. Mas eu realmente não posso fazer isso.",
  ui_story_5036_50361301_15_dialog_content = "Você já viu como eles treinam?",
  ui_story_5036_50361301_16_dialog_content = "Para atuar no palco, eles precisam de semanas de treinamento, além de um suprimento inesgotável de energia e entusiasmo. E eu sou muito deficiente em ambos os departamentos, garoto.",
  ui_story_5036_50361301_17_dialog_content = "Além disso, não tenho interesse em shows ou ídolos. Meus velhos ossos simplesmente não foram feitos para esse tipo de coisa infantil.",
  ui_story_5036_50361301_18_dialog_content = "E mesmo se eu subisse naquele palco, só estaria atrasando vocês, jovens.",
  ui_story_5036_50361301_19_dialog_content = "Então, em vez de tornar as coisas difíceis para todos, decidi usar minhas poucas habilidades para um bom uso! Como cuidar desse ovo e garantir que ele não estrague o show!",
  ui_story_5036_50361301_20_dialog_content = "Para alguém que diz não se importar com o show, com certeza você está demonstrando muita preocupação.",
  ui_story_5036_50361301_21_dialog_content = "Haha! Só não quero ficar na posição de dever um favor a um bando de garotos.",
  ui_story_5036_50361301_22_dialog_content = "Acho que é um pouco tarde para isso...",
  ui_story_5036_50361301_23_dialog_content = "Ahem, se você está falando sobre meus aprendizes, tudo isso faz parte do treinamento deles.",
  ui_story_5036_50361301_24_dialog_content = "Mas chega disso, você sentiu isso no caminho até aqui, não é? O ovo de Ouroboros ativou seus poderes novamente.",
  ui_story_5036_50361301_25_dialog_content = "Sim. Parecia que eu estava andando por horas antes de chegar aqui.",
  ui_story_5036_50361301_26_dialog_content = "Isso só pode significar que o Ouroboros detecta o perigo novamente e está tentando se defender.",
  ui_story_5036_50361301_27_dialog_content = "Mas e os Eclipsites que removemos ou as rachaduras que protegemos?",
  ui_story_5036_50361301_28_dialog_content = "Poderia ser porque os outros aurorianos estão muito longe?",
  ui_story_5036_50361301_29_dialog_content = "Com o show em pleno andamento, todos os aurorianos estão reunidos na frente do Colosso, o lugar mais distante de nossa posição atual.",
  ui_story_5036_50361301_30_dialog_content = "Se algo acontecesse aqui, seríamos os únicos a defendê-lo. Os outros não poderiam chegar aqui a tempo.",
  ui_story_5036_50361301_31_dialog_content = "Então você acha que o Ouroboros está com medo por causa disso?",
  ui_story_5036_50361301_32_dialog_content = "É possível!",
  ui_story_5036_50361301_33_dialog_content = "Que criatura covarde esse Ouroboros acabou sendo. Depois de todos esses anos a bordo de um Colossus infestado de Eclipsite, ele ainda está com medo!",
  ui_story_5036_50361301_34_dialog_content = "Acho que não tem medo deles tanto quanto tem medo de ficar sozinho de novo, Vic.",
  ui_story_5036_50361301_35_dialog_content = "Passei os primeiros dezessete anos da minha vida a bordo de um Colossus. Mesmo estando sozinho, nunca me senti sozinho porque tinha Soroz para me fazer companhia.",
  ui_story_5036_50361301_36_dialog_content = "Mas agora que fiz tantos amigos. Eu sei que nunca poderia me separar deles.",
  ui_story_5036_50361301_37_dialog_content = "Você fez um bom ponto.",
  ui_story_5036_50361301_38_dialog_content = "De qualquer forma, o que você quis dizer agora com o ovo \"estragando o show\"?",
  ui_story_5036_50361301_39_dialog_content = "Já está bem encaminhado. O que o ovo de Ouroboros poderia fazer com ele agora?",
  ui_story_5036_50361301_40_dialog_content = "Um observador atento como sempre.",
  ui_story_5036_50361301_41_dialog_content = "Como eu disse antes, algum fator desconhecido impediu que esse ovo eclodisse, e é por isso que ele cresceu em proporções monumentais.",
  ui_story_5036_50361301_42_dialog_content = "Mas, por essa mesma razão, também não tenho ideia de quando irá eclodir.",
  ui_story_5036_50361301_43_dialog_content = "Dado o tamanho atual do ovo, se o Ouroboros chocasse agora... Receio que teria um impacto enorme em todo o Colosso.",
  ui_story_5036_50361301_44_dialog_content = "Huh...?!",
  ui_story_5036_50361301_45_dialog_content = "Isso não significa que este ovo é tão perigoso quanto uma bomba-relógio, não é?!",
  ui_story_5036_50361301_46_dialog_content = "Precisamente!",
  ui_story_5036_50361301_47_dialog_content = "É por isso que decidi vigiá-lo, entende? Não apenas pelo bem do show, mas também pelo bem de nossas próprias vidas.",
  ui_story_5036_50361301_48_dialog_content = "E o fato de você ter chegado a tal conclusão significa que você tem aptidão para uma carreira em extrozoologia, PlayerName!",
  ui_story_5036_50361301_49_dialog_content = "O que você disse? Quer trabalhar comigo como meu mais novo aprendiz?",
  ui_story_5036_50361301_50_option_content = "Claro!",
  ui_story_5036_50361301_51_dialog_content = "Eu tenho que admitir, bestas maravilhosas são bem interessantes. Sem mencionar que muitos deles também estão ameaçados de extinção.",
  ui_story_5036_50361301_52_dialog_content = "Protegê-los seria uma escolha de carreira muito significativa.",
  ui_story_5036_50361301_53_dialog_content = "Um ponto de vista muito válido, PlayerName. Ou devo dizer, meu pequeno aprendiz?",
  ui_story_5036_50361301_54_dialog_content = "Mas estou lhe dizendo agora, não vou deixar você mandar em mim ou me mandar fazer recados de graça.",
  ui_story_5036_50361301_55_dialog_content = "*Soluço* Isso é jeito de ver seu mestre?",
  ui_story_5036_50361301_56_option_content = "Acho que vou passar.",
  ui_story_5036_50361301_57_dialog_content = "Pesquisar bestas maravilhosas é ótimo e tudo mais, mas depois de conhecer Fia e Shira, eu sei tudo sobre a vida como um de seus aprendizes...",
  ui_story_5036_50361301_58_dialog_content = "Ser enviado em investigações sem nenhum dinheiro, cuidar de feras maravilhosas, cuidar de seu mestre...",
  ui_story_5036_50361301_59_dialog_content = "Que tipo de vida é essa?!",
  ui_story_5036_50361301_60_dialog_content = "Tudo o que fazemos pelas feras maravilhosas é por amor e respeito a elas, por isso não pedimos nada em troca!",
  ui_story_5036_50361301_61_dialog_content = "Mas se você se opõe tanto a isso, não tentarei fazê-lo mudar de ideia.",
  ui_story_5036_50361301_62_dialog_content = "Já perdi tanto tempo aqui. Eu me pergunto como o show está indo.",
  ui_story_5036_50361301_63_dialog_content = "Vou voltar e avisar que está tudo bem, para que não continuem se preocupando conosco.",
  ui_story_5036_50361301_64_dialog_content = "Claro! Nesse caso, vou ficar aqui e...",
  ui_story_5036_50361301_65_dialog_content = "Kree—!",
  ui_story_5036_50361301_66_dialog_content = "Que barulho foi esse?",
  ui_story_5036_50361301_67_dialog_content = "Som? Que som? Tem certeza que não está ouvindo coisas?",
  ui_story_5036_50361301_68_dialog_content = "Oi, Carleen? Você acabou de ouvir um barulho estranho?",
  ui_story_5036_50361301_69_dialog_content = "Parecia um grito de animal.",
  ui_story_5036_50361301_70_dialog_content = "Ngh...",
  ui_story_5036_50361301_71_dialog_content = "Carleen! Você está bem?! O que é...",
  ui_story_5036_50361301_72_dialog_content = "O que está acontecendo...? Tão sonolento...",
  ui_story_5036_50361301_73_dialog_content = "Parecia... o Ouroboros...",
  ui_story_5036_50361301_74_dialog_content = "(Huh? Por que estou... tão... com sono...?)",
  ui_story_5036_50361301_75_dialog_content = "PlayerName? Qual é o problema? Sair dessa!",
  ui_story_5036_50361301_76_dialog_content = "Parece que não tenho escolha a não ser usar meu último recurso. Bica! Entre no bolso do PlayerName e coma todo o seu Nightium!",
  ui_story_5036_50361301_77_dialog_content = "Oi!",
  ui_story_5036_50361301_78_dialog_content = "O-o quê?! Não por favor! Qualquer coisa menos isso!",
  ui_story_5036_50361301_79_dialog_content = "Sabe quanto tempo eu trabalhei para salvar tudo isso?!",
  ui_story_5036_50361301_80_dialog_content = "Oh bom, você está acordado.",
  ui_story_5036_50361301_81_dialog_content = "Você ficou acordado até tarde ontem à noite ou algo assim? Você estava prestes a desmaiar.",
  ui_story_5036_50361301_82_dialog_content = "Huh? De jeito nenhum, na verdade, fui para a cama bem cedo ontem à noite.",
  ui_story_5036_50361301_83_dialog_content = "Estranho... Eu poderia jurar que ouvi o Ouroboros agora, e de repente me senti extremamente sonolento...",
  ui_story_5036_50361301_84_dialog_content = "Você ouviu o Ouroboros? Por que não ouvi?",
  ui_story_5036_50361301_85_dialog_content = "Estou falando sério! Se você não acredita em mim, apenas continue ouvindo; pode gritar de novo!",
  ui_story_5036_50361301_86_dialog_content = "Se você diz, ficarei atento.",
  ui_story_5036_50361301_87_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361301_88_dialog_content = "Não ouço nada, muito menos um Ouroboros! Você deve ter ouvido errado.",
  ui_story_5036_50361301_89_dialog_content = "Mas...",
  ui_story_5036_50361301_90_dialog_content = "<color=#e8d9bb>Baque—</color>",
  ui_story_5036_50361301_91_dialog_content = "Eu ouvi algo de novo! Só que desta vez não soou como o choro dos Ouroboros.",
  ui_story_5036_50361301_92_dialog_content = "Esse som, será?!",
  ui_story_5036_50361301_93_dialog_content = "Então você também ouve, certo?",
  ui_story_5036_50361301_94_dialog_content = "<color=#e8d9bb>Tum—Tump—</color>",
  ui_story_5036_50361301_95_dialog_content = "Oh, eu ouvi, tudo bem. Eu ouço alto e claro.",
  ui_story_5036_50361301_96_dialog_content = "É... um batimento cardíaco.",
  ui_story_5036_50361301_97_dialog_content = "Está vindo de dentro do ovo.",
  ui_story_5036_50361301_98_dialog_content = "Huh? V-você quer dizer que finalmente está chocando?!",
  ui_story_5036_50361301_99_dialog_content = "Esse cara tem o pior timing, você não concorda?",
  ui_story_5036_50361301_100_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5036_50361301_101_dialog_content = "E agora?!",
  ui_story_5036_50361301_102_dialog_content = "Cuidado, PlayerName!",
  ui_story_5036_50361301_103_dialog_content = "Algo está tentando romper a parede que fechamos ontem à noite!",
  ui_story_5036_50361301_104_dialog_content = "<color=#e8d9bb>Bum!!—</color>",
  ui_story_5036_50361301_105_dialog_content = "Graaaaaah-!",
  ui_story_5036_50361301_106_dialog_content = "É Eclipsita, Vic!",
  ui_story_5036_50361301_107_dialog_content = "Salve-nos, Bola de Pelos!",
  ui_story_5036_50361302_1_dialog_content = "Por que há tantos Eclipsitos aqui?!",
  ui_story_5036_50361302_2_dialog_content = "Achei que tínhamos nos livrado de todos ontem à noite!",
  ui_story_5036_50361302_3_dialog_content = "Parece que esses Eclipsites vieram de lugares ainda mais distantes.",
  ui_story_5036_50361302_4_dialog_content = "A julgar pelo quão agitados eles ficaram, acho que tem algo a ver com a incubação do Ouroboros.",
  ui_story_5036_50361302_5_dialog_content = "Seja o que for, temos que contar a Goldie e aos outros imediatamente!",
  ui_story_5036_50361302_6_dialog_content = "Se o Ouroboros é realmente sobre a escotilha, ficar a bordo do Colossus será muito perigoso para nós!",
  ui_story_5036_50361302_7_dialog_content = "Precisamos nos apressar e evacuar todos!",
  ui_story_5036_50361302_8_dialog_content = "É verdade que ficar aqui está completamente fora de questão.",
  ui_story_5036_50361302_9_dialog_content = "Afinal, esta sala pode cair em nossas cabeças assim que o Ouroboros chocar.",
  ui_story_5036_50361302_10_dialog_content = "Parece que é hora de correr!",
  ui_story_5036_50361302_11_dialog_content = "Deste jeito. Não se separe!",
  ui_story_5036_50361302_12_dialog_content = "Espere, acho que há duas pessoas no chão ali.",
  ui_story_5036_50361302_13_dialog_content = "É Vice e Carleen!",
  ui_story_5036_50361302_14_dialog_content = "Vício! Carleen! Acordar!",
  ui_story_5036_50361302_15_dialog_content = "O que está acontecendo? Eu não posso acordá-los!",
  ui_story_5036_50361302_16_dialog_content = "Isso poderia ser o trabalho do Ouroboros também?",
  ui_story_5036_50361302_17_dialog_content = "É muito perigoso deixá-los aqui. Teremos apenas que carregá-los.",
  ui_story_5036_50361302_18_dialog_content = "Tudo bem, deixe comigo. Eu vou pegá-los.",
  ui_story_5036_50361302_19_dialog_content = "Hrrrrrrng-ufa!",
  ui_story_5036_50361302_20_dialog_content = "Você pode considerar levantar pesos se conseguirmos sair daqui, PlayerName.",
  ui_story_5036_50361302_21_dialog_content = "Agora definitivamente não é a hora, Vic! Ajude-me a pegá-los!",
  ui_story_5036_50361302_22_dialog_content = "Acho que também não serei de muita ajuda nesse sentido. No entanto-",
  ui_story_5036_50361302_23_dialog_content = "Venha, Bola de Pelos!",
  ui_story_5036_50361302_24_dialog_content = "Piu!",
  ui_story_5036_50361302_25_dialog_content = "Pode ficar maior?!",
  ui_story_5036_50361302_26_dialog_content = "Obviamente! Mas isso não muda seu pelo macio e abraçável.",
  ui_story_5036_50361302_27_dialog_content = "Eu não poderia pedir uma cama melhor para minhas sonecas da tarde! Aqui, você quer sentir isso? O primeiro toque é grátis!",
  ui_story_5036_50361302_28_dialog_content = "M-Talvez da próxima vez, Vic...",
  ui_story_5036_50361302_29_dialog_content = "Agora então, Little Furball, ou devo dizer Big Furball? Preciso que carregue aquelas duas garotas ali.",
  ui_story_5036_50361302_30_dialog_content = "Chirrrp—!",
  ui_story_5036_50361302_31_dialog_content = "Vamos seguir em frente! Ainda temos que avisar os outros!",
  ui_story_5036_50361302_32_dialog_content = "Essa não...",
  ui_story_5036_50361302_33_dialog_content = "Parece que estão todos dormindo.",
  ui_story_5036_50361302_34_dialog_content = "Aquela garota até desmaiou no palco sozinha.",
  ui_story_5036_50361302_35_dialog_content = "...",
  ui_story_5036_50361302_36_dialog_content = "Goldie! Saia dessa, Goldie!",
  ui_story_5036_50361302_37_dialog_content = "Por que não consigo acordar nenhum deles...?",
  ui_story_5036_50361302_38_dialog_content = "Algo está estranho em sua condição. Este parece ser o trabalho da Luminatics.",
  ui_story_5036_50361302_39_dialog_content = "Você acha que o Ouroboros também fez isso?",
  ui_story_5036_50361302_40_dialog_content = "Mas se assim for, por que ainda estamos acordados quando todo mundo está em coma como este?",
  ui_story_5036_50361302_41_dialog_content = "Porque há algo especial em nós dois.",
  ui_story_5036_50361302_42_dialog_content = "Você é um celestita, possui habilidades psíquicas únicas.",
  ui_story_5036_50361302_43_dialog_content = "Quanto a mim, minha linhagem compartilha uma origem semelhante com os Ouroboros. Esta pode ser a fonte da minha imunidade.",
  ui_story_5036_50361302_44_dialog_content = "Existe alguma maneira de acordá-los?",
  ui_story_5036_50361302_45_dialog_content = "Não posso dizer com certeza, não.",
  ui_story_5036_50361302_46_dialog_content = "Mas como pode ser isso? Você mesmo acabou de dizer: Você compartilha uma origem com os Ouroboros! Você deve ter alguma coisa.",
  ui_story_5036_50361302_47_dialog_content = "Desculpe, mas além de serem duradouros, o Ouroboros e eu não temos muito mais em comum.",
  ui_story_5036_50361302_48_dialog_content = "Você pode ter uma chance melhor.",
  ui_story_5036_50361302_49_dialog_content = "Sua habilidade psíquica pode permitir que você sinta algo que não sei.",
  ui_story_5036_50361302_50_dialog_content = "Ok, acho que não temos outras ideias.",
  ui_story_5036_50361401_1_dialog_content = "Estou... dormindo?",
  ui_story_5036_50361401_2_dialog_content = "Espere, aqui é Eraveil! Estou sonhando de novo?",
  ui_story_5036_50361401_3_dialog_content = "Algo está diferente desta vez. A cena parece muito mais clara do que antes.",
  ui_story_5036_50361401_4_dialog_content = "Posso até ver uma torre branca bem ali.",
  ui_story_5036_50361401_5_dialog_content = "Espere, o que é aquilo voando acima dele? É aquele...",
  ui_story_5036_50361401_6_dialog_content = "Um dragão?",
  ui_story_5036_50361401_7_dialog_content = "Oh, eu definitivamente estou sonhando!",
  ui_story_5036_50361401_8_dialog_content = "Mas como? Como isso aconteceu? Vamos, Goldie. Você tem que acordar! O concerto ainda não acabou!",
  ui_story_5036_50361401_9_dialog_content = "Dizem que beliscar a coxa em um sonho vai te acordar.",
  ui_story_5036_50361401_10_dialog_content = "Aqui vai!",
  ui_story_5036_50361401_11_dialog_content = "Yeeeeowch!",
  ui_story_5036_50361401_12_dialog_content = "Por que não acordei?! Talvez eu precise me beliscar ainda mais!",
  ui_story_5036_50361401_13_dialog_content = "♪ La—La la ♪",
  ui_story_5036_50361401_14_dialog_content = "Essa voz... já a ouvi antes! Parece aquela garota caelestita, Chaminade!",
  ui_story_5036_50361401_15_dialog_content = "♪ Asas... embebidas ♪",
  ui_story_5036_50361401_16_dialog_content = "Acho que desta vez consigo entender a letra da música dela.",
  ui_story_5036_50361401_17_dialog_content = "Não consegui ouvir nada além da melodia da última vez.",
  ui_story_5036_50361401_18_dialog_content = "♪... casa ♪",
  ui_story_5036_50361401_19_dialog_content = "Parece que está vindo de lá.",
  ui_story_5036_50361401_20_dialog_content = "♪ Tudo o que resta são aqueles momentos em minhas memórias ♪",
  ui_story_5036_50361401_21_dialog_content = "♪ A torre branca está alta e orgulhosa ♪",
  ui_story_5036_50361401_22_dialog_content = "♪ Mas sua luz guia está além da minha visão ♪",
  ui_story_5036_50361401_23_dialog_content = "(A melodia soa tão bonita, mas o olhar em seu rosto está cheio de nada além de tristeza...)",
  ui_story_5036_50361401_24_dialog_content = "♪ Vaguear, passear, ver a terra e o mar ♪",
  ui_story_5036_50361401_25_dialog_content = "♪ Mas nunca se esqueça da casa dos seus sonhos ♪",
  ui_story_5036_50361401_26_dialog_content = "Hum? Não sabia que haveria outros visitantes.",
  ui_story_5036_50361401_27_dialog_content = "(Huh?! E-ela está falando comigo?!)",
  ui_story_5036_50361401_28_dialog_content = "(Isso nunca aconteceu em meus sonhos anteriores. A menos que... isso não seja um sonho?)",
  ui_story_5036_50361401_29_dialog_content = "H-Olá! Você deve ser Chaminade. Meu nome é Goldie. Eu sou um ídolo!",
  ui_story_5036_50361401_30_dialog_content = "Hum? Você sabe meu nome?",
  ui_story_5036_50361401_31_dialog_content = "Claro que eu faço! Minha amiga PlayerName é um celestita também! Ele usou seus poderes psíquicos para ver suas memórias do passado.",
  ui_story_5036_50361401_32_dialog_content = "É assim mesmo? Heheheh, isso é um pouco embaraçoso.",
  ui_story_5036_50361401_33_dialog_content = "Diga, o que exatamente é um \"ídolo\"?",
  ui_story_5036_50361401_34_dialog_content = "Um ídolo é alguém que usa o poder da música para trazer felicidade e esperança para outras pessoas. Eu sou um ídolo profissional!",
  ui_story_5036_50361401_35_dialog_content = "Isso é incrível! Eu também quero ser um ídolo!",
  ui_story_5036_50361401_36_dialog_content = "Ficarei feliz em compartilhar algumas dicas com você, se quiser. Ah, mas agora não é uma boa hora. Eu tenho que voltar para o meu show e terminar minha performance!",
  ui_story_5036_50361401_37_dialog_content = "Você sabe como posso sair daqui, Chaminade?",
  ui_story_5036_50361401_38_dialog_content = "Sinto muito... Mas não sei como sair deste lugar.",
  ui_story_5036_50361401_39_dialog_content = "Afinal, eu também não tenho como sair daqui.",
  ui_story_5036_50361401_40_dialog_content = "Não há saída?",
  ui_story_5036_50361401_41_dialog_content = "(Isso faz sentido, já que a verdadeira ela já é...)",
  ui_story_5036_50361401_42_dialog_content = "(Espere, se o verdadeiro Chaminade já está morto... Então quem, ou o que, está na minha frente?)",
  ui_story_5036_50361401_43_dialog_content = "Mm, tudo bem!",
  ui_story_5036_50361401_44_dialog_content = "Enquanto procurarmos, encontraremos um!",
  ui_story_5036_50361401_45_dialog_content = "<color=#e8d9bb>Falha—</color>",
  ui_story_5036_50361401_46_dialog_content = "Huh? O que foi aquele barulho?",
  ui_story_5036_50361401_47_dialog_content = "São eles!",
  ui_story_5036_50361401_48_dialog_content = "Eles estão vindo! Temos que sair daqui!",
  ui_story_5036_50361401_49_dialog_content = "\"Eles\"? De quem você está falando?",
  ui_story_5036_50361401_50_dialog_content = "Os Eclipsos!",
  ui_story_5036_50361401_51_dialog_content = "Graaaaaah—!",
  ui_story_5036_50361401_52_dialog_content = "Ah, ela não está brincando! Por que há tantos deles?!",
  ui_story_5036_50361401_53_dialog_content = "Grahhhhhh—!",
  ui_story_5036_50361401_54_dialog_content = "De onde todos eles vieram?!",
  ui_story_5036_50361401_55_dialog_content = "Eles estão voltando de novo, Goldie! Rápido, esconda-se!",
  ui_story_5036_50361401_56_dialog_content = "Não há onde se esconder, não com tantos deles. Nossa única escolha é lutar!",
  ui_story_5036_50361401_57_dialog_content = "Eu não vou deixar vocês Eclipsitas ficarem loucos por mais tempo!",
  ui_story_5036_50361402_1_dialog_content = "Oof-!",
  ui_story_5036_50361402_2_dialog_content = "Droga! Simplesmente não há fim para eles! Não podemos vencê-los todos!",
  ui_story_5036_50361402_3_dialog_content = "Grahh!",
  ui_story_5036_50361402_4_dialog_content = "Ahhh!",
  ui_story_5036_50361402_5_dialog_content = "Esqueça de mim e apenas corra! Eles vão desaparecer em breve, então fique longe por enquanto!",
  ui_story_5036_50361402_6_dialog_content = "Hã? Como assim?",
  ui_story_5036_50361402_7_dialog_content = "Kree—",
  ui_story_5036_50361402_8_dialog_content = "Kree-!",
  ui_story_5036_50361402_9_dialog_content = "O dragão está... brilhando!?",
  ui_story_5036_50361402_10_dialog_content = "É tão brilhante! Não consigo ver nada—!",
  ui_story_5036_50361402_11_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361402_12_dialog_content = "É só seguir em frente, os Eclipsites estão logo atrás... Hã? O-Para onde foram os Eclipsites?",
  ui_story_5036_50361402_13_dialog_content = "Eles se foram agora. Está tudo bem.",
  ui_story_5036_50361402_13X1_dialog_content = "O Ouroboros fez todos eles desaparecerem!",
  ui_story_5036_50361402_13X2_dialog_content = "Ah, sim, ainda não o apresentei a você, não é? Está lá, o pequenino voando no céu acima!",
  ui_story_5036_50361402_14_dialog_content = "Se foi? Você quer dizer que a luz do Ouroboros os livrou?",
  ui_story_5036_50361402_15_dialog_content = "Não, não é forte o suficiente para fazer isso. Tudo o que fiz foi começar esse sonho de novo.",
  ui_story_5036_50361402_16_dialog_content = "Então, isso é realmente um sonho!",
  ui_story_5036_50361402_17_dialog_content = "É sim. Um sonho feito para mim pelo Ouroboros.",
  ui_story_5036_50361402_18_dialog_content = "Já que seu amigo é celestita, então você já deve ter visto o que aconteceu comigo...",
  ui_story_5036_50361402_19_dialog_content = "Sim...",
  ui_story_5036_50361402_20_dialog_content = "Depois de sentir que morri protegendo-o, o Ouroboros foi dominado pela dor.",
  ui_story_5036_50361402_21_dialog_content = "Ele sentiu o último desejo do meu coração de voltar para minha casa, então criou Eraveil em seu sonho, e eu.",
  ui_story_5036_50361402_22_dialog_content = "Mas por causa de seu próprio desejo de não abandonar esse sonho, o Ouroboros se forçou a um sono sem fim.",
  ui_story_5036_50361402_23_dialog_content = "Então aqueles Eclipsites agora eram—",
  ui_story_5036_50361402_24_dialog_content = "Eles são meus medos.",
  ui_story_5036_50361402_25_dialog_content = "São manifestações do medo que senti em meus momentos finais. É por isso que eles continuam aparecendo constantemente e me atacando.",
  ui_story_5036_50361402_26_dialog_content = "Mas tudo bem, porque o Ouroboros está me protegendo. Quando eles estão prestes a me pegar, isso reinicia o sonho e os faz desaparecer!",
  ui_story_5036_50361402_27_dialog_content = "Espere, talvez você possa pedir ao Ouroboros para ajudá-lo a sair?",
  ui_story_5036_50361402_28_dialog_content = "Boa ideia! Vou perguntar agora!",
  ui_story_5036_50361402_29_dialog_content = "Ok! Mas antes, você poderia ficar e conversar comigo um pouco mais?",
  ui_story_5036_50361402_30_dialog_content = "Adoraria, Chaminade, adoraria mesmo. Mas meus fãs ainda estão esperando por mim lá fora.",
  ui_story_5036_50361402_31_dialog_content = "Não vai demorar, prometo! Eu só tenho uma pequena pergunta, tudo bem?",
  ui_story_5036_50361402_32_dialog_content = "Claro que é! O que é isso?",
  ui_story_5036_50361402_33_dialog_content = "Como é Eraveil hoje em dia?",
  ui_story_5036_50361402_34_dialog_content = "Por favor, diga! Eu sou tão curioso.",
  ui_story_5036_50361402_35_dialog_content = "Um... Eraveil?",
  ui_story_5036_50361402_36_dialog_content = "Me desculpe, mas eu nunca estive lá antes...",
  ui_story_5036_50361402_37_dialog_content = "Ai...",
  ui_story_5036_50361402_38_dialog_content = "Mas não se sinta tão para baixo! Embora eu nunca tenha estado lá, tenho um fiel amigo celestita que mora lá!",
  ui_story_5036_50361402_39_dialog_content = "Você quer dizer o celestita que mencionou anteriormente?",
  ui_story_5036_50361402_40_dialog_content = "Isso mesmo! O nome dele é PlayerName, e ele é uma das pessoas mais incríveis que já conheci!",
  ui_story_5036_50361402_41_dialog_content = "Antes de conhecê-lo, tudo que eu sabia era que ele era o piloto celestita de um Colossus que viajava pelo mundo.",
  ui_story_5036_50361402_42_dialog_content = "Ao longo de suas viagens, ele fez muitos amigos e passou por muitas aventuras. Ele também derrotou mais Eclipsites do que posso contar!",
  ui_story_5036_50361402_43_dialog_content = "Eu costumava ter tanto ciúme da vida dele. Para mim, era como se ele vivesse uma vida de total liberdade.",
  ui_story_5036_50361402_44_dialog_content = "Mas depois que conheci o verdadeiro ele, aprendi o quão difícil sua vida tem sido.",
  ui_story_5036_50361402_45_dialog_content = "Ele passou os primeiros anos de sua vida vivendo sozinho no subsolo. Não foi até que ele fez seu primeiro amigo que ele finalmente viu a luz do dia.",
  ui_story_5036_50361402_46_dialog_content = "Ele é o último dos Caelestitas e até reconstruiu Eraveil a partir de suas ruínas.",
  ui_story_5036_50361402_47_dialog_content = "O quê?",
  ui_story_5036_50361402_48_dialog_content = "O que você quer dizer? Eraveil foi... destruído? Só resta... um celestita?",
  ui_story_5036_50361402_49_dialog_content = "Ah! N-Não, eu não quis dizer isso! O que eu quis dizer—",
  ui_story_5036_50361402_50_dialog_content = "Minha... minha casa foi destruída...",
  ui_story_5036_50361402_51_dialog_content = "Eraveil... Eraveil realmente se foi?",
  ui_story_5036_50361402_52_dialog_content = "Mas como? Como pode ser isso?!",
  ui_story_5036_50361402_53_dialog_content = "<color=#e8d9bb>Crash!</color>",
  ui_story_5036_50361402_54_dialog_content = "<color=#e8d9bb>Rachadura-!</color>",
  ui_story_5036_50361402_55_dialog_content = "A paisagem dos sonhos está começando a desmoronar! É por causa das emoções de Chaminade?",
  ui_story_5036_50361402_56_dialog_content = "Chamada! P-Por favor, acalme-se!",
  ui_story_5036_50361402_57_dialog_content = "Minha casa... Eu só quero ir para casa... Ahhhhhh!",
  ui_story_5036_50361402_58_dialog_content = "Ela não está se acalmando de jeito nenhum...",
  ui_story_5036_50361402_59_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5036_50361402_60_dialog_content = "Cree! Kree—!",
  ui_story_5036_50361402_61_dialog_content = "Mais e mais do sonho está começando a desmoronar. Mas por que não está zerando?",
  ui_story_5036_50361402_62_dialog_content = "O que devo fazer? Talvez eu devesse começar a contar e pular todos os setes. Será que algo de bom vai acontecer?",
  ui_story_5036_50361402_63_dialog_content = "Não... Agora não é hora de ficar parado! Pelo menos preciso me afastar das partes do sonho que estão desmoronando!",
  ui_story_5036_50361402_64_dialog_content = "Aquela torre ali ainda parece estar em bom estado. É também o lugar mais próximo do Ouroboros.",
  ui_story_5036_50361402_65_dialog_content = "Vamos, Chaminade — Ahh!",
  ui_story_5036_50361402_66_dialog_content = "*Soluço*",
  ui_story_5036_50361402_67_dialog_content = "Uau! Ela não está me deixando chegar perto dela!",
  ui_story_5036_50361402_68_dialog_content = "Chamada! Chamada! Você precisa se acalmar!!!",
  ui_story_5036_50361402_69_dialog_content = "Ela não está me ouvindo...",
  ui_story_5036_50361402_70_dialog_content = "Se isso continuar, todo o sonho desabará ao nosso redor!",
  ui_story_5036_50361402_71_dialog_content = "Eu tenho que encontrar uma maneira de consertar esse sonho!",
  ui_story_5036_50361402_72_dialog_content = "Só espero que o Ouroboros saiba o que fazer!",
  ui_story_5036_50361402_73_dialog_content = "Esta torre parece interminável! Como ainda não estou no topo?",
  ui_story_5036_50361402_74_dialog_content = "Que tipo de lugar é esse? É tão escuro e vazio.",
  ui_story_5036_50361402_75_dialog_content = "Não! Não posso deixar meu medo do escuro me parar agora!",
  ui_story_5036_50361402_76_dialog_content = "Ah...",
  ui_story_5036_50361402_77_dialog_content = "Parece que nem este lugar está a salvo dos Eclipsites.",
  ui_story_5036_50361402_78_dialog_content = "Eu acho que faz sentido. Como centro do sonho, é o lugar mais estável.",
  ui_story_5036_50361402_79_dialog_content = "Até os Eclipsitas sabem fugir do perigo, ao que parece.",
  ui_story_5036_50361402_80_dialog_content = "Eu não tenho tempo a perder com eles, no entanto. Eu tenho que chegar ao topo!",
  ui_story_5036_50361402_81_dialog_content = "Aquela luz à frente deve ser a saída.",
  ui_story_5036_50361402_82_dialog_content = "Finalmente!",
  ui_story_5036_50361402_83_dialog_content = "Cree, cree!",
  ui_story_5036_50361402_84_dialog_content = "É o Ouroboros! Ei!",
  ui_story_5036_50361402_85_dialog_content = "Você pode consertar o sonho e fazer Chaminade se acalmar?",
  ui_story_5036_50361402_86_dialog_content = "Kree...",
  ui_story_5036_50361402_87_dialog_content = "(Ele parece preocupado. Está tentando me dizer que também não pode ajudar?)",
  ui_story_5036_50361402_88_dialog_content = "(O que devo fazer agora?!)",
  ui_story_5036_50361402_89_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_5036_50361402_90_dialog_content = "Até o céu está começando a desmoronar!!",
  ui_story_5036_50361402_91_dialog_content = "Kree! Kree—!",
  ui_story_5036_50361402_92_dialog_content = "O Ouroboros parece estar com muita dor...",
  ui_story_5036_50361402_93_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5036_50361402_94_dialog_content = "Ahhh! T-A torre está começando a desabar!",
  ui_story_5036_50361402_95_dialog_content = "Ahhhhhhh—!!!",
  ui_story_5036_50361402_96_dialog_content = "Goldie! Pegue minha mão!",
  ui_story_5036_50361402_97_dialog_content = "PlayerName!?",
  ui_story_5036_50361402_98_dialog_content = "O que você está fazendo aqui?!",
  ui_story_5036_50361402_99_dialog_content = "Percebemos que algo estava errado com o ovo Ouroboros, então voltamos ao palco para investigar.",
  ui_story_5036_50361402_100_dialog_content = "Mas quando voltamos para o show, todos estavam desmaiados! Além disso, havia vestígios dos Lumináticos de Ouroboros ao redor de seu corpo inconsciente.",
  ui_story_5036_50361402_101_dialog_content = "Então o Ouroboros finalmente eclodiu? Mas por que agora, de todos os tempos?!",
  ui_story_5036_50361402_102_dialog_content = "É possível que tenha chocado depois de ouvir sua música.",
  ui_story_5036_50361402_103_dialog_content = "Ao escrever sua música com uma melodia usada para ativar os Colossos, você pode ter dado involuntariamente ao Ouroboros o alerta de que ele precisava para nascer!",
  ui_story_5036_50361402_104_dialog_content = "O quê?!",
  ui_story_5036_50361402_105_dialog_content = "Se continuarmos enrolando, minhas mãos não vão conseguir segurar...",
  ui_story_5036_50361402_106_dialog_content = "Espere! Não deixe ir!!!",
  ui_story_5036_50361402_107_dialog_content = "Hahaha! Eu só estava brincando! Você realmente acha que eu não sou tão confiável?",
  ui_story_5036_50361402_108_dialog_content = "Certo, vamos tirá-la daqui agora!",
  ui_story_5036_50361402_109_dialog_content = "Aguente firme, Goldie!",
  ui_story_5036_50361402_110_dialog_content = "Ahhh!",
  ui_story_5036_50361402_111_dialog_content = "Estou acordado!",
  ui_story_5036_50361402_112_dialog_content = "Você está bem?",
  ui_story_5036_50361402_113_dialog_content = "Sim, minha cabeça está um pouco tonta...",
  ui_story_5036_50361402_114_dialog_content = "Finalmente... Depois de todo esse tempo, finalmente... Hah? W-eu estava sonhando?!",
  ui_story_5036_50361402_115_dialog_content = "Ugh... O que aconteceu?",
  ui_story_5036_50361402_116_dialog_content = "Minha cabeça... Estávamos dormindo?",
  ui_story_5036_50361402_117_dialog_content = "Bocejar. Bom Dia...? Ou devo dizer boa noite?",
  ui_story_5036_50361402_118_dialog_content = "Eu realmente adormeci ao lado de todos esses plebeus?! Ugh, vou ter que queimar essa roupa quando chegar em casa...",
  ui_story_5036_50361402_119_dialog_content = "Parece que todo mundo está começando a cair em si!",
  ui_story_5036_50361402_120_dialog_content = "É porque o sonho voltou ao normal?",
  ui_story_5036_50361402_121_dialog_content = "Não. É porque...",
  ui_story_5036_50361402_122_dialog_content = "o Ouroboros está prestes a eclodir.",
  ui_story_5036_50361501_1_dialog_content = "<color=#e8d9bb>Umbraton, às margens do rio Gold</color>",
  ui_story_5036_50361501_2_dialog_content = "Ei, o que diabos está acontecendo lá em cima? Que tipo de artista adormece no meio de seu ato?!",
  ui_story_5036_50361501_3_dialog_content = "Eu me pergunto se ela está bem.",
  ui_story_5036_50361501_4_dialog_content = "Não se preocupe! Tenho certeza que ela está bem. Ela é forte, afinal!",
  ui_story_5036_50361501_5_dialog_content = "O que diabos essas duas pessoas aleatórias estão fazendo no palco?",
  ui_story_5036_50361501_6_dialog_content = "Que golpe. Não vou perder mais tempo aqui.",
  ui_story_5036_50361501_7_dialog_content = "Só um momento, senhor.",
  ui_story_5036_50361501_8_dialog_content = "Ainda é muito cedo para sair. Afinal, tudo o que você viu fazia parte do show.",
  ui_story_5036_50361501_9_dialog_content = "O quê?",
  ui_story_5036_50361501_10_dialog_content = "Fizemos um grande esforço para planejar todos os efeitos especiais. Apenas cantar e dançar é tão chato, você não acha?",
  ui_story_5036_50361501_11_dialog_content = "Preparamos uma série de surpresas para complementar o show e torná-lo o mais emocionante possível, tudo para o seu prazer.",
  ui_story_5036_50361501_12_dialog_content = "Espero que todos fiquem mais um pouco e aproveitem o show. Eu prometo que não vai decepcionar.",
  ui_story_5036_50361501_13_dialog_content = "Tudo bem, vamos fazer o que você diz por enquanto.",
  ui_story_5036_50361501_14_dialog_content = "Obrigado pela sua compreensão e apoio! Também preparamos lanches e refrescos para todos.",
  ui_story_5036_50361501_15_dialog_content = "Por favor, ajudem-se.",
  ui_story_5036_50361501_16_dialog_content = "(Eu tenho a multidão sob controle por enquanto, mas isso não vai durar muito mais tempo.)",
  ui_story_5036_50361501_17_dialog_content = "(O que diabos está acontecendo lá em cima, Goldie?)",
  ui_story_5036_50361501_18_dialog_content = "(PlayerName e seus amigos também estão lá em cima... Só espero que eles não estejam em perigo...)",
  ui_story_5036_50361501_19_dialog_content = "<color=#e8d9bb>Enquanto isso, no Eulogoz</color>",
  ui_story_5036_50361501_20_dialog_content = "O que? O Ouroboros está chocando?!",
  ui_story_5036_50361501_21_dialog_content = "Eu sei que é repentino, mas não temos tempo para explicar.",
  ui_story_5036_50361501_22_dialog_content = "Se o Ouroboros chocar, vai desequilibrar todo o Colosso e nos colocar em perigo.",
  ui_story_5036_50361501_23_dialog_content = "Nossa principal prioridade agora é evacuar todos a bordo!",
  ui_story_5036_50361501_24_dialog_content = "E é melhor fazermos isso rápido, ou... Uh-oh. Parece que já estamos muito atrasados.",
  ui_story_5036_50361501_25_dialog_content = "Grahhhh—!!!",
  ui_story_5036_50361501_26_dialog_content = "Eclipsitos estão surgindo de dentro do Colosso!",
  ui_story_5036_50361501_27_dialog_content = "Acordem, todos! Assuma posições defensivas!",
  ui_story_5036_50361501_28_dialog_content = "Sim, minha senhora!",
  ui_story_5036_50361501_29_dialog_content = "Graaaaaah!",
  ui_story_5036_50361501_30_dialog_content = "Você não vai passar por mim!",
  ui_story_5036_50361501_31_dialog_content = "Droga! Não há fim para essas criaturas imundas?!",
  ui_story_5036_50361501_32_dialog_content = "Chega de reclamar. Foco na defesa.",
  ui_story_5036_50361501_33_dialog_content = "Sim, sim, eu sei!",
  ui_story_5036_50361501_34_dialog_content = "<color=#e8d9bb>Estrondo...</color>",
  ui_story_5036_50361501_35_dialog_content = "Todo o Colosso está tremendo! O chefe final está prestes a aparecer?!",
  ui_story_5036_50361501_36_dialog_content = "Aguentem firme, pessoal! Parece que algo está saindo do Colosso!",
  ui_story_5036_50361501_37_dialog_content = "Kree-!",
  ui_story_5036_50361501_38_dialog_content = "Um dragão?! É enorme!!",
  ui_story_5036_50361501_39_dialog_content = "Então realmente chocou!",
  ui_story_5036_50361501_40_dialog_content = "Grrr!",
  ui_story_5036_50361501_41_dialog_content = "Os Eclipsitas estão começando a atacar os Ouroboros!",
  ui_story_5036_50361501_42_dialog_content = "Kree... Kree...!",
  ui_story_5036_50361501_43_dialog_content = "Olha, irmã! Ali, no topo do Colosso!",
  ui_story_5036_50361501_44_dialog_content = "Isso é... um dragão?!",
  ui_story_5036_50361501_45_dialog_content = "Ei! O Colosso está tremendo muito. Vai cair do céu!",
  ui_story_5036_50361501_46_dialog_content = "<color=#e8d9bb>BUM!</color>",
  ui_story_5036_50361501_47_dialog_content = "Isto é mau! O Ouroboros acabou de chocar. Ainda não pode voar!",
  ui_story_5036_50361501_48_dialog_content = "Os ataques dos Eclipsites vão torná-lo ainda mais feroz!",
  ui_story_5036_50361501_49_dialog_content = "Existe alguma maneira de acalmá-lo primeiro?",
  ui_story_5036_50361501_50_dialog_content = "Que tal usar suas habilidades psíquicas?",
  ui_story_5036_50361501_51_dialog_content = "Vou tentar.",
  ui_story_5036_50361501_52_option_content = "\"Pare, Ouroboros!\"",
  ui_story_5036_50361501_53_dialog_content = "Kree-!",
  ui_story_5036_50361501_54_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5036_50361501_55_dialog_content = "Ah!",
  ui_story_5036_50361501_56_dialog_content = "Não vai me ouvir de jeito nenhum!",
  ui_story_5036_50361501_57_dialog_content = "Os Eclipsites... cercaram o palco.",
  ui_story_5036_50361501_58_dialog_content = "O concerto... arruinou totalmente...",
  ui_story_5036_50361501_59_dialog_content = "Goldie, controle-se! Ainda estamos em perigo!",
  ui_story_5036_50361501_60_dialog_content = "Eu sei, mas...",
  ui_story_5036_50361501_61_dialog_content = "Não há tempo a perder. Posições, todos! Devemos colocar uma distância entre os Eclipsitas e o dragão!",
  ui_story_5036_50361501_62_dialog_content = "Sim!",
  ui_story_5036_50361501_63_dialog_content = "Illumina também não vai recuar! A batalha do chefe acabou de começar!",
  ui_story_5036_50361501_64_dialog_content = "Sim!!!",
  ui_story_5036_50361501_65_dialog_content = "Vício, PlayerName! Vocês dois cobrem e escoltam os civis para longe da área de batalha!",
  ui_story_5036_50361501_66_dialog_content = "Entre em contato com os dirigíveis de Soroz e Lumopolis e elabore um plano de evacuação!",
  ui_story_5036_50361501_67_dialog_content = "Tudo bem, deixe comigo!",
  ui_story_5036_50361501_68_dialog_content = "Certo!",
  ui_story_5036_50361501_69_dialog_content = "Os Cavaleiros de Lumopolis são tão confiáveis em tempos de perigo como este!",
  ui_story_5036_50361501_70_dialog_content = "Você não tem nada para fazer? Encontre uma maneira de acalmar aquele dragão.",
  ui_story_5036_50361501_71_dialog_content = "Me poupe, eu não sou um lutador...",
  ui_story_5036_50361501_72_dialog_content = "Você não se importa. Evacue com o resto, então.",
  ui_story_5036_50361501_73_dialog_content = "Sem problemas. Vou me ver agora.",
  ui_story_5036_50361501_74_dialog_content = "Todos, venham aqui!",
  ui_story_5036_50361501_75_dialog_content = "Como vai Soroz, PlayerName?",
  ui_story_5036_50361501_76_dialog_content = "O Ouroboros não está se acalmando. Soroz não consegue se conectar com ele!",
  ui_story_5036_50361501_77_dialog_content = "Se ao menos houvesse uma maneira de acalmá-lo por apenas um segundo...",
  ui_story_5036_50361501_78_dialog_content = "Mas não parece que vai fazer isso, pelo menos não por muito tempo.",
  ui_story_5036_50361501_79_dialog_content = "Onde estão os dirigíveis Lumopolis?",
  ui_story_5036_50361501_80_dialog_content = "Obviamente já os contactei.",
  ui_story_5036_50361501_81_dialog_content = "O concerto já atraiu alguns nobres com suas aeronaves. Vários deles já estão ajudando na evacuação.",
  ui_story_5036_50361501_82_dialog_content = "O City Lord está enviando todas as aeronaves disponíveis em Lumopolis para cá, mas ainda levará algum tempo.",
  ui_story_5036_50361501_83_dialog_content = "Sem mencionar que Lumopolis só tem pequenos dirigíveis na maioria das vezes. Serão necessárias algumas viagens para transportar todas essas pessoas daqui.",
  ui_story_5036_50361501_84_dialog_content = "Temos que ganhar mais tempo para eles.",
  ui_story_5036_50361501_85_dialog_content = "Ugh—!",
  ui_story_5036_50361501_X85_dialog_content = "Segure firme!",
  ui_story_5036_50361501_87_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5036_50361501_88_dialog_content = "Lady Carleen, há muitos Eclipsites! Não podemos segurar nossas linhas!",
  ui_story_5036_50361501_89_dialog_content = "Ahh, pessoal de Lumópolis, é melhor sairmos daqui!",
  ui_story_5036_50361501_90_dialog_content = "O dragão está lutando ferozmente, e o Colosso é velho demais...",
  ui_story_5036_50361501_91_dialog_content = "Muitas de suas peças não aguentam a surra, está começando a desmoronar!",
  ui_story_5036_50361501_92_dialog_content = "Onde estão os dirigíveis?",
  ui_story_5036_50361501_93_dialog_content = "Relatório! Soroz não consegue se conectar, mas as aeronaves de Lumopolis estão a caminho!",
  ui_story_5036_50361501_94_dialog_content = "Estamos sem opções! Entre em contato com todas as equipes para retirar. Pare de defender o Ouroboros por enquanto e vá em direção ao povo!",
  ui_story_5036_50361501_95_dialog_content = "Sim!",
  ui_story_5036_50361501_96_dialog_content = "Carleen!",
  ui_story_5036_50361501_97_dialog_content = "Estou bem, estão todos aqui?",
  ui_story_5036_50361501_98_dialog_content = "Eles estão todos aqui, Lady Carleen!",
  ui_story_5036_50361501_99_dialog_content = "O primeiro lote de dirigíveis chegou. A evacuação está em andamento, mas...",
  ui_story_5036_50361501_100_dialog_content = "Precisa de tempo.",
  ui_story_5036_50361501_101_dialog_content = "Dirigíveis muito pequenos. Muitas pessoas.",
  ui_story_5036_50361501_102_dialog_content = "Farei o possível para ganhar tempo para você.",
  ui_story_5036_50361501_103_dialog_content = "Pressa! O Colosso pode tombar a qualquer momento!",
  ui_story_5036_50361501_104_dialog_content = "Sob... eu...",
  ui_story_5036_50361501_105_dialog_content = "Você está bem, Goldie?",
  ui_story_5036_50361501_106_dialog_content = "Estou bem... o show está todo arruinado, mas estou bem...",
  ui_story_5036_50361501_107_dialog_content = "Ainda assim, tenho que proteger meus fãs. Eles não podem se machucar por minha causa!",
  ui_story_5036_50361501_108_dialog_content = "Mesmo se... este é meu último show!",
  ui_story_5036_50361501_109_dialog_content = "Sim, vamos nos concentrar nos problemas em questão primeiro.",
  ui_story_5036_50361501_110_dialog_content = "A propósito, Vic, o Ouroboros pode realmente não - Vic?",
  ui_story_5036_50361501_111_dialog_content = "Para onde ele fugiu agora?",
  ui_story_5036_50361501_112_dialog_content = "Ele não evacuou com você?",
  ui_story_5036_50361501_113_dialog_content = "Achei que ele estava atrás de mim, então não prestei muita atenção!",
  ui_story_5036_50361501_114_dialog_content = "Oh, eu realmente não sou um lutador.",
  ui_story_5036_50361501_115_dialog_content = "Acho que o ouvi?",
  ui_story_5036_50361501_116_dialog_content = "Ali está ele!",
  ui_story_5036_50361501_117_dialog_content = "Bem, já que me considero um extrozoologista, é melhor começar a agir como um.",
  ui_story_5036_50361501_118_dialog_content = "Por que ele está ali sozinho?",
  ui_story_5036_50361501_119_dialog_content = "Volte aqui! É perigoso!",
  ui_story_5036_50361501_120_dialog_content = "Obrigado pelo lembrete, mas não posso. Ainda não.",
  ui_story_5036_50361501_121_dialog_content = "Ei você! Suas coisas nojentas e fantasmagóricas! Por aqui!",
  ui_story_5036_50361501_122_dialog_content = "Peeeko! Silvo-!",
  ui_story_5036_50361501_123_dialog_content = "Grrrr...",
  ui_story_5036_50361501_124_dialog_content = "Sim! É isso...",
  ui_story_5036_50361501_125_dialog_content = "Por que ir atrás de um Ouroboros quando há um auroriano indefeso bem aqui?",
  ui_story_5036_50361501_126_dialog_content = "(Apenas um pouco mais perto... Tenho que conduzi-los para longe do Ouroboros.)",
  ui_story_5036_50361501_127_dialog_content = "(A Coruja Lutumi deve ser suficiente para prender a atenção e ganhar algum tempo.)",
  ui_story_5036_50361501_128_option_content = "Vic, volte aqui!",
  ui_story_5036_50361501_129_dialog_content = "Hahaha! Não se preocupe com isso, estou totalmente bem!",
  ui_story_5036_50361501_130_dialog_content = "Somente o melhor extrozoologista poderia confiar sua vida a seus animais maravilhosos!",
  ui_story_5036_50361501_131_dialog_content = "Gahhhhhh—!",
  ui_story_5036_50361501_132_dialog_content = "(Bom! Eles morderam a isca!)",
  ui_story_5036_50361501_133_dialog_content = "(Agora, tudo que eu preciso é invocar a Coruja Lutumi!)",
  ui_story_5036_50361501_134_dialog_content = "Coruja Lutumi!",
  ui_story_5036_50361501_135_dialog_content = "Piu - piu, piu!",
  ui_story_5036_50361501_136_dialog_content = "Por que você está fugindo, Coruja Lutumi!? Volte aqui-!",
  ui_story_5036_50361501_137_dialog_content = "<color=#e8d9bb>Estrondo!</color>",
  ui_story_5036_50361501_138_dialog_content = "Kree!",
  ui_story_5036_50361501_139_dialog_content = "O quê?!",
  ui_story_5036_50361501_140_dialog_content = "<color=#e8d9bb>Whoosh-Bang!</color>",
  ui_story_5036_50361501_141_dialog_content = "Vic?",
  ui_story_5036_50361501_142_dialog_content = "Ai, ai, ai!",
  ui_story_5036_50361501_143_dialog_content = "(A cauda do Ouroboros o fez voar! Espere um minuto! Isso é...!)",
  ui_story_5036_50361501_144_dialog_content = "Vic! Corre!",
  ui_story_5036_50361501_145_dialog_content = "Tsk! Aquele dragão realmente não sabe ser gentil.",
  ui_story_5036_50361501_146_dialog_content = "PlayerName, o que você disse? Eu não ouvi você!",
  ui_story_5036_50361501_147_dialog_content = "Aaarrgh!",
  ui_story_5036_50361501_148_dialog_content = "Puxa... Estou cercado!",
  ui_story_5036_50361501_149_dialog_content = "Ei, Eclipsites, estou velho e isso me deixa com um gosto ruim!",
  ui_story_5036_50361501_150_dialog_content = "Olhe para o celestita ali! Ele é jovem e terno! E muito mais suculento do que eu!",
  ui_story_5036_50361501_151_dialog_content = "Graaaaaah!!!",
  ui_story_5036_50361501_152_dialog_content = "Salve-me, Bola de Pelos!",
  ui_story_5036_50361501_153_dialog_content = "PlayerName!",
  ui_story_5036_50361502_1_dialog_content = "Fabuloso! Eu ainda estou vivo!",
  ui_story_5036_50361502_2_dialog_content = "Mesmo que todo o meu plano de chamar a atenção dos Eclipsitas tenha falhado.",
  ui_story_5036_50361502_3_dialog_content = "Como você está com vontade de rir!?",
  ui_story_5036_50361502_4_dialog_content = "Se você tem um plano, precisa nos contar!",
  ui_story_5036_50361502_5_dialog_content = "Desculpe, desculpe! Eu estava tão preocupado com a segurança dos Ouroboros que esqueci completamente.",
  ui_story_5036_50361502_6_dialog_content = "Mas, só para constar, meu plano teria dado certo se não me mandasse voando.",
  ui_story_5036_50361502_7_dialog_content = "Este não é o momento para discutir quem teria!",
  ui_story_5036_50361502_8_dialog_content = "Existe alguma outra maneira de acalmá-lo?",
  ui_story_5036_50361502_9_dialog_content = "Infelizmente, não consigo pensar em nada além de derrotar todos os Eclipsites.",
  ui_story_5036_50361502_10_dialog_content = "Não podemos esperar que o Ouroboros reúna força suficiente para voar sozinho?",
  ui_story_5036_50361502_11_dialog_content = "Isso é um pouco otimista demais. Os Eclipsites não estão recuando.",
  ui_story_5036_50361502_12_dialog_content = "Se isso continuar, mesmo que o Ouroboros possa voar novamente, seria muito ferido.",
  ui_story_5036_50361502_13_dialog_content = "Quão...",
  ui_story_5036_50361502_14_dialog_content = "Lady Carleen, recebemos ordens do Senhor da Cidade.",
  ui_story_5036_50361502_15_dialog_content = "Continue.",
  ui_story_5036_50361502_16_dialog_content = "A evacuação está quase completa. As administrações de Illumina e Lumopolis concluíram sua avaliação de risco do Colossus.",
  ui_story_5036_50361502_17_dialog_content = "Eles decidiram deixar os soldados para trás para conter os Eclipsitas, manter o dragão sob controle e manter o equilíbrio do Colosso.",
  ui_story_5036_50361502_18_dialog_content = "Assim que o Colossus estiver fora de Umbraton, eles o derrubarão.",
  ui_story_5036_50361502_19_dialog_content = "Você quer derrubar o Colosso junto com o Ouroboros!? De jeito nenhum!",
  ui_story_5036_50361502_20_dialog_content = "Pode ser o último de seu tipo! Eles serão completamente extintos se você fizer isso!",
  ui_story_5036_50361502_21_dialog_content = "E eu não vou perder Eulogoz!",
  ui_story_5036_50361502_22_dialog_content = "Você tem uma ideia melhor? Se não, então cale a boca.",
  ui_story_5036_50361502_23_dialog_content = "O Colossus está logo acima da área mais populosa de Umbraton. Não vamos arriscar a vida de milhões de aurorianos!",
  ui_story_5036_50361502_24_dialog_content = "E se eu me recusar a deixar o Colosso?",
  ui_story_5036_50361502_25_dialog_content = "Vic, o que você está dizendo...?",
  ui_story_5036_50361502_26_dialog_content = "Eu sou um extrozoólogo. De jeito nenhum vou deixar que algum mal aconteça àquele Ouroboros.",
  ui_story_5036_50361502_27_dialog_content = "Se você quiser derrubar o Colosso, terá que me derrubar com ele.",
  ui_story_5036_50361502_28_dialog_content = "Vic, isso é perigoso!",
  ui_story_5036_50361502_29_dialog_content = "Pare de brincar!",
  ui_story_5036_50361502_30_dialog_content = "(O que eu faço? Como posso salvar o Ouroboros e o Colosso?)",
  ui_story_5036_50361502_31_dialog_content = "(Deve haver uma maneira...)",
  ui_story_5036_50361502_32_dialog_content = "Com certeza eles vão conseguir ouvir minha voz no chão através do equipamento!",
  ui_story_5036_50361502_33_dialog_content = "Que incrível, a criatura podia se comunicar usando a melodia que os Celestitas usam para controlar os Colossos.",
  ui_story_5036_50361502_34_dialog_content = "Ao escrever sua música com uma melodia usada para ativar os Colossos, você pode ter dado involuntariamente ao Ouroboros o alerta de que ele precisava para nascer!",
  ui_story_5036_50361502_35_dialog_content = "Há outra maneira que eu quero tentar!",
  ui_story_5036_50361502_36_dialog_content = "Hã?",
  ui_story_5036_50361502_37_dialog_content = "O que foi?",
  ui_story_5036_50361502_38_dialog_content = "Chaminade descobriu que os Ouroboros podiam entender as melodias que os Caelestites usavam para controlar os Colossi.",
  ui_story_5036_50361502_39_dialog_content = "Se pudermos tocar a melodia que desliga o Colossus e para os Eclipsites ao mesmo tempo, talvez possamos acalmá-lo.",
  ui_story_5036_50361502_40_dialog_content = "Vale a pena tentar.",
  ui_story_5036_50361502_41_dialog_content = "Uma música funcionaria mesmo se as habilidades psíquicas de PlayerName não pudessem alcançar o dragão?",
  ui_story_5036_50361502_42_dialog_content = "Bem... Contanto que seja alto o suficiente, devemos ser capazes de chamar sua atenção.",
  ui_story_5036_50361502_43_dialog_content = "Podemos usar o sistema de alto-falantes do palco!",
  ui_story_5036_50361502_44_dialog_content = "Sim. Vou precisar da ajuda de Goldie. Devemos ser capazes de fazer isso com os Luminatics dela e o equipamento!",
  ui_story_5036_50361502_45_dialog_content = "Eu?",
  ui_story_5036_50361502_46_dialog_content = "...",
  ui_story_5036_50361502_47_dialog_content = "Entendido.",
  ui_story_5036_50361502_48_dialog_content = "Meu show não pode terminar antes que eu termine minha música.",
  ui_story_5036_50361502_49_dialog_content = "Mesmo que eu não possa mais subir no palco como ídolo no futuro, contanto que você e meus fãs estejam por aí...",
  ui_story_5036_50361502_50_dialog_content = "Cantarei para todos vocês sempre que precisarem.",
  ui_story_5036_50361502_51_dialog_content = "Sem mencionar que Umbraton está logo abaixo de nós. É a minha casa e a casa dos meus fãs.",
  ui_story_5036_50361502_52_dialog_content = "Quão certo você está de que isso funcionará, PlayerName?",
  ui_story_5036_50361502_53_option_content = "Não posso te prometer nada...",
  ui_story_5036_50361502_54_option_content = "Eu quero tentar!",
  ui_story_5036_50361502_55_dialog_content = "Tá bom.",
  ui_story_5036_50361502_56_dialog_content = "Eu ajudo.",
  ui_story_5036_50361502_57_dialog_content = "Senhora Carleen! Você está falando sério?",
  ui_story_5036_50361502_58_dialog_content = "É claro. E também fornecerei suporte se falhar.",
  ui_story_5036_50361502_59_dialog_content = "Avise todas as equipes para ficarem de prontidão!",
  ui_story_5036_50361502_60_dialog_content = "Entendido. Cavaleiros, formem-se!",
  ui_story_5036_50361502_61_dialog_content = "Carleen, muito obrigado!",
  ui_story_5036_50361502_62_dialog_content = "Eu também ajudo!",
  ui_story_5036_50361502_63_dialog_content = "Mas a tripulação que cuida do sistema de alto-falantes já partiu em um dirigível.",
  ui_story_5036_50361502_64_dialog_content = "Não se esqueça de nós! Nós temos isso.",
  ui_story_5036_50361502_65_dialog_content = "Os equipamentos podem ser modificados, mas ainda são praticamente os mesmos. Deixe-os conosco.",
  ui_story_5036_50361502_66_dialog_content = "Gronru, Siobhan!?",
  ui_story_5036_50361502_67_dialog_content = "PlayerName, você está tentando desafiar alguns estágios superdifíceis, certo?",
  ui_story_5036_50361502_68_dialog_content = "Como eu poderia perder algo tão divertido?",
  ui_story_5036_50361502_69_dialog_content = "A-E eu!",
  ui_story_5036_50361502_70_dialog_content = "Eu tenho entrevistado pessoas nos últimos dias, incluindo aqueles que lidam com o sistema de alto-falantes.",
  ui_story_5036_50361502_71_dialog_content = "Eu também aprendi uma ou duas coisas com eles!",
  ui_story_5036_50361502_72_dialog_content = "Isso parece um esforço maluco, mas, por favor, deixe-me acompanhá-lo! Farei o possível para ajudar Goldie e você!",
  ui_story_5036_50361502_73_dialog_content = "Valeu...",
  ui_story_5036_50361502_74_dialog_content = "PlayerName, você com certeza tem um jeito de unir todo mundo.",
  ui_story_5036_50361502_75_dialog_content = "Essa habilidade por si só torna o Caelestite uma besta maravilhosa.",
  ui_story_5036_50361502_76_dialog_content = "Espere, eu não sou uma besta maravilhosa!",
  ui_story_5036_50361502_77_dialog_content = "Hahah. Não há tempo para debater.",
  ui_story_5036_50361502_78_dialog_content = "Estamos com pouco tempo. Vamos salvar o Ouroboros primeiro!",
  ui_story_5036_50361502_79_dialog_content = "Certo. Para o palco!",
  ui_story_5036_50361601_1_dialog_content = "Goldie, você memorizou a melodia que te ensinei?",
  ui_story_5036_50361601_2_dialog_content = "É claro! Cada nota dele!",
  ui_story_5036_50361601_3_dialog_content = "Mas há tantos Eclipsites em nosso caminho...",
  ui_story_5036_50361601_4_dialog_content = "Não se preocupe. Nós cuidaremos deles e abriremos o caminho para você.",
  ui_story_5036_50361601_5_dialog_content = "Sim. Deixe o combate conosco. Você apenas se concentra em cantar!",
  ui_story_5036_50361601_6_dialog_content = "De fato. Não posso lutar, mas o Bolinha de Pelos vai ajudar.",
  ui_story_5036_50361601_7_dialog_content = "Piu!",
  ui_story_5036_50361601_8_dialog_content = "Obrigado por ainda querer me ajudar, Goldie.",
  ui_story_5036_50361601_9_dialog_content = "Não precisa me agradecer.",
  ui_story_5036_50361601_10_dialog_content = "Você tem me ajudado nos últimos dias, PlayerName.",
  ui_story_5036_50361601_11_dialog_content = "Se não fosse a vossa ajuda, este concerto nunca teria acontecido.",
  ui_story_5036_50361601_12_dialog_content = "Mas estragou...",
  ui_story_5036_50361601_13_dialog_content = "Mesmo assim, sei quanto esforço você faz.",
  ui_story_5036_50361601_14_dialog_content = "O fracasso do show não muda esse fato.",
  ui_story_5036_50361601_15_dialog_content = "Então agora, é hora de retribuir!",
  ui_story_5036_50361601_16_dialog_content = "Beleza!",
  ui_story_5036_50361601_17_dialog_content = "Vamos então!",
  ui_story_5036_50361601_18_dialog_content = "Graaaaaah!!!",
  ui_story_5036_50361601_19_dialog_content = "Eclipsitos chegando! Prepare-se para a batalha!",
  ui_story_5036_50361602_1_dialog_content = "Chegamos ao palco! Como está o equipamento?",
  ui_story_5036_50361602_2_dialog_content = "O equipamento está bom!",
  ui_story_5036_50361602_3_dialog_content = "Saída de volume no máximo—!",
  ui_story_5036_50361602_4_dialog_content = "Grahhhhhh—!",
  ui_story_5036_50361602_5_dialog_content = "Hã?!",
  ui_story_5036_50361602_6_dialog_content = "Torrente Rápida!",
  ui_story_5036_50361602_7_dialog_content = "Obrigado!",
  ui_story_5036_50361602_8_dialog_content = "De nada.",
  ui_story_5036_50361602_9_dialog_content = "Deixe os Eclipsites conosco! Você apenas se concentra em manusear o equipamento!",
  ui_story_5036_50361602_10_dialog_content = "Enquanto estivermos aqui, não deixaremos nenhum Eclipsite passar!",
  ui_story_5036_50361602_11_dialog_content = "Grahhhh!",
  ui_story_5036_50361602_12_dialog_content = "Nem pensa em escapar!",
  ui_story_5036_50361602_13_dialog_content = "Aqui está sua chance! Pequena Bola de Pelos, ataque suas costas!",
  ui_story_5036_50361602_14_dialog_content = "Piu!",
  ui_story_5036_50361602_15_dialog_content = "Grahhhh—",
  ui_story_5036_50361602_16_dialog_content = "Uau, essa coisa é rápida. Até a Pequena Bola de Pêlos tem dificuldade em alcançá-lo.",
  ui_story_5036_50361602_17_dialog_content = "Ele continua correndo por aí. Quão problemático!",
  ui_story_5036_50361602_18_dialog_content = "Espere! Não deixe que isso interfira no canto de Goldie, pelo menos!",
  ui_story_5036_50361602_19_dialog_content = "Direita!",
  ui_story_5036_50361602_20_dialog_content = "(Todo mundo está lutando. Tenho que fazer meu trabalho.)",
  ui_story_5036_50361602_21_dialog_content = "Kree... Kree!",
  ui_story_5036_50361602_22_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5036_50361602_23_dialog_content = "Ouroboros, você também está lutando, não é?",
  ui_story_5036_50361602_24_dialog_content = "Apenas aguente mais um pouco. Confie em nós. Nós o protegeremos.",
  ui_story_5036_50361602_25_dialog_content = "Uhm... vou começar a cantar!",
  ui_story_5036_50361602_26_dialog_content = "Sim!",
  ui_story_5036_50361602_27_dialog_content = "(Calma, Goldie.)",
  ui_story_5036_50361602_28_dialog_content = "(Acalme os nervos dos Ouroboros com esta música e acalme-os.)",
  ui_story_5036_50361602_29_dialog_content = "(Torne esta música digna de uma despedida final do palco e da vida como um ídolo.)",
  ui_story_5036_50361602_30_dialog_content = "Ouroboros, ouça minha música!",
  ui_story_5036_50361602_31_dialog_content = "♪ O mundo é vasto, o universo é um oceano ♪",
  ui_story_5036_50361602_32_dialog_content = "♪ Nascemos como meteoritos, brincalhões e brilhantes ♪",
  ui_story_5036_50361602_33_dialog_content = "♪ Brincamos com alegria, mas às vezes cansamos ♪",
  ui_story_5036_50361602_34_dialog_content = "♪ As luzes de casa, guiam-nos calorosamente para os nossos ninhos ♪",
  ui_story_5036_50361602_35_dialog_content = "Todos, sigam as instruções e evacuem! O Shadowlord garantirá sua segurança!",
  ui_story_5036_50361602_36_dialog_content = "♪ As luzes de casa, guiam-nos calorosamente para os nossos ninhos ♪",
  ui_story_5036_50361602_37_dialog_content = "Irmã, você ouviu isso?",
  ui_story_5036_50361602_38_dialog_content = "É cantar!",
  ui_story_5036_50361602_39_dialog_content = "Senhorita, todas as pessoas evacuadas saíram da aeronave.",
  ui_story_5036_50361602_40_dialog_content = "OK. Prepare-se para sair novamente e evacuar o próximo grupo de civis!",
  ui_story_5036_50361602_41_dialog_content = "♪ As luzes de casa, guiam-nos calorosamente para os nossos ninhos ♪",
  ui_story_5036_50361602_42_dialog_content = "Isso é... cantar?",
  ui_story_5036_50361602_43_dialog_content = "Uma voz tão gentil. Está vindo do Colosso?",
  ui_story_5036_50361602_44_dialog_content = "♪ Criança cansada, vá dormir ♪",
  ui_story_5036_50361602_45_dialog_content = "♪ Que esta canção de ninar guarde seus sonhos ♪",
  ui_story_5036_50361602_46_dialog_content = "♪ Esta é a sua casa ♪",
  ui_story_5036_50361602_47_dialog_content = "Kree-!",
  ui_story_5036_50361602_48_dialog_content = "(O Ouroboros parece estar respondendo!)",
  ui_story_5036_50361602_49_dialog_content = "Carleen, PlayerName! Parece que está acalmando!",
  ui_story_5036_50361602_50_dialog_content = "Excelente! A música está funcionando!",
  ui_story_5036_50361602_51_dialog_content = "O Colosso parou de balançar. Isso vai funcionar!",
  ui_story_5036_50361602_52_dialog_content = "Avance nos Eclipsites!",
  ui_story_5036_50361602_53_dialog_content = "♪ Esta é a sua casa ♪",
  ui_story_5036_50361602_54_dialog_content = "Uma canção?",
  ui_story_5036_50361602_55_dialog_content = "É a melodia que desliga o Colossus. É suave como uma canção de ninar.",
  ui_story_5036_50361602_56_dialog_content = "Aquele é o Goldie cantando? Mas...",
  ui_story_5036_50361602_57_dialog_content = "♪ Agora aquela casa não existe mais ♪",
  ui_story_5036_50361602_58_dialog_content = "(Parece que estou ouvindo Chaminade cantando!)",
  ui_story_5036_50361602_59_dialog_content = "(Ela deve estar arrasada. Eu nem tive a chance de confortá-la...)",
  ui_story_5036_50361602_60_dialog_content = "(Ela pode ser apenas uma figura de um sonho e não existe realmente.)",
  ui_story_5036_50361602_61_dialog_content = "(Mas sua tristeza e solidão são tão reais.)",
  ui_story_5036_50361602_62_dialog_content = "(Então devo dedicar esta canção a você, Chaminade.)",
  ui_story_5036_50361602_63_dialog_content = "(E espero que isso leve embora sua tristeza.)",
  ui_story_5036_50361602_64_dialog_content = "♪ Agora aquela casa não existe mais ♪",
  ui_story_5036_50361602_65_dialog_content = "♪ Ainda assim, os jovens partem em viagens ♪",
  ui_story_5036_50361602_66_dialog_content = "♪ Pelas lágrimas que correm pela noite ♪",
  ui_story_5036_50361602_67_dialog_content = "♪ Através de tristezas e alegrias, partidas e reencontros ♪",
  ui_story_5036_50361602_68_dialog_content = "♪ Eles ainda podem ver a luz da esperança? ♪",
  ui_story_5036_50361602_69_dialog_content = "♪ A luz que ainda deve estar esperando ♪",
  ui_story_5036_50361602_70_dialog_content = "Torrente Rápida!",
  ui_story_5036_50361602_71_dialog_content = "Quantos mais há...?",
  ui_story_5036_50361602_72_dialog_content = "Grah!!!",
  ui_story_5036_50361602_73_dialog_content = "Assista! Está voltando!",
  ui_story_5036_50361602_74_dialog_content = "Não vou deixar você chegar perto!",
  ui_story_5036_50361602_75_dialog_content = "Essa é a sua música, Goldie?",
  ui_story_5036_50361602_76_dialog_content = "É tão quente, como o sol e o vento em Eraveil.",
  ui_story_5036_50361602_77_dialog_content = "Eu vejo agora. Mesmo que Eraveil tenha sido destruído, ele não acabou. Casa... pode ser reconstruída.",
  ui_story_5036_50361602_78_dialog_content = "Goldie, eu ouvi você.",
  ui_story_5036_50361602_79_dialog_content = "Então, eu deveria—",
  ui_story_5036_50361602_80_dialog_content = "♪ Tente enxugar essas lágrimas ♪",
  ui_story_5036_50361602_81_dialog_content = "♪ Enxugue essas lágrimas, parta novamente— ♪",
  ui_story_5036_50361602_82_dialog_content = "♪ Espalhe essa música longe ♪",
  ui_story_5036_50361602_83_dialog_content = "Obrigado, Goldie.",
  ui_story_5036_50361602_84_dialog_content = "Ídolo do futuro, confio Ouroboros e o futuro a você.",
  ui_story_5036_50361602_85_dialog_content = "Chaminade... parece ter desaparecido completamente.",
  ui_story_5036_50361602_86_dialog_content = "Kree—",
  ui_story_5036_50361602_87_dialog_content = "O Ouroboros se acalmou!",
  ui_story_5036_50361602_88_dialog_content = "Funcionou! PlayerName, seu plano funcionou!",
  ui_story_5036_50361602_89_dialog_content = "Isso é ótimo!",
  ui_story_5036_50361602_90_dialog_content = "Mas não podemos aguentar mais aqui!",
  ui_story_5036_50361602_91_dialog_content = "Ugh!",
  ui_story_5036_50361602_92_dialog_content = "Grah!!!",
  ui_story_5036_50361602_93_dialog_content = "Torrente Rápida!",
  ui_story_5036_50361602_94_dialog_content = "Grahh! Grah!",
  ui_story_5036_50361602_95_dialog_content = "Como essa coisa ainda está viva?!",
  ui_story_5036_50361602_96_dialog_content = "Qualquer Eclipsite que pode sobreviver neste Colossus não deve ser fácil.",
  ui_story_5036_50361602_97_dialog_content = "Apenas espere. O Ouroboros deve ser capaz de voar a qualquer minuto agora!",
  ui_story_5036_50361602_98_dialog_content = "Rugido-!",
  ui_story_5036_50361602_99_dialog_content = "Cuidado, Carleen!",
  ui_story_5036_50361602_100_dialog_content = "Cree!",
  ui_story_5036_50361602_101_dialog_content = "<color=#e8d9bb>Tapa-!</color>",
  ui_story_5036_50361602_102_dialog_content = "Rugido—",
  ui_story_5036_50361602_103_dialog_content = "Uau! O-O quê...?",
  ui_story_5036_50361602_104_dialog_content = "O Ouroboros enviou aquele Eclipsite voando com sua cauda!",
  ui_story_5036_50361602_105_dialog_content = "Cree, cree!",
  ui_story_5036_50361602_106_dialog_content = "Não parece mais com medo! É feliz!",
  ui_story_5036_50361602_107_dialog_content = "Isso foi brilhante! Sem aquele Eclipsite bagunçado, o resto deve ser fácil de manusear.",
  ui_story_5036_50361602_108_dialog_content = "Gelescer!",
  ui_story_5036_50361602_109_dialog_content = "Grrrr...",
  ui_story_5036_50361602_110_dialog_content = "Kree—!",
  ui_story_5036_50361602_111_dialog_content = "<color=#e8d9bb>Falha—</color>",
  ui_story_5036_50361602_112_dialog_content = "O Colossus está arrasando de novo!?",
  ui_story_5036_50361602_113_dialog_content = "O Ouroboros se acalmou.",
  ui_story_5036_50361602_114_dialog_content = "Espere! Parece estar voando!",
  ui_story_5036_50361602_115_dialog_content = "Kree—!",
  ui_story_5036_50361602_116_dialog_content = "Cree!",
  ui_story_5036_50361602_117_dialog_content = "Olha, o dragão do Colossus acabou de decolar!",
  ui_story_5036_50361602_118_dialog_content = "É verdade! Goldie ainda está no Colossus? ela está segura?",
  ui_story_5036_50361602_119_dialog_content = "Ela é um ídolo incrível.",
  ui_story_5036_50361602_120_dialog_content = "Não importa o que está por vir, ela vai conseguir.",
  ui_story_5036_50361602_121_dialog_content = "Então... apenas acredite nela.",
  ui_story_5036_50361602_122_dialog_content = "Direita!",
  ui_story_5036_50361602_123_dialog_content = "Eu também acredito nela!",
  ui_story_5036_50361602_124_dialog_content = "Tudo bem. Você deve se juntar aos outros na evacuação.",
  ui_story_5036_50361602_125_dialog_content = "Agora que o dragão voou, tudo acabou?",
  ui_story_5036_50361602_126_dialog_content = "Tenho que entrar em contato com eles e confirmar a situação.",
  ui_story_5036_50361602_127_dialog_content = "Relatório! Todo o pessoal evacuado do Wandering Colossus foi protegido.",
  ui_story_5036_50361602_128_dialog_content = "Apenas alguns sofreram ferimentos leves. Sem ferimentos graves ou mortes!",
  ui_story_5036_50361602_129_dialog_content = "Felizmente, o City Lord estava em uma aeronave perto do Wandering Colossus.",
  ui_story_5036_50361602_130_dialog_content = "Lumopolis só foi capaz de responder tão rapidamente e minimizar os ferimentos por causa disso.",
  ui_story_5036_50361602_131_dialog_content = "Qual é a situação atual com o Colosso e o dragão?",
  ui_story_5036_50361602_132_dialog_content = "O dragão deixou o Colossus, mas Carleen e o resto ainda estão a bordo.",
  ui_story_5036_50361602_133_dialog_content = "...",
  ui_story_5036_50361602_134_dialog_content = "PlayerName e Vice estão lá, então Carleen deve estar segura!",
  ui_story_5036_50361602_135_dialog_content = "Ordene aos dirigíveis que continuem com a evacuação do pessoal a bordo do Colossus.",
  ui_story_5036_50361602_136_dialog_content = "Sim, senhor!",
  ui_story_5036_50361602_137_dialog_content = "<color=#e8d9bb>Estrondo!</color>",
  ui_story_5036_50361602_138_dialog_content = "Hã?!",
  ui_story_5036_50361602_139_dialog_content = "O Colosso está tombando?!",
  ui_story_5036_50361602_140_dialog_content = "Aah?!",
  ui_story_5036_50361602_141_dialog_content = "A partida do Ouroboros mudou o equilíbrio do Colosso!",
  ui_story_5036_50361602_142_dialog_content = "Está ganhando altitude!",
  ui_story_5036_50361602_143_dialog_content = "O plano foi um grande sucesso!",
  ui_story_5036_50361602_144_dialog_content = "Vamos nos apressar e sair daqui. Existem muitos Eclipsites. Eles nos superam!",
  ui_story_5036_50361602_145_dialog_content = "PlayerName!",
  ui_story_5036_50361602_146_dialog_content = "O Ouroboros voou. Nós conseguimos!",
  ui_story_5036_50361602_147_dialog_content = "Que conclusão abençoada para todos nós!",
  ui_story_5036_50361602_148_option_content = "Onde está Chaminade?",
  ui_story_5036_50361602_149_dialog_content = "Achei que a tinha ouvido cantando com você.",
  ui_story_5036_50361602_150_dialog_content = "Acho que ela já se foi...",
  ui_story_5036_50361602_151_dialog_content = "Não se foi com o Ouroboros, mas se foi completamente.",
  ui_story_5036_50361602_152_dialog_content = "Entendo...",
  ui_story_5036_50361602_153_dialog_content = "Sim. Ela disse que confiaria tudo a mim.",
  ui_story_5036_50361602_154_dialog_content = "Ela provavelmente quer que essa música seja ouvida por todo o Astra.",
  ui_story_5036_50361602_155_option_content = "E o Eulogoz?",
  ui_story_5036_50361602_156_dialog_content = "Está tudo bem agora, mas a partida dos Ouroboros desviou seu caminho.",
  ui_story_5036_50361602_157_dialog_content = "Está ganhando altitude.",
  ui_story_5036_50361602_158_dialog_content = "PlayerName, não há tempo para bate-papo. Vamos sair daqui!",
  ui_story_5036_50361602_159_dialog_content = "A partida do Ouroboros mudou a rota do Eulogoz e a carga aliviada fez com que ele acelerasse.",
  ui_story_5036_50361602_160_dialog_content = "Sim, no ritmo que está indo agora, estaremos tão alto que não seremos capazes de respirar em dez minutos ou mais.",
  ui_story_5036_50361602_161_dialog_content = "Vamos nos apressar e sair daqui!",
  ui_story_5036_50361602_162_dialog_content = "Mas Eulogoz—",
  ui_story_5036_50361602_163_dialog_content = "Eulogoz pode nunca mais voltar...",
  ui_story_5036_50361602_164_dialog_content = "Mesmo Gronru não pode consertar o sistema de controle de Eulogoz em tão pouco tempo.",
  ui_story_5036_50361602_165_dialog_content = "Então todo o nosso esforço não foi em vão?",
  ui_story_5036_50361602_166_dialog_content = "Não mesmo!",
  ui_story_5036_50361602_167_dialog_content = "O show pode não ter saído como planejado, mas tivemos que compartilhá-lo com todos nesse ínterim.",
  ui_story_5036_50361602_168_dialog_content = "E aprendemos sobre Eulogoz e Chaminade através de nossa aventura.",
  ui_story_5036_50361602_169_dialog_content = "Enquanto não os esquecermos, eles estarão sempre conosco.",
  ui_story_5036_50361602_170_dialog_content = "...",
  ui_story_5036_50361602_171_option_content = "Vamos.",
  ui_story_5036_50361602_172_option_content = "Eu nunca vou esquecê-los.",
  ui_story_5036_50361602_173_dialog_content = "Sim!",
  ui_story_5036_50361602_174_dialog_content = "PlayerName, estamos ficando sem tempo.",
  ui_story_5036_50361602_175_dialog_content = "Vamos voltar.",
  ui_story_5036_50361602_176_dialog_content = "Certo.",
  ui_story_5036_50361602_177_dialog_content = "Desculpa, Eulogoz.",
  ui_story_5036_50361602_178_dialog_content = "Adeus.",
  ui_story_5036_50361701_1_dialog_content = "Engaje, Soroz!",
  ui_story_5036_50361701_2_dialog_content = "<color=#e8d9bb>Estrondo!</color>",
  ui_story_5036_50361701_3_dialog_content = "Eulogoz está voando cada vez mais alto, em direção ao universo lá em cima.",
  ui_story_5036_50361701_4_dialog_content = "Vai levar a canção de Chaminade às estrelas.",
  ui_story_5036_50361701_5_dialog_content = "Não importa o que aconteça, estamos finalmente seguros.",
  ui_story_5036_50361701_6_dialog_content = "Mesmo que o show tenha falhado e não tenhamos conseguido salvar Eulogoz.",
  ui_story_5036_50361701_7_dialog_content = "Todos estão seguros agora. O povo de Umbraton não precisa mais temer. Isso tem que ser o suficiente.",
  ui_story_5036_50361701_8_dialog_content = "O que ainda não entendo é por que o Ouroboros eclodiu de repente.",
  ui_story_5036_50361701_9_dialog_content = "Se ao menos chocasse um pouco mais tarde, as coisas seriam tão diferentes agora...",
  ui_story_5036_50361701_10_dialog_content = "Na verdade, pensei um pouco, e acho que é por minha causa.",
  ui_story_5036_50361701_11_dialog_content = "No meu sonho... Não, na verdade, era o sonho de Ouroboros. Conheci Chaminade.",
  ui_story_5036_50361701_12_dialog_content = "Conheceu? Você não quer dizer que sonhou com ela?",
  ui_story_5036_50361701_13_dialog_content = "Não. Eu a conheci.",
  ui_story_5036_50361701_14_dialog_content = "Quem ou o que realmente é Chaminade?",
  ui_story_5036_50361701_15_dialog_content = "Poderia realmente haver uma maneira de os mortos continuarem a existir?",
  ui_story_5036_50361701_16_dialog_content = "Só de pensar nisso me dá calafrios...",
  ui_story_5036_50361701_17_dialog_content = "Talvez a Chaminade no sonho fosse apenas uma invenção da imaginação dos Ouroboros.",
  ui_story_5036_50361701_18_dialog_content = "Quer dizer que ela não era a verdadeira Chaminade?",
  ui_story_5036_50361701_19_dialog_content = "Sim. Lembro-me que Chaminade em meu sonho disse—",
  ui_story_5036_50361701_20_dialog_content = "Ele sentiu o último desejo do meu coração de voltar para minha casa, então criou Eraveil em seu sonho, e eu.",
  ui_story_5036_50361701_21_dialog_content = "Então eu acho que o Eraveil e o Chaminade que vi no sonho foram todos criados pelos Ouroboros.",
  ui_story_5036_50361701_22_dialog_content = "Não estávamos todos imersos em sonhos no Colosso simplesmente por causa das habilidades psíquicas do Ouroboros.",
  ui_story_5036_50361701_23_dialog_content = "Estávamos sonhando porque estava sonhando.",
  ui_story_5036_50361701_24_dialog_content = "Não estávamos tendo o mesmo sonho. Estávamos todos compartilhando o sonho do dragão.",
  ui_story_5036_50361701_25_dialog_content = "Mas por que criou um sonho assim?",
  ui_story_5036_50361701_26_dialog_content = "Por saudade e ódio, provavelmente...",
  ui_story_5036_50361701_27_dialog_content = "Mesmo tendo se tornado um ovo, ainda podia sentir que Chaminade estava em perigo.",
  ui_story_5036_50361701_28_dialog_content = "Não poderia ajudá-la, mas sabia que seu desejo era voltar para casa.",
  ui_story_5036_50361701_29_dialog_content = "Então, o sonho nasceu de como sentia falta dela. Criou um sonho onde seu amigo finalmente voltou para casa.",
  ui_story_5036_50361701_30_dialog_content = "O Ouroboros continuou a dormir apenas para manter esse sonho vivo.",
  ui_story_5036_50361701_31_dialog_content = "Eu vejo. Não admira que nunca tenha chocado!",
  ui_story_5036_50361701_32_dialog_content = "Então, por que eclodiu de repente? Poderia ter algo a ver com o sonho também?",
  ui_story_5036_50361701_33_dialog_content = "Porque eu posso ter escorregado...",
  ui_story_5036_50361701_34_dialog_content = "Chaminade ficou arrasado ao saber que Eraveil foi destruído.",
  ui_story_5036_50361701_35_dialog_content = "Então o sonho desmoronou e nunca mais poderia voltar a ser como era.",
  ui_story_5036_50361701_36_dialog_content = "Eu nem tive a chance de me desculpar com ela.",
  ui_story_5036_50361701_37_dialog_content = "Mas, no final, ela queria que eu levasse a música para todos.",
  ui_story_5036_50361701_38_dialog_content = "Vou manter essa promessa, mesmo que não possa mais ser um ídolo.",
  ui_story_5036_50361701_39_dialog_content = "<color=#e8d9bb>Bip bip bip—</color>",
  ui_story_5036_50361701_40_dialog_content = "Ei! Um pedido de mensagem do Sheol!",
  ui_story_5036_50361701_41_dialog_content = "O-O que fazemos? Devemos responder?",
  ui_story_5036_50361701_42_dialog_content = "De alguma forma, tenho um mau pressentimento sobre isso.",
  ui_story_5036_50361701_43_dialog_content = "Espere, vamos perguntar ao meu grampo de cabelo!",
  ui_story_5036_50361701_44_dialog_content = "<color=#e8d9bb>Ding—</color>",
  ui_story_5036_50361701_45_dialog_content = "Está apontado para baixo. Isso é um bom sinal!",
  ui_story_5036_50361701_46_dialog_content = "Devemos responder?",
  ui_story_5036_50361701_47_dialog_content = "Vamos responder, PlayerName.",
  ui_story_5036_50361701_48_dialog_content = "O único caminho a seguir é enfrentar nossos problemas.",
  ui_story_5036_50361701_49_dialog_content = "Tudo bem então. Fazendo-a passar—",
  ui_story_5036_50361701_50_dialog_content = "PlayerName?",
  ui_story_5036_50361701_51_dialog_content = "Senhora Sheol? Estou ouvindo!",
  ui_story_5036_50361701_52_dialog_content = "Onde você está agora? O que está acontecendo?",
  ui_story_5036_50361701_53_dialog_content = "Estamos em Soroz. Estamos todos aqui. Todos estão bem.",
  ui_story_5036_50361701_54_dialog_content = "Ninguém está ferido? Isso é ótimo... agora então...",
  ui_story_5036_50361701_55_dialog_content = "GOL — MORRA!",
  ui_story_5036_50361701_56_dialog_content = "*Soluço*",
  ui_story_5036_50361701_57_dialog_content = "É melhor você se explicar. Como um show que deveria ser tranquilo se transformou nessa catástrofe!?",
  ui_story_5036_50361701_58_dialog_content = "eu, eh...",
  ui_story_5036_50361701_59_dialog_content = "Eu sinto Muito. Eu estraguei tudo...",
  ui_story_5036_50361701_60_dialog_content = "Eu não inspecionei o local com cuidado suficiente, então não consegui encontrar o ovo de Ouroboros no Colossus e perceber a ameaça potencial que ele representava.",
  ui_story_5036_50361701_61_dialog_content = "E eu não previ que o Ouroboros reagiria de alguma forma ao meu canto e eclodiria...",
  ui_story_5036_50361701_62_dialog_content = "Você sabe, você poderia simplesmente culpar Ouroboros por tudo.",
  ui_story_5036_50361701_63_dialog_content = "Não. Vou assumir total responsabilidade por isso e compensar integralmente todas as perdas pelo contrato.",
  ui_story_5036_50361701_64_dialog_content = "Suspiro... você realmente me ferrou.",
  ui_story_5036_50361701_65_dialog_content = "Investi muito dinheiro na promoção do show. Com a saída do Colossus, todo o dinheiro gasto na manutenção de seus equipamentos e na montagem do palco também foi por água abaixo.",
  ui_story_5036_50361701_66_dialog_content = "Sem contar que houve outros custos, como os custos de cuidar do público quando o incidente ocorreu.",
  ui_story_5036_50361701_67_dialog_content = "Sinto muito...",
  ui_story_5036_50361701_68_dialog_content = "Mas, por favor, fique tranquilo, eu pagarei tudo de volta.",
  ui_story_5036_50361701_69_dialog_content = "Mesmo que eu não seja mais um ídolo no futuro, ainda vou trabalhar duro para pagar⁠—",
  ui_story_5036_50361701_70_dialog_content = "Huh? Quando eu pedi para você cobrir as perdas?",
  ui_story_5036_50361701_71_dialog_content = "Ahn???",
  ui_story_5036_50361701_72_dialog_content = "O show foi um desastre, sim, mas você se apresentou inesperadamente bem!",
  ui_story_5036_50361701_73_dialog_content = "As emoções da sua música foram passadas não só para o Ouroboros, mas também para o público!",
  ui_story_5036_50361701_74_dialog_content = "Mesmo aqueles que nunca se interessaram por ídolos aprenderam sobre você por causa desse incidente!",
  ui_story_5036_50361701_75_dialog_content = "E muitos vieram perguntar sobre \"o ídolo\"!",
  ui_story_5036_50361701_76_dialog_content = "O quê?!",
  ui_story_5036_50361701_77_dialog_content = "Você não apenas concluiu seu contrato na íntegra, mas o excedeu em muito.",
  ui_story_5036_50361701_78_dialog_content = "A-Tá falando sério?",
  ui_story_5036_50361701_79_dialog_content = "eu sou? Por que você não descobre pelos seus fãs?",
  ui_story_5036_50361701_80_dialog_content = "Senhorita! Isso é você?",
  ui_story_5036_50361701_81_dialog_content = "É você! Você e sua irmã estão seguros?",
  ui_story_5036_50361701_82_dialog_content = "Estamos bem! Você foi incrível!",
  ui_story_5036_50361701_83_dialog_content = "A música era legal e você até domou aquele dragão!",
  ui_story_5036_50361701_84_dialog_content = "Todos viram como você foi corajoso! Tão legal!",
  ui_story_5036_50361701_85_dialog_content = "Sério? Heheh! Estou tão feliz em ouvir você dizer isso!",
  ui_story_5036_50361701_86_dialog_content = "Outra pessoa também quer falar com você!",
  ui_story_5036_50361701_87_dialog_content = "Esse é o Goldie?",
  ui_story_5036_50361701_88_dialog_content = "S-Sim, aqui é Goldie falando. E você é-?",
  ui_story_5036_50361701_89_dialog_content = "Você está interessado em ser meu solista pessoal?",
  ui_story_5036_50361701_90_dialog_content = "O que você disse?!",
  ui_story_5036_50361701_91_dialog_content = "Seu desempenho me fez acreditar que você é uma pessoa confiável de honra e valor.",
  ui_story_5036_50361701_92_dialog_content = "Por favor, seja meu solista! Posso te ajudar a cantar nos palcos mais luxuosos de toda Lumópolis.",
  ui_story_5036_50361701_93_dialog_content = "Obrigado pela sua generosa oferta, mas...",
  ui_story_5036_50361701_94_dialog_content = "Como posso convencê-lo? Diga seu preço!",
  ui_story_5036_50361701_95_dialog_content = "Não é uma questão de dinheiro. Prefiro continuar sendo um ídolo do que me tornar um artista particular.",
  ui_story_5036_50361701_96_dialog_content = "Um ídolo traz esperança e felicidade para todos, independentemente do status.",
  ui_story_5036_50361701_97_dialog_content = "Prometi a um importante amigo e predecessor trazer nossa música para todos!",
  ui_story_5036_50361701_98_dialog_content = "É assim mesmo...? Que pena.",
  ui_story_5036_50361701_99_dialog_content = "Bem, desejo-lhe boa sorte com os seus sonhos e com certeza irei ao seu próximo concerto.",
  ui_story_5036_50361701_100_dialog_content = "Muito obrigado!",
  ui_story_5036_50361701_101_dialog_content = "Então? Você está convencido agora?",
  ui_story_5036_50361701_102_dialog_content = "Sim! Sem dúvida!",
  ui_story_5036_50361701_103_dialog_content = "Então anime-se e prepare-se para o próximo desafio.",
  ui_story_5036_50361701_104_dialog_content = "Eu já preenchi sua agenda. Você terá muito o que fazer quando voltar para Umbraton.",
  ui_story_5036_50361701_105_dialog_content = "Ok! Vou voltar agora mesmo!",
  ui_story_5036_50361701_106_dialog_content = "A propósito, ouvi dizer que você descobriu um novo talento em potencial chamado Vic. Ele está aqui?",
  ui_story_5036_50361701_107_dialog_content = "Quem eu?",
  ui_story_5036_50361701_108_dialog_content = "Você está interessado em assinar como um dos meus ídolos?",
  ui_story_5036_50361701_109_dialog_content = "O que? Hahaha? Você deve estar brincando comigo.",
  ui_story_5036_50361701_110_dialog_content = "Não nasci para estar sob os holofotes. Eu gosto de passar tempo com os animais.",
  ui_story_5036_50361701_111_dialog_content = "Você não vai reconsiderar?",
  ui_story_5036_50361701_112_dialog_content = "Posso pagar generosamente e incluir o melhor champanhe de Umbraton como bônus.",
  ui_story_5036_50361701_113_dialog_content = "Isso com certeza parece atraente. Eu não precisaria cuidar da Pequena Bola de Pelos e poderia beber todos os dias...",
  ui_story_5036_50361701_114_dialog_content = "Chilro?! ",
  ui_story_5036_50361701_115_dialog_content = "CHILRO!!!",
  ui_story_5036_50361701_116_dialog_content = "Huh? Ei! Deixe ir, você! Solte!",
  ui_story_5036_50361701_117_dialog_content = "Parece que alguém discorda fortemente.",
  ui_story_5036_50361701_118_dialog_content = "Tudo bem então. Falaremos sobre isso em outra ocasião.",
  ui_story_5036_50361701_119_dialog_content = "Então, vejo todos vocês em Umbraton.",
  ui_story_5036_50361701_120_dialog_content = "Excelente! Realmente é... perfeito!",
  ui_story_5036_50361701_121_dialog_content = "Eu posso continuar a ser um ídolo!",
  ui_story_5036_50361701_122_dialog_content = "Parabéns, Goldie!",
  ui_story_5036_50361701_123_dialog_content = "Apesar de como este show falhou, da próxima vez eu vou conseguir!",
  ui_story_5036_50361701_124_dialog_content = "Por favor venha, PlayerName. Vou guardar para você os melhores lugares!",
  ui_story_5036_50361701_125_dialog_content = "É claro. É um acordo!",
  ui_story_5036_50361701_126_dialog_content = "Mas levará algum tempo até que isso aconteça.",
  ui_story_5036_50361701_127_dialog_content = "Depois que eu voltar, vou escrever uma música sobre essa provação!",
  ui_story_5036_50361701_128_dialog_content = "Parece que tudo está bem quando acaba bem.",
  ui_story_5036_50361701_129_dialog_content = "Com certeza parece. Uau, agora que tenho um momento para relaxar, de repente estou tão cansada.",
  ui_story_5036_50361701_130_dialog_content = "Já estou ficando com sono... Bocejo...",
  ui_story_5036_50361701_131_dialog_content = "Hmph! Se não fosse por esse drama, eu estaria tomando um bom banho quente agora!",
  ui_story_5036_50361701_132_dialog_content = "Sem banho, sem problemas.",
  ui_story_5036_50361701_133_dialog_content = "Nenhuma diferença, de qualquer maneira.",
  ui_story_5036_50361701_134_dialog_content = "Foi tão bom ver toda essa rara tecnologia antiga em Eulogoz.",
  ui_story_5036_50361701_135_dialog_content = "A tela e o sistema estéreo eram fascinantes. Estou inspirado!",
  ui_story_5036_50361701_136_dialog_content = "Estou me perguntando se devo examinar seus princípios de funcionamento e fazer alguns para o trono...",
  ui_story_5036_50361701_137_dialog_content = "Não me diga que...",
  ui_story_5036_50361701_138_dialog_content = "Então eu posso jogar a qualquer hora, o tempo todo!",
  ui_story_5036_50361701_139_dialog_content = "Como eu pensava.",
  ui_story_5036_50361701_140_dialog_content = "De qualquer forma. Vamos voltar à superfície primeiro.",
  ui_story_5036_50361701_141_dialog_content = "<color=#e8d9bb>Algum tempo depois</color>",
  ui_story_5036_50361701_142_dialog_content = "Já é dia. Não percebi que tanto tempo havia passado.",
  ui_story_5036_50361701_143_dialog_content = "Finalmente de volta à terra! Isso foi demais, não foi, Bolinha de Pelos?",
  ui_story_5036_50361701_144_dialog_content = "Piu!",
  ui_story_5036_50361701_145_dialog_content = "Nós é que lutamos enquanto você apenas assistia!",
  ui_story_5036_50361701_146_dialog_content = "Ei, não é justo dizer isso. Fiz o meu melhor para proteger Ouroboros também!",
  ui_story_5036_50361701_147_dialog_content = "Não importa, não vou discutir com você desde que você se esforçou.",
  ui_story_5036_50361701_148_dialog_content = "Vou decolar agora. Fia e Shira ainda estão esperando que eu volte para elas e conte sobre Ouroboros.",
  ui_story_5036_50361701_149_dialog_content = "Até a próxima.",
  ui_story_5036_50361701_150_dialog_content = "Mais tarde, Vic!",
  ui_story_5036_50361701_151_dialog_content = "Cuidado lá fora! Não seja sequestrado novamente!",
  ui_story_5036_50361701_152_dialog_content = "Não se preocupe! Eu sou um adulto totalmente confiável!",
  ui_story_5036_50361701_153_dialog_content = "Também levaremos um dirigível de volta a Lumopolis.",
  ui_story_5036_50361701_154_dialog_content = "(Sinceramente, tenho que arranjar alguém para preparar um banho quente para mim com antecedência da próxima vez...)",
  ui_story_5036_50361701_155_dialog_content = "Ei, seus pirralhos Rediesel Wrench. Da próxima vez que os vir, estarei mandando todos vocês para a prisão.",
  ui_story_5036_50361701_156_dialog_content = "O que? Que arrogante. Quem diabos você pensa que é?",
  ui_story_5036_50361701_157_dialog_content = "Mais tarde, celestita.",
  ui_story_5036_50361701_158_dialog_content = "Adeus!",
  ui_story_5036_50361701_159_dialog_content = "Todos se foram? Sio, vamos voltar também.",
  ui_story_5036_50361701_160_dialog_content = "Tudo bem. O tempo de férias acabou. É hora de voltar ao trabalho.",
  ui_story_5036_50361701_161_dialog_content = "Oficial Gronru, você não está voltando conosco no Colossus?",
  ui_story_5036_50361701_162_dialog_content = "Está bem. Sio e eu vamos de carro, para não atrapalhar seus planos.",
  ui_story_5036_50361701_163_dialog_content = "Além disso, preciso discutir com Sio a possibilidade de adicionar uma tela e um console de jogos ao trono!",
  ui_story_5036_50361701_164_dialog_content = "O-O que você disse!?",
  ui_story_5036_50361701_165_dialog_content = "Vamos, meu pequeno Sio!",
  ui_story_5036_50361701_166_dialog_content = "A-Ajude-me...!",
  ui_story_5036_50361701_167_dialog_content = "Parece que ainda existem problemas insolúveis para alguém como Siobhan.",
  ui_story_5036_50361701_168_dialog_content = "Acho que também devemos voltar.",
  ui_story_5036_50361701_169_dialog_content = "Sim, sim!",
  ui_story_5036_50361701_170_dialog_content = "Eu decidi!",
  ui_story_5036_50361701_171_dialog_content = "Ha? Que loucura você decidiu desta vez?",
  ui_story_5036_50361701_172_dialog_content = "Assim que voltarmos, vou convencer o chefe a colocar um palco na cabeça de Lepidoz!",
  ui_story_5036_50361701_173_dialog_content = "Isso realmente parece uma boa ideia!",
  ui_story_5036_50361701_174_dialog_content = "Ei! A ideia foi minha! Vou pedir ao chefe para fazer um estágio de ídolo!",
  ui_story_5036_50361701_175_dialog_content = "Volte aqui, você! Heavy Metal é música de verdade!",
  ui_story_5036_50361701_176_dialog_content = "Oh, que animado.",
  ui_story_5036_50361701_177_dialog_content = "Vamos nos despedir também, PlayerName.",
  ui_story_5036_50361701_178_dialog_content = "Obrigado por tudo!",
  ui_story_5036_50361701_179_dialog_content = "Você também. Você trabalhou duro para fazer esse show acontecer, e travamos uma longa batalha. É hora de descansar bem.",
  ui_story_5036_50361701_180_dialog_content = "Eu sou um ídolo profissional, você sabe. Só um cochilo e estarei pronto para ir!",
  ui_story_5036_50361701_181_dialog_content = "Por favor, esperem ansiosamente pelo meu próximo concerto!",
  ui_story_5036_50361701_182_dialog_content = "Vou ter a certeza de esperar por sua boa notícia!",
  ui_story_5036_50361701_183_dialog_content = "Então tchau!",
  ui_story_5036_50361701_184_dialog_content = "Então as tendências violentas de Goldie eram apenas boatos. Eu tenho que esclarecer isso no meu artigo.",
  ui_story_5036_50361701_185_dialog_content = "Ei, editor-chefe?",
  ui_story_5036_50361701_186_dialog_content = "<size=45>Brandy! Por que você demorou tanto para entrar em contato comigo?</size>",
  ui_story_5036_50361701_187_dialog_content = "Você será demitido se não tiver algo grande para mim!",
  ui_story_5036_50361701_188_dialog_content = "Eu investiguei os rumores de que Goldie é uma pessoa violenta. É tudo falso!",
  ui_story_5036_50361701_189_dialog_content = "...",
  ui_story_5036_50361701_190_dialog_content = "Isso é tudo o que você descobriu durante todo o tempo em que o Colosso Errante estava sobrevoando Umbraton!?",
  ui_story_5036_50361701_191_dialog_content = "Mesmo que sejam notícias falsas, ainda atrairão leitores, não é? Sem esse tipo de fofoca, teríamos que desligar.",
  ui_story_5036_50361701_192_dialog_content = "Estou muito desapontado com você, Brandy. Você está sendo rebaixado⁠—",
  ui_story_5036_50361701_193_dialog_content = "Espere! Essa não é a única coisa! Tenho detalhes exclusivos sobre o show do Wandering Colossus!",
  ui_story_5036_50361701_194_dialog_content = "O que!? Você é sério! Bem, traga-o aqui, então!",
  ui_story_5036_50361701_195_dialog_content = "Com uma condição.",
  ui_story_5036_50361701_196_dialog_content = "O que foi?",
  ui_story_5036_50361701_197_dialog_content = "O exclusivo e o artigo que dissipa os rumores sobre Goldie devem estar na mesma página.",
  ui_story_5036_50361701_198_dialog_content = "Quero que todos saibam que têm uma ideia errada sobre Goldie!",
  ui_story_5036_50361701_199_dialog_content = "T-Isso é pré-post...",
  ui_story_5036_50361701_200_dialog_content = "<size=45>Ugh, tudo bem, tudo bem!</size>",
  ui_story_5036_50361701_201_dialog_content = "Eu farei isso. Agora pegue seus relatórios aqui.",
  ui_story_5036_50361701_202_dialog_content = "Agora mesmo!",
  ui_story_5036_50361701_203_dialog_content = "Então você sequestrou o Drakolion com biscoitos de animais e se esgueirou até o Colosso Errante para investigá-lo... por nada!?",
  ui_story_5036_50361701_204_dialog_content = "Quase fui emboscado por Eclipsites enquanto tentava encontrar o Drakolion!",
  ui_story_5036_50361701_205_dialog_content = "Como você vai me compensar por isso, hein!? Mestre?",
  ui_story_5036_50361701_206_dialog_content = "Nós iremos! Apesar de não conseguir descobrir mais sobre o Ouroboros, nós o acordamos e recebemos muitas informações!",
  ui_story_5036_50361701_207_dialog_content = "O retorno do Ouroboros definitivamente agitará as coisas no Astra!",
  ui_story_5036_50361701_208_dialog_content = "Confie em mim, com as informações que tenho agora. Será fácil rastrear Ouroboros no futuro!",
  ui_story_5036_50361701_209_dialog_content = "Por que isso soa tão familiar?",
  ui_story_5036_50361701_210_dialog_content = "Foi o que ele disse da última vez.",
  ui_story_5036_50361701_211_dialog_content = "\"Confie em mim, com certeza vou ganhar muito dinheiro da próxima vez!\"",
  ui_story_5036_50361701_212_dialog_content = "Como é que você se lembra tão bem?",
  ui_story_5036_50361701_213_dialog_content = "Porque foi o que ele disse antes disso também.",
  ui_story_5036_50361701_214_dialog_content = "Mas, até agora, não houve nenhuma mudança positiva em sua situação financeira. Ele continua ficando mais pobre.",
  ui_story_5036_50361701_215_dialog_content = "Verdadeiro. Ele ainda não pagou pela maravilhosa ração do mês passado!",
  ui_story_5036_50361701_216_dialog_content = "*Soluço* Eu sou realmente um perdedor aos seus olhos?",
  ui_story_5036_50361701_217_dialog_content = "O que você esperava?",
  ui_story_5036_50361701_218_dialog_content = "Eu estou tão triste!",
  ui_story_5036_50361701_219_dialog_content = "Então, todo mundo acha que seria melhor eu ser um ídolo?",
  ui_story_5036_50361701_220_dialog_content = "Eles te aplaudiram porque tiveram pena de você. Você não deve levar isso a sério.",
  ui_story_5036_50361701_221_dialog_content = "*Soluço*",
  ui_story_5036_50361701_222_dialog_content = "Mas, você estava certo pela primeira vez. Ouroboros realmente estava no Wandering Colossus.",
  ui_story_5036_50361701_223_dialog_content = "Como descobriu?",
  ui_story_5036_50361701_224_dialog_content = "Talvez para o Ouroboros, ir para o Colossus fosse uma forma de retorno.",
  ui_story_5036_50361701_225_dialog_content = "Como assim?",
  ui_story_5036_50361701_226_dialog_content = "Não importa quanto tempo um Ouroboros pode viver ou quantas vezes já eclodiu...",
  ui_story_5036_50361701_227_dialog_content = "Começou como um ovo de outro Ouroboros.",
  ui_story_5036_50361701_228_dialog_content = "Um filhote depende de seus pais para proteção por instinto.",
  ui_story_5036_50361701_229_dialog_content = "O mesmo vale para um Ouroboros que retorna ao seu estágio de infância em cada ciclo de vida.",
  ui_story_5036_50361701_230_dialog_content = "No entanto, Ouroboroses são muito poucos em número. Muitos nunca encontram seus pais.",
  ui_story_5036_50361701_231_dialog_content = "Por causa disso, eles só podem procurar os Colossos, com quem compartilham fortes laços.",
  ui_story_5036_50361701_232_dialog_content = "Tratar os Colossos como seus pais... que triste.",
  ui_story_5036_50361701_233_dialog_content = "Bem, já que você compartilha sangue com um Ouroboros, isso significa que um dia você estará procurando um Colosso ou algo assim?",
  ui_story_5036_50361701_234_dialog_content = "Meu passado é um mistério! Não faça conjecturas malucas!",
  ui_story_5036_50361701_235_dialog_content = "Isso é verdade. Para alguém tão inútil quanto você, que nem consegue usar habilidades psíquicas, você provavelmente estava blefando quando disse que compartilha linhagens com um Ouroboros.",
  ui_story_5036_50361701_236_dialog_content = "É verdade!",
  ui_story_5036_50361701_237_dialog_content = "Se isso é verdade, por que os Ouroboros não vieram te encontrar?",
  ui_story_5036_50361701_238_dialog_content = "Não é isso que deveríamos estar investigando? Vamos—",
  ui_story_5036_50361701_239_dialog_content = "Kree-!",
  ui_story_5036_50361701_240_dialog_content = "?!"
}
return config
